import type { Lang } from "./types";

/**
 * Researched artist biographies.
 *
 * The project's content rule applies here more sharply than anywhere else: these are
 * real, living people. A plausible-sounding bio assembled from a model's memory gets
 * nationalities, labels and dates wrong, and being wrong about a person in public is a
 * different class of mistake from being wrong about a ticket price. So every entry is
 * researched from a citable source and carries it in `sources`; an artist we could not
 * verify simply has no entry, and their page keeps showing dates without a bio — the
 * same way an event with no announced line-up says so rather than inventing one.
 *
 * `bio` is two to four sentences, French first (the source of truth) and English for
 * `/en`. Facts only: where they are from, what they play, what they are known for.
 * No superlatives we cannot source, no "one of the most influential artists of his
 * generation" — that sentence is true of nobody and printable about everybody.
 */
export interface ArtistBio {
  /** Matches `Artist.slug` from lib/artists.ts (i.e. `slugify(name)`). */
  slug: string;
  bio: { fr: string; en: string };
  /** Country or city the artist is from, as stated by the source. */
  origin?: string;
  /** Year they started releasing/performing, when a source gives one. */
  since?: number;
  /** Labels, when documented — a strong relevance signal for the genre pages. */
  labels?: string[];
  /** URLs the facts came from. Never empty: no source, no entry. */
  sources: string[];
  /**
   * Le portrait a déménagé dans `lib/artist-photos.ts`.
   *
   * Il vivait ici, ce qui rendait la photo conditionnée à la bio : un artiste dont on
   * trouvait le portrait sur Commons mais dont on n'avait pas su écrire deux phrases
   * sourcées gardait son initiale dans un rond. Une image sous licence libre et un
   * texte vérifié sont deux faits indépendants — les coupler faisait perdre le premier
   * chaque fois que le second manquait. Utiliser `artistPhoto(slug)`.
   */
}

/* BIOS:start — generated by .research/artists/ingest.py, do not edit by hand */
export const BIOS: Record<string, ArtistBio> = {
  "2-engel-charlie": { slug: "2-engel-charlie", bio: { fr: "2 Engel & Charlie est un duo de DJ et producteurs berlinois, apparu en 2022, qui joue masqué en rose fluo. Leur son mise sur l'EDM rapide et des chœurs qu'ils chantent eux-mêmes. Ils ont collaboré avec Finch, Tream, DJ Robin, Harris & Ford et HBz, et sont entrés pour la première fois dans les charts allemands en 2023 avec « Tattoo », aux côtés de Finch et HBz. Ils sont signés chez Jinx Music.", en: "2 Engel & Charlie are a Berlin DJ and producer duo who emerged in 2022 and perform in neon-pink masks. Their sound leans on fast EDM and choir vocals they sing themselves. They have worked with Finch, Tream, DJ Robin, Harris & Ford and HBz, and first entered the German charts in 2023 with \"Tattoo\", alongside Finch and HBz. They are signed to Jinx Music." }, origin: "Berlin, Allemagne", since: 2022, labels: ["Jinx Music"], sources: ["https://de.wikipedia.org/wiki/2_Engel_%26_Charlie", "https://www.jinx-music.com/2engel-charlie"] }, // 2 Engel & Charlie
  "25emeheure": { slug: "25emeheure", bio: { fr: "25EMEHEURE est une DJ parisienne de hard techno, membre du collectif Organik. Ses sets, qu'elle décrit comme frontaux et sans détour, croisent hard techno, percussions et voix, et passent par le hardgroove, le schranz et la hard trance. Elle a joué au Warehouse de Nantes, au Rex Club, ainsi qu'à l'Insane Festival, à Impact et à l'Open Rave Festival.", en: "25EMEHEURE is a Paris hard techno DJ and a member of the Organik collective. Her sets, which she describes as head-on and unfiltered, cross hard techno, percussion and vocals, taking in hardgroove, schranz and hard trance. She has played Nantes's Warehouse, the Rex Club, and Insane Festival, Impact and Open Rave Festival." }, origin: "Paris, France", sources: ["https://www.warehouse-nantes.fr/artist/25emeheure", "https://djobooking.com/article/25emeheure-letoile-montante-du-hard-techno-qui-electrise-leurope"] }, // 25emeheure
  "2hot2play": { slug: "2hot2play", bio: { fr: "2HOT2PLAY est un duo installé à Berlin, qui mêle hard house, trance et techno dans un format rapide taillé pour les grandes salles. Il a publié sur Polyamor, RAW et sur Exhale Records, le label d'Amelie Lens.", en: "2HOT2PLAY are a Berlin-based duo blending hard house, trance and techno into a fast format built for big rooms. They have released on Polyamor, RAW and on Exhale Records, Amelie Lens's label." }, origin: "Berlin, Allemagne", labels: ["Polyamor", "RAW", "Exhale Records"], sources: ["https://www.dourfestival.eu/en/artiste/266-2hot2play/"] }, // 2HOT2PLAY
  "2manydjs": { slug: "2manydjs", bio: { fr: "2ManyDJs est le duo DJ formé par les frères David et Stephen Dewaele, également membres du groupe belge Soulwax, originaire de Gand. Ils se sont d'abord produits sous le nom The Flying Dewaele Brothers. Leur compilation As Heard on Radio Soulwax Pt. 2 (2002) a popularisé le mashup en club.", en: "2ManyDJs is the DJ duo of brothers David and Stephen Dewaele, also members of the Belgian band Soulwax from Ghent. They first performed as The Flying Dewaele Brothers. Their 2002 compilation As Heard on Radio Soulwax Pt. 2 helped popularise the club mashup." }, origin: "Gand, Belgique", sources: ["https://en.wikipedia.org/wiki/Soulwax"] }, // 2ManyDJs
  "36framez": { slug: "36framez", bio: { fr: "36framez est une DJ néerlandaise installée à Utrecht, également photographe de nuit. Elle joue en vinyle et son bac est entièrement house — rythmiques nerveuses portées par des voix queer, grooves deep et soul, et quelques disques à contre-emploi. Elle a joué à IsBurning, au Radion, à BRET et au festival ZeeZout.", en: "36framez is a Dutch DJ based in Utrecht who also works as a nightlife photographer. She plays vinyl and her record bag is all house — punchy rhythms carried by queer vocals, deep and soulful grooves, and the odd curveball. She has played IsBurning, Radion, BRET and the ZeeZout festival." }, origin: "Utrecht, Pays-Bas", sources: ["https://www.zeezout.info/event/zeezout-festival"] }, // 36framez
  "5napback": { slug: "5napback", bio: { fr: "5NAPBACK est un DJ et producteur belge originaire de Duffel. Il remporte le concours MNM Start To DJ en 2015 et a depuis joué à Tomorrowland et au Hype-O-Dream. Ses productions vont de la deep, progressive et electro house au trap et au hardstyle ; il sort chez CNR Records Belgium.", en: "5NAPBACK is a Belgian DJ and producer from Duffel. He won the MNM Start To DJ contest in 2015 and has since played Tomorrowland and Hype-O-Dream. His productions range from deep, progressive and electro house to trap and hardstyle; he releases on CNR Records Belgium." }, origin: "Duffel, Belgique", since: 2015, labels: ["CNR Records Belgium"], sources: ["https://cnrrecords.be/en/portfolio/5napback/", "https://5napback.com/"] }, // 5NAPBACK
  "808-state": { slug: "808-state", bio: { fr: "808 State est un groupe de musique électronique anglais formé en 1987 à Manchester par Graham Massey, Martin Price et Gerald Simpson. Son nom vient de la boîte à rythmes Roland TR-808. Le premier album, Newbuild, paraît en septembre 1988 ; le succès arrive en 1989 avec le titre « Pacific State ».", en: "808 State are an English electronic group formed in 1987 in Manchester by Graham Massey, Martin Price and Gerald Simpson. The name comes from the Roland TR-808 drum machine. Their debut album Newbuild came out in September 1988; commercial success followed in 1989 with \"Pacific State\"." }, origin: "Manchester, Royaume-Uni", since: 1987, sources: ["https://en.wikipedia.org/wiki/808_State", "https://api.discogs.com/database/search?artist=808+State&type=release&per_page=50"] }, // 808 State
  "999999999": { slug: "999999999", bio: { fr: "999999999 est un duo italien de hard techno formé en 2016, qui se produit exclusivement en live et uniquement au matériel analogique. Le duo a d'abord publié ses disques en vinyle seul sur son propre label NineTimesNine, avant de passer au numérique en 2020. Son morceau « 300000003 », sorti sur Planet Rhythm en 2018, a été repressé à plusieurs reprises et a fait connaître sa techno acide à un large public. Le duo organise aussi ses propres soirées 9x9 Invites en Europe.", en: "999999999 are an Italian hard techno duo formed in 2016 who perform exclusively as a hardware-only live act. They first put out records as a vinyl-only operation on their own NineTimesNine label before moving to digital in 2020. Their track \"300000003\", released on Planet Rhythm in 2018, went through repeated represses and brought their acid techno to a much wider audience. The pair also run their own 9x9 Invites parties across Europe." }, origin: "Italie", since: 2016, labels: ["NineTimesNine"], sources: ["https://www.awakenings.com/en/artists/999999999/1658/"] }, // 999999999
  "a-for-alpha": { slug: "a-for-alpha", bio: { fr: "Abby Gray, alias A For Alpha, est une DJ britannique dont les sets puisent dans l'underground des années 1990 et croisent house, garage, trance et techno. Elle tient une émission hebdomadaire sur SWU.FM, dirige son propre label et a joué à Fabric, Boiler Room, Glastonbury et Outlook.", en: "Abby Gray, who performs as A For Alpha, is a British DJ whose sets draw on the 1990s underground and move between house, garage, trance and techno. She holds a weekly residency on SWU.FM, runs her own imprint, and has played Fabric, Boiler Room, Glastonbury and Outlook." }, origin: "Royaume-Uni", sources: ["https://www.discogs.com/artist/12619907-A-For-Alpha"] }, // A For Alpha
  "a-m-c": { slug: "a-m-c", bio: { fr: "A.M.C est le nom de scène d'Alex Mark Calvert, DJ et producteur britannique de drum & bass, en activité depuis 2007. Il est connu pour ses sets sur quatre platines et a fondé le label Titan Records en 2011, qui a publié Emperor, Hypoxia et L 33. Il a remporté le titre de meilleur DJ aux Drum & Bass Awards tchèques et portugais.", en: "A.M.C is the stage name of Alex Mark Calvert, a British drum & bass DJ and producer, active since 2007. He is known for four-deck sets and founded the label Titan Records in 2011, which has released Emperor, Hypoxia and L 33. He has won best DJ at the Czech and Portuguese Drum & Bass Awards." }, origin: "Royaume-Uni", since: 2007, labels: ["Titan Records"], sources: ["https://www.featherstonemusic.co.uk/artists/a-m-c"] }, // A.M.C
  "a-teens": { slug: "a-teens", bio: { fr: "A*Teens est un groupe pop suédois formé à Stockholm en 1998 sous le nom ABBA Teens, d'abord consacré aux reprises d'ABBA. Ses disques, publiés par Stockholm Records, relèvent de l'europop et de l'euro house et se sont vendus à plus de neuf millions d'albums. Le groupe s'est séparé en 2004 avant de se reformer en 2024.", en: "A*Teens are a Swedish pop group formed in Stockholm in 1998 as ABBA Teens, initially devoted to ABBA covers. Their records, released by Stockholm Records, sit in europop and euro house and sold more than nine million albums. The group split in 2004 and reunited in 2024." }, origin: "Stockholm, Suède", since: 1998, labels: ["Stockholm Records"], sources: ["https://api.discogs.com/artists/81566", "https://en.wikipedia.org/wiki/A-Teens"] }, // A*Teens
  "aat": { slug: "aat", bio: { fr: "AAT est une DJ néerlandaise de La Haye. Elle se fait connaître en janvier 2023 en remportant le concours Toffler Talents, puis partage l'affiche avec Enzo Siragusa, Nick Curly ou Sidney Charles. Sa house groovy l'a menée à Loveland, Thuishaven et Mysteryland, puis en tournée en Asie — Bali, Tokyo, Shanghai, Séoul — avant d'être choisie comme résidente elrow pour 2025.", en: "AAT is a Dutch DJ from The Hague. She made her name in January 2023 by winning the Toffler Talents competition, then shared line-ups with Enzo Siragusa, Nick Curly and Sidney Charles. Her groovy house took her to Loveland, Thuishaven and Mysteryland, then on tour across Asia — Bali, Tokyo, Shanghai, Seoul — before she was picked as elrow's resident DJ for 2025." }, origin: "La Haye, Pays-Bas", since: 2023, sources: ["https://www.awakenings.com/en/artists/aat/386662/"] }, // AAT
  "above-beyond": { slug: "above-beyond", bio: { fr: "Above & Beyond est un groupe britannique de musique électronique formé en 2000, composé de Jono Grant, Tony McGuinness et du Finlandais Paavo Siljamäki. Le trio dirige le label Anjunabeats et a publié cinq albums studio. Deux de leurs singles, « We're All We Need » et « Northern Soul », ont été nommés aux Grammy Awards.", en: "Above & Beyond are a British electronic music group formed in 2000, made up of Jono Grant, Tony McGuinness and Finnish DJ Paavo Siljamäki. The trio run the Anjunabeats label and have released five studio albums. Two of their singles, \"We're All We Need\" and \"Northern Soul\", were nominated for Grammy Awards." }, origin: "Londres, Royaume-Uni", since: 2000, labels: ["Anjunabeats"], sources: ["https://en.wikipedia.org/wiki/Above_%26_Beyond_(band)"] }, // Above & Beyond
  "acid-arab": { slug: "acid-arab", bio: { fr: "Acid Arab est un groupe français d'électronique formé à Paris en 2012 par les DJ Guido Minisky et Hervé Carvalho, rejoints par Pierrot Casanova, Nicolas Borne et le claviériste Kenzi Bourras. Le projet greffe des structures rythmiques et des mélodies orientales et amazighes — raï algérien, chaâbi égyptien — sur une base d'acid house et de techno. Ils publient chez le label belge Crammed Discs, où sont parus « Musique de France » en 2016 et « Jdid » en 2019, après des premiers disques sur Versatile. Ils ont enregistré avec Omar Souleyman, Rachid Taha et Les Filles de Illighadad.", en: "Acid Arab are a French electronic group formed in Paris in 2012 by DJs Guido Minisky and Hervé Carvalho, later joined by Pierrot Casanova, Nicolas Borne and keyboard player Kenzi Bourras. The project grafts Middle Eastern and Amazigh rhythms and melodies — Algerian raï, Egyptian chaâbi — onto a base of acid house and techno. They record for the Belgian label Crammed Discs, home to \"Musique de France\" (2016) and \"Jdid\" (2019), after early records on Versatile. They have worked with Omar Souleyman, Rachid Taha and Les Filles de Illighadad." }, origin: "Paris, France", since: 2012, labels: ["Crammed Discs", "Versatile"], sources: ["https://fr.wikipedia.org/wiki/Acid_Arab"] }, // Acid Arab
  "acid-pauli": { slug: "acid-pauli", bio: { fr: "Acid Pauli est l'un des noms de scène de Martin Gretschmann, musicien électronique allemand né le 8 septembre 1973 en Bavière. Ancien programmeur du groupe The Notwist, il enregistre aussi sous le nom Console depuis 1995. Sous Acid Pauli, il publie une électronique lente et texturée sur Ouïe et Crosstown Rebels.", en: "Acid Pauli is one of the stage names of Martin Gretschmann, a German electronic musician born on 8 September 1973 in Bavaria. Formerly the programmer of the band The Notwist, he has also recorded as Console since 1995. As Acid Pauli he releases slow, textured electronic music on Ouïe and Crosstown Rebels." }, origin: "Bavière, Allemagne", labels: ["Ouïe", "Crosstown Rebels"], sources: ["https://en.wikipedia.org/wiki/Console_(musician)", "https://api.discogs.com/database/search?artist=Acid+Pauli&type=release"] }, // Acid Pauli
  "act-of-rage": { slug: "act-of-rage", bio: { fr: "Act of Rage est un DJ et producteur de hardstyle néerlandais, de son vrai nom Jacques Journée. Il s'est fait connaître par ses premières sorties sur le label Minus Is More, dans un registre raw hardstyle.", en: "Act of Rage is a Dutch hardstyle DJ and producer, real name Jacques Journée. He made his name with his first releases on the Minus Is More label, in a raw hardstyle vein." }, origin: "Pays-Bas", labels: ["Minus Is More"], sources: ["https://www.discogs.com/artist/3954322-Act-Of-Rage-2", "https://musicbrainz.org/ws/2/artist/?query=Act+of+Rage&fmt=json"] }, // Act of Rage
  "actress-m": { slug: "actress-m", bio: { fr: "DJ grenobloise active depuis 2019, Actress M est résidente du collectif Infrason. Ses sets mêlent italo disco, dark disco et EBM, dans un univers nourri par l'héritage des années 1980. Elle joue notamment à La Belle Électrique, à Grenoble.", en: "A Grenoble DJ active since 2019, Actress M is a resident of the Infrason collective. Her sets blend italo disco, dark disco and EBM, drawing on the legacy of the 1980s. She plays regularly at La Belle Électrique in Grenoble." }, origin: "Grenoble, France", since: 2019, sources: ["https://www.la-belle-electrique.com/en/events/dressing-club-italo-disco-2025"] }, // Actress M
  "adam-beyer": { slug: "adam-beyer", bio: { fr: "Adam Beyer, né le 15 mai 1976 à Stockholm, est un DJ et producteur suédois de techno. Il a fondé en 1996 le label Drumcode, devenu l'une des principales structures techno européennes, dont le catalogue accueille Amelie Lens, Joseph Capriati ou Pan-Pot. Il anime également l'émission hebdomadaire Drumcode Radio Live.", en: "Adam Beyer, born 15 May 1976 in Stockholm, is a Swedish techno DJ and producer. In 1996 he founded the Drumcode label, now one of Europe's major techno imprints, whose roster includes Amelie Lens, Joseph Capriati and Pan-Pot. He also hosts the weekly Drumcode Radio Live show." }, origin: "Stockholm, Suède", labels: ["Drumcode"], sources: ["https://en.wikipedia.org/wiki/Adam_Beyer", "https://en.wikipedia.org/wiki/Drumcode_Records"] }, // Adam Beyer
  "adam-f": { slug: "adam-f", bio: { fr: "Adam Fenton, né en 1972 à Liverpool, est un producteur et DJ anglais de drum & bass. Il se fait connaître avec les singles « Circles », « Metropolis » et « F-Jam » avant de publier son premier album, Colours, en 1997, récompensé par un MOBO Award. « Metropolis », sorti sur Metalheadz, reste l'un des morceaux de référence du techstep. Il a cofondé avec DJ Fresh le label Breakbeat Kaos.", en: "Adam Fenton, born in Liverpool in 1972, is an English drum & bass producer and DJ. He broke through with the singles \"Circles\", \"Metropolis\" and \"F-Jam\" before releasing his debut album Colours in 1997, which won a MOBO Award. \"Metropolis\", released on Metalheadz, remains a reference point for techstep. With DJ Fresh he co-founded the Breakbeat Kaos label." }, origin: "Liverpool, Royaume-Uni", since: 1995, labels: ["Metalheadz", "Positiva", "Breakbeat Kaos"], sources: ["https://en.wikipedia.org/wiki/Adam_F", "https://en.wikipedia.org/wiki/Colours_(Adam_F_album)", "https://www.musicradar.com/artists/adam-f-making-colours-revisited"] }, // Adam F
  "adam-ten": { slug: "adam-ten", bio: { fr: "Adam Ten est un DJ et producteur israélien de Tel-Aviv, résident du club The Block. Il joue de la house et de la techno teintées de percussions et d'indie dance, et a publié sur Diynamic, Crosstown Rebels, Disco Halal et Selador. Il dirige le label Maccabi House et a cofondé la série d'événements en plein air TERRA.", en: "Adam Ten is an Israeli DJ and producer from Tel Aviv and a resident of the club The Block. He plays house and techno shaded with percussion and indie dance, and has released on Diynamic, Crosstown Rebels, Disco Halal and Selador. He runs the Maccabi House label and co-founded the open-air event series TERRA." }, origin: "Tel-Aviv, Israël", labels: ["Maccabi House"], sources: ["https://strangetalent.agency/adam-ten"] }, // Adam Ten
  "adaro": { slug: "adaro", bio: { fr: "Adaro est le nom de scène de Thijs Ploegmakers, DJ et producteur néerlandais originaire de Schaijk. Il produit depuis 2002 et se tourne en 2008 vers le raw hardstyle, dont il est l'un des initiateurs, avec « The Haunter of the Dark » et « No Time To Sleep ». Classé 75e au DJ Mag Top 100 en 2013, il sort sur A2 Records jusqu'en 2014 puis fonde en 2015 le label Roughstate avec Ran-D, B-Front et Frequencerz.", en: "Adaro is the stage name of Thijs Ploegmakers, a Dutch DJ and producer from Schaijk. He has been producing since 2002 and turned to raw hardstyle in 2008, a style he helped originate, with \"The Haunter of the Dark\" and \"No Time To Sleep\". Ranked 75th in the 2013 DJ Mag Top 100, he released on A2 Records until 2014, then co-founded the Roughstate label in 2015 with Ran-D, B-Front and Frequencerz." }, origin: "Schaijk, Pays-Bas", since: 2002, labels: ["Roughstate", "A2 Records"], sources: ["https://en.wikipedia.org/wiki/Adaro_(DJ)"] }, // Adaro
  "adjuzt": { slug: "adjuzt", bio: { fr: "Adjuzt, de son vrai nom Maikel Rijkeboer, est un producteur et DJ de rawstyle originaire de Groningue, aux Pays-Bas. Il a signé « Elevate » avec Rebelion en 2022 et joué à Shockerz, Knockout Outdoor et Defqon.1 ; il a été nommé aux Hardstyle Awards dans la catégorie Best Talent.", en: "Adjuzt, real name Maikel Rijkeboer, is a rawstyle producer and DJ from Groningen in the Netherlands. He made 'Elevate' with Rebelion in 2022 and has played Shockerz, Knockout Outdoor and Defqon.1; he was nominated for Best Talent at the Hardstyle Awards." }, origin: "Groningue, Pays-Bas", sources: ["https://hardstyle.com/en/artists/adjuzt", "https://www.vipzone-samples.com/en/adjuzt/"] }, // Adjuzt
  "adrenalize": { slug: "adrenalize", bio: { fr: "Adrenalize est le nom de scène de Malthe Mehlskov, DJ et producteur hardstyle danois né le 21 octobre 1996. Sa discographie est presque entièrement hardstyle.", en: "Adrenalize is the stage name of Malthe Mehlskov, a Danish hardstyle DJ and producer born on 21 October 1996. His catalogue is almost entirely hardstyle." }, origin: "Danemark", sources: ["https://musicbrainz.org/artist/183b3df1-9ded-4277-ab11-a6fcb9a7cf44", "https://api.discogs.com/database/search?artist=Adrenalize&type=release&per_page=50"] }, // Adrenalize
  "adrian-mills": { slug: "adrian-mills", bio: { fr: "Adrián Mills est un DJ et producteur né en Espagne et installé dans le sud de l'Allemagne, où il vit depuis 2013. Il mêle les rythmes de la makina, les nappes de trance et une énergie hard techno. Il a lancé en 2021 au Gotec Club de Karlsruhe le label et la série de soirées 240 KM/H, et il est résident du Gotec ainsi que du collectif Adrenaline à Cologne.", en: "Adrián Mills is a DJ and producer born in Spain and based in southern Germany, where he has lived since 2013. He mixes makina rhythms, trance pads and hard techno energy. In 2021 he launched the label and party series 240 KM/H at Gotec Club in Karlsruhe, and he holds residencies at Gotec and with Cologne's Adrenaline collective." }, origin: "Espagne / Pforzheim, Allemagne", since: 2021, labels: ["240 KM/H"], sources: ["https://technobeatscloud.com/escena/deejays/adrian-mills"] }, // Adrián Mills
  "adriatique": { slug: "adriatique", bio: { fr: "Adriatique est un duo suisse formé par Adrian Shala et Adrian Schweizer — le nom vient de leur prénom commun. Ils se rencontrent en 2008 dans les clubs du pays et produisent ensemble depuis 2009 une house et une techno mélodiques et atmosphériques. Rattachés au label Diynamic de Solomun, ils fondent leur propre structure Siamese en 2016 et publient en septembre 2018 leur album Nude sur Afterlife, le label de Tale of Us.", en: "Adriatique is a Swiss duo made up of Adrian Shala and Adrian Schweizer — the name comes from their shared first name. They met in 2008 on the local club scene and have been producing melodic, atmospheric house and techno together since 2009. Affiliated with Solomun's Diynamic label, they founded their own imprint Siamese in 2016 and released their album Nude on Tale of Us's Afterlife in September 2018." }, origin: "Suisse", since: 2009, labels: ["Siamese", "Afterlife", "Diynamic"], sources: ["https://en.wikipedia.org/wiki/Adriatique"] }, // Adriatique
  "aerea": { slug: "aerea", bio: { fr: "AEREA est un duo madrilène — un couple d'artistes — qui produit et chante sa techno en live. Le projet a fait ses débuts à l'Aquasella, sur la scène Open Air du festival asturien.", en: "AEREA is a Madrid duo — an artist couple — who produce and sing their techno live. The project made its debut at Aquasella, on the Asturian festival's Open Air stage." }, origin: "Madrid, Espagne", sources: ["https://ra.co/dj/aerea", "https://viciousmagazine.com/news/aquasella-2026-presenta-su-cartel-mas-ambicioso-con-grandes-referentes-del-techno-internacional/"] }, // Aerea
  "afrojack": { slug: "afrojack", bio: { fr: "Nick van de Wall, alias Afrojack, est un DJ et producteur néerlandais né en 1987 à Spijkenisse. Il fonde son label Wall Recordings en 2007 et perce à l'international avec « Take Over Control » en 2010, avant un premier album, Forget the World, en 2014. Son répertoire mêle house, electro house et big room, et il a signé de nombreuses collaborations avec David Guetta, Pitbull ou Shakira.", en: "Nick van de Wall, known as Afrojack, is a Dutch DJ and producer born in 1987 in Spijkenisse. He founded the Wall Recordings label in 2007 and broke through internationally with \"Take Over Control\" in 2010, followed by a debut album, Forget the World, in 2014. His output blends house, electro house and big room, and he has collaborated widely with David Guetta, Pitbull and Shakira." }, origin: "Spijkenisse, Pays-Bas", since: 2007, labels: ["Wall Recordings"], sources: ["https://en.wikipedia.org/wiki/Afrojack"] }, // Afrojack
  "agents-of-time": { slug: "agents-of-time", bio: { fr: "Agents Of Time est un projet italien formé en 2013 par Andrea Di Ceglie, Luigi Tutolo et, un temps, Fedele Ladisa. Repérés avec le 12\" « Polina » sur Correspondant en 2014, ils se sont fait connaître par une techno mélodique jouée en live sur machines. Ils publient notamment chez Afterlife, le label de Tale Of Us, avec l'EP « Dream Vision ».", en: "Agents Of Time is an Italian project formed in 2013 by Andrea Di Ceglie, Luigi Tutolo and, for a time, Fedele Ladisa. Noticed with the 2014 12\" \"Polina\" on Correspondant, they became known for melodic techno performed live on hardware. They release on Afterlife, Tale Of Us' label, including the \"Dream Vision\" EP." }, origin: "Italie", since: 2013, labels: ["Afterlife", "Correspondant"], sources: ["https://kompakt.fm/artists/agents_of_time", "https://www.exitfest.org/en/agents-of-time-italys-perfect-melodic-techno-operatives"] }, // Agents Of Time
  "agnes": { slug: "agnes", bio: { fr: "Agnes Carlsson est une chanteuse suédoise. Après un long retrait, elle revient en 2020 avec le single « Fingers Crossed », puis l'album Magic Still Exists (2021, Universal Music Sweden), produit par Vargas & Lagola et tourné vers le disco. Sa discographie relève de l'europop et de l'euro house.", en: "Agnes Carlsson is a Swedish singer. After a long break she returned in 2020 with the single \"Fingers Crossed\", followed by the album Magic Still Exists (2021, Universal Music Sweden), produced by Vargas & Lagola and turned towards disco. Her discography sits in europop and euro house." }, origin: "Suède", labels: ["Universal Music Sweden", "Roxy Recordings"], sources: ["https://en.wikipedia.org/wiki/Magic_Still_Exists", "https://api.discogs.com/database/search?artist=Agnes&type=release"] }, // Agnes
  "aja-gulris": { slug: "aja-gulris", bio: { fr: "Aja Gulris est une DJ basée à Copenhague, résidente du club Culture Box et cofondatrice du collectif Peccāvī. Elle joue une techno mélodique sombre et hypnotique, faite de morceaux obscurs et de rythmiques roulantes.", en: "Aja Gulris is a Copenhagen-based DJ, a resident at Culture Box and co-founder of the Peccāvī collective. She plays dark, hypnotic melodic techno built on obscure records and rolling rhythms." }, origin: "Copenhague, Danemark", sources: ["https://backyard-sessions.se/aja-gulris", "https://soundcloud.com/ajagulris"] }, // Aja Gulris
  "alarico": { slug: "alarico", bio: { fr: "Alarico est le nom de scène d'Alarico Zucchi, DJ et producteur italien installé à Milan. Il commence à mixer à seize ans dans les clubs de sa région et se tourne ensuite vers une techno rapide, groovy et percussive, héritée des années 1990. Il forme avec Chlär le duo Funk Assault et a sorti ses disques sur Mutual Rytm, Token et Mindtrip.", en: "Alarico is the stage name of Alarico Zucchi, an Italian DJ and producer based in Milan. He started DJing at sixteen in local clubs and later moved towards fast, groovy, percussive techno rooted in the 1990s. With Chlär he forms the duo Funk Assault, and his records have come out on Mutual Rytm, Token and Mindtrip." }, origin: "Milan, Italie", sources: ["https://wololosound.com/entrevistas/alarico/", "https://musicbrainz.org/artist/19f27e4e-3f3b-4722-96c9-53c6f29d31a2"] }, // Alarico
  "alarico-pres-kenji-hina": { slug: "alarico-pres-kenji-hina", bio: { fr: "Alarico est un producteur et DJ techno italien, actif sous ce nom depuis 2019. Il fait ses débuts en production en 2020 avec l'EP « Cut Yo' Finger » sur Newrhythmic Records, puis lance son label vinyle Katana Records en 2021 avec « Raining Over Tokyo ». Kenji Hina est son second alias, inspiré par la culture japonaise, sous lequel il a publié la Tokyo Rythms Trilogy et l'EP « Kabukicho District » sur Emerald. Il a également sorti sur Mutual Rytm et Klockworks.", en: "Alarico is an Italian techno producer and DJ, active under that name since 2019. He debuted as a producer in 2020 with the \"Cut Yo' Finger\" EP on Newrhythmic Records, then launched his vinyl imprint Katana Records in 2021 with \"Raining Over Tokyo\". Kenji Hina is his second alias, drawn from Japanese culture, under which he released the Tokyo Rythms Trilogy and the \"Kabukicho District\" EP on Emerald. He has also released on Mutual Rytm and Klockworks." }, origin: "Italie", since: 2019, labels: ["Katana Records", "Mutual Rytm", "Klockworks"], sources: ["https://trifec.one/alarico/", "https://emerald.bandcamp.com/album/kabukicho-district-ep"] }, // Alarico pres. Kenji Hina
  "alignment": { slug: "alignment", bio: { fr: "Alignment est le projet de Francesco Pierfelici, DJ et producteur italien né en 1992 et installé à Berlin. Il dit avoir découvert la techno au Cocoricò de Riccione, et lance son alias en juillet 2015 : sa hard techno rapide et sans répit lui vaut le soutien de Ben Klock, Amelie Lens ou Richie Hawtin. Il est signé chez Voxnox depuis 2014 et publie aussi sur KNTXT, le label de Charlotte de Witte, ainsi que sur Involve Records, ARTS et Etruria Beat.", en: "Alignment is the project of Francesco Pierfelici, an Italian DJ and producer born in 1992 and based in Berlin. He says he discovered techno at the Cocoricò club in Riccione, and launched the alias in July 2015; his fast, relentless hard techno has drawn support from Ben Klock, Amelie Lens and Richie Hawtin. He has been signed to Voxnox since 2014 and also releases on Charlotte de Witte's KNTXT, as well as Involve Records, ARTS and Etruria Beat." }, origin: "Italie, installé à Berlin", since: 2015, labels: ["Voxnox", "KNTXT"], sources: ["https://www.beatportal.com/articles/464385-beatport-next-the-power-of-alignment", "https://electronicgroove.com/interview-alignment/"] }, // Alignment
  "alison-swing": { slug: "alison-swing", bio: { fr: "Alison Swing est une DJ née à Los Angeles et installée à Berlin depuis 2017, où elle est devenue résidente du club Renate dès son arrivée. Elle y a lancé sa propre soirée, Uforia, et codirige à Los Angeles la série de warehouse parties Dig Deeper avec la DJ Masha. Elle joue en vinyle et se définit d'abord comme sélectrice, entre house et disco.", en: "Alison Swing is a Los Angeles-born DJ who moved to Berlin in 2017 and became a resident at the Renate club almost immediately. She launched her own party there, Uforia, and co-runs the Los Angeles warehouse series Dig Deeper with DJ Masha. She plays vinyl and describes herself first of all as a selector, working between house and disco." }, origin: "Los Angeles, États-Unis", since: 2017, sources: ["https://djmag.com/content/get-know-alison-swing", "https://www.theransomnote.com/music/news/renate-resident-alison-swing-launches-new-party/"] }, // Alison Swing
  "alison-wonderland": { slug: "alison-wonderland", bio: { fr: "Alexandra Sholler, alias Alison Wonderland, est une productrice, DJ et chanteuse australienne née en 1986 à Sydney. Formée au violoncelle classique, elle a joué avec le Sydney Youth Opera avant de passer à la musique électronique et de sortir son premier single « Get Ready » en 2013. Ses trois albums — « Run » (2015), « Awake » (2018) et « Loner » (2022) — ont atteint la première place des classements dance australiens et américains ; « Ghost World » est paru en 2025.", en: "Alexandra Sholler, known as Alison Wonderland, is an Australian producer, DJ and singer born in 1986 in Sydney. Classically trained on cello, she played with the Sydney Youth Opera before moving into electronic music and releasing her debut single \"Get Ready\" in 2013. Her three albums — \"Run\" (2015), \"Awake\" (2018) and \"Loner\" (2022) — topped Australian and American dance charts; \"Ghost World\" followed in 2025." }, origin: "Sydney, Australie", since: 2013, sources: ["https://en.wikipedia.org/wiki/Alison_Wonderland", "https://www.allmusic.com/artist/alison-wonderland-mn0001868950"] }, // Alison Wonderland
  "alix-perez": { slug: "alix-perez", bio: { fr: "Alix Perez est le nom de scène d'Alix Depauw, producteur et DJ de drum & bass originaire de Charleroi, en Belgique, aujourd'hui installé en Nouvelle-Zélande. Sa musique est souvent rangée du côté du liquid funk. Il a fondé en 2016 le label et la marque de vêtements 1985 Music, après des sorties sur Shogun Audio et Exit Records.", en: "Alix Perez is the stage name of Alix Depauw, a drum & bass producer and DJ originally from Charleroi, Belgium, now based in New Zealand. His music is often described as liquid funk. In 2016 he founded the label and clothing imprint 1985 Music, after releases on Shogun Audio and Exit Records." }, origin: "Charleroi, Belgique", labels: ["1985 Music", "Shogun Audio", "Exit Records"], sources: ["https://en.wikipedia.org/wiki/Alix_Perez", "https://api.discogs.com/database/search?artist=Alix+Perez&type=release"] }, // Alix Perez
  "alle-farben": { slug: "alle-farben", bio: { fr: "Frans Zimmer, né en 1985 et installé à Berlin-Kreuzberg, mixe sous le nom Alle Farben depuis 2010 — d'abord Hundert Farben, en référence au peintre Friedensreich Hundertwasser. Parti de la tech house minimale, il bascule vers une house vocale avec l'album Synesthesia – I Think in Colours (2014) et les singles « She Moves (Far Away) » avec Graham Candy puis « Please Tell Rosie » avec Younotus.", en: "Frans Zimmer, born in 1985 and based in Berlin's Kreuzberg district, has DJed as Alle Farben since 2010 — first as Hundert Farben, after the painter Friedensreich Hundertwasser. He began with minimal tech house before turning to a vocal-led house sound on the album Synesthesia – I Think in Colours (2014) and the singles 'She Moves (Far Away)' with Graham Candy and 'Please Tell Rosie' with Younotus." }, origin: "Berlin, Allemagne", since: 2010, labels: ["Synesthesia Recordings"], sources: ["https://en.wikipedia.org/wiki/Alle_Farben", "https://electronicgroove.com/alle-farben-im-melody-man/"] }, // Alle Farben
  "alok": { slug: "alok", bio: { fr: "Alok, de son vrai nom Alok Achkar Peres Petrillo, est un DJ et producteur brésilien né le 26 août 1991 à Goiânia et basé à Brasília. Il débute dans la psytrance au sein du duo Logica avec son frère jumeau Bhaskar, avant de passer à la house en solo. Il publie notamment sur Spinnin' Records et Controversia.", en: "Alok, real name Alok Achkar Peres Petrillo, is a Brazilian DJ and producer born on 26 August 1991 in Goiânia and based in Brasília. He started out in psytrance as part of the duo Logica with his twin brother Bhaskar, before moving to house as a solo artist. He releases on Spinnin' Records and Controversia among others." }, origin: "Goiânia, Brésil", since: 2004, labels: ["Spinnin' Records", "Controversia"], sources: ["https://en.wikipedia.org/wiki/Alok_(DJ)", "https://www.discogs.com/artist/6629077-Alok-4"] }, // Alok
  "aly-fila": { slug: "aly-fila", bio: { fr: "Duo trance égyptien formé au Caire par Aly Amr Fathalah et Fadi Wassef Naguib, amis d'enfance qui commencent à jouer ensemble en 1999. Leur premier single, « Eye of Horus », sort en 2003. Ils lancent en 2006 l'émission radio Future Sound of Egypt, devenue trois ans plus tard un label du même nom, et publient l'album Rising Sun en 2010 puis Quiet Storm en 2013.", en: "Egyptian trance duo formed in Cairo by Aly Amr Fathalah and Fadi Wassef Naguib, childhood friends who began playing together in 1999. Their first single, \"Eye of Horus\", came out in 2003. In 2006 they launched the Future Sound of Egypt radio show, which became a label of the same name three years later, and released the album Rising Sun in 2010 followed by Quiet Storm in 2013." }, origin: "Le Caire, Égypte", since: 1999, labels: ["Future Sound of Egypt"], sources: ["https://en.wikipedia.org/wiki/Aly_%26_Fila", "https://trance-family.com/future-sound-of-egypt/"] }, // Aly & Fila
  "alycia-bezgo": { slug: "alycia-bezgo", bio: { fr: "Alycia Bezgo est une DJ belge installée à Bruxelles. Fille d'un ancien DJ, elle affûte son mixage à partir de 2023 et se fait connaître par un passage sur HÖR, puis joue à Tomorrowland, Awakenings et Teletech. Ses sets mêlent hardgroove, techno et trance, avec des références aux années 1990.", en: "Alycia Bezgo is a Belgian DJ based in Brussels. The daughter of a former DJ, she sharpened her mixing from 2023 and broke through with a HÖR stream, going on to play Tomorrowland, Awakenings and Teletech. Her sets mix hard groove, techno and trance, with nods to the 1990s." }, origin: "Bruxelles, Belgique", since: 2023, sources: ["https://paramountartists.com/artist/alycia-bezgo"] }, // Alycia Bezgo
  "amada": { slug: "amada", bio: { fr: "DJ hardcore néerlandaise née le 14 juillet 1991, Amada est originaire de Schimmert, dans le Limbourg. Elle joue sur les affiches hardcore néerlandaises, dont la Megarave organisée à la Maassilo de Rotterdam.", en: "A Dutch hardcore DJ born on 14 July 1991, Amada comes from Schimmert in Limburg. She plays Dutch hardcore line-ups, among them the Megarave held at the Maassilo in Rotterdam." }, origin: "Schimmert, Pays-Bas", sources: ["https://www.discogs.com/artist/3539573-Amada-3"] }, // Amada
  "amara": { slug: "amara", bio: { fr: "DJ et productrice néerlandaise de hard techno, Amara construit son son depuis plus de trois ans : partie de la schranz, elle passe par un registre industriel lourd avant d'évoluer vers quelque chose de plus rebondissant. Elle a joué à Verknipt, dont le festival 2024 à Utrecht, ainsi qu'à Nachtwacht, Dagcollege et Teletech.", en: "Dutch hard techno DJ and producer Amara has been shaping her sound for more than three years: she started in schranz, moved through heavy industrial territory and is now heading somewhere bouncier. She has played Verknipt, including the 2024 festival in Utrecht, as well as Nachtwacht, Dagcollege and Teletech." }, origin: "Pays-Bas", sources: ["https://soundcloud.com/verknipt-events/amara-verknipt-festival-2024-day-1", "https://ra.co/events/1724305"] }, // Amara
  "amber-broos": { slug: "amber-broos", bio: { fr: "Amber Broos, née le 16 octobre 2002 à Louvain, est une DJ et productrice belge, d'abord connue sous le nom DJ 13 amps. Elle a remporté à treize ans un concours qui lui a valu d'être parrainée par Robert Abigail. Elle a joué sur la mainstage de Tomorrowland, tient une émission mensuelle sur One World Radio et a sorti « Amok » sur Tomorrowland Music en 2023.", en: "Amber Broos, born 16 October 2002 in Leuven, is a Belgian DJ and producer, first known as DJ 13 amps. At thirteen she won a competition that led to a mentorship with Robert Abigail. She has played the Tomorrowland mainstage, hosts a monthly show on One World Radio and released 'Amok' on Tomorrowland Music in 2023." }, origin: "Louvain, Belgique", since: 2023, labels: ["Tomorrowland Music"], sources: ["https://en.wikipedia.org/wiki/Amber_Broos", "https://www.vrt.be/vrtnws/nl/2023/07/22/leuvense-amber-broos-20-is-jongste-vrouwelijke-dj-op-mainstage/"] }, // Amber Broos
  "ame": { slug: "ame", bio: { fr: "Âme est un duo allemand de house et de techno formé par Kristian Beyer et Frank Wiedemann, qui se sont rencontrés en 2000 dans le disquaire de Beyer à Karlsruhe. Leur single « Rej », paru en 2005, les fait connaître au-delà de l'Allemagne. La même année, ils fondent le label Innervisions avec Dixon.", en: "Âme are a German house and techno duo formed by Kristian Beyer and Frank Wiedemann, who met in 2000 at Beyer's record shop in Karlsruhe. Their 2005 single \"Rej\" brought them attention beyond Germany. That same year, they founded the Innervisions label with Dixon." }, origin: "Karlsruhe / Berlin, Allemagne", since: 2001, labels: ["Innervisions"], sources: ["https://en.wikipedia.org/wiki/%C3%82me", "https://www.discogs.com/artist/21735-Âme", "https://datatransmission.co/blog/what-is-innervisions/"] }, // Âme
  "amelie-lens": { slug: "amelie-lens", bio: { fr: "Amelie Lens, née le 31 mai 1990 à Vilvorde et installée à Anvers, est une DJ et productrice belge de techno. Ancienne mannequin, elle abandonne la mode en 2014 pour mixer, d'abord sous le nom de Renée, puis sort son premier EP, Exhale, en 2016 avant de signer sur Second State. Elle dirige aujourd'hui les labels Lenske et Exhale, ce dernier donnant aussi son nom à sa série d'événements.", en: "Amelie Lens, born 31 May 1990 in Vilvoorde and based in Antwerp, is a Belgian techno DJ and producer. A former model, she left fashion in 2014 to DJ, first under the name Renée, then released her first EP, Exhale, in 2016 before signing to Second State. She now runs the labels Lenske and Exhale, the latter also lending its name to her event series." }, origin: "Vilvorde / Anvers, Belgique", since: 2014, labels: ["Lenske", "Exhale", "Second State"], sources: ["https://fr.wikipedia.org/wiki/Amelie_Lens", "https://en.wikipedia.org/wiki/Amelie_Lens"] }, // Amelie Lens
  "amor": { slug: "amor", bio: { fr: "Amor est un duo français de DJs et producteurs formé par Julien Geloën (auparavant Blanc) et Darko. Le projet démarre en juin 2023 et signe chez Polydor (Universal Music France) en juillet 2025. Sa discographie tourne autour de l'afro house, avec le titre « Hasta Siempre » paru en juillet 2025, puis « Obsesion ».", en: "Amor are a French DJ and production duo made up of Julien Geloën (previously Blanc) and Darko. The project started in June 2023 and signed to Polydor (Universal Music France) in July 2025. Their catalogue centres on afro house, with \"Hasta Siempre\" released in July 2025, then \"Obsesion\"." }, origin: "France", since: 2023, labels: ["Polydor"], sources: ["https://www.sxpress.fr/artiste/amor/"] }, // Amor
  "amy-dabbs": { slug: "amy-dabbs", bio: { fr: "Amy Dabbs est une DJ et productrice née à Londres et installée à Berlin, dont les productions circulent entre house rapide, UK garage, breakbeat et jungle. Elle est résidente du club Renate à Berlin et passe régulièrement sur Rinse FM. Ses disques sortent notamment sur Aus Music, Heist, Shall Not Fade et sur son propre label Dabbs Traxx ; son EP « Green Room » paraît sur Shall Not Fade en novembre 2025.", en: "Amy Dabbs is a DJ and producer born in London and based in Berlin, whose productions move between high-energy house, UK garage, breakbeat and jungle. She is a resident at Berlin's Renate club and a regular on Rinse FM. Her records come out on Aus Music, Heist, Shall Not Fade and her own label Dabbs Traxx; her \"Green Room\" EP was released on Shall Not Fade in November 2025." }, origin: "Londres / Berlin", labels: ["Shall Not Fade", "Aus Music", "Heist", "Dabbs Traxx"], sources: ["https://shallnotfade.bandcamp.com/album/green-room-ep", "https://www.originssound.com/os-tapes/amy-dabbs-mix"] }, // Amy Dabbs
  "anais": { slug: "anais", bio: { fr: "Anaïs est une productrice et DJ de drum & bass originaire de Bristol. Ses disques sont parus sur Hospital Records, Invicta Audio et Deep In The Jungle, et sa production mêle basses lourdes et rythmiques marquées par la jungle.", en: "Anaïs is a drum & bass producer and DJ from Bristol. Her records have come out on Hospital Records, Invicta Audio and Deep In The Jungle, and her productions combine heavy basslines with jungle-influenced rhythms." }, origin: "Bristol, Royaume-Uni", labels: ["Hospital Records", "Invicta Audio", "Deep In The Jungle"], sources: ["https://www.monstercat.com/artist/anais"] }, // Anaïs
  "anders-hp": { slug: "anders-hp", bio: { fr: "Anders HP est un DJ basé à Copenhague, qui joue de la house et de la techno mélodiques et progressives, autour de 125 BPM. Il s'est produit à plusieurs reprises au Culture Box, notamment dans la Red Box, où son premier set du club a été enregistré en 2022.", en: "Anders HP is a Copenhagen-based DJ who plays melodic, progressive house and techno at around 125 BPM. He has played Culture Box several times, notably in the Red Box, where his club debut set was recorded in 2022." }, origin: "Copenhague, Danemark", sources: ["https://soundcloud.com/anders_hp", "https://soundcloud.com/anders_hp/culture-box-debut-1"] }, // Anders HP
  "andre-visior": { slug: "andre-visior", bio: { fr: "Andre Visior est un DJ et producteur de trance allemand. Sa discographie, publiée notamment sur Always Alive Recordings, Kontor Records et Breeze Records, relève de la trance, de la hard trance et de la trance progressive.", en: "Andre Visior is a German trance DJ and producer. His discography, released notably on Always Alive Recordings, Kontor Records and Breeze Records, sits in trance, hard trance and progressive trance." }, origin: "Allemagne", labels: ["Always Alive Recordings", "Kontor Records"], sources: ["https://api.discogs.com/database/search?artist=Andre+Visior&type=release"] }, // Andre Visior
  "andres-campo": { slug: "andres-campo", bio: { fr: "Andrés Campo est un DJ et producteur espagnol originaire de Huesca, en Aragon. Il joue de la techno, de la tech house et de la minimal techno, et a commencé comme résident de petits clubs de sa ville natale avant de tourner dans toute l'Espagne. Il a cofondé en 2019 le label EI8HT avec le Britannique Eats Everything, orienté vers une techno de groove plutôt que de martèlement. Il est aussi à l'origine du Raspafestival, à Huesca, et de Global Music, lancé à Saragosse en 2010.", en: "Andrés Campo is a Spanish DJ and producer from Huesca, in Aragon. He plays techno, tech house and minimal techno, and started out as a resident in small clubs in his home town before touring across Spain. In 2019 he co-founded the EI8HT label with Britain's Eats Everything, aimed at groove-led techno rather than relentless hammering. He is also behind the Raspafestival in Huesca and Global Music, launched in Zaragoza in 2010." }, origin: "Huesca, Espagne", labels: ["EI8HT"], sources: ["https://fanmusicfest.com/content/andres-campo", "https://www.magneticmag.com/2019/03/eats-everything-andres-campo-launch-new-label-ei8ht/"] }, // Andrés Campo
  "andy-c": { slug: "andy-c", bio: { fr: "Andy C est le nom de scène d'Andrew Michael Clarke, DJ et producteur anglais né en 1976 à Walsall. Il a cofondé RAM Records, label de drum and bass. Son premier succès arrive en 1993 avec « Valley of the Shadows », signé Origin Unknown, le duo qu'il formait avec Ant Miles ; en 2001, « Body Rock », avec Shimon, atteint la 28e place du classement des singles britanniques. RAM a depuis signé Chase & Status, Loadstar, Sub Focus et Wilkinson.", en: "Andy C is the stage name of Andrew Michael Clarke, an English DJ and record producer born in 1976 in Walsall. He co-founded the drum and bass label RAM Records. His first success came in 1993 with \"Valley of the Shadows\", released as Origin Unknown, his duo with Ant Miles; in 2001 \"Body Rock\", with Shimon, reached number 28 on the UK Singles Chart. RAM has since signed Chase & Status, Loadstar, Sub Focus and Wilkinson." }, origin: "Walsall, Angleterre", since: 1991, labels: ["RAM Records"], sources: ["https://en.wikipedia.org/wiki/Andy_C"] }, // Andy C
  "anetha": { slug: "anetha", bio: { fr: "Anetha est une DJ et productrice française née en 1989 à Bordeaux et installée à Paris. Passée par des études d'architecture et initiée aux platines à seize ans, elle défend une techno acide et hypnotique dont « Acid Train » (2017) reste le morceau signature. Elle a fondé en 2019 le label et collectif Mama Told Ya, et a mixé à la cérémonie de clôture des Jeux paralympiques de Paris en 2024.", en: "Anetha is a French DJ and producer born in Bordeaux in 1989 and based in Paris. Trained as an architect and behind the decks since she was sixteen, she plays acid-leaning, hypnotic techno, with \"Acid Train\" (2017) still her signature track. She founded the label and collective Mama Told Ya in 2019, and played the closing ceremony of the 2024 Paris Paralympic Games." }, origin: "Bordeaux, France", since: 2013, labels: ["Mama Told Ya"], sources: ["https://fr.wikipedia.org/wiki/Anetha"] }, // Anetha
  "angerfist": { slug: "angerfist", bio: { fr: "Angerfist, de son vrai nom Danny Masseling, né le 20 juin 1981 à Almere, est un producteur et DJ néerlandais de hardcore. Il publie son premier EP, Criminally Insane, en 2002, puis son premier album, Pissin' Razorbladez, en 2006. Il se produit derrière un masque de hockey blanc, accompagné sur scène par MC Prozac depuis 2006.", en: "Angerfist, real name Danny Masseling, born 20 June 1981 in Almere, is a Dutch hardcore producer and DJ. He released his first EP, Criminally Insane, in 2002, followed by his first album, Pissin' Razorbladez, in 2006. He performs behind a white hockey mask, joined on stage by MC Prozac since 2006." }, origin: "Almere, Pays-Bas", since: 2002, labels: ["Masters of Hardcore"], sources: ["https://fr.wikipedia.org/wiki/Angerfist", "https://en.wikipedia.org/wiki/Angerfist"] }, // Angerfist
  "anika-kunst": { slug: "anika-kunst", bio: { fr: "Anika Kunst est une DJ et productrice espagnole originaire de Grenade, active depuis plus de vingt ans et connue pour ses sets en vinyle entre techno et house. Elle a fondé le label Chapter Records en 2014 et publié des disques sur RSPX (Rekids) et Symbolism, le label de Ben Sims. Elle est résidente de la soirée The Pharm au Pacha Ibiza et anime la soirée Technológica au club Macarena de Barcelone.", en: "Anika Kunst is a Spanish DJ and producer from Granada, active for over twenty years and known for vinyl sets moving between techno and house. She founded the label Chapter Records in 2014 and has released on RSPX (Rekids) and on Symbolism, Ben Sims' label. She is a resident of The Pharm at Pacha Ibiza and runs the Technológica night at Barcelona's Macarena club." }, origin: "Grenade, Espagne", since: 2014, labels: ["Chapter Records"], sources: ["https://hoer.live/artist/anika-kunst-2/"] }, // Anika Kunst
  "anime": { slug: "anime", bio: { fr: "AniMe est le nom de scène de Barbara Palermo, DJ et productrice italienne née à Plaisance, spécialisée dans le hardcore. Elle apprend à mixer à dix-sept ans sous le nom DJ Eklipze et forme le duo Radioactive avant d'être repérée par Luca Pretolesi, qui la fait entrer sur le D-Boy Black Label. Signée chez Traxtorm Records en 2007, elle y sort l'EP « Detonate » en 2010. Elle a publié quatre albums et lancé son label Absolute Records en 2025.", en: "AniMe is the stage name of Barbara Palermo, an Italian DJ and producer born in Piacenza who specialises in hardcore. She learned to DJ at seventeen under the name DJ Eklipze and formed the duo Radioactive before being spotted by Luca Pretolesi, who brought her onto the D-Boy Black Label. She joined Traxtorm Records in 2007 and released the \"Detonate\" EP there in 2010. She has put out four albums and launched her own label, Absolute Records, in 2025." }, origin: "Plaisance, Italie", since: 1998, labels: ["Traxtorm Records", "Absolute Records"], sources: ["https://en.wikipedia.org/wiki/DJ_AniMe"] }, // AniMe
  "anish-kumar": { slug: "anish-kumar", bio: { fr: "Anish Kumar est un producteur britannique originaire de Washington, près de Sunderland, et basé à Cambridge. Sa house mêle breakbeats, northern soul et échantillons de cinéma bollywoodien. « Blackpool Boulevard », signé en 2021 avec Barry Can't Swim sur Technicolor (Ninja Tune), lui vaut le soutien de BBC Radio 1 ; son premier EP, Postcards, sort en 2022.", en: "Anish Kumar is a British producer from Washington, near Sunderland, now based in Cambridge. His house draws on breakbeats, northern soul and Bollywood film samples. 'Blackpool Boulevard', made with Barry Can't Swim for Ninja Tune's Technicolor imprint in 2021, brought BBC Radio 1 support; his first EP, Postcards, followed in 2022." }, origin: "Sunderland, Royaume-Uni", since: 2021, labels: ["Ninja Tune"], sources: ["https://www.juno.co.uk/junodaily/2022/12/07/anish-kumar-interview-it-cant-sound-like-it-was-obviously-made-in-a-computer/", "https://ninjatune.net/release/anish-kumar-x-barry-cant-swim/blackpool-boulevard"] }, // Anish Kumar
  "anna": { slug: "anna", bio: { fr: "Ana Miranda, née en 1985 à Amparo au Brésil, apprend le mix dans la boîte de nuit de son père et y joue dès ses quatorze ans. Installée en Europe à partir de 2015, elle publie sa techno hypnotique et mélodique sur Drumcode, Plus 8, Mute et Afterlife. Son morceau « Forever Ravers », signé avec Miss Kittin sur Kompakt en 2019, l'a fait connaître au-delà du circuit club.", en: "Ana Miranda, born in 1985 in Amparo, Brazil, learned to mix in her father's nightclub and was playing there by the age of fourteen. Based in Europe since 2015, she releases her hypnotic, melodic techno on Drumcode, Plus 8, Mute and Afterlife. \"Forever Ravers\", made with Miss Kittin for Kompakt in 2019, carried her name well beyond the club circuit." }, origin: "Amparo, Brésil", since: 1999, labels: ["Drumcode", "Plus 8", "Mute Records", "Afterlife"], sources: ["https://anna.dj/bio", "https://djmag.com/longreads/anna-talks-determination-meditation-and-power-her-incendiary-techno"] }, // ANNA
  "annasnel": { slug: "annasnel", bio: { fr: "DJ néerlandaise passée derrière les platines en 2024 après des années sur le dancefloor, ANNASNEL joue une house énergique, parfois teintée d'acid, où elle mêle voix accrocheuses, nappes progressives et drops appuyés. Elle est programmée au Smeerboel Festival d'Utrecht.", en: "A Dutch DJ who stepped behind the decks in 2024 after years on the dance floor, ANNASNEL plays energetic house with occasional acid touches, mixing catchy vocals, progressive keys and dramatic drops. She is booked for the Smeerboel Festival in Utrecht." }, origin: "Pays-Bas", since: 2024, sources: ["https://www.smeerboel.nl/line-up-stages/"] }, // ANNASNEL
  "anstandslos-durchgeknallt": { slug: "anstandslos-durchgeknallt", bio: { fr: "Anstandslos & Durchgeknallt est un duo de DJ allemand formé au printemps 2014 en Saxe, composé de Maria Dürrling et Oliver « Olli » Kleissle. Le duo s'est fait connaître par ses remixes deep house de titres pop et schlager — celui de « I Want It That Way » des Backstreet Boys dépasse les deux millions d'écoutes et leur vaut un contrat chez Sony Music. Leurs sets mêlent EDM, house allemande, hands-up et trance.", en: "Anstandslos & Durchgeknallt is a German DJ duo formed in spring 2014 in Saxony, made up of Maria Dürrling and Oliver \"Olli\" Kleissle. The pair made their name with deep house remixes of pop and schlager tracks — their take on the Backstreet Boys' \"I Want It That Way\" passed two million streams and earned them a Sony Music deal. Their sets mix EDM, German house, hands-up and trance." }, origin: "Saxe, Allemagne", since: 2014, labels: ["Sony Music"], sources: ["https://de.wikipedia.org/wiki/Anstandslos_%26_Durchgeknallt", "https://www.festival-sh.de/kuenstler/anstandslos-durchgeknallt"] }, // Anstandslos & Durchgeknallt
  "anthony-rother": { slug: "anthony-rother", bio: { fr: "Anthony Rother est un compositeur, producteur et patron de label allemand né le 29 avril 1972, installé à Offenbach-sur-le-Main. Il publie depuis la fin des années 1990 sur ses propres structures Psi49net et Datapunk, dans un registre electro et techno.", en: "Anthony Rother is a German electronic music composer, producer and label owner born on 29 April 1972, based in Offenbach am Main. Since the late 1990s he has released on his own Psi49net and Datapunk imprints, in an electro and techno vein." }, origin: "Offenbach-sur-le-Main, Allemagne", since: 1997, labels: ["Psi49net", "Datapunk"], sources: ["https://en.wikipedia.org/wiki/Anthony_Rother", "https://api.discogs.com/database/search?artist=Anthony+Rother&type=release"] }, // Anthony Rother
  "anyma": { slug: "anyma", bio: { fr: "Anyma est le projet solo de Matteo Milleri, producteur né à New York et installé à Berlin, par ailleurs moitié du duo Tale of Us. Il est cofondateur du label Afterlife Recordings et publie aussi chez Interscope. Sa musique relève de la techno et de la house mélodiques.", en: "Anyma is the solo project of Matteo Milleri, a producer born in New York and based in Berlin, otherwise one half of the duo Tale of Us. He is a co-founder of the Afterlife Recordings label and also releases on Interscope. His music sits in melodic techno and melodic house." }, origin: "New York, États-Unis / Berlin", since: 2011, labels: ["Afterlife Recordings", "Interscope"], sources: ["https://en.wikipedia.org/wiki/Anyma", "https://www.discogs.com/artist/9627886-Anyma-5"] }, // Anyma
  "aphtic": { slug: "aphtic", bio: { fr: "Aphøtic, de son prénom Mathijs, est un DJ et producteur de Rotterdam. Découvrant la techno en 2018 et les raves en 2019, il travaille son mix pendant la pandémie et se fait repérer par le promoteur néerlandais Verknipt, qui le programme sur ses soirées et son festival. Son nom vient de la zone aphotique, la couche marine que la lumière n'atteint pas — une image de sa techno dure et industrielle. Parmi ses titres : « Exterminate » et « Bring The Bass ».", en: "Aphøtic, first name Mathijs, is a DJ and producer from Rotterdam. He discovered techno in 2018 and raves in 2019, worked on his mixing through the pandemic and was picked up by Dutch promoter Verknipt, who booked him for its club nights and festival. His name comes from the aphotic zone, the layer of the ocean sunlight never reaches — an image of his hard, industrial techno. His tracks include \"Exterminate\" and \"Bring The Bass\"." }, origin: "Rotterdam, Pays-Bas", since: 2021, sources: ["https://edmidentity.com/2025/03/16/aphotic-interview/", "https://mixmagnl.com/read/get-to-knwo-aphotic-artists"] }, // Aphøtic
  "apocalipse": { slug: "apocalipse", bio: { fr: "Apocalipse est un DJ et producteur français de hard industrial techno, qui a forgé son identité dans les raves parisiennes. Il joue un son lourd et rapide, sombre et sans compromis. Il a fondé les collectifs La Piratech et Furi Techno, et joue régulièrement au Warehouse de Nantes, au Rex Club, au Nexus et au CO2, aux côtés d'artistes comme I Hate Models, Nico Moreno ou Basswell.", en: "Apocalipse is a French hard industrial techno DJ and producer who forged his identity in the Paris rave scene. He plays a heavy, fast, dark and uncompromising sound. He founded the La Piratech and Furi Techno collectives, and plays regularly at Warehouse in Nantes, Rex Club, Nexus and CO2, alongside artists such as I Hate Models, Nico Moreno and Basswell." }, origin: "Paris, France", sources: ["https://www.warehouse-nantes.fr/artist/lossa"] }, // Apocalipse
  "apparat": { slug: "apparat", bio: { fr: "Apparat est le nom de scène de Sascha Ring, musicien électronique allemand né le 27 juin 1978 à Quedlinburg. Ancien copropriétaire du label Shitkatapult, il a commencé par une techno de dancefloor avant de se tourner vers des formes ambient et un travail centré sur le design sonore plutôt que sur le rythme. Il forme aussi le duo Moderat avec Modeselektor.", en: "Apparat is the stage name of Sascha Ring, a German electronic musician born on 27 June 1978 in Quedlinburg. Formerly co-owner of the Shitkatapult label, he started out with dancefloor-oriented techno before shifting towards ambient work, more interested in designing sounds than beats. He also records as Moderat together with Modeselektor." }, origin: "Quedlinburg, Allemagne", labels: ["Shitkatapult", "Mute"], sources: ["https://en.wikipedia.org/wiki/Apparat_(musician)", "https://musicbrainz.org/ws/2/artist/?query=artist:Apparat&fmt=json"] }, // Apparat
  "ar-gang": { slug: "ar-gang", bio: { fr: "AR Gang est le collectif du label hardstyle néerlandais Aggressive Records, né en 2016 du morceau « Aggressive Acts » de Rooler et Malice. Il réunit sept artistes — Rooler, Sickmode, Malice, Riot Shift, Krowdexx, Mish et Levenkhan — qui tournent ensemble sous ce nom, notamment pour The AR Gang Show, produit avec Musical Madness à la Mitsubishi Electric Halle de Düsseldorf.", en: "AR Gang is the artist collective of the Dutch hardstyle label Aggressive Records, which grew out of the 2016 track \"Aggressive Acts\" by Rooler and Malice. It brings together seven artists — Rooler, Sickmode, Malice, Riot Shift, Krowdexx, Mish and Levenkhan — who tour together under the name, notably for The AR Gang Show, staged with Musical Madness at Düsseldorf's Mitsubishi Electric Halle." }, since: 2016, labels: ["Aggressive Records"], sources: ["https://hardstyle.com/en/news/ar-gang-the-party-lineup-musical-madness", "https://ar-gang.de/"] }, // AR Gang
  "argy": { slug: "argy", bio: { fr: "Argy est le nom de scène d'Argyris Theofilis, DJ et producteur né à Rhodes, en Grèce, et installé à Londres après un passage par Berlin. Il a été résident du Panorama Bar et a publié sur Crosstown Rebels, Cocoon, Desolat, Poker Flat et Cuttin' Headz, avec des collaborations signées Kerri Chandler et Manuel Göttsching.", en: "Argy is the stage name of Argyris Theofilis, a DJ and producer born on Rhodes, Greece, and based in London after a spell in Berlin. He held a residency at Panorama Bar and has released on Crosstown Rebels, Cocoon, Desolat, Poker Flat and Cuttin' Headz, with collaborations alongside Kerri Chandler and Manuel Göttsching." }, origin: "Rhodes, Grèce", sources: ["https://grayarea.co/artists/argy", "https://xceed.me/blog/en/interview-with-argy/"] }, // Argy
  "armand-van-helden": { slug: "armand-van-helden", bio: { fr: "Armand van Helden est un DJ, producteur et remixeur américain né le 16 février 1970 et originaire de Boston. Il sort ses premiers disques au début des années 1990 sur AV8, Nervous et Strictly Rhythm, et son remix de « Professional Widow » de Tori Amos puis « You Don't Know Me » l'installent dans la house des années 1990. Il forme ensuite le duo Duck Sauce avec A-Trak.", en: "Armand van Helden is an American DJ, producer and remixer born on 16 February 1970 and originally from Boston. He released his first records in the early 1990s on AV8, Nervous and Strictly Rhythm, and his remix of Tori Amos's \"Professional Widow\" and then \"You Don't Know Me\" established him in 1990s house music. He later formed the duo Duck Sauce with A-Trak." }, origin: "Boston, États-Unis", since: 1990, sources: ["https://en.wikipedia.org/wiki/Armand_van_Helden", "https://www.discogs.com/artist/3352-Armand-Van-Helden"] }, // Armand van Helden
  "armin-van-buuren": { slug: "armin-van-buuren", bio: { fr: "Armin van Buuren est un DJ et producteur néerlandais né en 1976 à Leyde, figure de la trance. Il a commencé à mixer au Club Nexus en 1996, en parallèle de ses études de droit à l'université de Leyde. Son émission « A State of Trance », lancée en mars 2001, est diffusée dans 84 pays. Il a fondé le label indépendant Armada Music, a été élu numéro un du Top 100 DJs de DJ Mag à cinq reprises entre 2007 et 2012, et a été fait officier de l'ordre d'Orange-Nassau en 2011.", en: "Armin van Buuren is a Dutch DJ and producer born in Leiden in 1976, a central figure in trance. He started DJing at Club Nexus in 1996 while studying law at Leiden University. His radio show \"A State of Trance\", launched in March 2001, is broadcast in 84 countries. He founded the independent label Armada Music, topped DJ Mag's Top 100 DJs poll five times between 2007 and 2012, and was appointed Officer of the Order of Orange-Nassau in 2011." }, origin: "Leyde, Pays-Bas", since: 1996, labels: ["Armada Music"], sources: ["https://en.wikipedia.org/wiki/Armin_van_Buuren"] }, // Armin van Buuren
  "artbat": { slug: "artbat", bio: { fr: "ARTBAT est un duo ukrainien de DJ et producteurs de Kyiv, formé par Artur Kryvenko et Vitaliy « Batish » Limarenko. Ils se rencontrent en 2014 dans un club et percent trois mois plus tard avec « Mandrake », soutenu par Richie Hawtin. Ils ont publié les EP Planeta et Upperground sur Diynamic Music et ont été élus Stars of the Year par Mixmag en 2019.", en: "ARTBAT is a Ukrainian DJ and producer duo from Kyiv made up of Artur Kryvenko and Vitaliy 'Batish' Limarenko. They met in a club in 2014 and broke through three months later with 'Mandrake', championed by Richie Hawtin. They released the Planeta and Upperground EPs on Diynamic Music and were named Mixmag Stars of the Year in 2019." }, origin: "Kyiv, Ukraine", since: 2014, labels: ["Diynamic Music"], sources: ["https://en.wikipedia.org/wiki/Artbat", "https://www.globalbrandsmagazine.com/who-is-artbat-meet-arthur-and-bash-the-ukrainian-electronic-music-duo/"] }, // ARTBAT
  "audrey-danza": { slug: "audrey-danza", bio: { fr: "Audrey Danza est une DJ, productrice et curatrice suisse, à la tête du label Proxima et résidente du Motel Campo à Genève. Son premier EP, Flora Formulas, pose une approche fondée sur la narration et l'exploration sonore. Elle a joué au Panorama Bar, au Robert Johnson, à Fabric et à Circoloco, ainsi qu'aux Nuits sonores et à Pitch Music & Arts.", en: "Audrey Danza is a Swiss DJ, producer and curator, head of the Proxima label and a resident at Motel Campo in Geneva. Her debut EP, Flora Formulas, set out an approach built on storytelling and sonic exploration. She has played Panorama Bar, Robert Johnson, Fabric and Circoloco, as well as Nuits sonores and Pitch Music & Arts." }, origin: "Genève, Suisse", labels: ["Proxima"], sources: ["https://www.omni-artists.co.uk/artists/audrey-danza", "https://musicbrainz.org/artist/18f31cd0-631d-47a7-82b8-23488bececf6"] }, // Audrey Danza
  "aurora-halal": { slug: "aurora-halal", bio: { fr: "Productrice et DJ new-yorkaise, Aurora Halal a créé la série de soirées Mutual Dreaming à Brooklyn puis le festival Sustain-Release dans l'État de New York. Elle sort sous son nom depuis 2014, après deux albums au sein du duo Innergaze, et joue une techno psychédélique en live hardware comme en DJ set. Elle est résidente du club Nowadays à New York et a été résidente de De School à Amsterdam.", en: "New York producer and DJ Aurora Halal created the Mutual Dreaming party series in Brooklyn and the Sustain-Release festival in upstate New York. She has released under her own name since 2014, after two albums as half of the duo Innergaze, and plays psychedelic techno in both hardware live and DJ sets. She is a resident at New York's Nowadays and was previously a resident at Amsterdam's De School." }, origin: "New York, États-Unis", since: 2014, labels: ["Mutual Dreaming Recordings"], sources: ["https://montreal.mutek.org/en/artists/aurora-halal", "https://nowadays.nyc/resident/aurora-halal/"] }, // Aurora Halal
  "autechre": { slug: "autechre", bio: { fr: "Autechre est un duo anglais de musique électronique formé en 1987 à Rochdale, près de Manchester, par Rob Brown et Sean Booth. Tous leurs albums paraissent chez Warp Records, à commencer par Incunabula en 1993, après leur apparition sur la compilation Artificial Intelligence en 1992. Partis d'une techno mélodique influencée par l'électro et le hip-hop des années 1980, ils ont évolué vers des compositions abstraites souvent rattachées à l'IDM.", en: "Autechre are an English electronic duo formed in 1987 in Rochdale, near Manchester, by Rob Brown and Sean Booth. All their albums have appeared on Warp Records, starting with Incunabula in 1993, after their appearance on the 1992 compilation Artificial Intelligence. Starting from melodic techno shaped by 1980s electro and hip-hop, they moved towards abstract compositions often filed under IDM." }, origin: "Rochdale, Angleterre", since: 1987, labels: ["Warp Records"], sources: ["https://en.wikipedia.org/wiki/Autechre"] }, // Autechre
  "avalon": { slug: "avalon", bio: { fr: "Leon Faridi, alias Avalon, est un producteur et DJ psytrance londonien. D'abord organisateur de warehouse parties et de free parties en plein air au Royaume-Uni, il commence à mixer en 2003, produit à partir de 2006 au sein du duo Reality Grid avec E.V.P., puis se consacre à son projet solo. Signé chez Nano Records après l'EP « Avalanche » en 2009, il sort son premier album « Distant Futures » en 2010 et mène en parallèle le projet Killerwatts avec Tristan.", en: "Leon Faridi, aka Avalon, is a London psytrance producer and DJ. First a promoter of warehouse and outdoor parties in the UK, he started DJing in 2003, began producing in 2006 in the duo Reality Grid with E.V.P., then focused on his solo project. Signed to Nano Records after the 2009 EP \"Avalanche\", he released his first album \"Distant Futures\" in 2010 and also runs the Killerwatts project with Tristan." }, origin: "Londres, Royaume-Uni", since: 2003, labels: ["Nano Records"], sources: ["https://nanomusic.net/artist/avalon/", "https://psymedia.co.za/avalon-uk-nano-interview/"] }, // Avalon
  "axmo": { slug: "axmo", bio: { fr: "AXMO est un duo de musique électronique lancé en 2020, dont le son reprend les codes de la dance des années 2000 : electro house, hands-up, happy hardcore et hardstyle. Le duo a signé des collaborations avec W&W et s'est produit à Parookaville, Airbeat One et Creamfields China.", en: "AXMO is an electronic duo launched in 2020, whose sound revisits the codes of 2000s dance music: electro house, hands-up, happy hardcore and hardstyle. The pair have collaborated with W&W and played Parookaville, Airbeat One and Creamfields China." }, since: 2020, sources: ["https://www.beatport.com/artist/axmo/770975/releases", "https://www.viberate.com/artist/axmo/"] }, // Axmo
  "axwell": { slug: "axwell", bio: { fr: "Axwell est le nom de scène d'Axel Christofer Hedfors, DJ, producteur et remixeur suédois né le 18 décembre 1977. Il dirige le label Axtone Records et forme, avec Steve Angello et Sebastian Ingrosso, le trio Swedish House Mafia.", en: "Axwell is the stage name of Axel Christofer Hedfors, a Swedish DJ, producer and remixer born on 18 December 1977. He runs the Axtone Records label and, with Steve Angello and Sebastian Ingrosso, makes up the trio Swedish House Mafia." }, origin: "Lund, Suède", labels: ["Axtone Records"], sources: ["https://en.wikipedia.org/wiki/Axwell", "https://en.wikipedia.org/wiki/Swedish_House_Mafia"] }, // Axwell
  "ayah-marar": { slug: "ayah-marar", bio: { fr: "Née Laura Ayah Marar à Amman d'un père jordanien et d'une mère tchéco-bulgare, Ayah Marar a grandi en Jordanie avant de s'installer au Royaume-Uni à dix-huit ans. Chanteuse, autrice et patronne de label, elle publie depuis 2003 sur des structures drum & bass, dubstep et house comme Breakbeat Kaos, Ministry of Sound et son propre label Hussle Girl.", en: "Born Laura Ayah Marar in Amman to a Jordanian father and a Czech-Bulgarian mother, Ayah Marar grew up in Jordan before moving to the UK at eighteen. A singer, songwriter and label owner, she has released since 2003 on drum & bass, dubstep and house imprints including Breakbeat Kaos, Ministry of Sound and her own Hussle Girl." }, origin: "Amman, Jordanie", labels: ["Hussle Girl"], sources: ["https://www.discogs.com/artist/2376385-Ayah-Marar", "https://ayahmarar.co.uk/"] }, // Ayah Marar
  "azuur": { slug: "azuur", bio: { fr: "Azuur est une DJ et productrice française de hard techno, basée à Paris. Elle joue des sets bruts et rapides, aux kicks incisifs, dans une veine de techno industrielle rehaussée de mélodies. Elle a signé l'EP « Fearless » avec Lady Maru.", en: "Azuur is a French hard techno DJ and producer based in Paris. She plays raw, fast sets with incisive kicks, in an industrial techno vein lifted by melodies. She released the EP \"Fearless\" with Lady Maru." }, origin: "Paris, France", sources: ["https://www.warehouse-nantes.fr/artist/azuur", "https://soundcloud.com/azuur-music"] }, // Azuur
  "azyr": { slug: "azyr", bio: { fr: "Azyr est le nom de scène d'Oliver Rowley, DJ, producteur et patron de label né à Blackpool, dans le nord-ouest de l'Angleterre. Il joue une hard techno rapide, rarement sous les 150 BPM, et s'est fait connaître en quatre ans, des soirées organisées avec ses amis dans sa ville natale aux grandes salles européennes. En mai 2026, Mixmag lui consacre sa couverture comme figure de la vague hard dance britannique.", en: "Azyr is the stage name of Oliver Rowley, a DJ, producer and label head born in Blackpool in north-west England. He plays fast hard techno that rarely drops below 150 BPM, and rose in four years from parties he threw with friends in his home town to large European venues. In May 2026 Mixmag put him on its cover as a figure of the UK hard dance wave." }, origin: "Blackpool, Royaume-Uni", sources: ["https://mixmag.net/feature/azyr-cover-feature-hard-techno-dj-blackpool-interview"] }, // Azyr
  "b1980": { slug: "b1980", bio: { fr: "B1980 est le projet solo du musicien belge Bert Libeert, batteur du groupe électro-rock Goose. Il adopte ce nom — son année de naissance — début 2020 avec la sortie « Zone », et publie depuis des EP de techno teintée d'EBM, d'industriel, d'electro et de kraut-wave, notamment sur Mosaique Records. Pour « Dissonance & Resonance », enregistré aux Safari Studios de Courtrai en 2022, il n'utilise qu'un synthétiseur Polivoks.", en: "B1980 is the solo project of Belgian musician Bert Libeert, drummer of the electro-rock band Goose. He took the name — his year of birth — in early 2020 with the release \"Zone\", and has since put out EPs of EBM-tinged techno drawing on industrial, electro and kraut-wave, notably on Mosaique Records. For \"Dissonance & Resonance\", recorded at Safari Studios in Kortrijk in 2022, he used only a Polivoks synthesiser." }, origin: "Belgique", since: 2020, labels: ["Mosaique Records"], sources: ["https://www.dmcworld.net/back-to-mine/back-to-mine-with-b1980/", "https://mqrotrecords.bandcamp.com/album/dissonance-resonance", "https://elgarajedefrank.es/en/interview-b1980/"] }, // B1980
  "babyschon": { slug: "babyschon", bio: { fr: "babyschön est une DJ installée à Londres, qui relie new wave, new beat, synth pop et house dans des sets tournés vers les sons percussifs. Elle anime chaque semaine l'émission Soup to Nuts sur NTS Radio.", en: "babyschön is a London-based DJ who connects new wave, new beat, synth pop and house in sets built on percussive sounds. She hosts the weekly Soup to Nuts show on NTS Radio." }, origin: "Londres, Royaume-Uni", sources: ["https://rallyrallyrally.co.uk/artist/babyschon"] }, // babyschön
  "badsista": { slug: "badsista", bio: { fr: "Rafaela Andrade, alias BADSISTA, est une DJ et productrice née et élevée à São Paulo, active dans la bass music depuis 2013. Ses sets et ses productions croisent techno, house jackin' et funk carioca. Membre fondatrice du collectif pauliste Bandida, qui met en avant productrices, graffeuses et photographes, elle publie son premier EP en 2016 sur le label Funk Na Caixa, réalise l'album « Pajubá » de Linn da Quebrada et reçoit le prix de meilleure productrice aux Women Music Awards 2018.", en: "Rafaela Andrade, known as BADSISTA, is a DJ and producer born and raised in São Paulo, active in bass music since 2013. Her sets and productions cross techno, jackin' house and funk carioca. A founding member of the São Paulo collective Bandida, which champions female producers, graffiti artists and photographers, she released her debut EP in 2016 on the Funk Na Caixa label, produced Linn da Quebrada's album \"Pajubá\" and won Best Music Producer at the 2018 Women Music Awards." }, origin: "São Paulo, Brésil", since: 2013, labels: ["Funk Na Caixa"], sources: ["https://djmag.com/features/recognise-badsista", "https://remezcla.com/features/music/badsista-bahidora-profile/", "https://crackmagazine.net/article/lists/baile-funk-in-10-tracks-by-sao-paulo-producer-badsista/"] }, // Badsista
  "barbara-butch": { slug: "barbara-butch", bio: { fr: "Barbara Butch, née Leslie Barbara Butch le 17 mars 1981, est une DJ française et militante lesbienne. Elle grandit à Paris dans une famille juive, tient d'abord un restaurant à Montpellier, puis s'installe derrière les platines des lieux queer et alternatifs parisiens : Rosa Bonheur, la Machine du Moulin Rouge, Glazart. Ses sets mêlent house, disco, funk et pop ; elle a reçu l'Out d'or 2021 de la personnalité LGBTI de l'année.", en: "Barbara Butch, born Leslie Barbara Butch on 17 March 1981, is a French DJ and lesbian activist. She grew up in Paris in a Jewish family, first ran a restaurant in Montpellier, then took up residence behind the decks of Paris's queer and alternative venues: Rosa Bonheur, La Machine du Moulin Rouge, Glazart. Her sets mix house, disco, funk and pop; she received the 2021 Out d'or award for LGBTI personality of the year." }, origin: "Paris, France", sources: ["https://fr.wikipedia.org/wiki/Leslie_Barbara_Butch", "https://www.paris.fr/pages/barbara-butch-dj-parisienne-militante-de-l-amour-19363"] }, // Barbara Butch
  "barber": { slug: "barber", bio: { fr: "Barber, de son vrai nom Jordi Blok, est un producteur et DJ néerlandais d'uptempo hardcore. Il publie sa première sortie officielle en 2017 et dirige le label Barbaric Records, consacré à ce style. Il joue sur les grandes affiches hardcore néerlandaises — Thunderdome, Defqon.1, Dominator, Decibel Outdoor, Harmony of Hardcore — et se produit aussi au sein du live Barbaric Records LIVE.", en: "Barber, real name Jordi Blok, is a Dutch uptempo hardcore producer and DJ. His first official release came out in 2017 and he runs Barbaric Records, a label devoted to the style. He plays the major Dutch hardcore bills — Thunderdome, Defqon.1, Dominator, Decibel Outdoor, Harmony of Hardcore — and also performs as part of the Barbaric Records LIVE act." }, origin: "Pays-Bas", since: 2017, labels: ["Barbaric Records"], sources: ["https://mostwanted.dj/en/artists/barber"] }, // Barber
  "bardix-le-gaulois": { slug: "bardix-le-gaulois", bio: { fr: "Bardix le Gaulois est un artiste français qui mêle instruments celtiques — flûtes, cornemuses, mélodies traditionnelles — et kicks de techno, un mélange qu'il appelle la « Gaulish Techno ». Ses performances sont scénographiées : il y incarne un barde gaulois en costume, filmé en forêt ou en pleine nature, un dispositif qui lui a construit une audience sur TikTok et en streaming. Il est représenté par l'agence Wart.", en: "Bardix le Gaulois is a French artist who mixes Celtic instruments — flutes, bagpipes, traditional melodies — with techno kicks, a blend he calls \"Gaulish Techno\". His performances are staged: he plays a Gaulish bard in period costume, filmed in forests and open landscapes, which built him an audience on TikTok and streaming. He is booked by the Wart agency." }, origin: "France", sources: ["https://wartiste.com/en/artists/bardix-le-gaulois"] }, // Bardix le Gaulois
  "bashkka": { slug: "bashkka", bio: { fr: "DJ et productrice née et installée à Munich, résidente du Blitz Club, elle croise une house et une techno rapides avec des samples vocaux kurdes et une bounce house d'inspiration chicagoane qu'elle chante elle-même. Militante trans, elle a publié son premier EP solo, Maktub, sur UMAY, le label à but non lucratif fondé par Nene H, et est représentée par l'agence de booking de Marcel Dettmann.", en: "A DJ and producer born and based in Munich and a resident at the Blitz Club, she crosses fast house and techno with Kurdish vocal samples and a Chicago-flavoured bounce house she sings herself. A trans activist, she released her first solo EP, Maktub, on UMAY, the non-profit label founded by Nene H, and is represented by Marcel Dettmann's booking agency." }, origin: "Munich, Allemagne", labels: ["UMAY"], sources: ["https://djmag.com/news/nene-h-launches-new-label-umay-bashkka-ep", "https://www.playfulmag.com/post/bashkka-not-just-a-hype"] }, // BASHKKA
  "beau-didier": { slug: "beau-didier", bio: { fr: "Beau Didier est un DJ et producteur néerlandais basé à Amsterdam, identifié à la techno hardgroove, chargée en basses et en voix. Il a publié sur Molekül, Mutual Rytm et [SELECTED], et joué à HÖR Berlin, Awakenings et Vault Sessions. En 2020 il a cofondé la plateforme amstellodamoise Vulged, qui organise des soirées underground.", en: "Beau Didier is a Dutch DJ and producer based in Amsterdam, identified with bass-heavy, vocal-driven hardgroove techno. He has released on Molekül, Mutual Rytm and [SELECTED], and played HÖR Berlin, Awakenings and Vault Sessions. In 2020 he co-founded the Amsterdam platform Vulged, which runs underground events." }, origin: "Amsterdam, Pays-Bas", labels: ["Molekül", "Mutual Rytm", "[SELECTED]"], sources: ["https://www.awakenings.com/en/artists/beau-didier/197641/"] }, // Beau Didier
  "bedouin": { slug: "bedouin", bio: { fr: "Bedouin est un duo américain de Brooklyn formé en 2012 par Tamer Malki et Rami Abousabe. Il joue de la house, de la deep house et de la melodic house, et publie sur Crosstown Rebels, All Day I Dream, Circoloco Records et son propre label Human by Default. Le duo a signé deux Essential Mix sur BBC Radio 1, en 2016 et 2020.", en: "Bedouin are an American duo from Brooklyn formed in 2012 by Tamer Malki and Rami Abousabe. They play house, deep house and melodic house, and release on Crosstown Rebels, All Day I Dream, Circoloco Records and their own imprint Human by Default. The duo recorded two BBC Radio 1 Essential Mixes, in 2016 and 2020." }, origin: "Brooklyn, États-Unis", since: 2012, labels: ["Human by Default", "Crosstown Rebels", "All Day I Dream"], sources: ["https://en.wikipedia.org/wiki/Bedouin_(DJs)"] }, // Bedouin
  "bella-claxton": { slug: "bella-claxton", bio: { fr: "Bella Claxton est une DJ australienne originaire de Melbourne, installée à Amsterdam. Ses sets, construits sur la durée plutôt que sur les ruptures, puisent dans la hard house, la trance, la psytrance et la techno rapide. Elle a fondé le label Cadence Records, dont le nom renvoie au nombre de pas par minute, et joue sur les scènes européennes après avoir percé dans les festivals australiens.", en: "Bella Claxton is an Australian DJ from Melbourne, based in Amsterdam. Her sets, built on duration rather than on drops, draw on hard house, trance, psytrance and fast techno. She founded the label Cadence Records, whose name refers to steps per minute, and now plays the European circuit after breaking through on Australian festival stages." }, origin: "Melbourne, Australie", labels: ["Cadence Records"], sources: ["https://www.pukkelpop.be/en/bands/bella-claxton", "https://mixmagnl.com/read/bella-claxton-built-with-cadence-artists"] }, // Bella Claxton
  "bellaire": { slug: "bellaire", bio: { fr: "Bellaire est un producteur français de house et de disco né en 1998. Ses disques paraissent sur AOC Records, entre house, deep house et sonorités disco.", en: "Bellaire is a French house and disco producer born in 1998. His records come out on AOC Records, between house, deep house and disco." }, origin: "France", labels: ["AOC Records"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Bellaire&fmt=json", "https://api.discogs.com/database/search?artist=Bellaire&type=release"] }, // Bellaire
  "ben-hemsley": { slug: "ben-hemsley", bio: { fr: "Ben Hemsley est un DJ et producteur britannique né le 6 juin 1996 à Newcastle upon Tyne. Sa musique croise house, rave et trance ; il a publié sur Ministry of Sound avant de lancer son propre label, bebé. Il a reçu le prix du meilleur producteur décerné par DJ Mag en 2023.", en: "Ben Hemsley is a British DJ and producer born on 6 June 1996 in Newcastle upon Tyne. His music crosses house, rave and trance; he released on Ministry of Sound before launching his own label, bebé. He won DJ Mag's Best Producer award in 2023." }, origin: "Newcastle upon Tyne, Royaume-Uni", since: 2019, labels: ["Ministry of Sound", "bebé"], sources: ["https://en.wikipedia.org/wiki/Ben_Hemsley", "https://djmag.com/features/ben-hemsley-advancing-trance-interview"] }, // Ben Hemsley
  "ben-klock": { slug: "ben-klock", bio: { fr: "Ben Klock, né en 1972 à Berlin-Ouest, est un DJ et producteur allemand de techno. Pianiste dans l'enfance, il sort son premier disque, Clockworks EP, en 1998 sur Sonar Kollektiv, puis devient résident du Berghain peu après l'ouverture du club en 2004. Il fonde le label Klockworks en 2006 et publie son album One sur Ostgut Ton en 2009.", en: "Ben Klock, born in 1972 in West Berlin, is a German techno DJ and producer. A pianist as a child, he released his first record, Clockworks EP, on Sonar Kollektiv in 1998, then became a resident at Berghain shortly after the club opened in 2004. He founded the Klockworks label in 2006 and released his album One on Ostgut Ton in 2009." }, origin: "Berlin, Allemagne", since: 1998, labels: ["Klockworks", "Ostgut Ton"], sources: ["https://fr.wikipedia.org/wiki/Ben_Klock", "https://en.wikipedia.org/wiki/Ben_Klock"] }, // Ben Klock
  "ben-sims": { slug: "ben-sims", bio: { fr: "Ben Sims, de son vrai nom Ben Stocker, est un DJ et producteur de techno britannique installé à Londres. Il a fondé les labels Theory Recordings, Hardgroove, Machine, Ingoma et Symbolism, et copilote le studio Hardgroove Mastering avec Paul Mac. Ses disques sont parus chez Tresor, Drumcode, Mosaic, Bass Culture et CLR, et il a signé des remixes pour Jeff Mills, Robert Hood, Kevin Saunderson, Carl Cox et Adam Beyer.", en: "Ben Sims, real name Ben Stocker, is a British techno DJ and producer based in London. He founded the labels Theory Recordings, Hardgroove, Machine, Ingoma and Symbolism, and co-runs the Hardgroove Mastering studio with Paul Mac. His records have appeared on Tresor, Drumcode, Mosaic, Bass Culture and CLR, and he has remixed Jeff Mills, Robert Hood, Kevin Saunderson, Carl Cox and Adam Beyer." }, origin: "Londres, Royaume-Uni", labels: ["Theory Recordings", "Hardgroove", "Symbolism", "Ingoma"], sources: ["https://bensims.bandcamp.com/", "https://www.discogs.com/artist/3947"] }, // Ben Sims
  "benga": { slug: "benga", bio: { fr: "Benga est le nom de scène d'Adegbenga Otomayomi Adejumo, musicien britannique né le 1er septembre 1986 à Croydon. Il compte parmi les producteurs qui ont fondé le dubstep, et figure sur des compilations comme Warrior Dubz de Mary Anne Hobbs et The Roots of Dubstep de Tempa. Il forme avec Skream et Artwork le trio Magnetic Man.", en: "Benga is the stage name of Adegbenga Otomayomi Adejumo, a British musician born on 1 September 1986 in Croydon. He is one of the producers who founded dubstep, and appears on compilations such as Mary Anne Hobbs's Warrior Dubz and Tempa's The Roots of Dubstep. With Skream and Artwork he makes up the trio Magnetic Man." }, origin: "Croydon, Londres, Royaume-Uni", sources: ["https://en.wikipedia.org/wiki/Benga_(musician)", "https://en.wikipedia.org/wiki/Magnetic_Man"] }, // Benga
  "benny-rodrigues": { slug: "benny-rodrigues", bio: { fr: "Benny Rodrigues est un DJ et producteur néerlandais né à Rotterdam en 1982, d'origine portugaise. Sous son propre nom il joue de la house et de la tech house ; depuis 2011 il utilise le pseudonyme ROD pour ses productions techno, décrites comme profondes et répétitives, entre Detroit, Berlin, acid et dub. Son EP « Malmok » est sorti sur Klockworks, le label de Ben Klock, et il a ensuite publié sur CLR, M_nus et Drumcode. Il est connu pour ses sets marathon, notamment au Berghain et au Trouw.", en: "Benny Rodrigues is a Dutch DJ and producer born in Rotterdam in 1982, of Portuguese descent. Under his own name he plays house and tech house; since 2011 he has used the alias ROD for his techno productions, described as deep and repetitive, drawing on Detroit, Berlin, acid and dub. His \"Malmok\" EP came out on Ben Klock's Klockworks label, and he has since released on CLR, M_nus and Drumcode. He is known for marathon sets, notably at Berghain and Trouw." }, origin: "Rotterdam, Pays-Bas", since: 2011, labels: ["Klockworks", "Drumcode"], sources: ["https://nl.wikipedia.org/wiki/Benny_Rodrigues"] }, // Benny Rodrigues
  "bery": { slug: "bery", bio: { fr: "BØĘRY, de son vrai nom Bram Steermann, est un DJ néerlandais de hard techno, batteur dans un groupe avant de venir à la musique électronique. Il fait ses débuts début 2024 à l'Area050 de Groningue et s'est fait connaître par ses sets mêlant techno industrielle et bochka, dont plusieurs All Night Long au Now&Wow, à la Graanfabriek et au Club Basis.", en: "BOERY, real name Bram Steermann, is a Dutch hard techno DJ who played drums in a band before turning to electronic music. He made his DJ debut in early 2024 at Area050 in Groningen and became known for sets mixing industrial techno and bochka, including all-night-long shows at Now&Wow, Graanfabriek and Club Basis." }, origin: "Groningue, Pays-Bas", since: 2024, sources: ["https://partyflock.nl/artist/159515/biography", "https://www.djguide.nl/djinfo.p?djid=9985&language=en"] }, // BØĘRY
  "biianco": { slug: "biianco", bio: { fr: "BIIANCO est un projet de production et de DJing né à New York, passé par Los Angeles et aujourd'hui basé à Londres, mené par un·e multi-instrumentiste qui utilise le pronom « they ». Le son tourne entre 140 et 150 BPM : acid, trance et techno mâtinés de house et de pop, en partie joués en direct aux claviers et aux percussions. Sur Ultra Records est paru le single « Get You Out » en 2024, après des collaborations avec Marlon Hoffstadt. BIIANCO se revendique queer, neurodivergent·e et handicapé·e, et milite pour l'inclusion dans l'industrie musicale.", en: "BIIANCO is a producer, DJ and multi-instrumentalist born in New York, trained in Los Angeles and now based in London. They play acid, trance and techno laced with house and pop at 140–150 BPM, performing part of it live on keys and percussion. Signed to Ultra Records, they released the single \"Get You Out\" there in 2024 and have collaborated with Marlon Hoffstadt. A queer, neurodivergent and disabled artist, they campaign for inclusion in the music industry." }, origin: "New York, États-Unis", since: 2019, labels: ["Ultra Records"], sources: ["https://djmag.com/features/studio-biianco"] }, // Biianco
  "bitter-babe": { slug: "bitter-babe", bio: { fr: "Laura Solarte, alias Bitter Babe, est une DJ et productrice colombienne originaire de Bogotá et installée à Berlin. Ses sets enchaînent raptor house, breakbeat, techno, guaracha et dembow. Elle a publié l'EP « Fuego Clandestino » avec Nick León sur le label colombien TraTraTrax.", en: "Laura Solarte, who performs as Bitter Babe, is a Colombian DJ and producer from Bogotá, based in Berlin. Her sets run through raptor house, breakbeat, techno, guaracha and dembow. She released the EP \"Fuego Clandestino\" with Nick León on the Colombian label TraTraTrax." }, origin: "Bogotá, Colombie", sources: ["https://crackmagazine.net/article/profiles/bitter-babe-interview-speed-of-life/", "https://tratratrax.bandcamp.com/album/fuego-clandestino"] }, // Bitter Babe
  "bizzey": { slug: "bizzey", bio: { fr: "Bizzey est le nom de scène de Leo Roelandschap, rappeur, MC, DJ et producteur néerlandais né le 11 mai 1989 à Amersfoort. En 2010 il fonde avec Jim Aasgier et Nizzle le groupe Yellow Claw, qu'il quitte en 2016 pour mener une carrière solo. Ses titres « Traag », « JA! » et « Drup » ont figuré en tête du top 40 néerlandais ; sa musique croise trap, hip-hop, dancehall et musique de club.", en: "Bizzey is the stage name of Leo Roelandschap, a Dutch rapper, MC, DJ and producer born on 11 May 1989 in Amersfoort. In 2010 he founded the group Yellow Claw with Jim Aasgier and Nizzle, leaving in 2016 for a solo career. His singles \"Traag\", \"JA!\" and \"Drup\" topped the Dutch charts; his music crosses trap, hip-hop, dancehall and club music." }, origin: "Amersfoort, Pays-Bas", since: 2010, sources: ["https://en.wikipedia.org/wiki/Bizzey", "https://www.errday.nl/artiest/bizzey/"] }, // Bizzey
  "black-coffee": { slug: "black-coffee", bio: { fr: "Nkosinathi Innocent Maphumulo, connu sous le nom de Black Coffee, est un DJ, producteur et auteur-compositeur sud-africain né le 11 mars 1976 à Durban. Il joue de la house, avec un versant afro house et deep house. Il a reçu huit South African Music Awards, quatre DJ Awards, deux Metro FM Awards et un Grammy Award du meilleur album dance/électronique.", en: "Nkosinathi Innocent Maphumulo, known as Black Coffee, is a South African DJ, record producer and songwriter born on 11 March 1976 in Durban. He plays house, with an afro house and deep house strand. His accolades include eight South African Music Awards, four DJ Awards, two Metro FM Awards and a Grammy Award for Best Dance/Electronic Album." }, origin: "Durban, Afrique du Sud", sources: ["https://en.wikipedia.org/wiki/Black_Coffee_(DJ)", "https://musicbrainz.org/artist/7fa03932-cd68-498f-aa4f-d4a6a2ce6071"] }, // Black Coffee
  "blasha-allatt": { slug: "blasha-allatt", bio: { fr: "Steffi Blasha et Tasha Allatt sont deux DJ de Manchester, résidentes et cofondatrices — avec aalice et Lucy Ironmonger — des soirées Meat Free, lancées en 2013. Leurs sets circulent entre techno, house et electro ; elles ont joué à Fabric, au Berghain, au FOLD, au Radion et à Awakenings, et ont ouvert en 2022 Frixxxion, un espace queer dédié à la techno à Manchester.", en: "Steffi Blasha and Tasha Allatt are a Manchester DJ duo, residents and co-founders — with aalice and Lucy Ironmonger — of the Meat Free parties, launched in 2013. Their sets move between techno, house and electro; they have played Fabric, Berghain, FOLD, Radion and Awakenings, and in 2022 opened Frixxxion, a queer techno space in Manchester." }, origin: "Manchester, Royaume-Uni", since: 2013, labels: ["Meat Free"], sources: ["https://www.fabriclondon.com/posts/audio-introducing-meat-free-duo-blasha-allatt", "https://www.stampthewax.com/2018/09/20/blasha-allatt/"] }, // Blasha & Allatt
  "blastoyz": { slug: "blastoyz", bio: { fr: "Blastoyz est le nom de scène de Kobi Nigreker, producteur et DJ israélien de psytrance. Il est classé deux années de suite au Top 100 DJs de DJ Mag et a joué à Tomorrowland, EDC Las Vegas, Ultra et Creamfields. Ses titres « Mandala », « Parvati Valley » et « After Dark » l'ont fait connaître, et il a remixé Above & Beyond.", en: "Blastoyz is the stage name of Kobi Nigreker, an Israeli psytrance producer and DJ. He was ranked in DJ Mag's Top 100 DJs two years running and has played Tomorrowland, EDC Las Vegas, Ultra and Creamfields. His tracks \"Mandala\", \"Parvati Valley\" and \"After Dark\" made his name, and he has remixed Above & Beyond." }, origin: "Israël", sources: ["https://blastoyz.com/about/", "https://welvrave.com/artists/blastoyz/"] }, // Blastoyz
  "blawan": { slug: "blawan", bio: { fr: "Blawan est le nom de scène de Jamie Roberts, producteur et DJ anglais originaire du Yorkshire du Sud, né en 1987. Il se fait connaître avec son premier disque Fram sur Hessle Audio, puis avec « Why They Hide Their Bodies Under My Garage? » en 2012, un morceau construit sur une grosse caisse 4/4 et une voix samplée des Fugees. Son remix de « Bloom » de Radiohead figure sur TKOL RMX 1234567 (2011).", en: "Blawan is the stage name of Jamie Roberts, an English producer and DJ from South Yorkshire, born in 1987. He came to attention with his debut Fram on Hessle Audio, then with 2012's \"Why They Hide Their Bodies Under My Garage?\", built on a heavy 4/4 bass drum and a sampled Fugees vocal. His remix of Radiohead's \"Bloom\" appears on TKOL RMX 1234567 (2011)." }, origin: "Doncaster, Royaume-Uni", since: 2010, labels: ["Hessle Audio", "R&S Records"], sources: ["https://en.wikipedia.org/wiki/Blawan", "https://musicbrainz.org/artist/c27d4389-390e-497c-9a41-dd446ace742c"] }, // Blawan
  "blond-ish": { slug: "blond-ish", bio: { fr: "Blond:ish est le nom de scène de Vivie-ann Bakos, DJ et productrice canadienne née en 1988. Elle publie depuis 2008 sur Kompakt, Defected ou Get Physical, entre melodic house, afro house et deep house. Elle a fondé la série de soirées et le label Abracadabra, est résidente au Pacha Ibiza, et a lancé l'association Bye Bye Plastic contre le plastique à usage unique dans les lieux de musique.", en: "Blond:ish is the stage name of Vivie-ann Bakos, a Canadian DJ and producer born in 1988. She has released since 2008 on Kompakt, Defected and Get Physical, moving between melodic house, afro house and deep house. She founded the Abracadabra party series and label, is a Pacha Ibiza resident, and started the Bye Bye Plastic nonprofit against single-use plastic in music venues." }, origin: "Canada", since: 2008, labels: ["Kompakt", "Defected", "Get Physical Music", "Abracadabra Music"], sources: ["https://en.wikipedia.org/wiki/Blond:ish"] }, // Blond:ish
  "bloody-mary": { slug: "bloody-mary", bio: { fr: "Marjorie Migliaccio, alias Bloody Mary, est une DJ et productrice française installée à Berlin depuis 2005. Elle joue en vinyle et en live hardware, entre techno, acid et minimal, et a sorti son premier album « Black Pearl » en 2009. En 2010 elle fonde le label Dame-Music ; elle est résidente du Tresor à Berlin.", en: "Marjorie Migliaccio, known as Bloody Mary, is a French DJ and producer who has been based in Berlin since 2005. She plays vinyl DJ sets and hardware live sets spanning techno, acid and minimal, and released her debut album \"Black Pearl\" in 2009. In 2010 she founded the Dame-Music label; she is a resident at Berlin's Tresor." }, origin: "France (basée à Berlin)", since: 2009, labels: ["Dame-Music"], sources: ["https://djmag.com/longreads/bloody-mary-keeping-fire-burning", "https://partyflock.nl/en/artist/56703/biography"] }, // Bloody Mary
  "bob-sinclar": { slug: "bob-sinclar", bio: { fr: "Christophe Le Friant, né en 1969 à Paris, cofonde le label Yellow Productions au début des années 1990 et fait partie des producteurs de la French touch. Après « Gym Tonic » (1998), réalisé avec Thomas Bangalter, il enchaîne les succès house « Love Generation » (2005), « World, Hold On » et « Rock This Party » (2006). Il pilote également le collectif Africanism All Stars.", en: "Christophe Le Friant, born in Paris in 1969, co-founded the Yellow Productions label in the early 1990s and belongs to the French touch generation of producers. After \"Gym Tonic\" (1998), made with Thomas Bangalter, he lined up the house hits \"Love Generation\" (2005), \"World, Hold On\" and \"Rock This Party\" (2006). He also steers the Africanism All Stars collective." }, origin: "Paris, France", since: 1992, labels: ["Yellow Productions"], sources: ["https://fr.wikipedia.org/wiki/Bob_Sinclar"] }, // Bob Sinclar
  "bon-entendeur": { slug: "bon-entendeur", bio: { fr: "Bon Entendeur est un trio français formé en 2012, composé d'Arnaud Bonet, Pierre Della Monica et Nicolas Boisseleau. Le projet s'est fait connaître par des mixtapes qui collent des extraits de voix françaises — discours politiques, dialogues de films, interviews de Jacques Chirac ou Richard Bohringer — sur des relectures électro teintées de disco, de funk et de hip-hop. Après la mixtape « Cluzet » en 2015, le trio publie son premier album « Aller-Retour » en 2019.", en: "Bon Entendeur is a French trio formed in 2012, made up of Arnaud Bonet, Pierre Della Monica and Nicolas Boisseleau. The project made its name with mixtapes layering French voices — political speeches, film dialogue, interviews with Jacques Chirac or Richard Bohringer — over electro reworks shaded with disco, funk and hip-hop. After the 2015 mixtape \"Cluzet\", the trio released its first album \"Aller-Retour\" in 2019." }, origin: "France", since: 2012, sources: ["https://fr.wikipedia.org/wiki/Bon_Entendeur", "https://whatthefrance.org/fr/bon-entendeur-le-trio-electronique-qui-diffuse-la-culture-francaise-a-letranger/"] }, // Bon Entendeur
  "bored-bouddha": { slug: "bored-bouddha", bio: { fr: "DJ italo-russe installée à Bruxelles, Bored Bouddha joue une techno deep et minimale traversée de passages hypnotiques et mélodiques, sur des basses rapides. Elle mêle à ses sets des voix issues de ses différentes cultures. Elle se produit régulièrement au C12.", en: "An Italian-Russian DJ based in Brussels, Bored Bouddha plays deep, minimal techno shot through with hypnotic and melodic passages over fast bass. She threads vocals drawn from her different cultures into her sets. She plays regularly at C12." }, origin: "Bruxelles, Belgique", sources: ["https://c12space.com/event/c12-nite-w-sandrien-bored-bouddha-amalie-hank/"] }, // Bored Bouddha
  "boris-brejcha": { slug: "boris-brejcha", bio: { fr: "Boris Brejcha, né le 26 novembre 1981 à Ludwigshafen, est un DJ et producteur allemand. Il qualifie lui-même son style de « high-tech minimal » et se produit derrière un masque de joker inspiré du carnaval de Venise. Il a cofondé en 2015 le label Fckng Serious avec Ann Clue et Deniz Bul, et a sorti l'album Space Diver en janvier 2020.", en: "Boris Brejcha, born 26 November 1981 in Ludwigshafen, is a German DJ and producer. He calls his own style \"high-tech minimal\" and performs behind a joker mask based on a Carnival of Venice design. He co-founded the label Fckng Serious in 2015 with Ann Clue and Deniz Bul, and released the album Space Diver in January 2020." }, origin: "Ludwigshafen, Allemagne", labels: ["Fckng Serious", "Ultra Records"], sources: ["https://en.wikipedia.org/wiki/Boris_Brejcha"] }, // Boris Brejcha
  "boss-priester": { slug: "boss-priester", bio: { fr: "Boss Priester est un producteur et DJ néerlandais installé à La Haye, qui joue un mélange de minimal, de house et de techno. Ses disques sont parus sur Ba Dum Tish, Dungeon Meat, Locus et Interweaved Records, et il gère en parallèle son propre label de dubplates, BPDUBS. Son travail est relayé par Enzo Siragusa, Alec Falconer ou Dr. Banana.", en: "Boss Priester is a Dutch producer and DJ based in The Hague who plays a mix of minimal, house and techno. His records have come out on Ba Dum Tish, Dungeon Meat, Locus and Interweaved Records, and he runs his own dubplate label, BPDUBS. His work is championed by the likes of Enzo Siragusa, Alec Falconer and Dr. Banana." }, origin: "La Haye, Pays-Bas", labels: ["BPDUBS", "Locus", "Ba Dum Tish"], sources: ["https://bosspriester.bandcamp.com/", "https://events.musicofourdesire.com/artist/boss-priester"] }, // Boss Priester
  "bou": { slug: "bou", bio: { fr: "Bou est le nom de scène de Mohamed Amine Bouguenna, musicien algéro-britannique installé à Manchester. Arrivé enfant en France puis en Angleterre, il joue son premier set en 2014 à dix-sept ans et sort son premier single, « Movements » avec Dutta, sur Clawhammer Recordz en 2015. Sa drum and bass l'a mené au Top 40 britannique avec « Closer », avec Slay, puis à la 5e place avec « Baddadan », signé avec Chase & Status en 2023.", en: "Bou is the stage name of Mohamed Amine Bouguenna, an Algerian-British musician based in Manchester. He arrived as a child in France and then England, played his first set in 2014 at seventeen and released his first single, \"Movements\" with Dutta, on Clawhammer Recordz in 2015. His drum and bass took him into the UK Top 40 with \"Closer\", featuring Slay, then to No. 5 with \"Baddadan\", made with Chase & Status in 2023." }, origin: "Manchester, Royaume-Uni", since: 2014, labels: ["Island Records"], sources: ["https://en.wikipedia.org/wiki/Bou_(musician)"] }, // Bou
  "bovski": { slug: "bovski", bio: { fr: "BOVSKI est un producteur et DJ allemand, apparu en 2023 avec un masque de cagoule blanche pour signature visuelle. Il croise UK garage, house et techno : son titre « Low Again » a dépassé vingt millions d'écoutes en deux mois, et « Do It Again » est paru en février 2026 sur GOTTA MOVE, le label d'Insomniac Music Group.", en: "BOVSKI is a German producer and DJ who emerged in 2023 with a white balaclava as his visual signature. He crosses UK garage, house and techno: his track \"Low Again\" passed twenty million streams in two months, and \"Do It Again\" was released in February 2026 on GOTTA MOVE, the Insomniac Music Group label." }, origin: "Allemagne", since: 2023, labels: ["GOTTA MOVE"], sources: ["https://findyoursounds.com/bovski-releases-vocal-ukg-single-do-it-again-for-his-debut-release-on-insomniacs-gotta-move-imprint/"] }, // BOVSKI
  "bow-miller": { slug: "bow-miller", bio: { fr: "Bow Miller est un DJ danois né en 1975, actif dans la scène underground de Copenhague depuis 2012. Il défend une slow house profonde et hypnotique, notamment au sein du projet Angebot monté avec les DJ Carbalido et Backhaus. Il a joué aux côtés de Be Svendsen, Satori et Kenneth Bager, et se produit dans des clubs de Copenhague comme le kat.4.", en: "Bow Miller is a Danish DJ born in 1975, active in Copenhagen's underground scene since 2012. He plays deep, hypnotic slow house, notably as part of the Angebot project he formed with DJs Carbalido and Backhaus. He has played alongside Be Svendsen, Satori and Kenneth Bager, and appears at Copenhagen clubs such as kat.4." }, origin: "Copenhague, Danemark", since: 2012, sources: ["https://mixmag.net/read/new-nightclub-kat-4-opens-in-copenhagen-news", "https://bandcamp.com/bowmiller"] }, // Bow Miller
  "boys-noize": { slug: "boys-noize", bio: { fr: "Boys Noize est le nom de scène d'Alexander Ridha, producteur et DJ allemand né en 1982. Il fonde son label Boysnoize Records en 2005 et signe des remixes pour Daft Punk, Depeche Mode ou Snoop Dogg. Il forme le duo Dog Blood avec Skrillex et Octave Minds avec Chilly Gonzales, et a été nommé aux Grammy Awards en 2019 pour « Midnight Hour ».", en: "Boys Noize is the stage name of Alexander Ridha, a German producer and DJ born in 1982. He founded his label Boysnoize Records in 2005 and has remixed Daft Punk, Depeche Mode and Snoop Dogg. He forms the duo Dog Blood with Skrillex and Octave Minds with Chilly Gonzales, and was Grammy-nominated in 2019 for \"Midnight Hour\"." }, origin: "Hambourg, Allemagne", since: 2005, labels: ["Boysnoize Records", "Ones and Zeros"], sources: ["https://en.wikipedia.org/wiki/Boys_Noize"] }, // Boys Noize
  "bradley-zero": { slug: "bradley-zero", bio: { fr: "Originaire de Leeds et installé à Peckham depuis 2006, Bradley Zero lance l'émission de radio Rhythm Section en 2009, devenue en 2012 une soirée bimensuelle au Canavan's Peckham Pool Club puis le label Rhythm Section International. Programmateur et présentateur pour Boiler Room, il tient une émission sur NTS depuis les débuts de la station et des résidences à Londres, au Public Records de New York et au Circoloco à Ibiza.", en: "From Leeds and based in Peckham since 2006, Bradley Zero started the Rhythm Section radio show in 2009; it became a fortnightly party at Canavan's Peckham Pool Club in 2012 and then the label Rhythm Section International. A programmer and host for Boiler Room, he has held a slot on NTS since the station's founding and residencies in London, at Public Records in New York and at Circoloco in Ibiza." }, origin: "Peckham, Londres, Royaume-Uni", since: 2009, labels: ["Rhythm Section International"], sources: ["https://ra.co/dj/bradleyzero/biography", "https://djmag.com/longreads/bradley-zero-state-rhythm", "https://www.amsterdam-dance-event.nl/en/artists-speakers/bradley-zero/17539/"] }, // Bradley Zero
  "breaze": { slug: "breaze", bio: { fr: "DJ actif depuis 2018 et représenté par l'agence belge Platform, Breaze s'est fait connaître en remportant l'Ultimate DJ Battle de TAGMAG et en atteignant la finale de MNM Start To DJ 2024. Il produit des remix hypertechno et a joué à Tomorrowland, Balaton Sound, Dour, Dance D-Vision et aux Gentse Feesten.", en: "A DJ active since 2018 and booked through the Belgian agency Platform, Breaze made his name by winning the TAGMAG Ultimate DJ Battle and reaching the final of MNM Start To DJ 2024. He produces hypertechno remixes and has played Tomorrowland, Balaton Sound, Dour, Dance D-Vision and the Gentse Feesten." }, origin: "Belgique", since: 2018, sources: ["https://www.platformagency.be/en/breaze"] }, // Breaze
  "bredren": { slug: "bredren", bio: { fr: "Bredren est un trio de drum & bass belge formé en 2011 à Lennik. Le groupe publie sur Flexout Audio, 1985 Music et Proximity Recordings.", en: "Bredren is a Belgian drum & bass trio formed in 2011 in Lennik. The group releases on Flexout Audio, 1985 Music and Proximity Recordings." }, origin: "Lennik, Belgique", since: 2011, labels: ["Flexout Audio", "1985 Music"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Bredren&fmt=json", "https://api.discogs.com/database/search?artist=Bredren&type=release"] }, // Bredren
  "brennan-heart": { slug: "brennan-heart", bio: { fr: "Brennan Heart, de son vrai nom Fabian Bohn, est un DJ et producteur de hardstyle néerlandais né le 2 mars 1982 à Helden, dans le Limbourg. Il a d'abord formé le duo Brennan & Heart avant de poursuivre seul sous ce nom. Il a publié sur Scantraxx puis WE R Music, et dirige aujourd'hui le label I AM HARDSTYLE.", en: "Brennan Heart, real name Fabian Bohn, is a Dutch hardstyle DJ and producer born on 2 March 1982 in Helden, Limburg. He first formed the duo Brennan & Heart before continuing solo under this name. He released on Scantraxx and then WE R Music, and now runs the I AM HARDSTYLE label." }, origin: "Helden, Limbourg, Pays-Bas", since: 2001, labels: ["Scantraxx", "I AM HARDSTYLE"], sources: ["https://en.wikipedia.org/wiki/Brennan_Heart", "https://www.discogs.com/artist/439312-Brennan-Heart"] }, // Brennan Heart
  "brent-honey": { slug: "brent-honey", bio: { fr: "Brent Honey est un DJ et producteur australien partagé entre Melbourne et Berlin. Ses sets, rapides et euphoriques, croisent techno, trance, hard house et hardgroove. Il a joué plus de trois cents dates pour des marques et festivals comme Intercell, Teletech, Terminal V, Echelon, Pitch Music and Arts et Beyond The Valley.", en: "Brent Honey is an Australian DJ and producer splitting his time between Melbourne and Berlin. His fast, euphoric sets cross techno, trance, hard house and hardgroove. He has played over three hundred dates for brands and festivals including Intercell, Teletech, Terminal V, Echelon, Pitch Music and Arts and Beyond The Valley." }, origin: "Melbourne, Australie / Berlin", sources: ["https://www.plusbitsagency.com/artists/brent-honey", "https://brenthoney.com/"] }, // Brent Honey
  "busy-p": { slug: "busy-p", bio: { fr: "Busy P est le nom de scène de Pedro Winter, producteur, DJ et patron de label français né le 21 avril 1975 à Paris. Il a été le manager de Daft Punk de 1996 à 2008 et a fondé en 2003 le label Ed Banger Records, où il a signé Justice, Breakbot, SebastiAn, Cassius, Mr. Oizo, DJ Mehdi et Myd.", en: "Busy P is the stage name of Pedro Winter, a French producer, DJ and label owner born on 21 April 1975 in Paris. He managed Daft Punk from 1996 to 2008 and in 2003 founded the label Ed Banger Records, signing Justice, Breakbot, SebastiAn, Cassius, Mr. Oizo, DJ Mehdi and Myd." }, origin: "Paris, France", since: 2003, labels: ["Ed Banger Records"], sources: ["https://en.wikipedia.org/wiki/Pedro_Winter"] }, // Busy P
  "buzzfuzz": { slug: "buzzfuzz", bio: { fr: "Mark Vos, alias Buzz Fuzz, est un DJ et producteur gabber néerlandais. Il débute en 1986 comme DJ swingbeat avant de former The Dreamteam avec The Prophet, DJ Dano puis DJ Gizmo, et de lancer avec eux le label Dreamteam Productions. Il produit aussi sous l'alias Bertocucci Feranzano, signataire de « XTC Love », et fonde son propre label Stuka Recordings en 2004.", en: "Mark Vos, who records as Buzz Fuzz, is a Dutch gabber DJ and producer. He started out as a swingbeat DJ in 1986 before forming The Dreamteam with The Prophet, DJ Dano and later DJ Gizmo, and launching the Dreamteam Productions label with them. He also produces as Bertocucci Feranzano, the name behind \"XTC Love\", and founded his own label Stuka Recordings in 2004." }, origin: "Pays-Bas", since: 1986, labels: ["Dreamteam Productions", "Stuka Recordings"], sources: ["https://www.discogs.com/artist/196886-Buzz-Fuzz"] }, // Buzzfuzz
  "call-super": { slug: "call-super", bio: { fr: "Call Super est un DJ et producteur qui publie depuis 2011, principalement sur Houndstooth et Dekmantel. Sa production croise techno, house et ambient, et intègre des instruments acoustiques comme la clarinette.", en: "Call Super is a DJ and producer who has been releasing since 2011, mainly on Houndstooth and Dekmantel. His output crosses techno, house and ambient, and takes in acoustic instruments such as the clarinet." }, since: 2011, labels: ["Houndstooth", "Dekmantel"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Call%20Super&fmt=json", "https://api.discogs.com/database/search?artist=Call+Super&type=release"] }, // Call Super
  "callush": { slug: "callush", bio: { fr: "Carolina Z., alias CALLUSH, est une DJ et productrice installée à Berlin. Venue du rock et du post-punk avant de découvrir les clubs à 18 ans, elle bâtit un son de techno industrielle qu'elle croise avec l'EBM, la trance, le hardgroove et la schranz. Elle dirige son label Riot Tapes.", en: "Carolina Z., known as CALLUSH, is a Berlin-based DJ and producer. She came from rock and post-punk before discovering clubs at 18, and built an industrial techno sound she crosses with EBM, trance, hardgroove and schranz. She runs her own label, Riot Tapes." }, origin: "Berlin, Allemagne", labels: ["Riot Tapes"], sources: ["https://6amgroup.com/articles/music-interviews/unveiling-the-sonic-rebellion-a-conversation-with-berlins-callush", "https://mixmagde.com/read/callush-artists"] }, // Callush
  "calvin-harris": { slug: "calvin-harris", bio: { fr: "Calvin Harris, de son vrai nom Adam Richard Wiles, est un DJ, producteur et chanteur écossais né en 1984 à Dumfries. Son premier album, « I Created Disco », est sorti en 2007 ; ont suivi « We Found Love » avec Rihanna, « Summer » et « How Deep Is Your Love ». Il détient le record du plus grand nombre de numéros un au Royaume-Uni dans les années 2010 et a placé neuf singles dans le top 10 britannique à partir du seul album « 18 Months ». Il a fondé le label Fly Eye Records en mars 2010.", en: "Calvin Harris, real name Adam Richard Wiles, is a Scottish DJ, producer and singer born in Dumfries in 1984. His first album, \"I Created Disco\", came out in 2007; \"We Found Love\" with Rihanna, \"Summer\" and \"How Deep Is Your Love\" followed. He holds the record for the most UK number-one singles of the 2010s, and pulled nine UK top-ten singles from the album \"18 Months\" alone. He founded the Fly Eye Records label in March 2010." }, origin: "Dumfries, Écosse", since: 2007, labels: ["Fly Eye Records"], sources: ["https://en.wikipedia.org/wiki/Calvin_Harris"] }, // Calvin Harris
  "camelphat": { slug: "camelphat", bio: { fr: "CamelPhat est un duo anglais de DJ et producteurs formé à Liverpool en 2006 par Dave Whelan et Mike Di Scala, qui s'étaient rencontrés dans le disquaire 3 Beat Records. Après des années de sorties sous divers pseudonymes, ils percent en 2017 avec « Cola », 3e du classement dance britannique et 18e des singles. Leur house teintée de tech house est parue sur Defected, Axtone et Glasgow Underground.", en: "CamelPhat are an English DJ and production duo formed in Liverpool in 2006 by Dave Whelan and Mike Di Scala, who met in the 3 Beat Records shop. After years of releases under various aliases, they broke through in 2017 with \"Cola\", which reached No. 3 on the UK Dance Chart and No. 18 on the UK Singles Chart. Their tech-house-leaning house has appeared on Defected, Axtone and Glasgow Underground." }, origin: "Liverpool, Royaume-Uni", since: 2006, labels: ["Defected", "Axtone", "Glasgow Underground"], sources: ["https://en.wikipedia.org/wiki/CamelPhat"] }, // CamelPhat
  "canelle-doublekick": { slug: "canelle-doublekick", bio: { fr: "Canelle Doublekick est une DJ et productrice parisienne, active depuis 2020 sur la scène hard house et trance. Elle joue de la hard dance, de la techno, de la trance et de la ghettotech ; son premier single « Dónde está la discoteca » (2023) croise makina et hard house. Membre du collectif La Darude, elle est passée par Boiler Room Paris, We Love Green et les Eurockéennes.", en: "Canelle Doublekick is a Paris DJ and producer, active since 2020 on the hard house and trance scene. She plays hard dance, techno, trance and ghettotech; her first single \"Dónde está la discoteca\" (2023) crosses makina with hard house. A member of the La Darude collective, she has played Boiler Room Paris, We Love Green and Eurockéennes." }, origin: "Paris, France", since: 2020, sources: ["https://mixmag.fr/read/canelle-doublekick-revient-avec-give-it-to-me-news", "https://yeah.paleo.ch/en/artist/2023/canelle-doublekick"] }, // Canelle Doublekick
  "cara-elizabeth": { slug: "cara-elizabeth", bio: { fr: "Cara Elizabeth est une DJ et productrice installée à Berlin, qui joue de la hard trance, de la hard techno et de la trance mêlant kicks appuyés et lignes mélodiques, souvent avec des éléments vocaux. Elle s'est produite au BLADE Festival et à HÖR Berlin.", en: "Cara Elizabeth is a Berlin-based DJ and producer playing hard trance, hard techno and trance, combining driving kicks with melodic lines and frequent vocal elements. She has performed at BLADE Festival and HOR Berlin." }, origin: "Berlin, Allemagne", sources: ["https://hoer.live/artist/cara-elizabeth-2/", "https://blade-festival.de/en/2024/artists/cara-elizabeth/"] }, // Cara Elizabeth
  "carista": { slug: "carista", bio: { fr: "Carista, de son vrai nom Carista Eendragt, est une DJ, productrice et curatrice néerlandaise née à Utrecht de parents surinamais. Ses sets circulent entre house italienne, broken beat, garage et techno, avec des racines revendiquées dans le hip-hop et la soul funk. Elle a fondé en 2017 United Identities, à la fois label, série de soirées et émission mensuelle sur NTS Radio, consacrée aux artistes basés aux Pays-Bas. Résidente de Red Light Radio puis de De School, elle a livré un Essential Mix sur BBC Radio 1 en février 2020 et reçu le Gieskes-Strijbis Podiumprijs en 2021.", en: "Carista, born Carista Eendragt, is a Dutch DJ, producer and curator from Utrecht, born to Surinamese parents. Her sets move between Italo house, broken beat, garage and techno, rooted in hip-hop and soul funk. In 2017 she founded United Identities, at once a label, a club night and a monthly NTS Radio show dedicated to Netherlands-based artists. A resident at Red Light Radio and then De School, she delivered a BBC Radio 1 Essential Mix in February 2020 and won the Gieskes-Strijbis Podiumprijs in 2021." }, origin: "Utrecht, Pays-Bas", since: 2012, labels: ["United Identities"], sources: ["https://djmag.com/features/carista-unifying-dancefloor-interview-united-identities"] }, // Carista
  "carl-cox": { slug: "carl-cox", bio: { fr: "Carl Andrew Cox est un DJ de club et de radio, propriétaire d'écurie de sport automobile et producteur britannique, né le 29 juillet 1962. Il joue de la house et de la techno et vit aujourd'hui à Frankston, dans l'État de Victoria en Australie.", en: "Carl Andrew Cox is a British house and techno club DJ, radio DJ, motorsport team owner and record producer, born on 29 July 1962. He lives in Frankston, Victoria, Australia." }, origin: "Royaume-Uni", sources: ["https://en.wikipedia.org/wiki/Carl_Cox", "https://api.discogs.com/database/search?artist=Carl+Cox&type=release&per_page=50"] }, // Carl Cox
  "carl-craig": { slug: "carl-craig", bio: { fr: "Carl Craig est un producteur et DJ américain né le 22 mai 1969 à Détroit. Il appartient à la deuxième vague de la techno de Détroit, apparue à la fin des années 1980, et a fondé le label Planet E Communications. Il enregistre sous son nom comme sous plusieurs pseudonymes, dont Psyche, BFC et Innerzone Orchestra.", en: "Carl Craig is an American producer and DJ born on 22 May 1969 in Detroit. He belongs to the second wave of Detroit techno that emerged in the late 1980s, and founded the label Planet E Communications. He records under his own name and under several aliases, including Psyche, BFC and Innerzone Orchestra." }, origin: "Détroit, États-Unis", labels: ["Planet E Communications"], sources: ["https://en.wikipedia.org/wiki/Carl_Craig", "https://musicbrainz.org/artist/6732e9f3-5f24-4ba4-aef1-a2a49442b96b"] }, // Carl Craig
  "carla-dal-forno": { slug: "carla-dal-forno", bio: { fr: "Carla dal Forno est une musicienne, chanteuse et multi-instrumentiste australienne. Après avoir joué dans le groupe melbournien Mole House puis dans F ingers et Tarcar, elle sort son premier album solo, « You Know What It's Like », sur le label londonien Blackest Ever Black en octobre 2016 — un disque enregistré entre Melbourne et Berlin. À la fermeture du label en 2019, elle publie son deuxième album, « Look Up Sharp », sur son propre label Kallista Records.", en: "Carla dal Forno is an Australian musician, singer and multi-instrumentalist. After playing in the Melbourne group Mole House and then in F ingers and Tarcar, she released her first solo album, \"You Know What It's Like\", on the London label Blackest Ever Black in October 2016 — a record made between Melbourne and Berlin. When the label closed in 2019, she released her second album, \"Look Up Sharp\", on her own Kallista Records." }, origin: "Australie", since: 2016, labels: ["Blackest Ever Black", "Kallista Records"], sources: ["https://www.discogs.com/release/9265639-Carla-dal-Forno-You-Know-What-Its-Like-", "https://carladalforno.bandcamp.com/album/you-know-what-its-like"] }, // Carla dal Forno
  "carlita": { slug: "carlita", bio: { fr: "Carlita est le nom de scène de Carla Frayman, DJ et musicienne turco-italienne née en 1995 à Istanbul d'un père turc et d'une mère italienne. Formée au violoncelle dès 8 ans, elle sort du conservatoire turc puis de la Royal Academy of Music à 16 ans, et joue aussi de la guitare et de la basse. Active depuis 2014, elle mêle house, techno et instruments acoustiques, et publie sur Ninja Tune / Counter Records.", en: "Carlita is the stage name of Carla Frayman, a Turkish-Italian DJ and musician born in 1995 in Istanbul to a Turkish father and an Italian mother. She took up the cello at 8, went through the Turkish Conservatory and graduated from the Royal Academy of Music at 16, and also plays guitar and bass. Active since 2014, she blends house, techno and acoustic instruments, and releases on Ninja Tune / Counter Records." }, origin: "Istanbul, Turquie", since: 2014, labels: ["Ninja Tune", "Counter Records"], sources: ["https://en.wikipedia.org/wiki/Carlita_(musician)"] }, // Carlita
  "carly-zeng": { slug: "carly-zeng", bio: { fr: "Née en Chine, Carly Zeng a commencé à collectionner les disques et à organiser des warehouse parties à Brooklyn avant de s'installer à Berlin. Elle y anime sa propre soirée, Dissident, et joue régulièrement pour Cocktail d'Amore et Body Language, deux rendez-vous de la scène queer berlinoise. Ses sets, construits au disque, passent de la house au tribal et à la trance progressive.", en: "Born in China, Carly Zeng started collecting records and throwing warehouse parties in Brooklyn before moving to Berlin. There she runs her own party, Dissident, and plays regularly for Cocktail d'Amore and Body Language, two fixtures of the city's queer scene. Her vinyl-led sets move between house, tribal and proggy material." }, origin: "Berlin, Allemagne", sources: ["https://ra.co/dj/carlyzeng/biography", "https://refugeworldwide.com/artists/carly-zeng"] }, // Carly Zeng
  "casa-mata": { slug: "casa-mata", bio: { fr: "Casa Mata est un producteur français originaire de Montpellier, qui mêle afro house et deep techno. Son remix de « Maria Maria » de Santana marque un tournant : Bob Sinclar, Hugel, Da Capo et Enoo Napa le jouent. Il a signé avec Hugel et Adam Trigger un remix de « Blessings » de Calvin Harris et Clementine Douglas, puis « Calypso » sur Madorasindahouse Records en octobre 2025.", en: "Casa Mata is a French producer from Montpellier who blends Afro house and deep techno. His remix of Santana's 'Maria Maria' was a turning point, picked up by Bob Sinclar, Hugel, Da Capo and Enoo Napa. He co-produced a remix of Calvin Harris and Clementine Douglas' 'Blessings' with Hugel and Adam Trigger, then released 'Calypso' on Madorasindahouse Records in October 2025." }, origin: "Montpellier, France", labels: ["Madorasindahouse Records"], sources: ["https://www.guettapen.com/2025/10/10/casa-mata-artiste-emergent-entre-afro-house-et-deep-techno/", "https://www.sxpress.fr/artiste/casa-mata/"] }, // Casa Mata
  "cassius": { slug: "cassius", bio: { fr: "Cassius était un duo français de house formé à Paris par Philippe Zdar et Hubert Blanc-Francard, alias Boom Bass. Rattaché au mouvement de la French touch de la fin des années 1990, il a publié chez Virgin, Ed Banger et Because Music. Le duo a pris fin en 2019 avec la mort de Philippe Zdar.", en: "Cassius were a French house duo formed in Paris by Philippe Zdar and Hubert Blanc-Francard, aka Boom Bass. Associated with the late-1990s French touch movement, they released on Virgin, Ed Banger and Because Music. The duo ended in 2019 with the death of Philippe Zdar." }, origin: "Paris, France", labels: ["Ed Banger Records", "Because Music"], sources: ["https://en.wikipedia.org/wiki/Cassius_(band)", "https://www.discogs.com/artist/3358-Cassius"] }, // Cassius
  "cc-disco": { slug: "cc-disco", bio: { fr: "DJ et productrice australienne originaire de Cobram, dans l'État de Victoria, CC:DISCO! est installée à Lisbonne. Ses sets tournent autour du disco, de la house et des sonorités balearic, qu'elle défend aussi en radio et sur Bandcamp.", en: "An Australian DJ and producer from Cobram, Victoria, CC:DISCO! is based in Lisbon. Her sets revolve around disco, house and balearic sounds, which she also champions on radio and Bandcamp." }, origin: "Cobram, Australie", sources: ["https://www.discogs.com/artist/9302284-CCDISCO", "https://ccdisco.bandcamp.com"] }, // CC:DISCO!
  "cedex-higher-underground": { slug: "cedex-higher-underground", bio: { fr: "Cedex & Higher Underground est un duo drum & bass belge de Gand. Ils ont publié sur Space Pirate Recordings, Soul Lab et Lifestyle Music, notamment « Red Alert » avec James Marvel et « The Alarm » sur la compilation Belgian Connection. Ils ont joué à Tomorrowland, Rampage et Star Warz.", en: "Cedex & Higher Underground are a Belgian drum & bass duo from Ghent. They have released on Space Pirate Recordings, Soul Lab and Lifestyle Music, including \"Red Alert\" with James Marvel and \"The Alarm\" on the Belgian Connection compilation. They have played Tomorrowland, Rampage and Star Warz." }, origin: "Gand, Belgique", labels: ["Space Pirate Recordings", "Lifestyle Music"], sources: ["https://jungledrumandbass.co.uk/news/cedex-higher-underground-being-you", "https://soundcloud.com/cedexhigherunderground"] }, // Cedex & Higher Underground
  "cedric": { slug: "cedric", bio: { fr: "Cédric est un DJ belge de la scène électronique carolorégienne. Il a rejoint le Rockerill en 2013, où il est résident des soirées FlashForward, et y a joué aux côtés de Laurent Garnier, Ellen Allien, Dave Clarke, Luke Slater ou Monika Kruse. Son mélange de house et de techno tire vers le deep mélodique, parfois l'afro. Il joue aussi au sein des groupes The Babel Orchestra et Between The Lines.", en: "Cédric is a Belgian DJ from the Charleroi electronic scene. He joined Rockerill in 2013, where he is a resident of the FlashForward nights, playing alongside Laurent Garnier, Ellen Allien, Dave Clarke, Luke Slater and Monika Kruse. His mix of house and techno leans melodic and deep, sometimes Afro. He also plays in the groups The Babel Orchestra and Between The Lines." }, origin: "Charleroi, Belgique", since: 2013, sources: ["https://www.rockerill.com/agenda/flashforward-onyvaa/49497/"] }, // Cédric
  "cerj": { slug: "cerj", bio: { fr: "CERJ est un DJ copenhaguois, cofondateur avec Only Ollie, Skarn et Aja Gulris du concept de soirée Peccāvī, consacré aux sonorités mélodiques sombres. Il s'est fait la main au Culture Box, à Ved Siden Af et à Raw Grooves avant d'y programmer ses propres invités.", en: "CERJ is a Copenhagen DJ, co-founder — with Only Ollie, Skarn and Aja Gulris — of the Peccāvī party concept, devoted to dark melodic sounds. He cut his teeth at Culture Box, Ved Siden Af and Raw Grooves before booking his own guests there." }, origin: "Copenhague, Danemark", sources: ["http://cphdeep.com/rising-aja-gulris-cerj-of-peccavi/", "https://culture-box.com/"] }, // Cerj
  "chain-reaction": { slug: "chain-reaction", bio: { fr: "Chain Reaction est un producteur et DJ hardstyle néerlandais, présent sur le label Minus Is More depuis sa création. Ses premiers titres — « Lellebel », « Answers », « The Record Breaking », « Like A Boss » — comptent parmi ceux qui ont installé le raw hardstyle comme sous-genre. Il joue sur les grandes scènes hard dance : Defqon.1, Supremacy, Dominator, Intents Festival et Decibel Outdoor.", en: "Chain Reaction is a Dutch hardstyle producer and DJ, on the Minus Is More label since its launch. His early tracks — \"Lellebel\", \"Answers\", \"The Record Breaking\", \"Like A Boss\" — are among those that established raw hardstyle as a subgenre. He plays the main hard dance stages: Defqon.1, Supremacy, Dominator, Intents Festival and Decibel Outdoor." }, labels: ["Minus Is More"], sources: ["https://mostwanted.dj/artists/chain-reaction/", "https://hardstyle.com/en/news/b2s-brings-back-hard-bass-loudness-en-pussy-lounge-in-2026"] }, // Chain Reaction
  "charlotte-de-witte": { slug: "charlotte-de-witte", bio: { fr: "Charlotte de Witte, née le 21 juillet 1992, est une DJ et productrice belge originaire de Gand. Elle défend une techno sombre et dépouillée, teintée d'acid et de minimale, après avoir débuté sous l'alias Raving George. Elle a fondé les labels KNTXT et Époque, et figure au classement Top 100 DJs de DJ Mag depuis 2019.", en: "Charlotte de Witte, born 21 July 1992, is a Belgian DJ and producer from Ghent. She is known for a dark, stripped-back take on techno drawing on acid and minimal, after starting out under the alias Raving George. She founded the labels KNTXT and Époque, and has charted in DJ Mag's Top 100 DJs since 2019." }, origin: "Gand, Belgique", labels: ["KNTXT", "Époque"], sources: ["https://en.wikipedia.org/wiki/Charlotte_de_Witte"] }, // Charlotte de Witte
  "chicane": { slug: "chicane", bio: { fr: "Chicane est le nom de scène de Nicholas Bracegirdle, musicien, DJ et producteur anglais né en 1971 à Chalfont St Giles. On lui doit « Offshore », « Saltwater », chanté par Máire Brennan de Clannad, et « Don't Give Up » avec Bryan Adams, numéro un au Royaume-Uni. Son premier album « Far from the Maddening Crowds » paraît en 1997 ; le suivant, « Behind the Sun » (2000), a été certifié or britannique.", en: "Chicane is the stage name of Nicholas Bracegirdle, an English musician, DJ and producer born in 1971 in Chalfont St Giles. He is behind \"Offshore\", \"Saltwater\", sung by Clannad's Máire Brennan, and the UK number one \"Don't Give Up\" with Bryan Adams. His debut album \"Far from the Maddening Crowds\" came out in 1997; its follow-up \"Behind the Sun\" (2000) was certified gold in the UK." }, origin: "Chalfont St Giles, Angleterre", since: 1994, labels: ["Armada Music", "Modena Records"], sources: ["https://en.wikipedia.org/wiki/Chicane_(musician)"] }, // Chicane
  "chlar": { slug: "chlar", bio: { fr: "Chlär est un DJ et producteur suisse installé à Berlin depuis fin 2017. Il joue une techno rapide et percussive, construite sur des boucles de ses propres productions. Il a cofondé en 2017 le label Bipolar Disorder avec Jules Auderset (The Chronics), puis lancé son propre label Primal Instinct en 2023, où est paru son EP « Modern Survival ». Il forme également le duo Funk Assault avec Alarico.", en: "Chlär is a Swiss DJ and producer who has been based in Berlin since late 2017. He plays fast, percussive techno built from loops of his own productions. In 2017 he co-founded the Bipolar Disorder label with Jules Auderset (The Chronics), then launched his own imprint Primal Instinct in 2023, home to his \"Modern Survival\" EP. He also makes up the duo Funk Assault with Alarico." }, origin: "Suisse", since: 2017, labels: ["Primal Instinct", "Bipolar Disorder"], sources: ["https://groove.de/2025/01/08/chlaer-es-ist-einfach-das-verrueckteste-zeug-zu-machen/"] }, // Chlär
  "chloe-caillet": { slug: "chloe-caillet", bio: { fr: "Chloé Caillet est une DJ, productrice et multi-instrumentiste née à Manhattan et arrivée à Paris à onze ans, de mère franco-italienne et de père franco-espagnol. Pianiste classique de formation, elle étudie le jazz en Angleterre puis le music business à l'université de New York, et passe par la promotion de clubs et l'A&R avant de mixer. Son premier EP, Intro, est sorti en mai 2023 sur CircoLoco Records ; elle est résidente du DC-10 à Ibiza et a fondé son label XCESS Records.", en: "Chloé Caillet is a DJ, producer and multi-instrumentalist born in Manhattan who moved to Paris at eleven, with a French-Italian mother and a French-Spanish father. A classically trained pianist, she studied jazz in England and music business at New York University, and worked in club promotion and A&R before DJing. Her first EP, Intro, came out in May 2023 on CircoLoco Records; she is a resident at DC-10 in Ibiza and founded her label XCESS Records." }, origin: "New York / Paris", labels: ["XCESS Records", "CircoLoco Records"], sources: ["https://djmag.com/features/chloe-caillet-modern-fusion-ibiza-interview"] }, // Chloé Caillet
  "chouhal": { slug: "chouhal", bio: { fr: "Sarah, alias chouhal, est une DJ maltaise. Elle construit sa place dans la scène électronique de l'île depuis trois ans et dirige le label Mama Told Ya, qu'elle a monté comme plateforme de collaboration. Elle joue une techno directe et joueuse, et figure à l'affiche du Dalma Festival 2026 aux côtés de Jeff Mills, Anetha, Freddy K et Clara Cuvé.", en: "Sarah, aka chouhal, is a Maltese DJ. She has spent three years building her place in the island's electronic scene and runs the Mama Told Ya label, set up as a platform for collaboration. She plays direct, playful techno, and is billed at Dalma Festival 2026 alongside Jeff Mills, Anetha, Freddy K and Clara Cuvé." }, origin: "Malte", labels: ["Mama Told Ya"], sources: ["https://localsmalta.com/artist/chouhal", "https://www.dalmafestival.com/"] }, // chouhal
  "chris-liebing": { slug: "chris-liebing", bio: { fr: "Chris Liebing est un DJ, producteur et animateur radio allemand né le 11 décembre 1968 à Gießen, en Hesse. Il tient sa première résidence au Red Brick de Gießen en 1991, puis devient résident de l'Omen à Francfort en 1996. Il a fondé le label CLR et a publié sur Novamute et Primate Recordings.", en: "Chris Liebing is a German DJ, producer and radio host born on 11 December 1968 in Gießen, Hesse. He held his first residency at Gießen's Red Brick in 1991, then became a resident at Frankfurt's Omen in 1996. He founded the CLR label and has released on Novamute and Primate Recordings." }, origin: "Gießen, Allemagne", since: 1991, labels: ["CLR", "Novamute", "Primate Recordings"], sources: ["https://en.wikipedia.org/wiki/Chris_Liebing", "https://www.discogs.com/artist/1711-Chris-Liebing"] }, // Chris Liebing
  "chris-rinox": { slug: "chris-rinox", bio: { fr: "Chris Rinox est un live act techno originaire de Saxe-Anhalt, lié de longue date à Leipzig, où il joue régulièrement au Sky Club. Son set est décrit comme une techno minimale brute et sombre, aux beats agressifs. Il a publié l'EP « Burst Mode » sur Rhakz Records en 2021.", en: "Chris Rinox is a live techno act from Saxony-Anhalt with long-standing ties to Leipzig, where he plays regularly at the Sky Club. His sound is described as raw, dark minimal techno with aggressive beats. He released the \"Burst Mode\" EP on Rhakz Records in 2021." }, origin: "Magdebourg, Allemagne", labels: ["Rhakz Records"], sources: ["https://www.skyclub-leipzig.de/artist/detail/92-chris-rinox-live-ehem-zehnvierzig-de"] }, // Chris Rinox
  "chris-stussy": { slug: "chris-stussy", bio: { fr: "Chris Stussy, de son vrai nom Niels Christian Steenbergen, est un DJ et producteur néerlandais né à Leiderdorp et élevé à Leyde. Il fonde son label Up the Stuss en 2020 et a également publié sur Fuse London, PIV et Kaoz Theory. Son single « All Night Long », sorti en 2023, marque son décollage, suivi de sa série de soirées USS lancée à Londres en 2025 et de l'album Lost, Found & Forgotten en 2026.", en: "Chris Stussy, real name Niels Christian Steenbergen, is a Dutch DJ and producer born in Leiderdorp and raised in Leiden. He founded his label Up the Stuss in 2020 and has also released on Fuse London, PIV and Kaoz Theory. His 2023 single \"All Night Long\" was his breakthrough, followed by his USS party series launched in London in 2025 and the album Lost, Found & Forgotten in 2026." }, origin: "Leiderdorp / Leyde, Pays-Bas", since: 2014, labels: ["Up the Stuss", "Fuse London", "PIV"], sources: ["https://en.wikipedia.org/wiki/Chris_Stussy"] }, // Chris Stussy
  "christian-loffler": { slug: "christian-loffler", bio: { fr: "Christian Löffler est un musicien allemand né à Greifswald, sur la côte balte. Il mêle techno, deep house, ambient et électronique, et a publié six albums studio, majoritairement sur le label Ki Records.", en: "Christian Löffler is a German musician born in Greifswald, on the Baltic coast. He plays a mix of techno, deep house, ambient and electronic music, and has released six studio albums, mostly on Ki Records." }, origin: "Greifswald, Allemagne", labels: ["Ki Records"], sources: ["https://en.wikipedia.org/wiki/Christian_L%C3%B6ffler", "https://api.discogs.com/database/search?artist=Christian+L%C3%B6ffler&type=release"] }, // Christian Löffler
  "cinthie": { slug: "cinthie", bio: { fr: "Cinthie est une DJ, productrice et patronne de label allemande installée à Berlin, où elle mixe depuis les années 1990. Elle joue et produit de la house, avec un attachement revendiqué à la house underground des années 90, et dirige les labels 803 Crystal Grooves et Collective Cuts ainsi que le disquaire berlinois Elevate. Son premier album, Skylines – City Lights, paraît en 2020.", en: "Cinthie is a German DJ, producer and label owner based in Berlin, where she has been DJing since the 1990s. She plays and produces house with an avowed attachment to 90s underground house, and runs the labels 803 Crystal Grooves and Collective Cuts as well as Berlin record shop Elevate. Her debut album, Skylines – City Lights, came out in 2020." }, origin: "Berlin, Allemagne", labels: ["803 Crystal Grooves", "Collective Cuts"], sources: ["https://toolroomrecords.com/news/qa-cinthie/"] }, // Cinthie
  "clara-cuve": { slug: "clara-cuve", bio: { fr: "Clara Cuvé est une DJ et productrice allemande née à Munich et installée à Berlin. Formée au piano classique dès l'âge de quatre ans, elle commence à produire à quinze ans, devient résidente du Rote Sonne à Munich et rejoint le label et collectif munichois Stock5, avant de s'installer à Berlin et de devenir résidente de la série MESS à l'OHM. Ses sets mêlent une techno rapide et groovy à des éléments de breakbeat, de jungle et de hardcore.", en: "Clara Cuvé is a German DJ and producer, born in Munich and based in Berlin. Classically trained on piano from the age of four, she started producing at fifteen, became a resident at Munich's Rote Sonne and joined the Munich label and collective Stock5, before moving to Berlin and taking up a residency at the MESS series at OHM. Her sets combine fast, groovy techno with breakbeat, jungle and hardcore." }, origin: "Munich, Allemagne", labels: ["Stock5"], sources: ["https://www.unvrs.com/artists/clara-cuv", "https://api.discogs.com/artists/7909185"] }, // Clara Cuvé
  "colette": { slug: "colette", bio: { fr: "Colette est une DJ et programmatrice nantaise, habituée du club Warehouse où elle joue régulièrement. Son set mêle deep house, electro et house, sur des rythmiques percussives et des ambiances solaires.", en: "Colette is a DJ and programmer from Nantes, a regular at the Warehouse club where she plays often. Her sets blend deep house, electro and house over percussive rhythms and sunlit moods." }, origin: "Nantes, France", sources: ["https://www.warehouse-nantes.fr/artist/colette", "https://www.warehouse-nantes.fr/event/warehouse-9-ans-avec-bob-sinclar"] }, // Colette
  "colin-benders": { slug: "colin-benders", bio: { fr: "Colin Benders, né en 1986 à Utrecht, s'est d'abord fait connaître sous le nom Kyteman à la tête du Kyteman Orchestra, dont l'album The Hermit Sessions (2009) s'est classé au top 5 néerlandais. Il joue depuis une techno entièrement improvisée sur synthétiseurs modulaires, chaque kick et chaque ligne de basse étant construits en direct. Ce live a été présenté à Awakenings, Dekmantel, à l'ADE et au Berghain.", en: "Colin Benders, born in 1986 in Utrecht, first made his name as Kyteman, leading the Kyteman Orchestra whose album The Hermit Sessions (2009) reached the Dutch top five. He now plays fully improvised techno on modular synthesisers, building every kick and bassline live. The show has been staged at Awakenings, Dekmantel, ADE and Berghain." }, origin: "Utrecht, Pays-Bas", sources: ["https://en.wikipedia.org/wiki/Colin_Benders", "https://www.awakenings.com/en/artists/colin-benders/270/"] }, // Colin Benders
  "coone": { slug: "coone", bio: { fr: "Koen Bauweraerts, alias Coone, est un DJ et producteur belge de hardstyle né le 30 mai 1983 à Turnhout. Il s'est d'abord fait connaître sur la scène jumpstyle avant de se consacrer au hardstyle.", en: "Koen Bauweraerts, known as Coone, is a Belgian hardstyle DJ and producer born on 30 May 1983 in Turnhout. He first made his name on the jumpstyle scene before focusing on hardstyle." }, origin: "Turnhout, Belgique", sources: ["https://en.wikipedia.org/wiki/Coone", "https://musicbrainz.org/artist/8ec5439a-ff50-4b0f-9e75-fc3e517e75ff"] }, // Coone
  "corentin-mab": { slug: "corentin-mab", bio: { fr: "DJ et producteur nantais, Corentin Mab est résident du club Warehouse à Nantes. Ses sets mêlent la deep house des années passées et la house actuelle, et il joue dans l'Ouest de la France et à Paris depuis plus de cinq ans. Il a partagé l'affiche avec Kerri Chandler, Detroit Swindle, Folamour, Jeremy Underground et Chez Damier.", en: "A DJ and producer from Nantes, Corentin Mab is a resident at the city's Warehouse club. His sets combine older deep house with present-day house, and he has been playing western France and Paris for over five years. He has shared bills with Kerri Chandler, Detroit Swindle, Folamour, Jeremy Underground and Chez Damier." }, origin: "Nantes, France", sources: ["https://warehouse-nantes.fr/artist/corentin-mab"] }, // Corentin Mab
  "cosmic-gate": { slug: "cosmic-gate", bio: { fr: "Cosmic Gate est un projet de trance allemand fondé en 1997 par Stefan Bossems (alias DJ Bossi) et Claus Terhoeven (alias Nic Chagall). Bossems a quitté le duo, que Terhoeven poursuit.", en: "Cosmic Gate is a German trance project founded in 1997 by Stefan Bossems (aka DJ Bossi) and Claus Terhoeven (aka Nic Chagall). Bossems has since left the duo, which Terhoeven continues." }, origin: "Krefeld, Allemagne", since: 1997, sources: ["https://de.wikipedia.org/wiki/Cosmic_Gate", "https://fr.wikipedia.org/wiki/Cosmic_Gate"] }, // Cosmic Gate
  "courtesy": { slug: "courtesy", bio: { fr: "Najaaraq Vestbirk, alias Courtesy, est une DJ et productrice danoise établie à Copenhague. Depuis 2018 elle dirige le label Kulør, qui documente la scène rapide de la ville et s'étend aux livres et aux expositions. Ses sets croisent techno rapide, trance déconstruite et electro, et elle a joué au Berghain, à Bassiani et au Sónar by Night.", en: "Najaaraq Vestbirk, known as Courtesy, is a Danish DJ and producer based in Copenhagen. Since 2018 she has run the Kulør label, which documents the city's fast techno scene and extends into books and exhibitions. Her sets cross fast techno, deconstructed trance and electro, and she has played Berghain, Bassiani and Sónar by Night." }, origin: "Copenhague, Danemark", since: 2016, labels: ["Kulør"], sources: ["https://djmag.com/content/courtesy-launches-new-label-kul%C3%B8r-danish-techno-and-trance-compilation", "https://crackmagazine.net/article/long-reads/the-kaleidoscopic-world-of-courtesy/"] }, // Courtesy
  "creeds": { slug: "creeds", bio: { fr: "Willy Taconné, producteur et DJ français né en mai 1992, a appris le piano avant de se mettre à la production adolescent. Longtemps rattaché à la frenchcore et à la reverse bass, il a basculé vers la hard techno avec « Push Up », sorti fin 2022 : le titre est devenu viral sur TikTok, a atteint la sixième place des ventes en Allemagne et a été certifié dans une dizaine de pays.", en: "Willy Taconné, a French producer and DJ born in May 1992, learned piano before moving into production as a teenager. Long associated with frenchcore and reverse bass, he swung towards hard techno with \"Push Up\", released in late 2022: the track went viral on TikTok, reached number six on the German singles chart and was certified in around ten countries." }, origin: "France", sources: ["https://fr.wikipedia.org/wiki/Creeds", "https://de.wikipedia.org/wiki/Creeds", "https://fourfourmag.com/in-conversation-with-creeds-i-was-ready-to-give-up-then-push-up-happened/"] }, // Creeds
  "curses": { slug: "curses", bio: { fr: "Curses est le projet de Luca Venezia, producteur et DJ new-yorkais installé à Berlin. Actif d'abord sous le nom Drop the Lime, il adopte ensuite un son de cold wave, new beat et italo disco, mêlé de guitares à la Morricone. Il dirige le label berlinois Ombra INTL et est résident des soirées Pornceptual.", en: "Curses is the project of Luca Venezia, a New York producer and DJ based in Berlin. He first worked as Drop the Lime before moving to a cold wave, new beat and italo disco sound laced with Morricone-style guitar. He runs the Berlin label Ombra INTL and is a resident at the Pornceptual parties." }, origin: "New York, États-Unis (basé à Berlin)", labels: ["Ombra INTL"], sources: ["https://www.beatportal.com/articles/462438-cover-story-curses-new-wave-acid-love-from-outer-space", "https://djmag.com/features/curses-interview-passion-and-attitude-eskimo-recordings"] }, // Curses!
  "cynthia-spiering": { slug: "cynthia-spiering", bio: { fr: "Cynthia Spiering est une DJ et productrice néerlandaise. Employée du Cultuurpodium Perron à Rotterdam, elle y découvre l'envers du décor et joue son premier set en 2016, à 18 ans. Ses sets tiennent des kicks durs et des sonorités rave et acid des années 1990. Elle fonde le label Courtoisy Records en 2019 et publie aussi sur Everyone On Acid et ERADYS.", en: "Cynthia Spiering is a Dutch DJ and producer. Working at Rotterdam's Cultuurpodium Perron showed her the inner workings of the scene, and she played her first gig in 2016 at 18. Her sets pair hard kicks with 1990s rave and acid sounds. She founded the label Courtoisy Records in 2019 and also releases on Everyone On Acid and ERADYS." }, origin: "Rotterdam, Pays-Bas", since: 2016, labels: ["Courtoisy Records"], sources: ["https://www.awakenings.com/en/artists/cynthia-spiering/60216/"] }, // Cynthia Spiering
  "d-block-s-te-fan": { slug: "d-block-s-te-fan", bio: { fr: "D-Block & S-te-Fan est un duo hardstyle néerlandais formé fin 2004 à La Haye par Diederik Bakker (D-Block) et Stefan den Daas (S-te-Fan). Ils ont signé les hymnes officiels de Qlimax en 2009 et de Defqon.1 en 2020, et publié quatre albums, de « Music Made Addictz » (2009) à « Enter Your Mind » (2021). Leur label, Scantraxx Evolutionz, est une filiale de Scantraxx, fondé par The Prophet. Depuis 2015, ils utilisent aussi l'alias DBSTF pour leurs productions big room.", en: "D-Block & S-te-Fan are a Dutch hardstyle duo formed in late 2004 in The Hague by Diederik Bakker (D-Block) and Stefan den Daas (S-te-Fan). They wrote the official anthems for Qlimax in 2009 and Defqon.1 in 2020, and have released four albums, from \"Music Made Addictz\" (2009) to \"Enter Your Mind\" (2021). Their label, Scantraxx Evolutionz, is a sub-label of The Prophet's Scantraxx. Since 2015 they have also used the alias DBSTF for their big room productions." }, origin: "La Haye, Pays-Bas", since: 2004, labels: ["Scantraxx Evolutionz"], sources: ["https://fr.wikipedia.org/wiki/D-Block_%26_S-te-Fan"] }, // D-Block & S-te-Fan
  "d-frek": { slug: "d-frek", bio: { fr: "DJ et producteur hardcore français originaire de Salon-de-Provence, D-Frek publie depuis le début des années 2000 sur Frenchcore Worldwide Recordings, Hardcore France Records et son propre label D-Frek Music. Il forme également le duo Neural Strikers avec Blaster.", en: "A French hardcore DJ and producer from Salon-de-Provence, D-Frek has been releasing since the early 2000s on Frenchcore Worldwide Recordings, Hardcore France Records and his own D-Frek Music label. He is also half of the duo Neural Strikers with Blaster." }, origin: "Salon-de-Provence, France", labels: ["Frenchcore Worldwide Recordings", "Hardcore France Records", "D-Frek Music"], sources: ["https://www.discogs.com/artist/4928956-D-Frek"] }, // D-Frek
  "da-tweekaz": { slug: "da-tweekaz", bio: { fr: "Da Tweekaz est un duo hardstyle norvégien formé par Kenth Kvien et Marcus Nordli, actif depuis la fin des années 2000 et installé en Belgique depuis 2012 pour se rapprocher des festivals du Benelux. Leurs disques paraissent chez Dirty Workz, et le premier album Time 2 Shine date de 2012. Le duo mène en parallèle le projet happy hardcore Tweekacore et le trio The Elite avec Coone et Hard Driver.", en: "Da Tweekaz are a Norwegian hardstyle duo made up of Kenth Kvien and Marcus Nordli, active since the late 2000s and based in Belgium since 2012 to be closer to the Benelux festival circuit. Their records come out on Dirty Workz, starting with the album Time 2 Shine in 2012. Alongside it they run the happy hardcore project Tweekacore and the trio The Elite with Coone and Hard Driver." }, origin: "Norvège", since: 2007, labels: ["Dirty Workz"], sources: ["https://nl.wikipedia.org/wiki/Da_Tweekaz", "https://no.wikipedia.org/wiki/Da_Tweekaz"] }, // Da Tweekaz
  "daft-funk-live": { slug: "daft-funk-live", bio: { fr: "Daft Funk Live est un groupe hommage à Daft Punk, qui rejoue la discographie du duo français en concert plutôt qu'en DJ set : instruments joués sur scène, casques et costumes reconstitués, scénographie et show lumière synchronisé. Le répertoire couvre la house, la techno et l'electro qui ont fait la carrière de Daft Punk, séparé en 2021.", en: "Daft Funk Live is a Daft Punk tribute act that replays the French duo's discography as a live show rather than a DJ set: instruments played on stage, reconstructed helmets and costumes, staging and a synchronised light show. The repertoire covers the house, techno and electro that made Daft Punk's career, the duo having split in 2021." }, sources: ["https://www.warehouse-nantes.fr/event/club-de-jour-invite-daft-funk-live"] }, // Daft Funk Live
  "dai-freyr": { slug: "dai-freyr", bio: { fr: "Daði Freyr Pétursson, né le 30 juin 1992 à Reykjavík, est un musicien islandais actif depuis 2012. Il grandit au Danemark jusqu'à ses neuf ans avant que sa famille ne s'installe dans le sud de l'Islande. À la tête du groupe Daði & Gagnamagnið, il devait représenter l'Islande à l'Eurovision 2020 avec « Think About Things », concours annulé ; il y participe finalement en 2021 avec « 10 Years » et termine quatrième.", en: "Daði Freyr Pétursson, born 30 June 1992 in Reykjavík, is an Icelandic musician active since 2012. He grew up in Denmark until the age of nine before his family settled in southern Iceland. Fronting the group Daði & Gagnamagnið, he was due to represent Iceland at Eurovision 2020 with \"Think About Things\" before the contest was cancelled; he took part in 2021 instead with \"10 Years\", finishing fourth." }, origin: "Reykjavík, Islande", since: 2012, sources: ["https://en.wikipedia.org/wiki/Da%C3%B0i_Freyr"] }, // Daði Freyr
  "damian-lazarus": { slug: "damian-lazarus", bio: { fr: "Damian Lazarus est un DJ et producteur britannique originaire de Londres. Son premier album, Smoke the Monster Out, paraît en mai 2009 après deux ans d'écriture. Sa discographie relève surtout de la tech house, de la house et de la deep house.", en: "Damian Lazarus is a British DJ and electronic music producer from London. His first album, Smoke the Monster Out, came out in May 2009 after two years of writing. His catalogue is mostly tech house, house and deep house." }, origin: "Londres, Royaume-Uni", sources: ["https://en.wikipedia.org/wiki/Damian_Lazarus", "https://api.discogs.com/database/search?artist=Damian+Lazarus&type=release&per_page=50"] }, // Damian Lazarus
  "damien-rk": { slug: "damien-rk", bio: { fr: "Damien RK est un DJ et producteur français de la scène hardstyle, en tournée en France et en Europe depuis plus de huit ans. Il joue l'ensemble des styles hard — hardstyle, rawstyle, hard trance, hardcore et frenchcore — et fait partie de l'équipe du label Hardstyle France Records. Il s'est produit à l'Electrobeach, à l'Elektric Park, au Warehouse de Nantes et à l'Intents Festival aux Pays-Bas.", en: "Damien RK is a French DJ and producer from the hardstyle scene, touring France and Europe for more than eight years. He plays the whole range of hard styles — hardstyle, rawstyle, hard trance, hardcore and frenchcore — and is part of the Hardstyle France Records label team. He has played Electrobeach, Elektric Park, Warehouse in Nantes and Intents Festival in the Netherlands." }, origin: "France", labels: ["Hardstyle France Records"], sources: ["https://www.damienrk.com/", "https://www.myfestival.fr/artistes/damien-rk"] }, // Damien RK
  "dan-bono": { slug: "dan-bono", bio: { fr: "Dan Bono est un DJ et producteur de la scène électronique nantaise, actif depuis plus de quinze ans dans une house dite « open-minded ». Il a fondé le disquaire Bubble Records, ouvert de 1995 à 2005, et il est cofondateur et directeur artistique des soirées Paradise et De La House. Il a partagé l'affiche avec Stacey Pullen, Purple Disco Machine, Claptone ou M.A.N.D.Y.", en: "Dan Bono is a DJ and producer from the Nantes electronic scene, active for more than fifteen years in an \"open-minded\" strain of house. He founded the record shop Bubble Records, open from 1995 to 2005, and co-founded and art-directs the Paradise and De La House parties. He has shared bills with Stacey Pullen, Purple Disco Machine, Claptone and M.A.N.D.Y." }, origin: "Nantes, France", sources: ["https://www.warehouse-nantes.fr/artist/dan-bono"] }, // Dan Bono
  "dan-shake": { slug: "dan-shake", bio: { fr: "Dan Shake est un DJ et producteur britannique. Il se fait remarquer en confiant un CD de maquettes à Kenny Dixon Jr., alias Moodymann, après un concert au festival Dimensions : deux titres, « Thinkin' » et « 3AM Jazz Club », paraissent ensuite sur le label Mahogani Music, dont il est le premier artiste installé hors de Détroit. Sa musique, fondée sur le sample, va de la house brute aux édits disco. Il dirige le label Shake.", en: "Dan Shake is a British DJ and producer. He got noticed by handing a demo CD to Kenny Dixon Jr., aka Moodymann, after a set at Dimensions Festival: two tracks, \"Thinkin'\" and \"3AM Jazz Club\", then came out on Mahogani Music, making him the label's first artist based outside Detroit. His sample-based music runs from raw house cuts to disco edits. He runs the Shake label." }, origin: "Royaume-Uni", labels: ["Shake"], sources: ["https://www.stampthewax.com/2016/08/01/dan-shake-interview/"] }, // Dan Shake
  "daniel-avery": { slug: "daniel-avery", bio: { fr: "Daniel Avery est un DJ et producteur anglais né le 30 septembre 1986 à Bournemouth. Il publie ses disques depuis 2009 sur Phantasy Sound, le label londonien fondé par Erol Alkan, et travaille une techno acide et texturée qui glisse volontiers vers l'ambient sur ses albums.", en: "Daniel Avery is an English DJ and producer born on 30 September 1986 in Bournemouth. He has released on Phantasy Sound, the London label founded by Erol Alkan, since 2009, working an acid-leaning, textured techno that often drifts into ambient on his albums." }, origin: "Bournemouth, Royaume-Uni", since: 2009, labels: ["Phantasy Sound"], sources: ["https://en.wikipedia.org/wiki/Daniel_Avery_(music_producer)", "https://www.discogs.com/artist/2519485-Daniel-Avery"] }, // Daniel Avery
  "danke-al": { slug: "danke-al", bio: { fr: "Danke Al est un DJ toulousain, président de l'association Biphase et membre du collectif du même nom. Digger, il navigue entre rave, techno, hardtrance et acid techno. Il a joué au Bikini de Ramonville, notamment aux soirées Rave On ! aux côtés de Shlømo, Narciss et DJ Heartstring, puis à la soirée Unfaced avec Jacidorex.", en: "Danke Al is a Toulouse DJ, president of the Biphase association and a member of the collective of the same name. A digger, he moves between rave, techno, hard trance and acid techno. He has played Le Bikini in Ramonville, notably the Rave On! nights alongside Shlømo, Narciss and DJ Heartstring, and later the Unfaced night with Jacidorex." }, origin: "Toulouse, France", sources: ["https://www.toulouseblog.fr/nuit-sans-repit-au-bikini-la-soiree-unfaced-va-faire-trembler-les-murs/", "https://lebikini.com/2022/10/21/rave-on-octobre-2022"] }, // Danke Al
  "danth": { slug: "danth", bio: { fr: "Danth est le nom de scène de Daniel Busenthür, DJ et producteur allemand originaire de Cologne. Il commence à mixer en 2018 au Bootshaus, la salle de sa ville, et joue un répertoire qui va de la house aux sons de festival et au hardstyle.", en: "Danth is the stage name of Daniel Busenthür, a German DJ and producer from Cologne. He started DJing in 2018 at Bootshaus, his home town's club, and plays a repertoire running from house to festival sounds and hardstyle." }, origin: "Cologne, Allemagne", since: 2018, sources: ["https://bootshaus.tv/artists/danth/"] }, // Danth
  "daria-kolosova": { slug: "daria-kolosova", bio: { fr: "Daria Kolosova est une DJ ukrainienne née à Lutugino, dans l'est du pays. Elle joue pour la première fois en février 2010, puis s'installe à Kyiv où elle devient résidente du club Keller sous l'alias Dar:k et co-lance la série de soirées Materia UA. Sous son propre nom, elle mêle techno rapide, breakbeat, electro et jungle, et s'est produite au Berghain, à Bassiani, au Fabric et à Awakenings.", en: "Daria Kolosova is a Ukrainian DJ born in Lutugino, in the east of the country. She played her first show in February 2010, then moved to Kyiv where she became a resident at Keller under the alias Dar:k and co-founded the Materia UA party series. Under her own name she blends fast techno with breakbeat, electro and jungle, and has played Berghain, Bassiani, Fabric and Awakenings." }, origin: "Lutugino, Ukraine", since: 2010, sources: ["https://dgtl-festival.com/en/artists/daria-kolosova/", "https://www.liaisonartists.com/artists/daria-kolosova/"] }, // Daria Kolosova
  "darkside": { slug: "darkside", bio: { fr: "DARKSIDE est un groupe américain formé à New York en 2011 par Nicolas Jaar et Dave Harrington. Après une pause à partir de 2014, le projet reprend avec l'annonce du morceau « Spiral » en 2020. Sa musique croise électronique, house déviante et rock psychédélique.", en: "DARKSIDE is an American band formed in New York in 2011 by Nicolas Jaar and Dave Harrington. After a hiatus from 2014, the project resumed with the announcement of \"Spiral\" in 2020. Their music crosses electronic music, left-field house and psychedelic rock." }, origin: "New York, États-Unis", since: 2011, sources: ["https://www.discogs.com/artist/2522005-DARKSIDE-22", "https://musicbrainz.org/ws/2/artist/?query=DARKSIDE&fmt=json"] }, // DARKSIDE
  "darrell-pulse": { slug: "darrell-pulse", bio: { fr: "Darrell Pulse est un DJ écossais, résident de la soirée techno Pulse au Bongo Club d'Édimbourg, où il joue aux côtés des autres résidents Sean Laird et Shaun Johnston. La soirée y reçoit régulièrement des invités techno comme Slam, Surgeon ou SPFDJ.", en: "Darrell Pulse is a Scottish DJ and a resident of the Pulse techno night at Edinburgh's Bongo Club, where he plays alongside fellow residents Sean Laird and Shaun Johnston. The night regularly hosts techno guests such as Slam, Surgeon and SPFDJ." }, origin: "Édimbourg, Écosse", sources: ["https://www.thebongoclub.co.uk/event/pulse-slam/"] }, // Darrell Pulse
  "darwin": { slug: "darwin", bio: { fr: "DJ canadienne installée à Berlin, Darwin a fondé en 2014 REEF, une série de raves de 24 heures née à la Griessmuehle et aujourd'hui hébergée au Berghain. Elle dirige depuis 2015 le label SPE:C, qui publie de la techno, du dubstep, des breaks et de la drum & bass. Ses sets circulent de la techno à la bass music britannique et à la jungle.", en: "A Canadian DJ based in Berlin, Darwin founded REEF in 2014, a series of 24-hour raves born at Griessmuehle and now hosted at Berghain. Since 2015 she has run the SPE:C label, releasing techno, dubstep, breaks and drum & bass. Her sets travel from techno to UK bass music and jungle." }, origin: "Berlin, Allemagne", since: 2014, labels: ["SPE:C"], sources: ["https://mixmag.net/feature/in-session-darwin", "https://groove.de/2019/02/05/am-start-darwin-reef-griessmuehle/", "https://www.berghain.berlin/en/events/77271/"] }, // Darwin
  "dasha-rush": { slug: "dasha-rush", bio: { fr: "Dasha Rush est une productrice et DJ née en Russie, de nationalité française et installée à Berlin. Sa techno se déploie sur plusieurs plans, du club au terrain expérimental et ambient — l'album Sleepstep en est l'illustration la plus connue — et s'accompagne de collaborations avec des plasticiens et des danseurs. Elle dirige son label Fullpanda Records et sa sous-division plus exploratoire, Hunger to Create.", en: "Dasha Rush is a Russian-born, French-national producer and DJ based in Berlin. Her techno works on several levels at once, from the club to experimental and ambient territory — the album Sleepstep being the best-known example — alongside collaborations with visual artists and dancers. She runs the label Fullpanda Records and its more exploratory sub-label, Hunger to Create." }, origin: "Russie, installée à Berlin", labels: ["Fullpanda Records", "Hunger to Create"], sources: ["https://grayarea.co/artists/dasha-rush"] }, // Dasha Rush
  "dave-clarke": { slug: "dave-clarke", bio: { fr: "Dave Clarke, de son nom complet David Maurice Clarke, est un DJ, producteur et animateur de radio anglais né le 19 septembre 1968 à Brighton. Il joue de la techno et de l'electro, et c'est le présentateur de la BBC John Peel qui l'a surnommé « The Baron of Techno ».", en: "Dave Clarke, full name David Maurice Clarke, is an English DJ, producer and radio presenter born on 19 September 1968 in Brighton. He plays techno and electro, and it was BBC broadcaster John Peel who nicknamed him \"The Baron of Techno\"." }, origin: "Brighton, Royaume-Uni", since: 1990, sources: ["https://en.wikipedia.org/wiki/Dave_Clarke_(DJ)", "https://musicbrainz.org/artist/0d7fffb1-c282-4995-96a9-f6f2ea3c86e0"] }, // Dave Clarke
  "dave-lambert": { slug: "dave-lambert", bio: { fr: "Dave Lambert est un DJ et producteur belge actif depuis les années 1990, où il lance son propre concept de soirée au Paradox d'Anvers. Il a été résident du Versuz, de La Rocca et du Zillion, et a joué à toutes les éditions de Tomorrowland, dont la mainstage en 2010 et 2012. Sa discographie compte plus de quarante compilations et des remixes pour Fedde Le Grand ou Benny Benassi ; il joue une house deep, mélodique et tech, ainsi que des sets rétro et classics.", en: "Dave Lambert is a Belgian DJ and producer active since the 1990s, when he started his own party concept at Paradox in Antwerp. He has been a resident at Versuz, La Rocca and Zillion, and has played every edition of Tomorrowland, including the mainstage in 2010 and 2012. His discography includes more than forty compilations and remixes for the likes of Fedde Le Grand and Benny Benassi; he plays deep, melodic and tech house alongside retro and classics sets." }, origin: "Anvers, Belgique", since: 1990, sources: ["https://www.groundcontrolagency.be/artist/dave-lambert"] }, // Dave Lambert
  "dave-replay": { slug: "dave-replay", bio: { fr: "Dave Replay est un producteur et DJ allemand, résident du Bootshaus de Cologne, où il a commencé sa carrière. Il joue de l'electro house et a partagé l'affiche des grands festivals allemands avec Zedd, Dimitri Vegas & Like Mike ou Swedish House Mafia. Il a sorti des titres sur Dirty Dutch Records et Pandafunk.", en: "Dave Replay is a German producer and DJ, a resident at Cologne's Bootshaus where his career began. He plays electro house and has shared major German festival bills with Zedd, Dimitri Vegas & Like Mike and Swedish House Mafia. He has released on Dirty Dutch Records and Pandafunk." }, origin: "Allemagne", labels: ["Dirty Dutch Records", "Pandafunk"], sources: ["https://bootshaus.tv/artists/dave-replay/"] }, // Dave Replay
  "david-guetta": { slug: "david-guetta", bio: { fr: "Pierre David Guetta, né le 7 novembre 1967, est un DJ et producteur français. Il a publié son premier album, Just a Little More Love, en 2002, puis connu un succès international avec One Love (2009). Il a été élu numéro un du classement DJ Mag Top 100 DJs en 2011, 2020, 2021, 2023 et 2025.", en: "Pierre David Guetta, born 7 November 1967, is a French DJ and record producer. He released his debut album Just a Little More Love in 2002 and broke through internationally with One Love (2009). He was voted number one in the DJ Mag Top 100 DJs poll in 2011, 2020, 2021, 2023 and 2025." }, origin: "Paris, France", since: 2002, sources: ["https://en.wikipedia.org/wiki/David_Guetta"] }, // David Guetta
  "davyboi": { slug: "davyboi", bio: { fr: "Davyboi est un DJ et producteur munichois d'origine polonaise, danseur avant de passer derrière les platines. Il joue des sets à haute énergie entre trance, eurodance et hard dance, et sort sur le label Polyamor Records, notamment « Shining Heart » et « Discotheque » avec Mika Heggemann. Il a joué à HÖR Berlin, au Thuishaven et à la Rote Sonne de Munich.", en: "Davyboi is a Munich DJ and producer of Polish descent, a dancer before he moved behind the decks. He plays high-energy sets spanning trance, eurodance and hard dance, and releases on Polyamor Records, including 'Shining Heart' and 'Discotheque' with Mika Heggemann. He has played HOR Berlin, Thuishaven and Munich's Rote Sonne." }, origin: "Munich, Allemagne", labels: ["Polyamor Records"], sources: ["https://davyboi.de/", "https://www.electriclove.at/en/artist/davyboi/"] }, // Davyboi
  "dax-j": { slug: "dax-j", bio: { fr: "Dax J, de son vrai nom Dax Heddon, est un DJ et producteur de techno né à Londres et installé à Berlin. Il commence à mixer à quinze ans sur les radios pirates londoniennes et publie ses premiers vinyles en 2005 dans la jungle et la drum & bass, avant de basculer vers la techno. Il fonde le label Monnom Black en 2013 et tient son propre studio de mastering à Berlin.", en: "Dax J, real name Dax Heddon, is a techno DJ and producer born in London and based in Berlin. He started DJing at fifteen on London pirate radio and put out his first vinyl in 2005 in jungle and drum & bass, before moving to techno. He founded the Monnom Black label in 2013 and runs his own mastering studio in Berlin." }, origin: "Londres, Royaume-Uni / Berlin, Allemagne", since: 2005, labels: ["Monnom Black"], sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/dax-j/20348/", "https://www.discogs.com/artist/819825"] }, // Dax J
  "deborah-de-luca": { slug: "deborah-de-luca", bio: { fr: "Deborah De Luca, née le 23 juillet 1980 à Naples, est une DJ et productrice italienne. Elle a grandi aux Vele di Scampia, dans la périphérie napolitaine, et joue une techno dure et minimale. Elle a créé son propre label, Sola_Mente Records, pour sortir sa musique de manière indépendante, et a publié les albums Ten (2018) et She Sleeps (2020). Son set filmé par Cercle au château de Chambord en 2017 dépasse les 25 millions de vues sur YouTube.", en: "Deborah De Luca, born 23 July 1980 in Naples, is an Italian DJ and producer. She grew up in the Vele di Scampia on the city's outskirts and plays hard, minimal techno. She set up her own label, Sola_Mente Records, to release her music independently, and put out the albums Ten (2018) and She Sleeps (2020). Her set filmed by Cercle at the Château de Chambord in 2017 has passed 25 million views on YouTube." }, origin: "Naples, Italie", since: 2012, labels: ["Sola_Mente Records"], sources: ["https://es.wikipedia.org/wiki/Deborah_De_Luca"] }, // Deborah De Luca
  "dennis-cruz": { slug: "dennis-cruz", bio: { fr: "Denis de Galdo Troyano, connu sous le nom de Dennis Cruz, est un DJ et producteur espagnol né en 1983. Il produit depuis 2010 et travaille la tech house et la techno, avec des influences funk, dub et latines. Il a publié sur Saved, Deeperfect et Moon Harbour, et a créé ses propres labels.", en: "Denis de Galdo Troyano, known as Dennis Cruz, is a Spanish DJ and record producer born in 1983. He has been producing since 2010, working in tech house and techno with funk, dub and Latin influences. He has released on Saved, Deeperfect and Moon Harbour, and founded his own labels." }, origin: "Espagne", since: 2010, labels: ["Saved", "Deeperfect", "Moon Harbour"], sources: ["https://en.wikipedia.org/wiki/Dennis_Cruz", "https://api.discogs.com/database/search?artist=Dennis+Cruz&type=release&per_page=50"] }, // Dennis Cruz
  "desolate-discotheque": { slug: "desolate-discotheque", bio: { fr: "Desolate Discotheque est un DJ, curateur et organisateur berlinois, actif depuis une quinzaine d'années dans la scène techno-EBM-wave européenne. Il fonde en 2019 Crave Tapes, label indépendant berlinois de cassettes et de vinyles, et joue aussi sous le nom Disko Kommando au sein du collectif RITMO3000. Ses sets croisent italo-disco, EBM, coldwave et dark disco.", en: "Desolate Discotheque is a Berlin DJ, curator and promoter, active for some fifteen years in the European techno-EBM-wave scene. In 2019 he founded Crave Tapes, a Berlin independent cassette and vinyl label, and he also plays as Disko Kommando within the RITMO3000 collective. His sets cross italo disco, EBM, coldwave and dark disco." }, origin: "Berlin, Allemagne", since: 2019, labels: ["Crave Tapes"], sources: ["https://cravetapes.bandcamp.com/album/desolation", "https://m.soundcloud.com/desolatediscotheque"] }, // Desolate Discotheque
  "digitalism": { slug: "digitalism", bio: { fr: "Digitalism est un duo électronique allemand formé à Hambourg en 2004 par Jens Moelle et İsmail Tüfekçi. Il est signé sur le label français Kitsuné, ainsi que sur Virgin Records et Astralwerks selon les territoires. Sa discographie relève surtout de l'electro et de la house, avec des incursions electroclash.", en: "Digitalism are a German electronic duo formed in Hamburg in 2004 by Jens Moelle and İsmail Tüfekçi. They are signed to the French label Kitsuné, as well as Virgin Records and Astralwerks elsewhere. Their catalogue is mostly electro and house, with electroclash excursions." }, origin: "Hambourg, Allemagne", since: 2004, labels: ["Kitsuné"], sources: ["https://en.wikipedia.org/wiki/Digitalism_(band)", "https://api.discogs.com/database/search?artist=Digitalism&type=release&per_page=50"] }, // Digitalism
  "dimension": { slug: "dimension", bio: { fr: "Dimension, de son vrai nom Robert Etheridge, est un producteur et DJ anglais né en 1991 à Londres. Il produit de la drum and bass et a sorti son premier single, « Delight », en 2012 avant d'être signé sur MTA Records par Chase & Status en 2014. Son single « Desire », avec Sub Focus, est entré au UK Singles Chart en 2018 et a été certifié disque de platine au Royaume-Uni. Son premier album, « Organ », est sorti en mars 2021 et s'est classé numéro un des ventes dance britanniques.", en: "Dimension, real name Robert Etheridge, is an English producer and DJ born in London in 1991. He makes drum and bass and released his first single, \"Delight\", in 2012 before being signed to MTA Records by Chase & Status in 2014. His single \"Desire\" with Sub Focus charted on the UK Singles Chart in 2018 and went platinum in the UK. His debut album \"Organ\" came out in March 2021 and entered the UK Official Dance Chart at number one." }, origin: "Londres, Royaume-Uni", since: 2012, labels: ["MTA Records"], sources: ["https://en.wikipedia.org/wiki/Dimension_(musician)"] }, // Dimension
  "dimitri-from-paris": { slug: "dimitri-from-paris", bio: { fr: "Dimitrios Yerasimos, né en 1963 à Istanbul de parents grecs et élevé à Paris, commence à la radio — Radio 7 puis NRJ, où il tient une émission jusqu'en 1998. Producteur et DJ house, il signe les albums Sacrebleu (1996) et Monsieur Dimitri's De-Luxe House of Funk, réalise des bandes-son de défilés pour Chanel, Gaultier et Lagerfeld, et s'est spécialisé dans les rééditions et remixes disco, notamment pour le label BBE. Il a été fait chevalier des Arts et des Lettres en 2005.", en: "Dimitrios Yerasimos, born in Istanbul in 1963 to Greek parents and raised in Paris, started out on radio — Radio 7, then NRJ, where he hosted a show until 1998. A house producer and DJ, he released the albums Sacrebleu (1996) and Monsieur Dimitri's De-Luxe House of Funk, scored runway shows for Chanel, Gaultier and Lagerfeld, and has specialised in disco reissues and remixes, notably for the BBE label. He was made a Chevalier des Arts et des Lettres in 2005." }, origin: "Paris, France", since: 1994, labels: ["BBE Music"], sources: ["https://en.wikipedia.org/wiki/Dimitri_from_Paris", "https://bbemusic.com/artist/dimitri-from-paris"] }, // Dimitri From Paris
  "disclosure": { slug: "disclosure", bio: { fr: "Duo britannique formé en 2010 à Reigate, dans le Surrey, par les frères Guy et Howard Lawrence. Leur house traversée de UK garage et de 2-step a percé avec l'album Settle (2013), numéro un au Royaume-Uni, et le single « Latch » chanté par Sam Smith. Ont suivi Caracal (2015), Energy (2020) et Alchemy (2023).", en: "British duo formed in 2010 in Reigate, Surrey, by brothers Guy and Howard Lawrence. Their house music, shot through with UK garage and 2-step, broke through with the album Settle (2013), a UK number one, and the single \"Latch\" featuring Sam Smith. Caracal (2015), Energy (2020) and Alchemy (2023) followed." }, origin: "Reigate, Royaume-Uni", since: 2010, labels: ["PMR Records", "Island Records"], sources: ["https://en.wikipedia.org/wiki/Disclosure_(band)"] }, // Disclosure
  "dixon": { slug: "dixon", bio: { fr: "Dixon est le nom de scène de Steffen Berkhahn, DJ et producteur allemand né en 1975, basé à Berlin. Il a fondé le label Innervisions et a été élu numéro un du classement Resident Advisor chaque année de 2013 à 2016.", en: "Dixon is the stage name of Steffen Berkhahn, a German DJ and producer born in 1975 and based in Berlin. He founded the Innervisions label and topped Resident Advisor's DJ poll every year from 2013 to 2016." }, origin: "Berlin, Allemagne", labels: ["Innervisions"], sources: ["https://en.wikipedia.org/wiki/Dixon_(DJ)"] }, // Dixon
  "dj-aligator": { slug: "dj-aligator", bio: { fr: "DJ Aligator est le nom de scène d'Ali Asghar Movasat, producteur et DJ irano-danois né à Téhéran. Il connaît un succès international avec « The Whistle Song », extrait de son premier album « Payback Time » paru en 2000 : quadruple disque de platine au Danemark, le morceau atteint la 5e place au Royaume-Uni en janvier 2002 et il l'interprète à Top of the Pops. En 2022, Steve Aoki et Timmy Trumpet l'invitent sur « The Whistle ».", en: "DJ Aligator is the stage name of Ali Asghar Movasat, an Iranian-Danish producer and DJ born in Tehran. He had international success with \"The Whistle Song\", taken from his first album \"Payback Time\" in 2000: four times platinum in Denmark, it reached No. 5 in the UK in January 2002 and he performed it on Top of the Pops. In 2022 Steve Aoki and Timmy Trumpet featured him on \"The Whistle\"." }, origin: "Téhéran, Iran", since: 1994, sources: ["https://en.wikipedia.org/wiki/DJ_Aligator"] }, // DJ Aligator
  "dj-breakfast": { slug: "dj-breakfast", bio: { fr: "DJ Breakfast est un DJ drum & bass de Copenhague, membre du collectif Drum & Bass Klubben avec Bobby 6 Killa, HDN, Maxi Mo et L.A.D.J. Le collectif programme régulièrement des soirées au Culture Box et dans le quartier de Nørrebro.", en: "DJ Breakfast is a drum & bass DJ from Copenhagen and a member of the Drum & Bass Klubben collective alongside Bobby 6 Killa, HDN, Maxi Mo and L.A.D.J. The collective regularly programmes nights at Culture Box and around the Nørrebro district." }, origin: "Copenhague, Danemark", sources: ["https://ra.co/events/2154919", "https://www.facebook.com/DrumAndBassKlubben/"] }, // DJ Breakfast
  "dj-caline": { slug: "dj-caline", bio: { fr: "DJ Caline est un DJ et producteur parisien, l'un des visages de la scène bouncy et hard trance française. À la croisée de la bounce, de la trance et de la dance music, il joue régulièrement au Rex Club, à la Machine du Moulin Rouge et au Trabendo, ainsi qu'au festival Madame Loyal et en Boiler Room.", en: "DJ Caline is a Paris DJ and producer, one of the faces of the French bouncy and hard trance scene. Working at the meeting point of bounce, trance and dance music, he plays regularly at Rex Club, La Machine du Moulin Rouge and Le Trabendo, as well as Madame Loyal festival and Boiler Room." }, origin: "Paris, France", sources: ["https://www.warehouse-nantes.fr/artist/dj-caline"] }, // DJ Caline
  "dj-cosworth": { slug: "dj-cosworth", bio: { fr: "DJ, producteur et patron de label basé à Manchester, DJ Cosworth dirige Hardline, structure consacrée au UK garage, au speed garage et à la tech house. Son EP « HARD30 » est sorti sur son propre label.", en: "A Manchester-based DJ, producer and label head, DJ Cosworth runs Hardline, an imprint devoted to UK garage, speed garage and tech house. His \"HARD30\" EP came out on his own label." }, origin: "Manchester, Royaume-Uni", labels: ["Hardline Sounds"], sources: ["https://constellatetalent.com/artist/dj-cosworth/", "https://hardlinesounds.bandcamp.com/album/hard30-2"] }, // DJ Cosworth
  "dj-cringey": { slug: "dj-cringey", bio: { fr: "DJ Cringey est une DJ et productrice néo-zélandaise installée à Berlin. Ses sets croisent techno, acid, EBM et house, et elle a joué au Hive Festival, à WECANDANCE, à l'Amnesia Ibiza et sur les soirées Teletech. Son album Cringey Core est paru sur le label Bamboo.", en: "DJ Cringey is a New Zealand DJ and producer based in Berlin. Her sets cross techno, acid, EBM and house, and she has played Hive Festival, WECANDANCE, Amnesia Ibiza and Teletech events. Her album Cringey Core came out on the Bamboo label." }, origin: "Berlin, Allemagne", labels: ["Bamboo"], sources: ["http://www.spinartistagency.com/dod-copy"] }, // DJ Cringey
  "dj-f-r-a-n-k": { slug: "dj-f-r-a-n-k", bio: { fr: "DJ F.R.A.N.K., de son vrai nom Frank Van Herwegen, est un DJ et producteur belge né le 10 décembre 1970 à Schoten. Il mixe depuis ses seize ans et a travaillé comme disquaire à Anvers. Remixeur du groupe The Underdog Project au début des années 2000, il signe en 2010 le titre « Discotex! (Yah!) », numéro un en Belgique.", en: "DJ F.R.A.N.K., real name Frank Van Herwegen, is a Belgian DJ and producer born on 10 December 1970 in Schoten. He has been DJing since the age of sixteen and worked as a record seller in Antwerp. A remixer for The Underdog Project in the early 2000s, in 2010 he scored a number one in Belgium with \"Discotex! (Yah!)\"." }, origin: "Schoten, Belgique", since: 1986, sources: ["https://en.wikipedia.org/wiki/DJ_F.R.A.N.K."] }, // DJ F.R.A.N.K.
  "dj-gigola": { slug: "dj-gigola", bio: { fr: "DJ Gigola est une DJ et productrice berlinoise, membre du collectif et label Live From Earth. Elle a terminé des études de médecine avant de vivre de la musique, et revendique un jeu sans frontières de genre : trance techno des années 2000, tech house et son high energy d'aujourd'hui, plus quelques détours par le rap et la pop. Son EP Bigroom Sensual (Live From Earth, 2024) met en scène cette réconciliation entre générations de dancefloor.", en: "DJ Gigola is a Berlin DJ and producer and a member of the Live From Earth collective and label. She finished a medical degree before turning to music full time, and plays deliberately across genre lines: early-2000s trance techno, tech house and today's high-energy sound, with detours through rap and pop. Her EP Bigroom Sensual (Live From Earth, 2024) frames that as a reconciliation between dancefloor generations." }, origin: "Berlin, Allemagne", labels: ["Live From Earth"], sources: ["https://www.exitfest.org/en/dj-gigola-the-creative-mind-of-the-new-techno-generation-from-berlin", "https://livefromearth.bandcamp.com/album/bigroom-sensual"] }, // DJ Gigola
  "dj-isaac": { slug: "dj-isaac", bio: { fr: "DJ Isaac est le nom de scène de Roel Schutrups, DJ et producteur néerlandais né en 1974 à Winschoten. Il compte parmi les fondateurs du hardstyle, se fait connaître en 1995 avec « Bad Dreams » et fonde son label X-Rate Records en 2003. Il a également publié sur Scantraxx et Dirty Workz, et joué à Defqon.1, Qlimax et EDC Las Vegas.", en: "DJ Isaac is the stage name of Roel Schutrups, a Dutch DJ and producer born in 1974 in Winschoten. He is one of the founders of hardstyle, broke through in 1995 with \"Bad Dreams\" and started his X-Rate Records label in 2003. He has also released on Scantraxx and Dirty Workz, and played Defqon.1, Qlimax and EDC Las Vegas." }, origin: "Winschoten, Pays-Bas", since: 1995, labels: ["X-Rate Records"], sources: ["https://nl.wikipedia.org/wiki/DJ_Isaac"] }, // DJ Isaac
  "dj-snake": { slug: "dj-snake", bio: { fr: "William Grigahcine, né à Paris en 1986 et d'origine algérienne, produit depuis 2009 un electro house croisé de trap et de moombahton. « Turn Down for What » avec Lil Jon (2013), « Lean On » avec Major Lazer et MØ (2015) puis « Taki Taki » (2018) l'ont porté au premier plan mondial. Il a publié les albums Encore (2016), Carte Blanche (2019) et Nomad (2025).", en: "William Grigahcine, born in Paris in 1986 and of Algerian descent, has been producing electro house crossed with trap and moombahton since 2009. \"Turn Down for What\" with Lil Jon (2013), \"Lean On\" with Major Lazer and MØ (2015) and \"Taki Taki\" (2018) took him worldwide. He has released the albums Encore (2016), Carte Blanche (2019) and Nomad (2025)." }, origin: "Paris, France", since: 2009, labels: ["Interscope Records", "Première Classe"], sources: ["https://fr.wikipedia.org/wiki/DJ_Snake"] }, // DJ Snake
  "dj-tennis": { slug: "dj-tennis", bio: { fr: "DJ Tennis est le nom de scène de Manfredi Romano, DJ, producteur et patron de label italien né le 27 décembre 1970 à Parme. Il étudie l'informatique tout en organisant des soirées et des tournées de groupes, puis fonde l'agence de booking Daze à Milan en 1995. En 2010 il crée avec Greg Oreck le label Life and Death, et sort par ailleurs sur Kompakt, !K7 et AUS Music.", en: "DJ Tennis is the stage name of Manfredi Romano, an Italian DJ, producer and label owner born on 27 December 1970 in Parma. He studied computer science while organising parties and band tours, then founded the booking agency Daze in Milan in 1995. In 2010 he started the Life and Death label with Greg Oreck, and has also released on Kompakt, !K7 and AUS Music." }, origin: "Parme, Italie", since: 2010, labels: ["Life and Death", "Kompakt", "!K7"], sources: ["https://en.wikipedia.org/wiki/DJ_Tennis"] }, // DJ Tennis
  "djerry-c": { slug: "djerry-c", bio: { fr: "Djerry C est un DJ suisse actif depuis les années 1990, résident du D! Club de Lausanne depuis 2004 et directeur artistique de la salle. Il a joué à Ibiza (El Divino, Eden, Space, Bora Bora), ainsi qu'au Montreux Jazz Festival, au Caprices Festival et à Electrosanne. Son répertoire est passé de la house à la techno.", en: "Djerry C is a Swiss DJ active since the 1990s, resident at Lausanne's D! Club since 2004 and the venue's artistic director. He has played in Ibiza (El Divino, Eden, Space, Bora Bora) as well as the Montreux Jazz Festival, Caprices Festival and Electrosanne. His repertoire has moved from house to techno." }, origin: "Lausanne, Suisse", since: 2004, sources: ["https://www.superstardeejay.com/mix008-djerry-c/", "https://www.amsterdam-dance-event.nl/en/artists-speakers/djerry-c/16056/"] }, // Djerry C
  "djrum": { slug: "djrum", bio: { fr: "Felix Manuel, alias Djrum, est un producteur britannique formé au piano jazz qui a appris à mixer sur la collection de disques de sa mère. Son premier EP, Mountains, sort sur 2nd Drop Records en 2011 ; il publie ensuite sur Ilian Tape, R&S Records et Houndstooth. Ses disques croisent jazz, dubstep, breakbeat, ambient et techno.", en: "Felix Manuel, who records as Djrum, is a British producer trained as a jazz pianist who learned to DJ on his mother's record collection. His first EP, Mountains, came out on 2nd Drop Records in 2011; he has since released on Ilian Tape, R&S Records and Houndstooth. His records move between jazz, dubstep, breakbeat, ambient and techno." }, origin: "Royaume-Uni", since: 2011, labels: ["R&S Records", "Houndstooth", "2nd Drop Records"], sources: ["https://en.wikipedia.org/wiki/Djrum", "https://www.rewirefestival.nl/artist/djrum"] }, // DjRUM
  "dom-dolla": { slug: "dom-dolla", bio: { fr: "Louis Matheson, connu sous le nom de Dom Dolla, est un producteur, DJ, auteur-compositeur et remixeur australien né le 18 janvier 1992. Wikipédia le décrit comme un producteur de tech house ; ses sorties relèvent aussi de la house et de la progressive house.", en: "Louis Matheson, known as Dom Dolla, is an Australian producer, DJ, songwriter and remixer born on 18 January 1992. Wikipedia describes him as a tech house producer; his releases also cover house and progressive house." }, origin: "Australie", sources: ["https://en.wikipedia.org/wiki/Dom_Dolla", "https://api.discogs.com/database/search?artist=Dom+Dolla&type=release&per_page=50"] }, // Dom Dolla
  "donato-dozzy": { slug: "donato-dozzy", bio: { fr: "Donato Dozzy, de son vrai nom Donato Scaramuzzi, est un DJ et producteur italien né à Rome, actif derrière les platines depuis le début des années 1980. Il s'est fait connaître pour une techno hypnotique et lentement évolutive, forgée lors de ses résidences au Brancaleone de Rome puis au Panorama Bar de Berlin, où il tenait les after de 2004 à 2006. Il a cofondé le label Aquaplano avec Nuel en 2008, puis Spazio Disponibile avec Neel, et publié son premier album solo, « K », sur Further Records en 2010. Son projet Voices from the Lake, avec Neel, a sorti en 2012 un album homonyme salué par la critique.", en: "Donato Dozzy, born Donato Scaramuzzi, is an Italian DJ and producer from Rome who has been playing records since the early 1980s. He is known for a hypnotic, slowly unfolding strain of techno shaped by residencies at Rome's Brancaleone and Berlin's Panorama Bar, where he handled the after-hours from 2004 to 2006. He co-founded the Aquaplano label with Nuel in 2008 and later Spazio Disponibile with Neel, and released his first solo album, \"K\", on Further Records in 2010. His Voices from the Lake project with Neel put out a widely praised self-titled album in 2012." }, origin: "Rome, Italie", since: 1983, labels: ["Aquaplano", "Spazio Disponibile", "Further Records"], sources: ["https://www.innerspaces.it/artists/donato-dozzy/"] }, // Donato Dozzy
  "dorian-craft": { slug: "dorian-craft", bio: { fr: "DJ et producteur français basé à Cannes, Dorian Craft publie depuis 2012 sur 303Lovers, CasaTech Records et Diversions Music. Ses disques relèvent de la tech house, de la deep house et de la progressive house.", en: "A French DJ and producer based in Cannes, Dorian Craft has been releasing since 2012 on 303Lovers, CasaTech Records and Diversions Music. His records sit in tech house, deep house and progressive house." }, origin: "Cannes, France", labels: ["303Lovers", "CasaTech Records", "Diversions Music"], sources: ["https://www.discogs.com/artist/2910268-Dorian-Craft"] }, // Dorian Craft
  "doudou-md": { slug: "doudou-md", bio: { fr: "Doudou MD est une DJ néerlandaise basée à Amsterdam, fille d'une chanteuse et pianiste classique néerlandaise et d'un percussionniste congolais. Elle joue surtout en vinyle une house et une techno nourries des sons britanniques, américains et allemands des années 1990, portées par des percussions marquées. Elle est résidente de la soirée house SlapFunk à Utrecht et habituée de la série amstellodamoise VBX.", en: "Doudou MD is a Dutch DJ based in Amsterdam, daughter of a Dutch classical singer-pianist and a Congolese percussionist. She plays mostly vinyl sets of house and techno drawn from 1990s British, American and German sounds, driven by strong percussion. She is a resident of the Utrecht house party SlapFunk and a regular at Amsterdam's VBX series." }, origin: "Amsterdam, Pays-Bas", sources: ["https://djmag.com/features/recognise-078-doudou-md", "https://dekmantelfestival.com/artists/doudou-md"] }, // Doudou MD
  "dr-donk": { slug: "dr-donk", bio: { fr: "Dr Donk est un DJ et producteur allemand basé à Cologne, actif dans les registres uptempo, rawstyle et hardcore. Il a construit son personnage autour d'un décor de clinique médicale, jusqu'au nom d'artiste et au titre de ses sets. Ses morceaux paraissent sur les labels du circuit hard dance — Greazy Recordz, Snakepit Music, Defqon.1 Records, Q-dance Records ou Basscon — et il joue au Bootshaus de Cologne comme à Parookaville.", en: "Dr Donk is a German DJ and producer based in Cologne, working in the uptempo, rawstyle and hardcore end of hard dance. He built his persona around a medical-clinic conceit, from the stage name down to the framing of his sets. His tracks come out on hard dance labels including Greazy Recordz, Snakepit Music, Defqon.1 Records, Q-dance Records and Basscon, and he plays Cologne's Bootshaus as well as Parookaville." }, origin: "Cologne, Allemagne", labels: ["Greazy Recordz", "Snakepit Music", "Q-dance Records"], sources: ["https://hardstyle.com/en/artists/dr-donk", "https://www.parookaville.com/de/artist/dr-donk"] }, // Dr Donk
  "dr-donk-presents-zaagstep": { slug: "dr-donk-presents-zaagstep", bio: { fr: "Dr. Donk est un producteur et DJ de la scène hard dance, connu pour le ZAAGSTEP, un format qu'il a lui-même nommé et qui croise le zaag et l'uptempo avec le dubstep et la drum & bass. Il l'a présenté à Rampage Open Air et à Parookaville, et son album ZAAGSTEP paraît en novembre 2026 sur le label bass Disciple.", en: "Dr. Donk is a hard dance producer and DJ known for ZAAGSTEP, a format he named himself, crossing zaag and uptempo with dubstep and drum & bass. He previewed it at Rampage Open Air and Parookaville, and his ZAAGSTEP album is due in November 2026 on the bass label Disciple." }, labels: ["Disciple"], sources: ["https://hardnews.nl/en/dr-donk-brings-zaagstep-to-bootshaus-with-exclusive-album-showcase/"] }, // Dr. Donk presents Zaagstep
  "dr-peacock": { slug: "dr-peacock", bio: { fr: "Stefan Dekker, néerlandais originaire de Limmen, produit de la frenchcore depuis 2010. Il a fondé Peacock Records, puis Frenchcore Worldwide en 2017 et Euphoric Frenchcore Records en 2019, et signé avec Angerfist l'album The Deadfaced Dimension (2013). Il a joué au Defqon.1, au Thunderdome et au Qlimax, où son set de 2019 était le premier set frenchcore de l'histoire de l'événement.", en: "Stefan Dekker, a Dutch producer from Limmen, has been making frenchcore since 2010. He founded Peacock Records, then Frenchcore Worldwide in 2017 and Euphoric Frenchcore Records in 2019, and made the album The Deadfaced Dimension (2013) with Angerfist. He has played Defqon.1, Thunderdome and Qlimax, where his 2019 set was the event's first ever frenchcore set." }, origin: "Limmen, Pays-Bas", since: 2010, labels: ["Peacock Records", "Frenchcore Worldwide"], sources: ["https://en.wikipedia.org/wiki/Dr._Peacock"] }, // Dr. Peacock
  "drea": { slug: "drea", bio: { fr: "Drea est une DJ espagnole, habituée du Razzmatazz à Barcelone et l'une des premières DJ espagnoles à obtenir une résidence sur Rinse FM. Ses sets partent du R&B des années 1990, passent par des edits afrobeat et finissent sur de la house vocale et du dance funk. Elle a joué au Fabric à Londres, à Else à Berlin, à La Machine du Moulin Rouge à Paris et au Paradiso d'Amsterdam, et fait la première partie de Bad Gyal au Palau Sant Jordi.", en: "Drea is a Spanish DJ, a regular at Barcelona's Razzmatazz and one of the first Spanish DJs to hold a residency on Rinse FM. Her sets start with 90s R&B, move through afrobeat edits and end on vocal house and dance funk. She has played Fabric in London, Else in Berlin, La Machine du Moulin Rouge in Paris and Paradiso in Amsterdam, and opened for Bad Gyal at the Palau Sant Jordi." }, origin: "Barcelone, Espagne", sources: ["https://hoer.live/artist/drea/", "https://ra.co/dj/drea-es/biography"] }, // Drea
  "dt43": { slug: "dt43", bio: { fr: "DT43 est un DJ et producteur de techno industrielle originaire de Maastricht, aux Pays-Bas. Il perce en 2024 : bookings sur AREA050, premier passage au Complex de Maastricht, victoire au concours DJ du festival Tegendraads, puis un set au Club Hard d'Anvers. Ses sets tiennent sur des BPM élevés, des kicks massifs et des voix sombres.", en: "DT43 is an industrial techno DJ and producer from Maastricht in the Netherlands. He broke through in 2024: bookings at AREA050, a first appearance at Complex in his home city, a win in the DJ contest for Tegendraads festival, and a set at Club Hard in Antwerp. His sets are built on high BPMs, heavy kicks and dark vocals." }, origin: "Maastricht, Pays-Bas", since: 2024, sources: ["https://events.musicofourdesire.com/artist/dt43", "https://partyflock.nl/artist/170719:DT43"] }, // DT43
  "dual-damage": { slug: "dual-damage", bio: { fr: "Dual Damage est un duo néerlandais de raw hardstyle formé par Thijs Rooijakkers et Jesper Habraken. Leur son repose sur des kicks lourds, des breaks énergiques et des mélodies planantes, avec la « PVC kick » comme signature. Ils publient notamment sur Ravage Records, avec des titres comme « Gold Sky », « Into The Wild » ou « Built 2 Break ».", en: "Dual Damage are a Dutch raw hardstyle duo made up of Thijs Rooijakkers and Jesper Habraken. Their sound rests on heavy kicks, energetic breaks and uplifting melodies, with the \"PVC kick\" as their signature. They release notably on Ravage Records, with tracks such as \"Gold Sky\", \"Into The Wild\" and \"Built 2 Break\"." }, origin: "Pays-Bas", labels: ["Ravage Records"], sources: ["https://hardstyle.com/en/artists/dual-damage", "https://www.discogs.com/artist/12581201"] }, // Dual Damage
  "dusky": { slug: "dusky", bio: { fr: "Dusky est un duo électronique anglais de Londres formé en 2011 par Alfie Granger-Howell et Nick Harriman, qui produisaient auparavant sous le nom de Solarity. Leur musique navigue entre deep house, tech house, techno et breakbeat. Après des sorties sur Anjunadeep, Aus Music, Dogmatik et Polydor, ils lancent leur propre label 17 Steps en juillet 2014 avec l'EP Love Taking Over.", en: "Dusky is an English electronic duo from London formed in 2011 by Alfie Granger-Howell and Nick Harriman, who previously produced as Solarity. Their music moves between deep house, tech house, techno and breakbeat. After releases on Anjunadeep, Aus Music, Dogmatik and Polydor, they launched their own label 17 Steps in July 2014 with the Love Taking Over EP." }, origin: "Londres, Royaume-Uni", since: 2011, labels: ["17 Steps", "Anjunadeep", "Aus Music"], sources: ["https://en.wikipedia.org/wiki/Dusky"] }, // Dusky
  "dvs1": { slug: "dvs1", bio: { fr: "DVS1 est le nom de scène de Zak Khutoretsky, DJ et producteur de techno américain installé à Minneapolis. Il s'est fait connaître par ses sets longs et par ses labels HUSH et Mistress Recordings.", en: "DVS1 is the stage name of Zak Khutoretsky, an American techno DJ and producer based in Minneapolis. He is known for his extended sets and for his labels HUSH and Mistress Recordings." }, origin: "Minneapolis, États-Unis", sources: ["https://en.wikipedia.org/wiki/DVS1"] }, // DVS1
  "dyen": { slug: "dyen", bio: { fr: "Producteur et DJ néerlandais de Rotterdam, il commence la production à dix-sept ans et sort ses premiers disques à partir de 2017. Il décrit sa musique comme de la « neorave » ou de la hard techno old school : des kicks hérités du gabber des années 1990 croisés avec des synthés trance agressifs. Il a publié sur Possession, EXHALE et Filth On Acid.", en: "Dutch producer and DJ from Rotterdam, he started producing at seventeen and put out his first records from 2017 on. He calls his music \"neorave\" or old-school hard techno: kicks inherited from 1990s gabber crossed with aggressive trance synths. He has released on Possession, EXHALE and Filth On Acid." }, origin: "Rotterdam, Pays-Bas", since: 2017, labels: ["Possession", "EXHALE", "Filth On Acid"], sources: ["https://reckless-rec.com/artists/dyen/", "https://dyen.bandcamp.com/"] }, // DYEN
  "e-x-e-c-u-t-e": { slug: "e-x-e-c-u-t-e", bio: { fr: "E.X.E.C.U.T.E est un producteur et DJ hardcore dont la discographie, référencée sur Discogs, paraît notamment sur HMA Records et Offensive Rage, avec des titres comme « Hardcore Is Your Destiny » et « Yeah We Are… ».", en: "E.X.E.C.U.T.E is a hardcore producer and DJ whose Discogs-listed discography comes out on labels including HMA Records and Offensive Rage, with tracks such as \"Hardcore Is Your Destiny\" and \"Yeah We Are…\"." }, labels: ["HMA Records", "Offensive Rage"], sources: ["https://www.discogs.com/artist/13607083-EXECUTE"] }, // E.X.E.C.U.T.E
  "eats-everything": { slug: "eats-everything", bio: { fr: "Eats Everything est le nom de scène de Daniel Pearce, DJ et producteur anglais de Bristol. Il se fait connaître en 2011 avec « Entrance Song », paru sur Pets Recordings, puis enchaîne les sorties sur Dirtybird, Hypercolour et Futureboogie. Sa house croise la bass music britannique, le garage, la techno et la jungle. Il a été élu meilleur DJ britannique par DJ Mag en 2012.", en: "Eats Everything is the stage name of Daniel Pearce, an English DJ and producer from Bristol. He came to prominence in 2011 with \"Entrance Song\" on Pets Recordings, then released on Dirtybird, Hypercolour and Futureboogie. His house crosses with UK bass, garage, techno and jungle. He was voted Best British DJ by DJ Mag in 2012." }, origin: "Bristol, Angleterre", since: 2000, labels: ["Pets Recordings", "Hypercolour", "Futureboogie", "Edible Beats"], sources: ["https://en.wikipedia.org/wiki/Eats_Everything"] }, // Eats Everything
  "ed-rush-optical": { slug: "ed-rush-optical", bio: { fr: "Ed Rush & Optical est un duo britannique de drum & bass formé par Ben Settle (Ed Rush) et Matt Quinn (Optical), associés depuis le milieu des années 1990. Ils fondent le label Virus Recordings en 1998 et publient la même année l'album Wormhole, considéré comme un disque pivot dans la formation du neurofunk. Suivront The Creeps (2000), The Original Doctor Shade (2003), Chameleon (2006) et Travel the Galaxy (2009).", en: "Ed Rush & Optical are a British drum & bass duo made up of Ben Settle (Ed Rush) and Matt Quinn (Optical), partners since the mid-1990s. They founded the Virus Recordings label in 1998 and released the album Wormhole the same year, a record widely described as pivotal in the development of neurofunk. It was followed by The Creeps (2000), The Original Doctor Shade (2003), Chameleon (2006) and Travel the Galaxy (2009)." }, origin: "Londres, Royaume-Uni", since: 1997, labels: ["Virus Recordings", "Prototype", "Metalheadz"], sources: ["https://en.wikipedia.org/wiki/Optical_(musician)", "https://en.wikipedia.org/wiki/Wormhole_(album)"] }, // Ed Rush & Optical
  "eileen": { slug: "eileen", bio: { fr: "Eileen est une DJ installée à Amsterdam, où elle s'est mise aux platines après son arrivée dans la ville. Ses sélections vont de la house au funk, à la disco, à la soul et au hip-hop, en revendiquant la house de Chicago, Detroit et New York et l'influence de Theo Parrish, Larry Heard et Ron Trent. Elle est résidente du Doka, le club en sous-sol du Volkshotel, de SAMA Space à Tbilissi et d'Operator Radio.", en: "Eileen is an Amsterdam-based DJ who took up the decks after moving to the city. Her selections run from house to funk, disco, soul and hip-hop, drawing openly on the house of Chicago, Detroit and New York and on Theo Parrish, Larry Heard and Ron Trent. She is a resident at Doka, the basement club of the Volkshotel, at SAMA Space in Tbilisi and on Operator Radio." }, origin: "Amsterdam, Pays-Bas", sources: ["https://ra.co/dj/eileen-nl/biography", "https://3voor12.vpro.nl/update~0461333f-d083-4714-9378-87ddc09963a4~eileen-soulvolle-house-vol-gemeenschapszin~.html"] }, // Eileen
  "eliasz": { slug: "eliasz", bio: { fr: "Eliasz est un DJ nantais qui débute le mix en 2016 avec son frère Verdun et s'oriente vers la tech house et la techno mélodique. Ancien membre du collectif Social Groove, il joue depuis cinq ans pour les soirées « Terror Jungle » de Philippe B au Warehouse de Nantes, et a partagé l'affiche avec Fatboy Slim, Claptone ou Chus & Ceballos. Il est membre de l'association MORE.", en: "Eliasz is a DJ from Nantes who started mixing in 2016 with his brother Verdun and moved towards tech house and melodic techno. A former member of the Social Groove collective, he has played Philippe B's \"Terror Jungle\" nights at Nantes' Warehouse for five years, and has shared bills with Fatboy Slim, Claptone and Chus & Ceballos. He is a member of the MORE association." }, origin: "Nantes, France", since: 2016, sources: ["https://www.warehouse-nantes.fr/artist/eliasz"] }, // Eliasz
  "ellen-allien": { slug: "ellen-allien", bio: { fr: "Ellen Fraatz, née à Berlin-Ouest, mixe dans les clubs de la ville depuis 1992 et façonne une techno expérimentale proche de l'IDM, qu'elle chante parfois en allemand et en anglais. Elle a fondé le label BPitch Control en 1999 et publié notamment Berlinette (2003), Thrills (2005) et Orchestra of Bubbles (2006) avec Apparat.", en: "Ellen Fraatz, born in West Berlin, has been DJing in the city's clubs since 1992 and shapes an experimental techno close to IDM, over which she sometimes sings in German and English. She founded the BPitch Control label in 1999 and released Berlinette (2003), Thrills (2005) and Orchestra of Bubbles (2006) with Apparat." }, origin: "Berlin, Allemagne", since: 1992, labels: ["BPitch Control"], sources: ["https://en.wikipedia.org/wiki/Ellen_Allien"] }, // Ellen Allien
  "ely-oaks": { slug: "ely-oaks", bio: { fr: "Ely Oaks est un DJ et producteur né à Kitzbühel, en Autriche, et installé à Berlin. Il croise la pop électronique commerciale avec la tech house et la techno, et enregistre pour le label berlinois Jinx Music. Son single « Running Around » s'est classé 32e au Royaume-Uni et 33e en Allemagne.", en: "Ely Oaks is a DJ and producer born in Kitzbühel, Austria, and based in Berlin. He crosses commercial electronic pop with tech house and techno, and records for the Berlin label Jinx Music. His single \"Running Around\" charted at No. 32 in the UK and No. 33 in Germany." }, origin: "Kitzbühel, Autriche", since: 2021, labels: ["Jinx Music"], sources: ["https://de.wikipedia.org/wiki/Ely_Oaks", "https://www.jinx-music.com/elyoaksepk"] }, // Ely Oaks
  "emilija": { slug: "emilija", bio: { fr: "Emilija est une DJ née à Vilnius, en Lituanie, et installée à Bruxelles. Elle mêle des hard house profondes, une techno sensuelle et des morceaux eurodance, sur des lignes de basse acid et des voix volontairement décalées. Son premier été de festivals, en 2023, l'a menée notamment sur une scène du Dour Festival.", en: "Emilija is a DJ born in Vilnius, Lithuania, and based in Brussels. She blends deep hard house cuts, sultry techno and eurodance tracks over acid basslines and deliberately tongue-in-cheek vocals. Her first festival summer, in 2023, included a stage at Dour Festival." }, origin: "Vilnius, Lituanie", sources: ["https://enfntsterribles.com/editorial-we-talked-to-techno-dj-emilija-about-music-fashion-and-more/", "https://www.apelago.com/artist-roster/emilija"] }, // Emilija
  "enrico-sangiuliano": { slug: "enrico-sangiuliano", bio: { fr: "Producteur et DJ italien originaire d'Émilie-Romagne, Enrico Sangiuliano perce en 2015 avec son remix de « Can You Hear Me » de DJ Boris, puis avec l'EP « Moon Rocks » qui fait de lui l'artiste techno le plus vendu sur Beatport en 2016. Il publie en juin 2018 son premier album, « Biomorph », sur le label Drumcode d'Adam Beyer. En 2022, il lance NINETOZERO, un label conçu pour ne compter que dix sorties avant de s'arrêter, accompagné de la série de soirées SOLO en all-night-long.", en: "An Italian producer and DJ from the Emilia region, Enrico Sangiuliano broke through in 2015 with his remix of DJ Boris's \"Can You Hear Me\", then with the \"Moon Rocks\" EP that made him Beatport's best-selling techno artist of 2016. In June 2018 he released his first album, \"Biomorph\", on Adam Beyer's Drumcode label. In 2022 he launched NINETOZERO, a label designed to run for exactly ten releases before ending, paired with his SOLO all-night-long party series." }, origin: "Émilie-Romagne, Italie", labels: ["Drumcode", "NINETOZERO"], sources: ["https://www.drumcode.se/artists/enrico-sangiuliano", "https://electronicgroove.com/interview-enrico-sangiuliano-2022/"] }, // Enrico Sangiuliano
  "enzo-siragusa": { slug: "enzo-siragusa", bio: { fr: "Enzo Siragusa est un DJ et producteur britannique né en 1978 de parents siciliens installés à Maidenhead, dans le Berkshire. Passé par le jungle des raves britanniques du début des années 1990, il bascule vers la house à 16 ans. Fin 2008, il lance FUSE, une soirée dominicale au 93 Feet East dans l'est de Londres, devenue une marque internationale doublée d'un label FUSE et de son pendant plus profond, INFUSE. Son son, house dubbée à basses lourdes traversée de références jungle, garage et techno, est surnommé « Fusic » par son public.", en: "Enzo Siragusa is a British DJ and producer born in 1978 to Sicilian parents settled in Maidenhead, Berkshire. A junglist raised on early-1990s UK rave culture, he switched to house at 16. In late 2008 he launched FUSE, a Sunday party at 93 Feet East in East London that grew into an international brand with its own FUSE label and a deeper sister imprint, INFUSE. His sound — dubbed-out house with heavy sub-bass, threaded with jungle, garage and techno — has been nicknamed \"Fusic\" by his audience." }, origin: "Maidenhead, Royaume-Uni", since: 2008, labels: ["FUSE", "INFUSE"], sources: ["https://djmag.com/longreads/enzo-siragusa-lighting-fuse"] }, // Enzo Siragusa
  "eric-prydz": { slug: "eric-prydz", bio: { fr: "Producteur suédois né en 1976 à Täby, près de Stockholm, il répartit sa production entre la house progressive signée Pryda et la techno plus dure de son alias Cirez D. « Call on Me » (2004) est resté cinq semaines en tête des ventes britanniques, avant « Pjanoo » (2008) et l'album Opus (2016). Ses spectacles EPIC et HOLO reposent sur des dispositifs holographiques de grande échelle.", en: "Swedish producer born in 1976 in Täby, near Stockholm, splitting his output between the progressive house he signs as Pryda and the harder techno of his Cirez D alias. \"Call on Me\" (2004) spent five weeks at number one in the UK, followed by \"Pjanoo\" (2008) and the album Opus (2016). His EPIC and HOLO shows are built around large-scale holographic staging." }, origin: "Täby, Suède", since: 2004, labels: ["Pryda", "Mouseville Records"], sources: ["https://en.wikipedia.org/wiki/Eric_Prydz"] }, // Eric Prydz
  "eris-drew": { slug: "eris-drew", bio: { fr: "Eris Drew est une DJ et productrice américaine installée près de Chicago, où elle a été résidente du Smartbar. Elle mixe en vinyle depuis les années 1990 une house traversée de breakbeats et de sons rave, qu'elle appelle la « Motherbeat ». Elle codirige avec Octo Octa le label et la soirée T4T LUV NRG, et a signé un volume de la série DJ-Kicks chez !K7.", en: "Eris Drew is an American DJ and producer based near Chicago, where she was a Smartbar resident. Since the 1990s she has played vinyl sets of house shot through with breakbeats and rave sounds, a style she calls the \"Motherbeat\". She co-runs the label and party T4T LUV NRG with Octo Octa, and recorded a volume of the DJ-Kicks series for !K7." }, origin: "Chicago, États-Unis", labels: ["T4T LUV NRG", "!K7"], sources: ["https://erisdrew.bandcamp.com/album/dj-kicks-eris-drew"] }, // Eris Drew
  "erol-alkan": { slug: "erol-alkan", bio: { fr: "Erol Alkan est un DJ, producteur et remixeur londonien né le 30 mai 1974, d'origine chypriote turque. Actif depuis 1993, il s'est d'abord fait connaître par sa soirée londonienne Trash. Il a fondé le label Phantasy Sound, sur lequel paraissent notamment les disques de Daniel Avery.", en: "Erol Alkan is a London DJ, producer and remixer born on 30 May 1974, of Turkish Cypriot descent. Active since 1993, he first made his name with his London club night Trash. He founded the Phantasy Sound label, home to Daniel Avery among others." }, origin: "Londres, Royaume-Uni", since: 1993, labels: ["Phantasy Sound"], sources: ["https://en.wikipedia.org/wiki/Erol_Alkan", "https://www.discogs.com/artist/117051-Erol-Alkan"] }, // Erol Alkan
  "eskei83": { slug: "eskei83", bio: { fr: "Eskei83 est un DJ et producteur allemand venu du turntablism : il est le premier DJ allemand sacré champion du monde Red Bull Thre3style, en 2014, et compte huit victoires en battle. Après des années en open format, il a orienté son jeu et ses productions vers la drum & bass et le dubstep, en y gardant le scratch comme signature. Il sort notamment sur Monstercat.", en: "Eskei83 is a German DJ and producer who came up through turntablism: he was the first German DJ crowned Red Bull Thre3style World Champion, in 2014, and has eight battle wins to his name. After years in open format, he steered his sets and productions towards drum & bass and dubstep, keeping scratching as his signature. He releases on Monstercat, among others." }, origin: "Allemagne", labels: ["Monstercat"], sources: ["https://www.monstercat.com/artist/eskei83", "https://openbeatz.de/en/artist/eskei83/"] }, // Eskei83
  "etienne-de-crecy": { slug: "etienne-de-crecy", bio: { fr: "Étienne de Crécy est un DJ et producteur français né le 25 février 1969. Il produit de la musique électronique, principalement de la house, et a également enregistré sous les noms EDC, Superdiscount, Minos Pour Main Basse et Mooloodjee.", en: "Étienne de Crécy is a French DJ and producer born on 25 February 1969. He produces electronic music, primarily house, and has also recorded under the names EDC, Superdiscount, Minos Pour Main Basse and Mooloodjee." }, origin: "Lyon, France", sources: ["https://en.wikipedia.org/wiki/%C3%89tienne_de_Cr%C3%A9cy", "https://musicbrainz.org/artist/f174152d-da33-46bd-8cb4-c8d24b834bf7"] }, // Etienne de Crécy
  "evil-activities": { slug: "evil-activities", bio: { fr: "Evil Activities est un projet hardcore néerlandais formé en 1998 par Telly Luyks et Kelly van Soest. Kelly van Soest en est aujourd'hui le seul membre d'origine, rejoint par E-Life en 2016.", en: "Evil Activities is a Dutch hardcore project formed in 1998 by Telly Luyks and Kelly van Soest. Kelly van Soest is now its only original member, joined by E-Life in 2016." }, origin: "Pays-Bas", since: 1998, sources: ["https://en.wikipedia.org/wiki/Evil_Activities"] }, // Evil Activities
  "fadi-mohem": { slug: "fadi-mohem", bio: { fr: "Fadi Mohem a grandi à Spandau, dans la banlieue de Berlin, et fait ses premiers pas de DJ et producteur en 2011. Résident du Berghain, il a sorti des disques sur SPANDAU20, Klockworks et Seilscheibenpfeiler, collaboré avec Ben Klock et Rødhåd, et lancé son propre label Mohem en 2022.", en: "Fadi Mohem grew up in Spandau on the outskirts of Berlin and took his first steps as a DJ and producer in 2011. A Berghain resident, he has released on SPANDAU20, Klockworks and Seilscheibenpfeiler, collaborated with Ben Klock and Rodhad, and launched his own label Mohem in 2022." }, origin: "Berlin, Allemagne", since: 2011, labels: ["SPANDAU20", "Klockworks", "Mohem"], sources: ["https://www.awakenings.com/en/artists/fadi-mohem/33902/"] }, // Fadi Mohem
  "faithless": { slug: "faithless", bio: { fr: "Faithless est un groupe de dance anglais formé à Londres en 1995 autour de Rollo, Sister Bliss et Maxi Jazz. Rollo est resté membre de studio et n'a jamais joué sur scène avec le groupe. Leur premier album, « Reverence », sort en 1996 et le plus récent, « Champion Sound », en 2025. Leur musique mêle électronique, trip hop, house et trance, et ils ont été en tête d'affiche de quatre éditions de Glastonbury.", en: "Faithless are an English dance act formed in London in 1995 around Rollo, Sister Bliss and Maxi Jazz. Rollo remained a studio-only member and has never performed live with the band. Their first album \"Reverence\" came out in 1996 and their most recent, \"Champion Sound\", in 2025. Their music blends electronic, trip hop, house and trance, and they have headlined four editions of Glastonbury." }, origin: "Londres, Angleterre", since: 1995, labels: ["Sony Music", "Arista Records"], sources: ["https://en.wikipedia.org/wiki/Faithless"] }, // Faithless
  "fakear": { slug: "fakear", bio: { fr: "Fakear est le nom de scène de Théo Le Vigoureux, producteur et DJ français né le 13 mai 1991. Il publie depuis 2011, d'abord chez Nowadays Records, une musique électronique nourrie de samples et d'influences trip-hop.", en: "Fakear is the stage name of Théo Le Vigoureux, a French producer and DJ born on 13 May 1991. He has released since 2011, first on Nowadays Records, making sample-based electronic music with trip-hop leanings." }, origin: "Caen, France", since: 2011, labels: ["Nowadays Records"], sources: ["https://en.wikipedia.org/wiki/Fakear", "https://fr.wikipedia.org/wiki/Fakear"] }, // Fakear
  "fantasm": { slug: "fantasm", bio: { fr: "Kenzo Meservey, originaire de Los Angeles et installé à Lyon, s'est fait connaître en 2023 dans la techno industrielle et rave. Ses morceaux « Requiem Psycho » avec Hades, « NFWU » avec Exproz et « Red Spider Lilly » l'ont porté jusqu'à la 93e place du Top 100 DJs de DJ Mag en 2025, où il entrait pour la première fois. Il est un habitué des soirées Verknipt.", en: "Kenzo Meservey, from Los Angeles and based in Lyon, made his mark in 2023 in industrial and rave techno. His tracks \"Requiem Psycho\" with Hades, \"NFWU\" with Exproz and \"Red Spider Lilly\" carried him to number 93 in DJ Mag's Top 100 DJs in 2025, his first appearance on the list. He is a regular at Verknipt parties." }, origin: "Los Angeles, États-Unis", since: 2023, sources: ["https://djmag.com/top100djs/2025/93/fantasm", "https://mixmagnl.com/read/fantasm-artists"] }, // Fantasm
  "faster-horses": { slug: "faster-horses", bio: { fr: "Faster Horses est un DJ et producteur britannique installé à Manchester depuis 2021, où il a construit un répertoire mêlant techno UK, jungle, garage et bassline. Repéré par le label et collectif Teletech, il joue depuis sur de grandes scènes et a réorienté ses productions comme ses sets vers le UK garage et la hard house.", en: "Faster Horses is a British DJ and producer who moved to Manchester in 2021, where he built a range taking in UK techno, jungle, garage and bassline. Picked up by the Teletech label and collective, he began playing larger stages and has since steered both his productions and his sets towards UK garage and hard house." }, origin: "Manchester, Royaume-Uni", since: 2021, sources: ["https://partyflock.nl/artist/162688:Faster-Horses", "https://www.awakenings.com/en/artists/faster-horses/382757/"] }, // Faster Horses
  "fatboy-slim": { slug: "fatboy-slim", bio: { fr: "Norman Cook, né en 1963 à Bromley et installé à Brighton, adopte l'alias Fatboy Slim en 1995 pour un big beat bâti sur des breakbeats hip-hop et l'énergie de l'acid house. L'album You've Come a Long Way, Baby (1998) et les singles « The Rockafeller Skank », « Praise You » et « Right Here, Right Now » l'ont fait sortir des clubs. Il enregistre principalement pour Skint Records.", en: "Norman Cook, born in Bromley in 1963 and based in Brighton, took the Fatboy Slim alias in 1995 for a big beat built on hip-hop breakbeats and the energy of acid house. The album You've Come a Long Way, Baby (1998) and the singles \"The Rockafeller Skank\", \"Praise You\" and \"Right Here, Right Now\" carried him well beyond the clubs. He records mainly for Skint Records." }, origin: "Bromley, Royaume-Uni", since: 1995, labels: ["Skint Records", "Southern Fried Records"], sources: ["https://en.wikipedia.org/wiki/Fatboy_Slim"] }, // Fatboy Slim
  "fatima-hajji": { slug: "fatima-hajji", bio: { fr: "Fatima Hajji est une DJ, productrice et patronne de label espagnole née à Salamanque, aujourd'hui installée près de Madrid. Fille d'un père marocain, elle a grandi entre les musiques arabes de la maison et la techno découverte à l'adolescence. Son premier EP, « Turblasmin », sort en 2008 sur Xtiluxe Records ; « Violines », en 2013, reprend un extrait du chanteur de raï Cheb Khaled. Elle joue une hard techno rapide et frontale et dirige le label Silver M.", en: "Fatima Hajji is a Spanish DJ, producer and label owner born in Salamanca and now based near Madrid. The daughter of a Moroccan father, she grew up between the Arabic music played at home and the techno she found as a teenager. Her first EP, \"Turblasmin\", came out in 2008 on Xtiluxe Records; \"Violines\", in 2013, sampled the raï singer Cheb Khaled. She plays fast, front-facing hard techno and runs the Silver M label." }, origin: "Salamanque, Espagne", since: 2008, labels: ["Silver M"], sources: ["https://djmag.com/features/fatima-hajji-force-nature", "https://musicbrainz.org/artist/0c0f88db-c1f2-4f3b-8bbf-8cace9196c59"] }, // Fatima Hajji
  "fava": { slug: "fava", bio: { fr: "MC et DJ drum & bass allemand, Fava commence en 2001 en organisant les soirées Jungle Club à Fribourg. Il tient le micro sur les scènes de Hospitality et de Liquicity avant de passer aux platines en 2019, à l'invitation du Liquicity Festival pour un b2b avec MC Mota. Il publie sur SUNANDBASS Recordings, V Recordings et son propre label Beatalistics.", en: "German drum & bass MC and DJ Fava started out in 2001 running the Jungle Club nights in his home town of Freiburg. He hosted stages for Hospitality and Liquicity before moving to the decks in 2019, when Liquicity Festival invited him to play back-to-back with MC Mota. He releases on SUNANDBASS Recordings, V Recordings and his own label Beatalistics." }, origin: "Fribourg, Allemagne", since: 2001, labels: ["Beatalistics", "V Recordings"], sources: ["https://ukf.com/read/we-need-to-talk-about-fava/"] }, // Fava
  "felix-jaehn": { slug: "felix-jaehn", bio: { fr: "Felix Jaehn est un DJ et producteur allemand né le 28 août 1994 à Hambourg. Son remix de « Cheerleader » d'OMI, numéro un du Billboard Hot 100 en 2015, l'a fait connaître à l'international. Sa production relève de la house, de la tropical house et de la dance-pop.", en: "Felix Jaehn is a German DJ and record producer born on 28 August 1994 in Hamburg. Their remix of OMI's \"Cheerleader\" topped the Billboard Hot 100 in 2015 and brought them international attention. Their output sits in house, tropical house and dance-pop." }, origin: "Hambourg, Allemagne", since: 2013, labels: ["Virgin"], sources: ["https://en.wikipedia.org/wiki/Felix_Jaehn", "https://api.discogs.com/database/search?artist=Felix+Jaehn&type=release"] }, // Felix Jaehn
  "felix-krocher": { slug: "felix-krocher", bio: { fr: "Felix Kröcher est un DJ et producteur de techno allemand né le 1er décembre 1983 à Francfort-sur-le-Main. Il a d'abord officié sous le nom de DJ Bundesschranzler, mot-valise formé sur « Bundeskanzler » et « schranz », le terme qui désigne la techno dure allemande dont il est issu.", en: "Felix Kröcher is a German techno DJ and producer born on 1 December 1983 in Frankfurt am Main. He first performed as DJ Bundesschranzler, a portmanteau of \"Bundeskanzler\" and \"schranz\", the term for the hard German techno he came out of." }, origin: "Francfort-sur-le-Main, Allemagne", sources: ["https://www.discogs.com/artist/102027-Felix-Kröcher", "https://www.discogs.com/artist/243560-DJ-Bundesschranzler"] }, // Felix Kröcher
  "fenim0re": { slug: "fenim0re", bio: { fr: "FENIM0RE est un DJ et producteur de techno basé à Berlin. Ses disques paraissent depuis 2025 sur Agora Records (« Neubau », « Mediaval »), Grab The Groove (« Invasive Thoughts ») et des compilations de BCCO et Transition, entre techno et hard techno. Il a signé le 478e épisode du podcast HATE.", en: "FENIM0RE is a Berlin-based techno DJ and producer. Since 2025 his records have come out on Agora Records (\"Neubau\", \"Mediaval\"), Grab The Groove (\"Invasive Thoughts\") and compilations for BCCO and Transition, between techno and hard techno. He recorded the 478th episode of the HATE podcast." }, origin: "Berlin, Allemagne", since: 2025, labels: ["Agora Records", "Grab The Groove"], sources: ["https://www.discogs.com/release/34140304-Fenim0re-Invasive-Thoughts", "https://soundcloud.com/hate_music/fenimore-hate-podcast-478"] }, // FENIM0RE
  "feral": { slug: "feral", bio: { fr: "Feral est un DJ et producteur italien basé à Rome, connu pour ses disques sur le label suédois Hypnus Records — « Ultraviolet Radiation » (2020), « Crossroads » (2022) et « Mind Garden » (2024). Sa deep techno atmosphérique s'appuie sur l'expérimentation hardware et sur les percussions tribales. Il a fondé son propre label, Aube Rouge, en 2020.", en: "Feral is an Italian DJ and producer based in Rome, known for his records on the Swedish label Hypnus Records — \"Ultraviolet Radiation\" (2020), \"Crossroads\" (2022) and \"Mind Garden\" (2024). His atmospheric deep techno is built on hardware experimentation and tribal percussion. He founded his own label, Aube Rouge, in 2020." }, origin: "Rome, Italie", labels: ["Hypnus Records", "Aube Rouge"], sources: ["https://hypnusrecords.com/feral", "https://mnmt.no/magazine/2020/12/02/an-interview-with-feral-about-his-new-label-laube-rouge-and-his-interest-in-old-amusement-parks/"] }, // Feral
  "ferry-corsten": { slug: "ferry-corsten", bio: { fr: "DJ, producteur et patron de label néerlandais né le 4 décembre 1973 à Rotterdam, Ferry Corsten produit de la trance sous son nom et sous les alias Moonman, Albion et Pulp Victim. Il est aussi la moitié des projets Gouryella et Veracocha, et dirige le label Flashover Recordings.", en: "Dutch DJ, producer and label owner born on 4 December 1973 in Rotterdam, Ferry Corsten makes trance under his own name and as Moonman, Albion and Pulp Victim. He is also half of the Gouryella and Veracocha projects, and runs the Flashover Recordings label." }, origin: "Rotterdam, Pays-Bas", since: 1993, labels: ["Flashover Recordings", "Tsunami Records"], sources: ["https://www.discogs.com/artist/4223-Ferry-Corsten", "http://www.ferrycorsten.com"] }, // Ferry Corsten
  "finnebassen": { slug: "finnebassen", bio: { fr: "Finnebassen est un DJ et producteur norvégien basé à Oslo, où il jouait déjà avant sa percée internationale en 2012. Son morceau « If You Only Knew », sorti sur le label britannique Electronique, atteint la 3e place du classement nu-disco de Beatport, et il publie la même année deux titres sur Noir Music. Il joue lui-même les parties de guitare qu'on entend sur nombre de ses productions house, mélodiques et teintées de disco.", en: "Finnebassen is a Norwegian DJ and producer based in Oslo, where he was already playing before his international breakthrough in 2012. His track \"If You Only Knew\", released on UK label Electronique, reached number 3 on Beatport's nu-disco chart, and the same year he put out two tracks on Noir Music. He plays himself the guitar parts heard on many of his melodic, disco-tinged house productions." }, origin: "Oslo, Norvège", since: 2012, labels: ["Electronique", "Noir Music"], sources: ["https://www.deephouseamsterdam.com/exclusive-interview-with-finnebassen/", "https://www.traxsource.com/artist/87390/"] }, // Finnebassen
  "fisher": { slug: "fisher", bio: { fr: "Fisher est le nom de scène de Paul Nicholas Fisher, producteur et DJ australien né en 1985 sur la Gold Coast. Il a couru plusieurs saisons du circuit qualificatif de la World Surf League avant de se tourner vers la musique en 2012, d'abord au sein du duo Cut Snake. En solo, il produit une house teintée de tech house parue sur Dirtybird et sur son label Catch & Release, et a été nommé aux ARIA Music Awards et aux Grammy Awards.", en: "Fisher is the stage name of Paul Nicholas Fisher, an Australian producer and DJ born in 1985 on the Gold Coast. He spent several seasons on the World Surf League Qualifying Series before turning to music in 2012, first as one half of the duo Cut Snake. Solo, he makes house shot through with tech house, released on Dirtybird and on his own Catch & Release label, and has been nominated for both ARIA Music Awards and Grammy Awards." }, origin: "Gold Coast, Australie", since: 2012, labels: ["Dirtybird", "Catch & Release"], sources: ["https://en.wikipedia.org/wiki/Fisher_(musician)"] }, // Fisher
  "fjaak": { slug: "fjaak", bio: { fr: "FJAAK est un projet techno berlinois formé en 2009. Ses disques sont parus sur 50Weapons puis sur son propre label FJAAK, et sa production croise la techno avec des rythmes breakbeat et electro.", en: "FJAAK is a Berlin techno project formed in 2009. Its records came out on 50Weapons and then on its own FJAAK label, crossing techno with breakbeat and electro rhythms." }, origin: "Berlin, Allemagne", since: 2009, labels: ["FJAAK", "50Weapons"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:FJAAK&fmt=json", "https://api.discogs.com/database/search?artist=FJAAK&type=release"] }, // FJAAK
  "floating-points": { slug: "floating-points", bio: { fr: "Sam Shepherd, originaire de Manchester, mène en parallèle une carrière électronique et un doctorat en neurosciences obtenu à University College London. Ses albums Elaenia (2015), Crush (2019) et Cascade (2024) croisent house, jazz et écriture orchestrale, et il dirige le label Pluto Records. Promises (2021), enregistré avec Pharoah Sanders et le London Symphony Orchestra, a été nommé au Mercury Prize.", en: "Sam Shepherd, from Manchester, runs an electronic career alongside a PhD in neuroscience taken at University College London. His albums Elaenia (2015), Crush (2019) and Cascade (2024) cross house, jazz and orchestral writing, and he runs the Pluto Records label. Promises (2021), recorded with Pharoah Sanders and the London Symphony Orchestra, was nominated for the Mercury Prize." }, origin: "Manchester, Royaume-Uni", since: 2009, labels: ["Pluto Records"], sources: ["https://en.wikipedia.org/wiki/Floating_Points"] }, // Floating Points
  "flymeon": { slug: "flymeon", bio: { fr: "Flymeon est un DJ et producteur français dont le son croise la hard techno et l'imaginaire du heavy metal — textures, instruments et univers visuel compris. Il publie sur Rave Alert Records l'EP « Paris Under Control » et son titre « Paris Acid City » (2023), puis les EP « Blood On The Dancefloor » et « Raving Mothafucka ».", en: "Flymeon is a French DJ and producer whose sound crosses hard techno with the world of heavy metal — textures, instruments and visual identity included. On Rave Alert Records he released the \"Paris Under Control\" EP and its track \"Paris Acid City\" (2023), followed by the \"Blood On The Dancefloor\" and \"Raving Mothafucka\" EPs." }, origin: "France", since: 2020, labels: ["Rave Alert Records"], sources: ["https://ravealert.bandcamp.com/album/paris-acid-city", "https://www.cultr.com/news/flymeon-presents-his-new-banger-paris-acid-city/", "https://harderstylemap.com/artist/flymeon/"] }, // Flymeon
  "folamour": { slug: "folamour", bio: { fr: "Folamour, de son vrai nom Bruno Boumendil, est un DJ et producteur français, fondateur du label FHUO Records. Formé à la guitare, à la batterie et aux percussions, il se fait remarquer avec l'EP Deeply Rooted Vibes vers 2014, puis avec les albums Umami en 2017, Ordinary Drugs en 2019 et The Journey en 2021, où il délaisse les samples pour des instruments joués et des textes originaux. Son répertoire mêle house, disco et future jazz.", en: "Folamour, real name Bruno Boumendil, is a French DJ and producer and the founder of FHUO Records. Trained on guitar, drums and percussion, he broke through with the EP Deeply Rooted Vibes around 2014, then with the albums Umami in 2017, Ordinary Drugs in 2019 and The Journey in 2021, on which he set samples aside for live instruments and original lyrics. His catalogue blends house, disco and future jazz." }, origin: "France", since: 2014, labels: ["FHUO Records"], sources: ["https://fr.wikipedia.org/wiki/Folamour_(musicien)", "https://en.wikipedia.org/wiki/Folamour"] }, // Folamour
  "four-tet": { slug: "four-tet", bio: { fr: "Kieran Hebden, né en 1977 à Putney (Londres), enregistre sous le nom de Four Tet une électronique bricolée à partir de samples, d'abord au sein du groupe post-rock Fridge. Ses albums « Rounds » (2003) et « There Is Love in You » (2010) l'ont établi en solo, et il a enregistré plusieurs disques d'improvisation avec le batteur de jazz Steve Reid ainsi que des collaborations avec Burial et Thom Yorke. Il a aussi produit Omar Souleyman et arrangé l'album « Sound Ancestors » de Madlib en 2021.", en: "Born in Putney, London in 1977, Kieran Hebden records as Four Tet, making sample-built electronic music, first within the post-rock band Fridge. His albums \"Rounds\" (2003) and \"There Is Love in You\" (2010) established him as a solo artist, and he cut several improvised records with jazz drummer Steve Reid as well as collaborations with Burial and Thom Yorke. He has also produced Omar Souleyman and arranged Madlib's 2021 album \"Sound Ancestors\"." }, origin: "Londres, Angleterre", sources: ["https://en.wikipedia.org/wiki/Four_Tet"] }, // Four Tet
  "fox-stevenson": { slug: "fox-stevenson", bio: { fr: "Fox Stevenson est le nom de scène de Stanley Stevenson-Byrne, auteur-compositeur, DJ et producteur anglais né le 25 janvier 1993 à Leeds. Anciennement connu sous les noms Stan SB et Stan SSB, il produit de la bass music, principalement de la drum and bass et du glitch hop, et a publié deux albums et onze EP.", en: "Fox Stevenson is the stage name of Stanley Stevenson-Byrne, an English singer-songwriter, DJ and producer born on 25 January 1993 in Leeds. Formerly known as Stan SB and Stan SSB, he produces bass music, mostly drum and bass and glitch hop, and has released two albums and eleven EPs." }, origin: "Leeds, Royaume-Uni", sources: ["https://en.wikipedia.org/wiki/Fox_Stevenson"] }, // Fox Stevenson
  "francesco-del-garda": { slug: "francesco-del-garda", bio: { fr: "Francesco Del Garda est un DJ italien qui joue exclusivement en vinyle, format auquel il est resté fidèle depuis ses seize ans. Ses sets circulent entre house, electro, garage, techno et minimale, et reposent sur des disques rares dénichés au fil des bacs. En 2017, il a lancé son label Timeless pour publier de jeunes producteurs au style marqué. Il joue aussi bien en cave qu'en plein air, notamment au Dimensions Festival.", en: "Francesco Del Garda is an Italian DJ who plays vinyl only, a format he has stuck with since he was sixteen. His sets move between house, electro, garage, techno and minimal, built on rare records turned up through years of digging. In 2017 he launched his label Timeless to put out young producers with a distinctive style. He plays basements and open-air festivals alike, including Dimensions Festival." }, origin: "Italie", labels: ["Timeless"], sources: ["https://www.horstartsandmusic.com/programme/francesco-del-garda", "https://www.paradisecity.be/en/bands/francesco-del-garda"] }, // Francesco Del Garda
  "franky-kloeck": { slug: "franky-kloeck", bio: { fr: "Franky Kloeck est un DJ belge qui commence à mixer en 1992 au Barocci, à Zundert, avant de devenir résident du Cherry Moon pendant quatre ans. Il enchaîne ensuite les résidences dans les clubs belges Carat, Bel-Air, Extreme, BBC, Globe et Illusion. Il fait partie du projet Cherry Moon Trax, publié sur Bonzai Records, qui a marqué la trance et la hard house belges des années 1990.", en: "Franky Kloeck is a Belgian DJ who began playing in 1992 at Barocci in Zundert before becoming a Cherry Moon resident for four years. He then held residencies at the Belgian clubs Carat, Bel-Air, Extreme, BBC, Globe and Illusion. He was part of the Cherry Moon Trax project, released on Bonzai Records, which shaped Belgian trance and hard house in the 1990s." }, origin: "Belgique", since: 1992, labels: ["Bonzai Records"], sources: ["https://partyflock.nl/artist/548/biography"] }, // Franky Kloeck
  "freddi": { slug: "freddi", bio: { fr: "DJ et producteur basé à Amsterdam, Freddi oriente depuis peu ses sets vers la hard house, la trance et le progressive. Son remix de « Misschien (Kwijt) » de Gotu Jim l'a fait connaître, et ses propres productions ont été jouées par Job Jobse et Rozie.", en: "An Amsterdam-based DJ and producer, Freddi has recently steered his sets towards hard house, trance and progressive. His remix of Gotu Jim's \"Misschien (Kwijt)\" brought him attention, and his own productions have been picked up by Job Jobse and Rozie." }, origin: "Amsterdam, Pays-Bas", sources: ["https://fundamentalceg.nl/lineup.html"] }, // Freddi
  "freddy-k": { slug: "freddy-k", bio: { fr: "Freddy K, de son vrai nom Alessio Armeni, est un DJ et producteur italien installé à Berlin depuis 2009. À Rome, il lance en 1993 l'émission puis le mouvement Virus (radio, disquaire, soirées), sort son premier EP Control sur ACV et l'album Rage Of Age en 1995. Il a cofondé le label Elettronica Romana avec Sandro Nasonte, créé K1971 en 2005 puis le label KEY Vinyl en 2011. Il est connu pour ses sets marathon en vinyle.", en: "Freddy K, real name Alessio Armeni, is an Italian DJ and producer who has been based in Berlin since 2009. In Rome he launched the Virus radio show and movement in 1993 (radio, record shop, parties), released his first EP Control on ACV and the album Rage Of Age in 1995. He co-founded the Elettronica Romana label with Sandro Nasonte, started K1971 in 2005 and the KEY Vinyl label in 2011. He is known for his marathon vinyl-only sets." }, origin: "Rome, Italie", since: 1993, labels: ["KEY Vinyl", "K1971", "Elettronica Romana"], sources: ["https://www.awakenings.com/en/artists/freddy-k/214347/"] }, // Freddy K
  "frederic": { slug: "frederic", bio: { fr: "Frederic. est un DJ, producteur et organisateur installé à Berlin, actif en Europe depuis 2017. Ses sets tiennent des tempos élevés avec des passages mélodiques et atmosphériques. Il est co-fondateur du collectif et label Selected, né il y a une dizaine d'années pour ouvrir des dates aux DJs débutants, et a sorti Fainted en 2022 puis l'EP Rather Be With You en 2025. Il a joué pour HÖR, Boiler Room, Blackworks et Teletech.", en: "Frederic. is a DJ, producer and promoter based in Berlin, active across Europe since 2017. His sets hold high tempos with melodic, atmospheric passages. He co-founded the Selected crew and label about a decade ago to give emerging DJs dates to play, and released Fainted in 2022 and the EP Rather Be With You in 2025. He has played for HÖR, Boiler Room, Blackworks and Teletech." }, origin: "Berlin, Allemagne", since: 2017, labels: ["Selected", "Raise Records"], sources: ["https://mixmagde.com/read/frederic-s-selected-redefining-the-energy-of-modern-techno-artists", "https://www.attackmagazine.com/news/frederic-confirms-2026-festival-appearances/"] }, // Frederic.
  "funk-tribu": { slug: "funk-tribu", bio: { fr: "Funk Tribu est un DJ et producteur colombien né à Bogotá et installé à Berlin. Il travaille une techno rapide nourrie de hard trance et de hard groove, avec des lignes de basse funk. Le titre « Phonky Tribu », sorti en 2021, l'a fait connaître au-delà de la Colombie et lui a ouvert les grands festivals européens.", en: "Funk Tribu is a Colombian DJ and producer born in Bogotá and based in Berlin. He works a fast techno fed by hard trance and hard groove, with funk-leaning basslines. His 2021 track \"Phonky Tribu\" brought him attention beyond Colombia and opened the doors of major European festivals." }, origin: "Bogotá, Colombie", sources: ["https://www.discogs.com/artist/8301698-Funk-Tribu", "https://www.insomniac.com/music/artists/funk-tribu/"] }, // Funk Tribu
  "furyan": { slug: "furyan", bio: { fr: "Furyan, de son vrai nom Charley Schrijn, est un DJ et producteur hardcore de Rotterdam. Il commence à mixer du hard dance à dix-huit ans et décroche une résidence au Hollywood Music Hall, puis se consacre entièrement au hardcore en 2009. Son premier disque solo sort sur Rotterdam Records en 2010 avant qu'il ne rejoigne Neophyte Records en 2013.", en: "Furyan, real name Charley Schrijn, is a hardcore DJ and producer from Rotterdam. He began playing hard dance records at eighteen and earned a residency at the Hollywood Music Hall, then turned fully to hardcore in 2009. His first solo release came out on Rotterdam Records in 2010 before he joined Neophyte Records in 2013." }, origin: "Rotterdam, Pays-Bas", since: 2009, labels: ["Neophyte Records", "Rotterdam Records"], sources: ["https://partyflock.nl/artist/53657/biography", "https://www.djguide.nl/djinfo.p?djid=9277&language=en"] }, // Furyan
  "future-666": { slug: "future-666", bio: { fr: "DJ et producteur techno, Viktor alias future.666 s'installe à Berlin après ses premiers sets et y joue pour BCCO dès 2017, dont il devient résident. Il dirige le label et le collectif BCCO, qui organise des soirées dans plusieurs pays. Son mixage repose sur trois à quatre CDJ superposés, pour des sets rapides et tournoyants.", en: "Techno DJ and producer Viktor, aka future.666, moved to Berlin after his first sets and played for BCCO from 2017, later becoming a resident. He runs the BCCO label and collective, which throws parties in several countries. He mixes on three to four layered CDJs, for fast, spiralling sets." }, origin: "Berlin, Allemagne", labels: ["BCCO"], sources: ["https://ra.co/dj/future666/biography", "https://bcco.bandcamp.com/album/bccova18-curated-by-future-666"] }, // Future.666
  "g-ha": { slug: "g-ha", bio: { fr: "g-HA est le nom de scène de Geir Holger, DJ et programmateur norvégien basé à Oslo. Avec Ola « Olanskii » Smith-Simonsen, il fonde la série de soirées Sunkissed puis tient la résidence du vendredi (Frædag) au club Jaeger, ouvert par Olanskii à Oslo en 2011. Le duo joue un répertoire large, du disco à la micro-house en passant par la techno.", en: "g-HA is the stage name of Geir Holger, a Norwegian DJ and promoter based in Oslo. With Ola \"Olanskii\" Smith-Simonsen he founded the Sunkissed party series and holds the Friday (Frædag) residency at Jaeger, the club Olanskii opened in Oslo in 2011. The duo plays a wide repertoire, from disco to micro-house by way of techno." }, origin: "Oslo, Norvège", sources: ["https://jaegeroslo.no/residents/g-ha-olanskii/"] }, // g-HA
  "g-ha-olanskii": { slug: "g-ha-olanskii", bio: { fr: "g-HA & Olanskii est le duo norvégien formé par Geir « g-HA » Holger et Ola « Olanskii » Smith-Simonsen, à Oslo. Ils ont lancé la série de soirées Sunkissed puis la résidence Frædag du Jaeger, club fondé par Olanskii, et ont tenu des résidences au Panorama Bar, au Fabric et au Robert Johnson.", en: "g-HA & Olanskii are the Norwegian duo of Geir \"g-HA\" Holger and Ola \"Olanskii\" Smith-Simonsen, based in Oslo. They started the Sunkissed party series and then the Frædag residency at Jaeger, the club Olanskii founded, and have held residencies at Panorama Bar, Fabric and Robert Johnson." }, origin: "Oslo, Norvège", sources: ["https://jaegeroslo.no/residents/g-ha-olanskii/"] }, // g-HA & Olanskii
  "gabry-ponte": { slug: "gabry-ponte", bio: { fr: "Gabry Ponte, de son vrai nom Gabriele Ponte, est un DJ et producteur italien né en 1973. Il est membre du groupe Eiffel 65, avec lequel il signe « Blue (Da Ba Dee) », et poursuit depuis une carrière solo entre eurodance et house.", en: "Gabry Ponte, real name Gabriele Ponte, is an Italian DJ and producer born in 1973. He is a member of Eiffel 65, with whom he made \"Blue (Da Ba Dee)\", and has since pursued a solo career between eurodance and house." }, origin: "Turin, Italie", labels: ["BlissCorporation", "Dance And Love"], sources: ["https://en.wikipedia.org/wiki/Gabry_Ponte", "https://fr.wikipedia.org/wiki/Gabry_Ponte"] }, // Gabry Ponte
  "galrav": { slug: "galrav", bio: { fr: "Galrav est un DJ finlandais de musiques hard, actif depuis plus de vingt ans dans la scène hard dance de Finlande. Ses sets mêlent hard techno récente et classiques du hard des années 2000.", en: "Galrav is a Finnish hard dance DJ who has been active in Finland's hard music scene for more than twenty years. His sets mix current hard techno with 2000s hard dance classics." }, origin: "Finlande", sources: ["https://soundcloud.com/galrav"] }, // Galrav
  "gandoolf": { slug: "gandoolf", bio: { fr: "DJ originaire de Carnac et basé à Nantes, Gandoolf est le fondateur et résident du collectif La Nouvelle. Il joue du hardgroove, de la schranz et de la hard music, entre les registres de Charlotte de Witte, Klangkuenstler et Svetec. Il s'est produit aux Plages Électroniques et à l'Écume Festival, et fait partie des résidents réguliers du Warehouse à Nantes.", en: "A DJ from Carnac and based in Nantes, Gandoolf founded and resides at the La Nouvelle collective. He plays hardgroove, schranz and hard music, in the register of Charlotte de Witte, Klangkuenstler and Svetec. He has played Plages Électroniques and Écume Festival, and is a regular at Nantes club Warehouse." }, origin: "Carnac, France", sources: ["https://warehouse-nantes.fr/artist/gandoolf"] }, // Gandoolf
  "gerd-janson": { slug: "gerd-janson", bio: { fr: "Gerd Janson est un DJ, producteur et journaliste musical allemand, élevé près de Francfort. Il a fondé le label Running Back et tient depuis 2000 une résidence au Robert-Johnson de Francfort aux côtés de Thomas Hammann. Il produit aussi au sein du duo Tuff City Kids avec Phillip Lauer.", en: "Gerd Janson is a German DJ, producer and music journalist raised just outside Frankfurt. He founded the Running Back label and has held a residency at Frankfurt's Robert-Johnson club alongside Thomas Hammann since 2000. He also produces as one half of Tuff City Kids with Phillip Lauer." }, origin: "Francfort, Allemagne", labels: ["Running Back"], sources: ["https://www.awakenings.com/en/artists/gerd-janson/538/"] }, // Gerd Janson
  "gissa": { slug: "gissa", bio: { fr: "GISSA est un producteur et DJ néerlandais basé à Alphen aan den Rijn. Il joue une house percussive et accrocheuse, taillée pour les grandes salles, après des débuts à quatorze ans sur des rythmiques hip-hop. Il publie chez Insomniac Records et AWD, avec un passage annoncé chez Armada Music, et joue au Melkweg, au Cuckoosnest et à Thuishaven.", en: "GISSA is a Dutch producer and DJ based in Alphen aan den Rijn. He plays a percussive, hook-led strain of house built for big rooms, after starting out at fourteen on hip-hop drums. He releases on Insomniac Records and AWD, with a run announced on Armada Music, and plays Melkweg, Cuckoosnest and Thuishaven." }, origin: "Alphen aan den Rijn, Pays-Bas", labels: ["Insomniac Records", "AWD"], sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/gissa/2730656/"] }, // Gissa
  "globul": { slug: "globul", bio: { fr: "Globul est un DJ et organisateur belge, résident du Rockerill à Charleroi. Organisateur depuis la fin des années 1990 et DJ depuis plus de vingt ans, il commence à mixer sérieusement en 1992 dans une veine techno de Detroit et acid, après un parcours d'auditeur passé par Kraftwerk, la new wave et l'industriel (Front 242, Nitzer Ebb). Ses sets mêlent disco, acid, tech, Detroit, deep-tech et rythmes tribaux ; il co-organise les soirées Always Underground et Sound Memory.", en: "Globul is a Belgian DJ and promoter, a resident at Rockerill in Charleroi. A promoter since the late 1990s and a DJ for more than twenty years, he started mixing seriously in 1992 in a Detroit techno and acid vein, after a listening path that ran from Kraftwerk through new wave and industrial (Front 242, Nitzer Ebb). His sets mix disco, acid, tech, Detroit, deep-tech and tribal rhythms, and he co-runs the Always Underground and Sound Memory nights." }, origin: "Charleroi, Belgique", since: 1992, sources: ["https://www.rockerill.com/agenda/les-aperos-industriels-fetent-globul/2660/"] }, // Globul
  "gogol-bordello": { slug: "gogol-bordello", bio: { fr: "Gogol Bordello est un groupe de punk rock américain formé en 1999 dans le Lower East Side de Manhattan par des musiciens venus du monde entier. Son répertoire mêle musiques rom et ukrainienne, punk et dub, avec accordéon et violon, et le groupe est connu pour ses concerts très théâtraux et ses tournées permanentes. Son chanteur Eugene Hütz a partagé l'affiche d'Everything Is Illuminated (2005) avec Elijah Wood.", en: "Gogol Bordello is an American punk rock band formed in 1999 on Manhattan's Lower East Side by musicians from all over the world. Its repertoire mixes Romani and Ukrainian music with punk and dub, using accordion and violin, and the band is known for theatrical shows and constant touring. Singer Eugene Hütz co-starred in Everything Is Illuminated (2005) with Elijah Wood." }, origin: "New York, États-Unis", since: 1999, sources: ["https://en.wikipedia.org/wiki/Gogol_Bordello"] }, // Gogol Bordello
  "goldie": { slug: "goldie", bio: { fr: "Clifford Joseph Price, né en 1965 en Angleterre, se fait d'abord connaître comme graffeur avant de devenir une figure de la jungle et de la drum and bass britanniques des années 1990. Il publie des disques sous les noms Rufige Kru et Metalheads et cofonde le label Metalheadz. Son album « Timeless » entre en 1995 à la septième place des charts britanniques. Il est aussi acteur, notamment dans « Le monde ne suffit pas » et « Snatch ».", en: "Born in England in 1965, Clifford Joseph Price first made his name as a graffiti artist before becoming a central figure in 1990s UK jungle and drum and bass. He released records as Rufige Kru and Metalheads and co-founded the Metalheadz label. His album \"Timeless\" entered the UK charts at number seven in 1995. He also acts, notably in \"The World Is Not Enough\" and \"Snatch\"." }, origin: "Angleterre", labels: ["Metalheadz"], sources: ["https://en.wikipedia.org/wiki/Goldie"] }, // Goldie
  "golpe": { slug: "golpe", bio: { fr: "Golpe est un DJ et producteur de hard techno actif depuis le début des années 2000. Ses disques paraissent notamment sur Animasola, Cannibal Society et Audiocode, et son EP « Hard Techno Nation », remixé par SveTec, est sorti sur Mad Made.", en: "Golpe is a hard techno DJ and producer who has been active since the early 2000s. His records have come out on Animasola, Cannibal Society and Audiocode among others, and his \"Hard Techno Nation\" EP, remixed by SveTec, was released on Mad Made." }, since: 2003, labels: ["Cannibal Society", "Animasola", "Mad Made"], sources: ["https://madmade.bandcamp.com/album/hard-techno-nation-ep", "https://www.beatport.com/artist/golpe/93715"] }, // Golpe
  "gpf": { slug: "gpf", bio: { fr: "GPF, pour Greazy Puzzy Fuckerz, est un duo hardcore reconnaissable à son « pipe kick », un kick fortement distordu, et aux masques que ses membres portent sur scène. Ils ont fondé leur label GPF Recordz en 2017 et publié l'album Lovin' Ain't Greazy en 2018. Ils ont collaboré avec Timmy Trumpet, Paul Elstak et Primate.", en: "GPF, short for Greazy Puzzy Fuckerz, is a hardcore duo recognisable by its \"pipe kick\", a heavily distorted kick, and by the masks its members wear on stage. They founded their label GPF Recordz in 2017 and released the album Lovin' Ain't Greazy in 2018. They have worked with Timmy Trumpet, Paul Elstak and Primate." }, since: 2017, labels: ["GPF Recordz"], sources: ["https://hardstyle.com/en/artists/gpf", "https://edm.fandom.com/wiki/GPF"] }, // GPF
  "grace-dahl": { slug: "grace-dahl", bio: { fr: "Grace Dahl est une DJ et productrice techno née à Budapest et installée à Amsterdam, d'origine finlandaise et hongroise. Ses parents organisaient des soirées électroniques à Budapest dans les années 1990. Elle commence à sortir des disques en 2018 sur Coincidence Records, puis publie l'EP « Dark Side of Desire » sur Khazad Records, et fonde son propre label Serial Disc Touchers en 2024. Elle est résidente des soirées Vault Sessions.", en: "Grace Dahl is a techno DJ and producer born in Budapest and based in Amsterdam, of Finnish and Hungarian descent. Her parents ran electronic music events in Budapest in the 1990s. She began releasing in 2018 on Coincidence Records, followed by the EP \"Dark Side of Desire\" on Khazad Records, and founded her own label Serial Disc Touchers in 2024. She is a resident at Vault Sessions." }, origin: "Budapest, Hongrie (basée à Amsterdam)", since: 2018, labels: ["Serial Disc Touchers"], sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/grace-dahl/20716/", "https://909originals.com/2025/03/26/the-most-exciting-part-of-this-journey-is-that-nothing-is-ever-static-grace-dahl-chats-to-909originals/"] }, // Grace Dahl
  "groove-armada": { slug: "groove-armada", bio: { fr: "Groove Armada est un duo électronique anglais composé d'Andy Cato et Tom Findlay, formé à Londres après qu'un ami commun les eut présentés. Leur soirée « Captain Sensual at the Helm of the Groove Armada » leur a donné leur nom. Ils se font connaître en 1997 avec « At the River », qui sample « Old Cape Cod » de Patti Page, puis avec « I See You Baby » et « Superstylin' ». Ils ont publié neuf albums studio.", en: "Groove Armada are an English electronic duo made up of Andy Cato and Tom Findlay, formed in London after a mutual friend introduced them. Their club night \"Captain Sensual at the Helm of the Groove Armada\" gave them their name. They broke through in 1997 with \"At the River\", which samples Patti Page's \"Old Cape Cod\", then with \"I See You Baby\" and \"Superstylin'\". They have released nine studio albums." }, origin: "Londres, Angleterre", since: 1996, labels: ["Columbia Records", "Cooking Vinyl", "BMG"], sources: ["https://en.wikipedia.org/wiki/Groove_Armada"] }, // Groove Armada
  "gusgus": { slug: "gusgus", bio: { fr: "GusGus est un groupe islandais de musique électronique fondé à Reykjavík en 1995, au départ comme un collectif de cinéma et de théâtre. Sa production navigue entre techno, house, downtempo et ambient, du premier album Polydistortion (1997) à Arabian Horse (2011), son disque le mieux classé. Le groupe a publié chez 4AD puis Kompakt et son propre label Oroom, et a remixé Björk, Depeche Mode et Sigur Rós.", en: "GusGus are an Icelandic electronic group founded in Reykjavík in 1995, initially as a film and acting collective. Their output moves between techno, house, downtempo and ambient, from the first album Polydistortion (1997) to Arabian Horse (2011), their highest-charting record. They have released on 4AD, then Kompakt and their own Oroom label, and have remixed Björk, Depeche Mode and Sigur Rós." }, origin: "Reykjavík, Islande", since: 1995, labels: ["Oroom", "Kompakt", "4AD"], sources: ["https://en.wikipedia.org/wiki/GusGus"] }, // GusGus
  "gyrofield": { slug: "gyrofield", bio: { fr: "Kiana Li, alias gyrofield, est une productrice née à Hong Kong et installée à Bristol. Elle produit de la drum & bass, de la jungle et de la techno ambiante, avec des sorties chez Metalheadz, Critical, VISION (le label de Noisia) et Kapsela, et l'EP « These Heavens » paru en 2024. Elle est résidente sur NTS Radio.", en: "Kiana Li, known as gyrofield, is a Hong Kong-born, Bristol-based producer. She makes drum & bass, jungle and ambient techno, with releases on Metalheadz, Critical, Noisia's VISION and Kapsela, plus the 2024 EP \"These Heavens\". She is a resident on NTS Radio." }, origin: "Hong Kong (basée à Bristol, Royaume-Uni)", since: 2017, labels: ["Overview Music", "Kapsela"], sources: ["https://montreal.mutek.org/en/artists/gyrofield", "https://www.rollingstone.com/music/music-features/gyrofield-electronic-producer-interview-1235289268/"] }, // gyrofield
  "halo": { slug: "halo", bio: { fr: "Halō est un projet commun des Néerlandais DubVision et Third Party, associés au duo russe Matisse & Sadko. La formation a fait ses débuts en DJ set le 7 mars 2026 à la Ziggo Dome d'Amsterdam pour Don't Let Daddy Know, et joue sa première date britannique le 9 octobre 2026 aux Drumsheds de Londres.", en: "Halō is a joint project by Dutch acts DubVision and Third Party together with Russian duo Matisse & Sadko. The group made its DJ-set debut on 7 March 2026 at Amsterdam's Ziggo Dome for Don't Let Daddy Know, and plays its first UK date on 9 October 2026 at Drumsheds in London." }, since: 2026, sources: ["https://edm.com/news/dubvision-third-party-matisse-sadko-new-supergroup-halo/", "https://drumshedslondon.com/event/dldk/", "https://www.1001tracklists.com/tracklist/m6z3k5t/halo-dont-let-daddy-know-ziggo-dome-amsterdam-netherlands-2026-03-07.html"] }, // Halō
  "hamdi": { slug: "hamdi", bio: { fr: "Producteur et DJ britannique originaire d'Oxford puis installé à Brighton, Hamdi mêle dubstep, UK garage, grime et UK funky dans la tradition des sound systems anglais. Son morceau « Skanka », paru en 2022, l'a fait connaître internationalement, après « Show Me » avec Sammy Virji ; il a ensuite signé « Push » avec Skrillex en 2024.", en: "British producer and DJ from Oxford, later based in Brighton, Hamdi threads dubstep, UK garage, grime and UK funky through the British soundsystem tradition. His 2022 track \"Skanka\" broke him internationally, following \"Show Me\" with Sammy Virji; he then made \"Push\" with Skrillex in 2024." }, origin: "Oxford, Royaume-Uni", sources: ["https://www.beatportal.com/articles/108907-introducing-hamdi", "https://ukf.com/read/we-need-to-talk-about-hamdi/"] }, // Hamdi
  "hannah-laing": { slug: "hannah-laing", bio: { fr: "DJ et productrice écossaise née en 1994 à Dundee, Hannah Laing joue une trance, une techno et une hard house à haute énergie. Elle a exercé dix ans comme assistante dentaire avant de passer à la musique à plein temps après un set remarqué à Creamfields en 2022 ; elle a été nommée aux DJ Mag Best of Britain en 2023 et a réalisé un Essential Mix de deux heures sur BBC Radio 1. Son label et marque d'événements Doof a lancé en juillet 2025 le festival Doof in the Park à Camperdown Park, à Dundee, devant environ 15 000 personnes.", en: "A Scottish DJ and producer born in Dundee in 1994, Hannah Laing plays high-energy trance, techno and hard house. She worked as a dental nurse for ten years before turning to music full time after a well-received Creamfields set in 2022; she was nominated for a DJ Mag Best of Britain award in 2023 and recorded a two-hour Essential Mix for BBC Radio 1. Her label and events brand Doof launched the Doof in the Park festival at Camperdown Park in Dundee in July 2025, drawing some 15,000 people." }, origin: "Dundee, Écosse", labels: ["Doof"], sources: ["https://en.wikipedia.org/wiki/Hannah_Laing", "https://en.wikipedia.org/wiki/Doof_in_the_Park"] }, // Hannah Laing
  "hardwell": { slug: "hardwell", bio: { fr: "Robbert van de Corput, connu sous le nom de Hardwell, est un DJ et producteur néerlandais né le 7 janvier 1988 à Breda. Sa discographie se répartit surtout entre progressive house et electro house, avec des incursions trance et hardstyle.", en: "Robbert van de Corput, known as Hardwell, is a Dutch DJ and producer born on 7 January 1988 in Breda. His catalogue sits mostly in progressive house and electro house, with trance and hardstyle excursions." }, origin: "Breda, Pays-Bas", sources: ["https://musicbrainz.org/artist/170d6637-36e0-49dd-a225-c4fd5b77a285", "https://api.discogs.com/database/search?artist=Hardwell&type=release&per_page=50"] }, // Hardwell
  "harry-nash": { slug: "harry-nash", bio: { fr: "Harry Nash est un DJ allemand actif à plein temps depuis 1984 et résident du club ToY à Stuttgart depuis 1996, où il a joué plus de 1 700 sets d'afterhours. Il figure à l'affiche de Wonderful Days, le festival de rave classique de Stuttgart consacré aux disques trance, techno et happy hardcore des années 1990 et 2000.", en: "Harry Nash is a German DJ who has worked full time since 1984 and has been a resident at Club ToY in Stuttgart since 1996, where he has played more than 1,700 afterhours sets. He appears on the bill of Wonderful Days, the Stuttgart classic rave festival built on 1990s and 2000s trance, techno and happy hardcore records." }, origin: "Stuttgart, Allemagne", since: 1984, sources: ["https://ra.co/dj/harrynash/biography", "https://rausgegangen.de/en/events/wonderful-days-the-classic-rave-festival-stuttgart-vol-ii-0/"] }, // Harry Nash
  "hashashin": { slug: "hashashin", bio: { fr: "DJ et producteur techno d'Amsterdam, actif depuis 2006 d'abord sous l'alias Ici Sans Merci. Il est un pilier des collectifs AURA Amsterdam, Bastion Techno et RADION Amsterdam. Quand RADION fête ses dix ans en janvier 2026 en lançant son label, il figure sur la compilation inaugurale « Decennial Revelry », un double vinyle de dix titres réunissant des artistes néerlandais.", en: "An Amsterdam techno DJ and producer, active since 2006, originally under the alias Ici Sans Merci. He is a fixture of the AURA Amsterdam, Bastion Techno and RADION Amsterdam collectives. When RADION marked ten years in January 2026 by launching its label, he featured on the inaugural compilation \"Decennial Revelry\", a ten-track double vinyl of Dutch artists." }, origin: "Amsterdam, Pays-Bas", since: 2006, sources: ["https://evl.one/radion-amsterdam-launches-record-label", "https://radionamsterdam.bandcamp.com/album/rad001-decennial-revelry"] }, // Hashashin
  "hausgardian": { slug: "hausgardian", bio: { fr: "DJ belge du Pays Noir, Hausgardian mixe depuis 2012. Sa bascule vers la techno remonte à un concert de Kevin Saunderson et Laurent Garnier au Rockerill de Charleroi ; il joue depuis dans les soirées électroniques du pays, du Rockerill à Abstract et Rêve Bivouac, avec des sets tech et deep house.", en: "A Belgian DJ from the Pays Noir, Hausgardian has been playing since 2012. His turn towards techno dates back to seeing Kevin Saunderson and Laurent Garnier at the Rockerill in Charleroi; he has since played electronic nights across the country, from Rockerill to Abstract and Rêve Bivouac, with tech and deep house sets." }, origin: "Charleroi, Belgique", since: 2012, sources: ["https://www.rockerill.com/agenda/les-aperos-industriels/13594/"] }, // Hausgardian
  "hayley-zalassi": { slug: "hayley-zalassi", bio: { fr: "Hayley Zalassi est une DJ et productrice originaire de Glasgow. Elle découvre l'électronique adolescente sous le chapiteau Slam de T In The Park, puis travaille au bar des Arches avant de passer aux platines. Sa première date au Fly Open Air en 2021 lance sa carrière ; ses sets et ses productions — « Strange Faces », « Ex Appeal » — tiennent d'une house teintée de techno.", en: "Hayley Zalassi is a DJ and producer from Glasgow. She discovered electronic music as a teenager in the Slam tent at T In The Park, then worked the bar at the Arches before taking to the decks. A 2021 booking at Fly Open Air opened things up; her sets and records — 'Strange Faces', 'Ex Appeal' — sit in house shaded with techno." }, origin: "Glasgow, Écosse", sources: ["https://www.scotsman.com/whats-on/arts-and-entertainment/under-the-radar-hayley-zalassi-3785762", "http://www.dmcworld.net/dmc-world/hayley-zalassi/"] }, // Hayley Zalassi
  "headbanger": { slug: "headbanger", bio: { fr: "The Headbanger est un producteur et DJ hardcore néerlandais, actif dans la scène gabber depuis le début des années 1990 : son « The Headbanger EP » paraît sur vinyle sous le nom Da Headbanger. Il fait partie de la génération de producteurs de Rotterdam qui a défini le son gabber, aux côtés de Rotterdam Terror Corps, Neophyte et Ruffneck.", en: "The Headbanger is a Dutch hardcore producer and DJ, active in the gabber scene since the early 1990s: his \"The Headbanger EP\" was released on vinyl under the name Da Headbanger. He belongs to the generation of Rotterdam producers who defined the gabber sound, alongside Rotterdam Terror Corps, Neophyte and Ruffneck." }, origin: "Pays-Bas", sources: ["https://musicbrainz.org/artist/d9d13b3d-1dbb-4258-9809-e2def9cff128", "https://www.discogs.com/release/107357-The-Headbanger-The-Headbanger-EP"] }, // Headbanger
  "hector-oaks": { slug: "hector-oaks", bio: { fr: "Héctor Oaks est un DJ, producteur et patron de label espagnol né à Madrid et installé à Berlin. Il est connu pour ses sets de techno rapide, souvent joués en vinyle, et cite la culture rave et la « Ruta del Bakalao » espagnole parmi ses influences. Il a fondé les labels OAKS et KAOS, est devenu résident du club Bassiani à Tbilissi, et son premier album, « As We Were Saying », est paru en 2018 sur le label du club.", en: "Héctor Oaks is a Spanish DJ, producer and label owner born in Madrid and based in Berlin. He is known for fast techno sets, often played on vinyl, and cites rave culture and Spain's \"Ruta del Bakalao\" among his influences. He founded the labels OAKS and KAOS, became a resident at the Tbilisi club Bassiani, and released his debut album \"As We Were Saying\" on the club's label in 2018." }, origin: "Madrid, Espagne", labels: ["OAKS", "KAOS"], sources: ["https://en.wikipedia.org/wiki/H%C3%A9ctor_Oaks"] }, // Héctor Oaks
  "hedemann": { slug: "hedemann", bio: { fr: "Hedemann est une DJ et productrice techno néerlandaise, dont le son va de la techno groovy et percussive à une techno old-school brute et roulante. Venue du hip-hop, elle bascule après sa première soirée techno et se fait la main en organisant des fêtes clandestines pendant le confinement. Elle a depuis joué au Oost à Groningue, à la Heineken Experience Hall d'Amsterdam, au De Pip à La Haye, ainsi qu'au Groundless Factory à Pékin et au GreenFest au Kosovo.", en: "Hedemann is a Dutch techno DJ and producer whose sound ranges from groovy, percussive techno to raw old-school driving techno. She came from hip-hop and switched after her first techno party, cutting her teeth throwing illegal parties during lockdown. She has since played Oost in Groningen, the Heineken Experience Hall in Amsterdam, De Pip in The Hague, as well as Groundless Factory in Beijing and GreenFest in Kosovo." }, origin: "Pays-Bas", sources: ["https://www.bevrijdingsfestivalfryslan.nl/artiest/hedemann/"] }, // Hedemann
  "hedex": { slug: "hedex", bio: { fr: "Hedex est le nom de scène de Jack Hedges, DJ et producteur de drum & bass britannique originaire de Cambridge. Il sort ses premiers morceaux à seize ans, signe chez Dubz Audio l'année suivante, puis devient une figure du label Crucast. Son registre est le jump-up.", en: "Hedex is the stage name of Jack Hedges, a British drum & bass DJ and producer from Cambridge. He released his first tracks at sixteen, signed to Dubz Audio a year later, and went on to become a fixture of the Crucast label. His register is jump-up." }, origin: "Cambridge, Royaume-Uni", labels: ["Dubz Audio", "Crucast"], sources: ["https://ukf.com/read/we-need-to-talk-about-hedex/", "https://api.discogs.com/database/search?artist=Hedex&type=release"] }, // Hedex
  "helena-hauff": { slug: "helena-hauff", bio: { fr: "DJ et productrice hambourgeoise, elle compose sur du matériel exclusivement analogique une électro acide traversée d'EBM et d'industriel. Elle a tenu la soirée « Birds and Other Instruments » au Golden Pudel Club, sorti son premier EP en 2013, puis les albums Discreet Desires (2015) et Qualm (2018) chez Ninja Tune. Elle dirige le label Return to Disorder.", en: "A DJ and producer from Hamburg, she works on strictly analogue gear, building acid-tinged electro shot through with EBM and industrial. She ran the \"Birds and Other Instruments\" night at the Golden Pudel Club, released her first EP in 2013, then the albums Discreet Desires (2015) and Qualm (2018) on Ninja Tune. She runs the Return to Disorder label." }, origin: "Hambourg, Allemagne", since: 2013, labels: ["Return to Disorder", "Ninja Tune"], sources: ["https://en.wikipedia.org/wiki/Helena_Hauff"] }, // Helena Hauff
  "helena-lauwaert": { slug: "helena-lauwaert", bio: { fr: "DJ belge apparue en 2022 dans la scène gantoise, où elle joue notamment au Contrast et au Charlatan. Ses sets font se croiser house, techno, hard dance, hard trance et speed house. En septembre 2026, elle signe son premier plateau en festival avec « Helena Lauwaert & Friends » au Voodoo Village, à Grimbergen.", en: "A Belgian DJ who came up in 2022 in the Ghent scene, playing venues such as Contrast and Charlatan. Her sets run house, techno, hard dance, hard trance and speed house together. In September 2026 she hosts her first festival stage, \"Helena Lauwaert & Friends\", at Voodoo Village in Grimbergen." }, origin: "Gand, Belgique", since: 2022, sources: ["https://www.voodoovillage.be/artists/helena-lauwaert", "https://www.ravejungle.com/2026/06/24/voodoo-village-2026-lineup-stages/"] }, // Helena Lauwaert
  "hilight-tribe": { slug: "hilight-tribe", bio: { fr: "Hilight Tribe est un groupe français qui joue une « natural trance » : une transe rejouée en direct par des musiciens, sans ordinateur, à la percussion, à la guitare, à la basse, à la batterie, au didgeridoo et au sitar. Le collectif nourrit son répertoire d'instruments et de rythmes rapportés du Mali, du Sénégal, du Burkina Faso, d'Inde et du Brésil. Son morceau « Free Tibet » a été repris par Vini Vici, et le groupe a signé « Great Spirit » avec Vini Vici et Armin van Buuren en 2017.", en: "Hilight Tribe are a French band playing what they call natural trance: trance performed live by musicians rather than computers, on percussion, guitar, bass, drums, didgeridoo and sitar. The group builds its repertoire from instruments and rhythms brought back from Mali, Senegal, Burkina Faso, India and Brazil. Their track \"Free Tibet\" was reworked by Vini Vici, and in 2017 the band recorded \"Great Spirit\" with Vini Vici and Armin van Buuren." }, origin: "France", sources: ["https://www.tranceinfrance.com/hilight-tribe/", "https://ravefeed.com/2017/08/24/interview-hilight-tribe/"] }, // Hilight Tribe
  "hitoshi": { slug: "hitoshi", bio: { fr: "Né à Osaka, Hitoshi vit à Helsinki depuis 2020 environ et y joue depuis un premier passage au Vum en 2022. Il est venu à la musique électronique par la techno berlinoise avant de se faire connaître pour ses sets disco en vinyle, et fait glisser ses sets entre house brute, disco et acid. Il est aussi producteur à IDA Radio Helsinki et joue régulièrement au Kaiku.", en: "Born in Osaka, Hitoshi has lived in Helsinki since around 2020 and has played there since a first club date at Vum in 2022. He came to electronic music through Berlin techno before becoming known for vinyl disco sets, and moves between raw house, disco and acid. He also produces at IDA Radio Helsinki and plays regularly at Kaiku." }, origin: "Osaka, Japon / Helsinki, Finlande", since: 2022, sources: ["https://www.flowfestival.com/en/program/music/hitoshi/", "https://www.myhelsinki.fi/visit/eat-and-drink/clubbing-scene-in-helsinki/"] }, // Hitoshi
  "holy-priest": { slug: "holy-priest", bio: { fr: "Holy Priest est un producteur et DJ allemand installé à Oberhausen, en Rhénanie-du-Nord-Westphalie, où il tient son studio. Il joue masqué et garde son identité secrète, sur une hard techno industrielle faite de kicks saturés, de basses distordues et de lignes acid. Il publie des EP depuis 2020, chez Revised Records, CodeX Recordings et Chlore Records, dont une série aux titres latins (Unus, Duo, Tres) et le morceau « Rave Penetrator ».", en: "Holy Priest is a German producer and DJ based in Oberhausen, North Rhine-Westphalia, where he keeps his studio. He performs masked and keeps his identity private, playing industrial-edged hard techno built on saturated kicks, distorted bass and acid lines. He has been putting out EPs since 2020 on Revised Records, CodeX Recordings and Chlore Records, including a run of Latin-titled releases (Unus, Duo, Tres) and the track \"Rave Penetrator\"." }, origin: "Oberhausen, Allemagne", since: 2020, labels: ["Revised Records", "CodeX Recordings", "Chlore Records"], sources: ["https://fr.wikipedia.org/wiki/Holy_Priest"] }, // Holy Priest
  "honey-dijon": { slug: "honey-dijon", bio: { fr: "Honey Redmond, née en 1968 dans le South Side de Chicago, mixe sous le nom de Honey Dijon et vit entre New York et Berlin. Formée dans le sillage de DJ comme Derrick Carter et Mark Farina, elle commence à mixer dans les années 1990 et à produire vers 2000, entre house et techno. Son premier album, « The Best of Both Worlds », paraît en 2017 ; elle travaille aussi régulièrement avec la mode, notamment Louis Vuitton et Dior.", en: "Born in 1968 on Chicago's South Side, Honey Redmond DJs as Honey Dijon and is based between New York City and Berlin. Mentored by DJs such as Derrick Carter and Mark Farina, she began DJing in the 1990s and producing around 2000, working between house and techno. Her debut album \"The Best of Both Worlds\" came out in 2017, and she works regularly with fashion houses including Louis Vuitton and Dior." }, origin: "Chicago, États-Unis", sources: ["https://en.wikipedia.org/wiki/Honey_Dijon"] }, // Honey Dijon
  "horse-meat-disco": { slug: "horse-meat-disco", bio: { fr: "Horse Meat Disco est un collectif de DJs britannique fondé en 2003 à Londres, né d'une soirée du même nom. Sa sélection tourne autour du disco, du nu-disco et de la house, et ses compilations paraissent notamment sur Glitterbox Recordings.", en: "Horse Meat Disco is a British DJ collective founded in London in 2003, out of the club night of the same name. Their selection revolves around disco, nu-disco and house, and their compilations appear on labels such as Glitterbox Recordings." }, origin: "Londres, Royaume-Uni", since: 2003, labels: ["Glitterbox Recordings"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Horse%20Meat%20Disco&fmt=json", "https://api.discogs.com/database/search?artist=Horse+Meat+Disco&type=release"] }, // Horse Meat Disco
  "horsegiirl": { slug: "horsegiirl", bio: { fr: "horsegiirL est le nom de scène de Stella Stallion, DJ et chanteuse allemande née le 20 avril 2000, active depuis 2022 et basée à Berlin. Elle se produit masquée derrière une tête de cheval et joue un répertoire de happy hardcore et de UK hardcore. Son premier album, Nature Is Healing, est sorti le 5 juin 2026 chez RCA Records.", en: "horsegiirL is the stage name of Stella Stallion, a German DJ and singer born on 20 April 2000, active since 2022 and based in Berlin. She performs behind a horse head mask and plays happy hardcore and UK hardcore. Her debut album, Nature Is Healing, was released on 5 June 2026 on RCA Records." }, origin: "Berlin, Allemagne", since: 2022, labels: ["Live from Earth", "RCA Records"], sources: ["https://en.wikipedia.org/wiki/HorsegiirL"] }, // horsegiirL
  "hubbabubbaklubb-djs": { slug: "hubbabubbaklubb-djs", bio: { fr: "Groupe formé à Oslo en 2012, Hubbabubbaklubb publie sur le label norvégien Snorkel Records une musique qui tient du disco, de la house et du balearic. Ses membres jouent aussi en DJ set, notamment aux soirées Frædag du club Jaeger, à Oslo.", en: "Formed in Oslo in 2012, Hubbabubbaklubb release on the Norwegian label Snorkel Records, in a vein that draws on disco, house and balearic sounds. Its members also play DJ sets, notably at the Frædag nights at Oslo's Jaeger club." }, origin: "Oslo, Norvège", since: 2012, labels: ["Snorkel Records"], sources: ["https://www.discogs.com/artist/3139871-hubbabubbaklubb", "https://hubbabubbaklubb.bandcamp.com/album/dr-mmen-dr-mmerne-dr-mmer-remixed"] }, // Hubbabubbaklubb DJs
  "huma-utku": { slug: "huma-utku", bio: { fr: "Compositrice et artiste sonore née et élevée à Istanbul, installée à Berlin, Hüma Utku mêle électronique industrielle, techno et enregistrements de terrain, avec des instruments traditionnels du Moyen-Orient. Elle publie « Şeb-i Yelda » en 2018 sous le nom R.A.N. sur Karlrecords, puis son premier album Gnosis en 2019 sur le même label, et The Psychologist en 2022 chez Editions Mego. Sélectionnée par la plateforme SHAPE en 2021, elle a joué à Berlin Atonal et au CTM Festival.", en: "A composer and sound artist born and raised in Istanbul and based in Berlin, Hüma Utku combines industrial electronics, techno and field recordings with traditional Middle Eastern instruments. She released \"Şeb-i Yelda\" in 2018 under the name R.A.N. on Karlrecords, followed by her debut album Gnosis in 2019 on the same label and The Psychologist on Editions Mego in 2022. Selected by the SHAPE platform in 2021, she has performed at Berlin Atonal and CTM Festival." }, origin: "Istanbul, Turquie", since: 2016, labels: ["Karlrecords", "Editions Mego"], sources: ["https://www.musicboard-berlin.de/en/huema-utku/", "https://shapeplatform.eu/artist/hu%CC%88ma-utku/", "https://karlrecords.bandcamp.com/album/gnosis"] }, // Hüma Utku
  "human-safari": { slug: "human-safari", bio: { fr: "Human Safari est un DJ et producteur maltais, résident du Glitch Festival. Il joue depuis une quinzaine d'années une techno teintée d'improvisation jazz, de percussions tribales et de hardgroove, souvent avec des éléments instrumentaux joués en direct. Il a sorti des disques sur R&S Records et l'EP « Culture Shock » sur Mutual Rytm, et s'est produit au Stone Techno Festival, à l'Unfold et au RSO.", en: "Human Safari is a Maltese DJ and producer, a resident at Glitch Festival. For some fifteen years he has played techno shaded with jazz improvisation, tribal percussion and hardgroove, often with live instrumental elements. He has released on R&S Records and put out the EP \"Culture Shock\" on Mutual Rytm, and has played Stone Techno Festival, Unfold and RSO." }, origin: "Malte", labels: ["R&S Records", "Mutual Rytm"], sources: ["https://www.beatportal.com/articles/1284730-human-safari-on-charting-new-currents-in-electronic-music-with-r-s-records", "https://humansafari.bandcamp.com/"] }, // Human Safari
  "hybrid-minds": { slug: "hybrid-minds", bio: { fr: "Hybrid Minds est un duo britannique de drum and bass composé de Josh White et Matt Lowe, actif depuis le début des années 2010. Ils travaillent le versant liquide du genre : basses roulantes, nappes atmosphériques et voix invitées, avec des collaborations récurrentes avec les chanteuses Charlotte Haining et Alexa Harley. Leur premier album, « Mountains », est paru en 2013. Ils publient l'essentiel de leur musique sur leur propre label, Hybrid Music.", en: "Hybrid Minds are a British drum and bass duo made up of Josh White and Matt Lowe, active since the early 2010s. They work the liquid end of the genre: rolling basslines, atmospheric pads and guest vocals, with recurring collaborations with singers Charlotte Haining and Alexa Harley. Their debut album \"Mountains\" came out in 2013. They release most of their music on their own label, Hybrid Music." }, origin: "Royaume-Uni", since: 2012, labels: ["Hybrid Music"], sources: ["https://relentlessbeats.com/2025/04/artist-spotlight-who-is-hybrid-minds/"] }, // Hybrid Minds
  "hypnosis-therapy": { slug: "hypnosis-therapy", bio: { fr: "Hypnosis Therapy est un duo sud-coréen formé à Séoul en 2022 par le producteur Jflow, membre de Hippy Was Gipsy, et le rappeur Jjangyou. Leur musique mêle breakbeats, techno, punk et expérimentations. Ils ont publié les albums « Hypnosis Therapy » (2022), « Psilocybin » (2023) et « Raw Survival » (2024), et joué à SXSW, au Roskilde Festival et au Reeperbahn Festival.", en: "Hypnosis Therapy is a South Korean duo formed in Seoul in 2022 by producer Jflow, a member of Hippy Was Gipsy, and rapper Jjangyou. Their music mixes breakbeats, techno, punk and experimental sounds. They have released the albums \"Hypnosis Therapy\" (2022), \"Psilocybin\" (2023) and \"Raw Survival\" (2024), and played SXSW, Roskilde Festival and Reeperbahn Festival." }, origin: "Séoul, Corée du Sud", since: 2022, sources: ["https://www.roskilde-festival.dk/en/line-up/music/hypnosis-therapy", "https://www.reeperbahnfestival.com/en/act/hypnosis-therapy"] }, // Hypnosis Therapy
  "hysta": { slug: "hysta", bio: { fr: "Thaïs Morel, née en 1998 à La Gacilly dans le Morbihan, mixe sous le nom d'Hysta un hardcore mainstream hérité des free parties bretonnes, où elle a commencé sur vinyle à 16 ans. Elle a sorti des titres sur Masters of Hardcore, The Third Movement et Q-dance Music, et est devenue en 2023 la première DJ française à jouer sur la scène principale du Thunderdome. En septembre 2025, elle a donné un set hardcore d'une heure au deuxième étage de la tour Eiffel.", en: "Born in 1998 in La Gacilly, Brittany, Thaïs Morel DJs as Hysta, playing mainstream hardcore rooted in the Breton free-party scene where she started out on vinyl at sixteen. She has released on Masters of Hardcore, The Third Movement and Q-dance Music, and in 2023 became the first French female DJ to play Thunderdome's main stage. In September 2025 she performed a one-hour hardcore set on the second floor of the Eiffel Tower." }, origin: "La Gacilly, Morbihan, France", since: 2014, labels: ["Masters of Hardcore", "The Third Movement", "Q-dance Music"], sources: ["https://fr.wikipedia.org/wiki/Hysta"] }, // Hysta
  "i-hate-models": { slug: "i-hate-models", bio: { fr: "I Hate Models, de son vrai nom Guillaume Labadie, né le 8 juin 1995, est un producteur et DJ français de techno, qui a grandi dans le sud de la France. Il débute en 2015 et publie son premier EP, Warehouse Memories, sur le label ARTS en 2016, avant de rejoindre le label londonien Perc Trax où paraît son premier album, L'Âge des métamorphoses, en juin 2019. Il apparaît quasi systématiquement masqué en public et limite ses échanges avec la presse.", en: "I Hate Models, real name Guillaume Labadie, born 8 June 1995, is a French techno producer and DJ who grew up in the south of France. He started in 2015 and released his first EP, Warehouse Memories, on the ARTS label in 2016, before joining London's Perc Trax, which issued his first album, L'Âge des métamorphoses, in June 2019. He almost always appears masked in public and keeps his press contact to a minimum." }, origin: "Sud de la France", since: 2015, labels: ["ARTS", "Perc Trax"], sources: ["https://fr.wikipedia.org/wiki/I_Hate_Models", "https://en.wikipedia.org/wiki/I_Hate_Models"] }, // I Hate Models
  "il-est-vilaine": { slug: "il-est-vilaine", bio: { fr: "Il Est Vilaine est un duo électronique parisien formé par Simon et Florent, épaulé sur le visuel par Apollo Thomas. Leur musique mêle house et techno à une acid-wave marquée par le post-punk et le krautrock. Leur premier EP, « Scandale », est paru en 2014 sur leur propre label Dialect Recordings, avant que Kill The DJ ne publie « Lumière noire » à l'été 2015.", en: "Il Est Vilaine are a Parisian electronic duo made up of Simon and Florent, with Apollo Thomas handling their visuals. Their music welds house and techno to an acid-wave streak marked by post-punk and krautrock. Their first EP, \"Scandale\", came out in 2014 on their own Dialect Recordings label, before Kill The DJ released \"Lumière noire\" in the summer of 2015." }, origin: "Paris, France", since: 2014, labels: ["Dialect Recordings", "Kill The DJ"], sources: ["https://vice.com/fr/article/rznbj3/il-est-vilaine-interview-2015"] }, // Il Est Vilaine
  "ilario-alicante": { slug: "ilario-alicante", bio: { fr: "Né en 1988 à Livourne, en Italie, Ilario Alicante commence comme résident du club Pachamama à Pise avant de rejoindre le collectif Cocoon de Sven Väth. Ses premiers titres marquants sont « Vacaciones en Chile » et « Living Near Africa », publié sur Cécille Records ; à vingt ans, il devient le plus jeune artiste programmé au Time Warp de Rotterdam. Il a fondé son propre label, Deep Moves Records, et sort régulièrement sur Drumcode.", en: "Born in Livorno, Italy in 1988, Ilario Alicante started out as a resident at the Pachamama club in Pisa before joining Sven Väth's Cocoon collective. His early standout tracks were \"Vacaciones en Chile\" and \"Living Near Africa\", released on Cécille Records; at twenty he became the youngest artist billed at Time Warp in Rotterdam. He founded his own label, Deep Moves Records, and releases regularly on Drumcode." }, origin: "Livourne, Italie", labels: ["Deep Moves Records", "Cocoon", "Drumcode"], sources: ["https://www.drumcode.se/artists/ilario-alicante"] }, // Ilario Alicante
  "in-furcht": { slug: "in-furcht", bio: { fr: "In Furcht est un producteur et DJ techno installé à Berlin, également ingénieur du son. Son jeu et ses productions reposent sur une techno rapide et bouclée, portée par des shakers groovy et des voix accrocheuses, avec des références assumées au son du début des années 2000. Il fonde son label GROOVE2000 début 2023, où paraît son premier EP, après une apparition sur une compilation du label Isarn.", en: "In Furcht is a Berlin-based techno producer and DJ, also a sound engineer. His DJing and his productions rest on fast, loopy techno driven by groovy shakers and catchy vocals, with openly worn early-2000s references. He founded his label GROOVE2000 in early 2023, where his debut EP appeared, after featuring on a various-artists compilation for the Isarn label." }, origin: "Berlin, Allemagne", since: 2023, labels: ["GROOVE2000"], sources: ["https://hoer.live/artist/in-furcht-2/", "https://soundcloud.com/infurcht"] }, // In Furcht
  "in-verruf": { slug: "in-verruf", bio: { fr: "In Verruf, de son vrai nom Ferdinand Hartmann, est un DJ et producteur allemand installé à Berlin. Son nom de scène signifie « tombé en discrédit ». Il est signé depuis 2019 sur le R-Label Group de Kobosil, où paraît son morceau « Too Much DMT », et joue une hard techno dense et industrielle.", en: "In Verruf, real name Ferdinand Hartmann, is a German DJ and producer based in Berlin. His stage name means \"fallen into disrepute\". He has been signed since 2019 to Kobosil's R-Label Group, home to his track \"Too Much DMT\", and plays a dense, industrial-leaning hard techno." }, origin: "Berlin, Allemagne", since: 2019, labels: ["R-Label Group"], sources: ["https://openbeatz.de/artist/in-verruf/", "https://www.discogs.com/artist/7588132-In-verruf"] }, // In Verruf
  "indira-paganotto": { slug: "indira-paganotto", bio: { fr: "Indira Paganotto, née le 30 mai 1992, est une DJ et productrice espagnole de techno. Sa discographie mêle techno et psytrance, un croisement qu'elle a porté sur des labels comme KNTXT et Second State avant de fonder son propre label, ARTCORE.", en: "Indira Paganotto, born 30 May 1992, is a Spanish techno DJ and record producer. Her discography sits between techno and psy-trance, a crossover she released on labels such as KNTXT and Second State before founding her own label, ARTCORE." }, origin: "Espagne", labels: ["ARTCORE", "KNTXT", "Second State"], sources: ["https://en.wikipedia.org/wiki/Indira_Paganotto", "https://api.discogs.com/database/search?artist=Indira+Paganotto&type=release"] }, // Indira Paganotto
  "interplanetary-criminal": { slug: "interplanetary-criminal", bio: { fr: "De son vrai nom Zachary Bruce, né en 1993 à Blackburn et installé à Manchester, il produit depuis 2012 un UK garage nerveux mêlé de speed garage et de breakbeat. Il a cofondé le label ATW Records avec Main Phase en 2019, et « B.O.T.A. (Baddest of Them All) », signé avec Eliza Rose en 2022, lui a valu deux semaines en tête des ventes britanniques et une nomination aux BRIT Awards.", en: "Real name Zachary Bruce, born in 1993 in Blackburn and based in Manchester, he has been producing edgy UK garage laced with speed garage and breakbeat since 2012. He co-founded the ATW Records label with Main Phase in 2019, and \"B.O.T.A. (Baddest of Them All)\", made with Eliza Rose in 2022, spent two weeks at number one in the UK and earned a BRIT Award nomination." }, origin: "Blackburn, Royaume-Uni", since: 2012, labels: ["ATW Records", "Shall Not Fade"], sources: ["https://en.wikipedia.org/wiki/Interplanetary_Criminal"] }, // Interplanetary Criminal
  "iosio": { slug: "iosio", bio: { fr: "IOSIO est un DJ et producteur néerlandais de Rotterdam, identifié à la bouncy techno : une techno rebondissante traversée d'influences trance. Il a joué au club TURN et à la Van Nelle Fabriek de Rotterdam, et ses productions ont été soutenues par Amelie Lens et Indira Paganotto.", en: "IOSIO is a Dutch DJ and producer from Rotterdam, identified with bouncy techno: a springy strain of techno shot through with trance influences. He has played club TURN and Rotterdam's Van Nelle Fabriek, and his productions have been supported by Amelie Lens and Indira Paganotto." }, origin: "Rotterdam, Pays-Bas", sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/iosio/2759357/", "https://soundcloud.com/club-turn/iosio-dj-set"] }, // IOSIO
  "isa-roos": { slug: "isa-roos", bio: { fr: "Isa Roos est une DJ et productrice néerlandaise, active depuis 2021. Partie de l'afrobeats et des musiques urbaines, elle s'est orientée vers l'afro house, l'afro tech et la deep house, qu'elle mêle dans ses sets et dans ses propres productions.", en: "Isa Roos is a Dutch DJ and producer, active since 2021. Starting out with afrobeats and urban music, she moved towards afro house, afro tech and deep house, which she blends in her sets and in her own productions." }, origin: "Pays-Bas", since: 2021, sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/isa-roos/2695348/"] }, // Isa Roos
  "isabel-soto": { slug: "isabel-soto", bio: { fr: "Isabel Soto est une DJ et productrice née au Venezuela, installée à Berlin après avoir formé son style dans la scène underground de Montréal. Sa techno joue sur les textures abstraites et les rythmes percussifs. Elle a fondé le label NYXII Records et a fait ses débuts sur Ostgut Ton avec l'EP Morphosis, paru en décembre 2025.", en: "Isabel Soto is a Venezuelan-born DJ and producer based in Berlin, having shaped her style in Montreal's underground scene. Her techno works on abstract textures and percussive rhythms. She founded the NYXII Records label and made her Ostgut Ton debut with the EP Morphosis, released in December 2025." }, origin: "Venezuela", labels: ["NYXII Records", "Ostgut Ton"], sources: ["https://www.awakenings.com/en/artists/isabel-soto/386520/", "https://ostgut.bandcamp.com/album/morphosis"] }, // Isabel Soto
  "isaiah": { slug: "isaiah", bio: { fr: "Isaiah Gesser est un DJ et producteur techno d'Amsterdam, connu pour son approche hard groove. Il est cofondateur des collectifs Frenzy et Vulged, et figure sur « Decennial Revelry », la compilation qui a ouvert le catalogue du label lancé par le club RADION pour ses dix ans, avec un titre en collaboration avec Beau Didier.", en: "Isaiah Gesser is a techno DJ and producer from Amsterdam, known for his hard groove approach. He co-founded the collectives Frenzy and Vulged, and appears on \"Decennial Revelry\", the compilation that opened the catalogue of the label launched by RADION club for its tenth anniversary, with a track made with Beau Didier." }, origin: "Amsterdam, Pays-Bas", sources: ["https://www.awakenings.com/en/artists/isaiah/197658/", "https://wearesoundspace.com/radion-amsterdam-record-label-decennial-revelry/"] }, // Isaiah
  "ivory": { slug: "ivory", bio: { fr: "Daniel Tagliaferri, alias Ivory, est un producteur, DJ et guitariste italien installé à Milan. Il a publié sur Innervisions, Afterlife, Kompakt, Bedrock, Chapter 24 et Multinotes, et tient sa résidence au Volt Club de Milan.", en: "Daniel Tagliaferri, who records as Ivory, is an Italian producer, DJ and guitarist based in Milan. He has released on Innervisions, Afterlife, Kompakt, Bedrock, Chapter 24 and Multinotes, and holds a residency at Milan's Volt Club." }, origin: "Milan, Italie", labels: ["Innervisions", "Afterlife", "Kompakt", "Multinotes"], sources: ["https://ra.co/dj/ivory", "https://whenwedip.com/2019/08/interview-ivory/"] }, // Ivory
  "ivy": { slug: "ivy", bio: { fr: "[IVY], de son vrai nom Jasmin Emily Bernard, est une DJ et productrice britannique de drum & bass. Ses sets croisent les codes de la rave des années 1990 et la drum & bass contemporaine. Elle figure à l'affiche du Korsakov Weekender 2026, l'édition des dix ans, au Maassilo de Rotterdam.", en: "[IVY], real name Jasmin Emily Bernard, is a British drum & bass DJ and producer. Her sets cross 1990s rave codes with contemporary drum & bass. She is on the bill for the 2026 Korsakov Weekender, the tenth-anniversary edition, at Rotterdam's Maassilo." }, origin: "Royaume-Uni", sources: ["https://www.lovethatbass.com/news/korsakov-weekender/", "https://www.korsakovmusic.com/"] }, // [IVY]
  "james-hype": { slug: "james-hype", bio: { fr: "James Hype, de son vrai nom James Edward Lee Marsland, est un DJ et producteur anglais né le 26 novembre 1989 à Greasby, dans le Merseyside. Il publie depuis 2016 sur son label Stereohype puis chez Warner, dans un registre tech house et EDM, et est connu pour ses mixes très techniques.", en: "James Hype, real name James Edward Lee Marsland, is an English DJ and producer born on 26 November 1989 in Greasby, Merseyside. He has released since 2016 on his Stereohype label and then on Warner, in a tech house and EDM vein, and is known for his highly technical mixing." }, origin: "Greasby, Merseyside, Royaume-Uni", since: 2016, labels: ["Stereohype", "Warner Records"], sources: ["https://en.wikipedia.org/wiki/James_Hype", "https://www.discogs.com/artist/5319800-James-Hype"] }, // James Hype
  "jamie-jones": { slug: "jamie-jones", bio: { fr: "Né en 1980 à Bontnewydd, au pays de Galles, il joue une house teintée de tech house et dirige le label Hot Creations. Il a lancé en 2012 la soirée Paradise, tenue huit saisons au DC10 d'Ibiza avant de rejoindre l'Amnesia en 2022, et fait partie du collectif Hot Natured, dont le single « Benediction » est entré au classement britannique en 2012.", en: "Born in 1980 in Bontnewydd, Wales, he plays house shaded with tech house and runs the Hot Creations label. In 2012 he launched the Paradise party, which ran eight seasons at DC10 in Ibiza before moving to Amnesia in 2022, and he is part of the Hot Natured collective, whose single \"Benediction\" charted in the UK in 2012." }, origin: "Bontnewydd, Pays de Galles", since: 2003, labels: ["Hot Creations"], sources: ["https://en.wikipedia.org/wiki/Jamie_Jones_(DJ)"] }, // Jamie Jones
  "jan-blomqvist": { slug: "jan-blomqvist", bio: { fr: "Jan Blomqvist est un producteur et chanteur allemand né le 10 janvier 1982 à Celle et installé à Berlin depuis 2002. Guitariste et chanteur de punk à ses débuts, il passe à la musique électronique au début des années 2000 et développe ce qu'il appelle le « concert techno » : de la techno mélodique et de la deep house jouées avec chant en direct et instruments organiques. Il a publié les albums « Remote Control » et « Disconnected », et fondé en 2024 son label Disconnected.", en: "Jan Blomqvist is a German producer and singer born on 10 January 1982 in Celle and based in Berlin since 2002. A punk guitarist and singer at first, he moved to electronic music in the early 2000s and developed what he calls \"concert techno\": melodic techno and deep house performed with live vocals and organic instruments. He released the albums \"Remote Control\" and \"Disconnected\", and founded his label Disconnected in 2024." }, origin: "Celle / Berlin, Allemagne", since: 2002, labels: ["Armada Music", "Disconnected"], sources: ["https://www.armadamusic.com/artists/jan-blomqvist", "https://www.grammy.com/news/jan-blomqvist-talks-playing-coachella-berlin-techno-covering-rolling-stones/"] }, // Jan Blomqvist
  "jan-loup": { slug: "jan-loup", bio: { fr: "Jan Loup est une productrice, DJ et technicienne son basée à Toulouse, active depuis 2018. Ses sets assemblent dubstep contemporain, drum & bass profonde et halftime percussif. Elle a joué aux Nuits sonores, à la Gaîté Lyrique, à Positive Education et au Berghain, et co-anime à Toulouse Le Comité Des Fêtes, dédié à la culture sound system.", en: "Jan Loup is a producer, DJ and sound engineer based in Toulouse, active since 2018. Her sets assemble modern dubstep, deep drum & bass and percussive halftime. She has played Nuits sonores, Gaîté Lyrique, Positive Education and Berghain, and co-runs Le Comité Des Fêtes in Toulouse, devoted to sound system culture." }, origin: "Toulouse, France", since: 2018, sources: ["https://www.uselessseconds.com/jan-loup", "https://fr.ra.co/dj/janloup"] }, // Jan Loup
  "jan-vervloet": { slug: "jan-vervloet", bio: { fr: "Jan Vervloet est un producteur et DJ belge actif depuis 1991. Connu pour ses projets dance grand public — Fiocco, Scoop, D.H.T. —, il a publié plus d'une centaine de titres sous différents alias, entre rave, hardcore, techno, progressive house, trance et electro. Fiocco, formé à Anvers, a placé « Afflitto » neuf semaines en tête des charts dance belges avant de se diffuser dans le reste de l'Europe.", en: "Jan Vervloet is a Belgian producer and DJ active since 1991. Known for mainstream dance projects such as Fiocco, Scoop and D.H.T., he has released more than a hundred tracks under various aliases, spanning rave, hardcore, techno, progressive house, trance and electro. Fiocco, formed in Antwerp, held the Belgian dance charts' number one spot for nine weeks with \"Afflitto\" before breaking through the rest of Europe." }, origin: "Anvers, Belgique", since: 1991, labels: ["Bonzai", "High Contrast Recordings", "The Hype Records"], sources: ["https://api.discogs.com/artists/69449", "https://en.wikipedia.org/wiki/Fiocco_(group)"] }, // Jan Vervloet
  "jana-rush": { slug: "jana-rush", bio: { fr: "Jana Rush est une productrice et DJ de Chicago, initiée au mix à dix ans par Jam Master K et Gant-Man. Son premier maxi paraît en 1996 sur Dance Mania, un split avec DJ Deeon, alors qu'elle a quinze ans. Après treize ans d'interruption, elle reprend la production en 2013 et publie l'album Pariah en 2017 : un disque ancré dans le footwork de Chicago, traversé de jungle, d'acid, de jazz et de house.", en: "Jana Rush is a Chicago producer and DJ, taught to mix at ten by Jam Master K and Gant-Man. Her first 12-inch came out in 1996 on Dance Mania, a split with DJ Deeon, when she was fifteen. After a thirteen-year break she returned to production in 2013 and released the album Pariah in 2017, a record rooted in Chicago footwork and shot through with jungle, acid, jazz and house." }, origin: "Chicago, États-Unis", since: 1996, labels: ["Dance Mania", "Objects Limited"], sources: ["https://mixmag.net/feature/chicago-og-jana-rush-creates-unconventional-footwork-thats-making-an-impact", "https://jaru.bandcamp.com/album/pariah"] }, // Jana Rush
  "jane-fitz": { slug: "jane-fitz", bio: { fr: "DJ londonienne, Jane Fitz a débuté comme journaliste musicale avant de partir à Hong Kong à 23 ans, où elle découvre la scène dance locale. Elle a tenu la soirée Peg de 1999 à 2009, puis a lancé Night Moves en 2012 avec Jade Seatle. Ses sets passent de la house profonde à la techno psychédélique, à l'acid et à la trance ; elle est résidente du Pickle Factory à Londres et du festival gallois Freerotation.", en: "London DJ Jane Fitz started out as a music journalist before moving to Hong Kong at 23, where she discovered the local dance scene. She ran the party Peg from 1999 to 2009, then launched Night Moves in 2012 with Jade Seatle. Her sets move between deep house, psychedelic techno, acid and trance; she is a resident at London's Pickle Factory and at the Welsh festival Freerotation." }, origin: "Londres, Royaume-Uni", sources: ["https://tokyo.mutek.org/en/artists/jane-fitz", "https://www.theransomnote.com/music/interviews/dj-to-dj-night-moves-to-night-moves-jade-seatle-jane-fitz/"] }, // Jane Fitz
  "japau": { slug: "japau", bio: { fr: "Berlinois né en 1993, Japau produit une techno hard et industrielle bâtie sur des basses insistantes et des kicks durs. Il fonde en 2019 le label PA•RA•DO•XON 030 avec Luisa Victoria, et joue régulièrement au H7 Warehouse, au Club Basis, ainsi qu'aux soirées Verknipt et Toffler.", en: "Born in Berlin in 1993, Japau makes hard and industrial techno built on driving basslines and hard kicks. In 2019 he founded the PA•RA•DO•XON 030 label with Luisa Victoria, and plays regularly at H7 Warehouse, Club Basis and at Verknipt and Toffler events." }, origin: "Berlin, Allemagne", since: 2019, labels: ["PA•RA•DO•XON 030"], sources: ["https://trifec.one/japau/", "https://soundcloud.com/japau"] }, // Japau
  "jasmine-not-jafar": { slug: "jasmine-not-jafar", bio: { fr: "Jasmine Not Jafar est un duo français de techno live, formé à Tours. Voix et synthétiseurs modulaires y servent une fête revendiquée comme militante et féministe. Le duo a été sélectionné aux iNOUïS du Printemps de Bourges 2026, dont il a remporté le prix du public.", en: "Jasmine Not Jafar are a French live techno duo formed in Tours. Voices and modular synthesisers drive a party they claim as activist and feminist. The duo were selected for the iNOUïS of Printemps de Bourges 2026, where they won the audience prize." }, origin: "Tours, France", sources: ["https://www.printemps-bourges.com/artiste/jasmine-not-jafar/", "https://www.riffx.fr/jasmine-not-jafar-laureates-du-prix-public-riffx-inouis-2026/"] }, // Jasmine Not Jafar
  "jayda-g": { slug: "jayda-g", bio: { fr: "Jayda G, de son vrai nom Jayda Guy, est une productrice et DJ canadienne originaire de Grand Forks, en Colombie-Britannique. Elle a vécu à Vancouver, Berlin puis Londres et a cogéré le label Freakout Cult entre 2015 et 2018. Elle publie sur !K7 Records et a été nommée aux Grammy Awards 2021 dans la catégorie meilleur enregistrement électronique pour « Both of Us ».", en: "Jayda G, born Jayda Guy, is a Canadian producer and DJ from Grand Forks, British Columbia. She has lived in Vancouver, Berlin and London, and co-ran the Freakout Cult label between 2015 and 2018. She releases on !K7 Records and was nominated at the 2021 Grammy Awards in the best dance recording category for \"Both of Us\"." }, origin: "Grand Forks, Canada", since: 2016, labels: ["!K7 Records", "Freakout Cult"], sources: ["https://en.wikipedia.org/wiki/Jayda_G", "https://www.discogs.com/artist/4430477-Jayda-G"] }, // Jayda G
  "jazzy-ch": { slug: "jazzy-ch", bio: { fr: "Jasmin Fumagalli, alias JAZZY, est une DJ et productrice suisse basée à Zurich. Autodidacte formée dans la scène rave underground, elle joue une hard techno brute qu'elle mêle à des éléments de harder styles, de trap et de synthwave. En 2025, elle cofonde le label KRAWALL Records avec Zatox et Jowi, sur lequel sort le titre commun FILTH.", en: "Jasmin Fumagalli, who performs as JAZZY, is a Swiss DJ and producer based in Zurich. Self-taught and shaped by the underground rave scene, she plays a raw strain of hard techno that draws on harder styles, trap and synthwave. In 2025 she co-founded the KRAWALL Records label with Zatox and Jowi, home to their joint single FILTH." }, origin: "Zurich, Suisse", labels: ["KRAWALL Records"], sources: ["https://www.scantraxx.com/labels/krawall-records", "https://fourfourmag.com/in-conversation-with-jazzy-techno-isnt-all-love/", "https://www.beatport.com/release/filth/5536295"] }, // Jazzy (CH)
  "jazzy-ie": { slug: "jazzy-ie", bio: { fr: "Yasmine Byrne, connue sous le nom de Jazzy, est une chanteuse et DJ irlandaise originaire de Dublin. Son style croise dance-pop, house et hip-hop. Son single Giving Me, sorti en 2023, l'a placée en tête du classement des singles irlandais — une première pour une artiste irlandaise depuis quatorze ans.", en: "Yasmine Byrne, who performs as Jazzy, is an Irish singer and DJ from Dublin. Her sound sits between dance-pop, house and hip-hop. Her 2023 single Giving Me took her to number one on the Irish Singles Chart, the first Irish woman to top it in fourteen years." }, origin: "Dublin, Irlande", sources: ["https://en.wikipedia.org/wiki/Jazzy_(singer)", "https://en.wikipedia.org/wiki/Giving_Me", "https://djmag.com/cover-features/jazzy-new-dance-pop-sensation"] }, // Jazzy (IE)
  "jeff-mills": { slug: "jeff-mills", bio: { fr: "Jeff Mills, né le 18 juin 1963 à Détroit, est un DJ, producteur et compositeur américain, également connu sous le nom de « The Wizard ». À la fin des années 1980, il cofonde le collectif Underground Resistance avec Mike Banks et Robert Hood, avant de le quitter pour une carrière solo et de créer son label Axis Records en 1992. Il a reçu l'ordre des Arts et des Lettres en 2017.", en: "Jeff Mills, born 18 June 1963 in Detroit, is an American DJ, producer and composer, also known as \"The Wizard\". In the late 1980s he co-founded the Underground Resistance collective with Mike Banks and Robert Hood, then left for a solo career and started his label Axis Records in 1992. He was awarded the Ordre des Arts et des Lettres in 2017." }, origin: "Détroit, États-Unis", labels: ["Axis Records", "Underground Resistance"], sources: ["https://en.wikipedia.org/wiki/Jeff_Mills"] }, // Jeff Mills
  "jekkamai": { slug: "jekkamai", bio: { fr: "JEKKAMAÏ est un DJ installé à Bruxelles, qui mêle techno, ghettotech et musiques bass dans des sets tournés vers les club sounds internationaux. Il co-fonde et programme SIZZLEPROOF, un collectif et une plateforme consacrés à la visibilité des personnes racisées dans la musique électronique, et tient une résidence sur GIMIC Radio.", en: "JEKKAMAÏ is a Brussels-based DJ mixing techno, ghettotech and bass music in sets built on global club sounds. He co-founded and curates SIZZLEPROOF, a collective and platform dedicated to highlighting people of colour in electronic music, and holds a residency on GIMIC Radio." }, origin: "Bruxelles, Belgique", sources: ["https://www.kurious.be/artists/jekkamai/"] }, // JEKKAMAÏ
  "jennifer-cardini": { slug: "jennifer-cardini", bio: { fr: "Jennifer Cardini est une DJ et productrice française installée à Berlin, derrière les platines depuis une trentaine d'années. Formée dans les clubs parisiens, où elle tient une résidence au Pulp, elle sort le mix Feeling Strange chez Kompakt avant de fonder en 2011 le label Correspondant, prolongement de sa résidence au Rex Club. Elle dirige aussi Dischi Autunno et, depuis 2023, Færies Records, monté avec l'artiste et cinéaste Lou Fauroux.", en: "Jennifer Cardini is a French DJ and producer based in Berlin who has been behind the decks for some thirty years. She came up in Paris clubs, with a residency at Le Pulp, released the mix Feeling Strange on Kompakt, and in 2011 founded the label Correspondant as an extension of her Rex Club residency. She also runs Dischi Autunno and, since 2023, Færies Records, set up with the artist and filmmaker Lou Fauroux." }, origin: "France, installée à Berlin", labels: ["Correspondant", "Dischi Autunno", "Færies Records"], sources: ["https://djmag.com/news/jennifer-cardini-celebrates-30-years-djing-new-label-faeries-records", "https://correspondantmusic.com/jennifer-cardini/biography/"] }, // Jennifer Cardini
  "jennifer-loveless": { slug: "jennifer-loveless", bio: { fr: "DJ et productrice originaire de Melbourne, Jennifer Loveless publie depuis 2007 sur Butter Sessions, Pure Space Recordings et Sex Tags UFO. Ses disques circulent entre house, techno, electro et ambient.", en: "A DJ and producer from Melbourne, Jennifer Loveless has been releasing since 2007 on Butter Sessions, Pure Space Recordings and Sex Tags UFO. Her records move between house, techno, electro and ambient." }, origin: "Melbourne, Australie", labels: ["Butter Sessions", "Pure Space Recordings"], sources: ["https://www.discogs.com/artist/7651260-Jennifer-Loveless", "http://jenniferloveless.com/"] }, // Jennifer Loveless
  "joachim-pastor": { slug: "joachim-pastor", bio: { fr: "Joachim Pastor est un DJ et producteur français originaire de Paris, rattaché à la scène techno mélodique. Il cofonde en 2013 le label et collectif Hungry Music avec Worakls et NTO, avant de rejoindre Armada Music en 2020 pour y publier son premier album, Greater Message. Sa musique, aux harmonies orchestrales et cinématographiques, s'est prolongée avec l'album PHANTOMGRID en 2025 et la bande originale du documentaire The Final Season.", en: "Joachim Pastor is a French DJ and producer from Paris, part of the melodic techno scene. He co-founded the Hungry Music label and collective with Worakls and NTO in 2013, then joined Armada Music in 2020 to release his first album, Greater Message. His music, built on orchestral and cinematic harmonies, continued with the album PHANTOMGRID in 2025 and the score for the documentary The Final Season." }, origin: "Paris, France", labels: ["Hungry Music", "Armada Music"], sources: ["https://www.armadamusic.com/artists/joachim-pastor-1", "https://en.wikipedia.org/wiki/Hungry_Music", "https://www.discogs.com/artist/1355294"] }, // Joachim Pastor
  "joakim-lundell": { slug: "joakim-lundell", bio: { fr: "Joakim Alexander Lundell, né le 9 octobre 1985, également connu sous le nom de Jockiboi, est un vidéaste, personnalité médiatique et musicien suédois. Il produit de la musique électronique de danse et a notamment publié « All I Need » avec Arrhult et « Sun Goes Down » avec Oberg.", en: "Joakim Alexander Lundell, born 9 October 1985 and also known as Jockiboi, is a Swedish YouTuber, media personality and musician. He produces electronic dance music and has released tracks including 'All I Need' with Arrhult and 'Sun Goes Down' with Oberg." }, origin: "Suède", sources: ["https://en.wikipedia.org/wiki/Joakim_Lundell", "https://www.viberate.com/artist/joakim-lundell/"] }, // Joakim Lundell
  "job-jobse": { slug: "job-jobse", bio: { fr: "Job Jobse est un DJ néerlandais installé à Amsterdam. Il a d'abord programmé le club Trouw, où il est passé d'assistant à responsable des bookings, avant de devenir résident de son successeur De School. En avril 2012, il fait venir Tale of Us pour la première soirée du label Life and Death, dont il devient ensuite le manager. Il a lancé en septembre 2025 son propre label, Planet Strangelove, inauguré par quatre relectures de « Pasion » de Pianoman.", en: "Job Jobse is a Dutch DJ based in Amsterdam. He first worked as a programmer at the Trouw club, rising from assistant to head booker, before becoming a resident at its successor De School. In April 2012 he booked Tale of Us for the first Life and Death label night, and went on to manage the label. In September 2025 he launched his own imprint, Planet Strangelove, opened by four reworks of Pianoman's \"Pasion\"." }, origin: "Amsterdam, Pays-Bas", labels: ["Planet Strangelove", "Life and Death"], sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/job-jobse/20342/", "https://www.skiddle.com/news/all/Dutch-DJ-producer-Job-Jobse-launches-new-label-Planet-Strangelove/60530/"] }, // Job Jobse
  "johannes-schuster": { slug: "johannes-schuster", bio: { fr: "Johannes Schuster est un DJ et producteur de hard techno basé à Cologne, résident de l'Artheater depuis 2017 ainsi que des soirées 303 et Unreal. Il mêle sonorités industrielles, acid et grooves old-school, et a sorti des disques sur Soma, Green Fetish, Voxnox et RND Records.", en: "Johannes Schuster is a hard techno DJ and producer based in Cologne, resident at the Artheater since 2017 as well as the 303 and Unreal nights. He blends industrial sounds, acid and old-school grooves, and has released on Soma, Green Fetish, Voxnox and RND Records." }, origin: "Cologne, Allemagne", since: 2017, labels: ["Soma", "Voxnox", "Green Fetish"], sources: ["https://electronicgroove.com/artist-profile-johannes-schuster/", "https://soma-records.bandcamp.com/album/panic-ep"] }, // Johannes Schuster
  "john-digweed": { slug: "john-digweed", bio: { fr: "John Digweed est un DJ et producteur britannique né en 1967 à Hastings. Il forme avec Sasha le duo Sasha & John Digweed, et le projet Bedrock avec Nick Muir. Il a été élu numéro un du classement DJ Mag en 2001. Sa discographie relève surtout de la progressive house et de la tech house.", en: "John Digweed is a British DJ and producer born in 1967 in Hastings. He forms the duo Sasha & John Digweed with Sasha, and Bedrock with Nick Muir. He was voted No. 1 DJ in DJ Mag in 2001. His catalogue is mostly progressive house and tech house." }, origin: "Hastings, Royaume-Uni", sources: ["https://en.wikipedia.org/wiki/John_Digweed", "https://api.discogs.com/database/search?artist=John+Digweed&type=release&per_page=50"] }, // John Digweed
  "john-morales": { slug: "john-morales", bio: { fr: "DJ du Bronx depuis le début des années 1970, John Morales s'est mis en 1975 à découper la bande magnétique à la lame de rasoir pour allonger ses disques : il fait partie des premiers à produire des « extended mixes » et des medleys, d'abord diffusés en acétates via Sunshine Sound. Ses deux premiers mixes officiels, « Dance and Shake Your Tambourine » (Universal Robot Band) et « I'm Caught Up » (Inner Life), le font connaître ; il signe ensuite plus de cinq cents titres, seul et avec Sergio Munzibai sous le nom M & M Productions.", en: "A Bronx DJ since the early 1970s, John Morales started splicing tape with razor blades in 1975 to make his records last longer, and was among the first to produce \"extended mixes\" and medleys, initially issued as acetates through Sunshine Sound. His first two official mixes, \"Dance and Shake Your Tambourine\" (Universal Robot Band) and \"I'm Caught Up\" (Inner Life), made his name; he has since worked on more than five hundred songs, alone and with Sergio Munzibai as M & M Productions." }, origin: "Bronx, New York, États-Unis", since: 1975, sources: ["https://www.discogs.com/artist/49258", "https://api.discogs.com/artists/49258"] }, // John Morales
  "jonathan-kaspar": { slug: "jonathan-kaspar", bio: { fr: "Jonathan Kaspar est un DJ et producteur allemand basé à Cologne, résident du club Gewölbe. Il fait partie des artistes du label colonais Kompakt et a publié sur Crosstown Rebels, Objektivity, Pets Recordings, Poker Flat et l'antenne KX de Kompakt. Ses sets, décrits comme mélodiques et groovy, tiennent aussi bien la place de warm-up que celle de tête d'affiche.", en: "Jonathan Kaspar is a German DJ and producer based in Cologne, where he holds a residency at the Gewölbe club. He is one of the artists on the Cologne label Kompakt and has released on Crosstown Rebels, Objektivity, Pets Recordings, Poker Flat and Kompakt's KX imprint. His sets, described as melodic and groovy, work as warm-ups as well as headline slots." }, origin: "Cologne, Allemagne", labels: ["Kompakt", "Crosstown Rebels", "Poker Flat", "Pets Recordings"], sources: ["https://kompakt.fm/artists/jonathankaspar"] }, // Jonathan Kaspar
  "jordan-brando": { slug: "jordan-brando", bio: { fr: "Jordan Brando est un DJ et producteur australien né et élevé à Melbourne. Sa musique mêle tech house, house et techno, avec des basses appuyées et des percussions serrées. Sa première sortie sur Club Sweat, « Rockin », date de 2018 ; il a depuis publié sur Defected, Relief et Toolroom.", en: "Jordan Brando is an Australian DJ and producer born and raised in Melbourne. His music blends tech house, house and techno, with driving basslines and tight percussion. His first Club Sweat release, \"Rockin\", came out in 2018; he has since released on Defected, Relief and Toolroom." }, origin: "Melbourne, Australie", since: 2018, labels: ["Club Sweat", "Defected", "Toolroom"], sources: ["https://clubsweat.bandcamp.com/album/rockin", "https://themusic.com.au/features/meet-sweat-it-out-s-new-signing-jordan-brando-and-his-steamy-new-thumper-rockin/vvF80NPS1dQ/13-09-18"] }, // Jordan Brando
  "joris-delacroix": { slug: "joris-delacroix", bio: { fr: "Joris Delacroix, né en 1987 à Montpellier, est un musicien, producteur et DJ français. Formé au piano dès quatre ans, il découvre la musique électronique à seize ans et publie son premier EP en 2008 sur Timid Records. Signé ensuite chez Way of House, il sort l'album Room With View en 2011, puis Going Back en 2016 et Night Visions en 2018 ; son répertoire relève de la house, de la deep house et de la techno mélodique.", en: "Joris Delacroix, born in 1987 in Montpellier, is a French musician, producer and DJ. Trained on piano from the age of four, he discovered electronic music at sixteen and released his first EP on Timid Records in 2008. Later signed to Way of House, he released the album Room With View in 2011, followed by Going Back in 2016 and Night Visions in 2018; his output sits in house, deep house and melodic techno." }, origin: "Montpellier, France", since: 2008, labels: ["Way of House", "Hungry Music"], sources: ["https://fr.wikipedia.org/wiki/Joris_Delacroix"] }, // Joris Delacroix
  "joris-voorn": { slug: "joris-voorn", bio: { fr: "Joris Voorn, né le 25 février 1977, est un DJ et producteur néerlandais qui vit à Amsterdam. Il a lancé sa carrière avec les EP « Muted Trax » (2002) et « Lost Memories » (2003), et a été élu talent de l'année aux Dutch DJ Awards en 2003. Il codirige avec Edwin Oosterwal les labels amstellodamois Green, fondé en 2005, et Rejected. Sa compilation Balance 014, parue en 2009, mélange cent morceaux sur un double CD.", en: "Joris Voorn, born 25 February 1977, is a Dutch DJ and producer who lives in Amsterdam. He launched his career with the EPs \"Muted Trax\" (2002) and \"Lost Memories\" (2003), and was named Talent of the Year at the Dutch DJ Awards in 2003. With Edwin Oosterwal he co-runs the Amsterdam labels Green, founded in 2005, and Rejected. His 2009 compilation Balance 014 blends one hundred tracks across a double CD." }, origin: "Amsterdam, Pays-Bas", since: 2002, labels: ["Green", "Rejected"], sources: ["https://en.wikipedia.org/wiki/Joris_Voorn"] }, // Joris Voorn
  "jorja-smith": { slug: "jorja-smith", bio: { fr: "Jorja Smith est une chanteuse et autrice-compositrice anglaise née en 1997 à Walsall, dans les Midlands de l'Ouest. Repérée en 2016, elle publie deux EP puis l'album Lost & Found en 2018. Sa musique est classée entre R&B, pop, hip-hop, grime et UK garage.", en: "Jorja Smith is an English singer and songwriter born in 1997 in Walsall, West Midlands. Signed in 2016, she released two EPs and then the album Lost & Found in 2018. Her music is classified across R&B, pop, hip-hop, grime and UK garage." }, origin: "Walsall, Royaume-Uni", since: 2016, labels: ["FAMM"], sources: ["https://en.wikipedia.org/wiki/Jorja_Smith"] }, // Jorja Smith
  "joseph-capriati": { slug: "joseph-capriati", bio: { fr: "Joseph Capriati, né Giuseppe Capriati en 1987 à Caserte, est un DJ et producteur italien. Il commence à mixer à onze ans dans sa ville natale, puis devient résident du Disco Seven sous le nom de Prince J. Son premier disque, le « Formaldehyde EP », paraît en 2007 sur Globox Recordings ; il enchaîne ensuite les sorties sur Drumcode, CLR et Analytic Trail avant de fonder son propre label, Redimension Music.", en: "Joseph Capriati, born Giuseppe Capriati in 1987 in Caserta, is an Italian DJ and producer. He started DJing at eleven in his home town, then became a resident at Disco Seven under the name Prince J. His first record, the \"Formaldehyde EP\", came out in 2007 on Globox Recordings; releases on Drumcode, CLR and Analytic Trail followed, before he founded his own label, Redimension Music." }, origin: "Caserte, Italie", since: 2006, labels: ["Redimension Music"], sources: ["https://en.wikipedia.org/wiki/Joseph_Capriati"] }, // Joseph Capriati
  "josh-baker": { slug: "josh-baker", bio: { fr: "Josh Baker est un DJ, producteur et patron de label britannique basé à Manchester, qui a commencé à mixer à 17 ans. Il produit une house minimale et deep tech, secteur dans lequel il a été l'artiste et le label les plus vendus sur Beatport. Il codirige le label et la soirée You&Me, a lancé le Hide&Seek Festival dans le nord-ouest de l'Angleterre, et cofondé la plateforme d'apprentissage en ligne Syntho Hub. Mixmag l'a cité parmi les DJ qui façonnent 2025.", en: "Josh Baker is a British DJ, producer and label owner based in Manchester, who started DJing at 17. He makes minimal and deep tech house, a field in which he has been Beatport's best-selling artist and label. He co-runs the You&Me label and party, launched the Hide&Seek Festival in North West England, and co-founded the online learning platform Syntho Hub. Mixmag named him among the DJs shaping 2025." }, origin: "Manchester, Royaume-Uni", labels: ["You&Me"], sources: ["https://www.internationalmusicsummit.com/ims-speakers/josh-baker"] }, // Josh Baker
  "joshwa": { slug: "joshwa", bio: { fr: "Joshua Dickens, DJ et producteur britannique, s'est formé seul à la production à l'adolescence avant de se faire remarquer en 2018 avec un remix de « Praise You » de Fatboy Slim. Son morceau « My Humps » avec Lee Foss (2021) puis l'EP Bass Go Boom (2023) sur Hot Creations l'installent dans la tech house. Il dirige ses propres labels, No Bad Fridays et No Bad Edits.", en: "Joshua Dickens, a British DJ and producer, taught himself production as a teenager before drawing attention in 2018 with a remix of Fatboy Slim's \"Praise You\". His track \"My Humps\" with Lee Foss (2021) and then the Bass Go Boom EP (2023) on Hot Creations established him in tech house. He runs his own labels, No Bad Fridays and No Bad Edits." }, origin: "Royaume-Uni", since: 2018, labels: ["Hot Creations", "No Bad Fridays"], sources: ["https://www.beatportal.com/articles/1017091-joshwa-drops-disco-laced-house-ep-lost-in-music-on-hot-creations", "https://www.beatportal.com/articles/464256-joshwa-lands-on-hot-creations-with-bass-go-boom-ep", "https://www.cultr.com/news/uk-dj-producer-joshwa-drops-highly-anticipated-ep-on-hot-creations/"] }, // Joshwa
  "joss-dean": { slug: "joss-dean", bio: { fr: "Joss Dean est un DJ et producteur britannique installé à Londres, actif dans la scène house underground du pays. Il joue une house profonde et dépouillée, qu'il décrit lui-même comme hypnotique et minimale mais toujours tenue par un groove ; son morceau « Was I Loved? » en donne la mesure. Frère du DJ Max Dean et cousin de Luke Dean, il a grandi entouré de house et joue à Amnesia, au DC-10 et au Studio 338.", en: "Joss Dean is a British DJ and producer based in London, active on the country's underground house circuit. He plays deep, stripped-back house that he describes as hypnotic and minimal but always held together by groove; his track \"Was I Loved?\" shows what he means. The brother of DJ Max Dean and cousin of Luke Dean, he grew up surrounded by house and plays Amnesia, DC-10 and Studio 338." }, origin: "Londres, Royaume-Uni", sources: ["https://magneticmag.com/2026/03/joss-dean-interview/"] }, // Joss Dean
  "jowi": { slug: "jowi", bio: { fr: "Jowi est une DJ et productrice suisse basée à Lugano, qui joue une hard techno industrielle teintée de gabber. En octobre 2025, elle cofonde avec Jazzy et Zatox le label KRAWALL Records, conçu comme un point de chute pour les artistes qui poussent la dance music vers le plus dur, quel que soit le genre. C'est là qu'est paru son single « Submerged » en juin 2026.", en: "Jowi is a Swiss DJ and producer based in Lugano who plays industrial hard techno with a gabber edge. In October 2025 she co-founded the label KRAWALL Records with Jazzy and Zatox, meant as a home for artists pushing dance music in a harder direction whatever the genre. Her single \"Submerged\" came out there in June 2026." }, origin: "Lugano, Suisse", since: 2025, labels: ["KRAWALL Records"], sources: ["https://www.musicnews.com/news/2026-06-14-jowi-releases-hard-techno-single-submerged-on-new-label-krawall-records"] }, // Jowi
  "joy-orbison": { slug: "joy-orbison", bio: { fr: "Joy Orbison, de son vrai nom Peter O'Grady, est un producteur et DJ anglais né en 1986 à Croydon, au sud de Londres. Sa musique croise house, dubstep, UK funky, UK garage et jungle, une combinaison qui a explosé avec « Hyph Mngo », paru chez Hotflush Recordings en 2009. Il a cofondé le label Hinge Finger en 2012 avec Will Bankhead et publié l'album Still Slipping Vol. 1 en 2021.", en: "Joy Orbison, real name Peter O'Grady, is an English producer and DJ born in 1986 in Croydon, south London. His music crosses house, dubstep, UK funky, UK garage and jungle, a mix that broke wide open with \"Hyph Mngo\", released on Hotflush Recordings in 2009. He co-founded the label Hinge Finger with Will Bankhead in 2012 and put out the album Still Slipping Vol. 1 in 2021." }, origin: "Croydon, Royaume-Uni", since: 2009, labels: ["Hinge Finger", "Hotflush Recordings"], sources: ["https://en.wikipedia.org/wiki/Joy_Orbison"] }, // Joy Orbison
  "justin-jay": { slug: "justin-jay", bio: { fr: "Justin Jay est un producteur et DJ américain installé à Los Angeles. Il signe sa première sortie sur le label Dirtybird de Claude VonStroke en 2011, alors qu'il est encore étudiant à l'USC, puis publie sur Culprit, Southern Fried Records et Pets Recordings avant de fonder son propre label, Fantastic Voyage. Sa house emprunte à la soul, au funk et au jazz, souvent avec des instruments joués.", en: "Justin Jay is an American producer and DJ based in Los Angeles. His first release came out on Claude VonStroke's Dirtybird label in 2011, while he was still a student at USC; he went on to release on Culprit, Southern Fried Records and Pets Recordings before founding his own label, Fantastic Voyage. His house music draws on soul, funk and jazz, often with live instruments." }, origin: "Los Angeles, États-Unis", since: 2011, labels: ["Dirtybird", "Fantastic Voyage"], sources: ["https://www.grammy.com/news/justin-jay-joy-djing-expanding-his-horizons-and-how-fans-think-hes-still-college/", "https://eclecticartists.com/justin-jay/"] }, // Justin Jay
  "k-lone": { slug: "k-lone", bio: { fr: "K-LONE est le nom de scène de Josiah Gladwell, producteur et DJ britannique. Il codirige avec Facta le label Wisdom Teeth, fondé en 2014, et gère deux autres structures, Sweet N Tasty et Wych. Son premier album Cape Cira paraît en 2020, suivi de Swells en juillet 2023, un disque tourné vers la deep house et la pop électronique avec une participation vocale d'Eliza Rose.", en: "K-LONE is the stage name of Josiah Gladwell, a British producer and DJ. With Facta he co-runs the Wisdom Teeth label, founded in 2014, and he also runs two further imprints, Sweet N Tasty and Wych. His first album, Cape Cira, came out in 2020, followed by Swells in July 2023, a record leaning towards deep house and electronic pop with guest vocals from Eliza Rose." }, origin: "Royaume-Uni", since: 2014, labels: ["Wisdom Teeth", "Sweet N Tasty", "Wych"], sources: ["https://wisdomteethuk.bandcamp.com/artists", "https://djmag.com/news/k-lone-announces-new-album-swells-wisdom-teeth"] }, // K-LONE
  "k-motionz": { slug: "k-motionz", bio: { fr: "K Motionz est un producteur et DJ britannique de drum & bass. Il évolue principalement dans le registre jump up, la branche la plus percussive et la plus club du genre.", en: "K Motionz is a British drum & bass producer and DJ. He works mainly in jump up, the most percussive, club-oriented branch of the genre." }, origin: "Royaume-Uni", sources: ["https://www.last.fm/music/K+Motionz/+tags", "https://www.discogs.com/artist/3012443-K-Motionz"] }, // K Motionz
  "k-tee": { slug: "k-tee", bio: { fr: "K-Tee est une DJ et curatrice lausannoise. Ses sets mêlent techno, UK bass et drum & bass. Elle est régulièrement programmée à La Gravière, à Genève, où elle a joué en février 2026 aux côtés d'Animistic Beliefs et en août 2026 avec le trio américain Black Rave Culture.", en: "K-Tee is a DJ and curator based in Lausanne. Her sets bring together techno, UK bass and drum & bass. She plays regularly at La Gravière in Geneva, where she shared the bill with Animistic Beliefs in February 2026 and with the American trio Black Rave Culture in August 2026." }, origin: "Lausanne, Suisse", sources: ["http://lagraviere.ch/evenement/pulsion-11/", "http://lagraviere.ch/evenement/black-rave-culture/"] }, // K-Tee
  "kaizersoze": { slug: "kaizersoze", bio: { fr: "Olivier Muller mixe depuis plus de trente ans sur la scène électronique suisse, d'abord sous le pseudonyme Millenium, aujourd'hui sous celui de Kaizersoze. Basé à Genève, il a joué en Europe et en Amérique latine et partagé les platines avec Erick Morillo et DJ Pierre. Son répertoire va de la deep house à la tech house et à la deep tech, avec des sonorités afro-latines. Il est le fondateur et résident de la série de soirées Santeria.", en: "Olivier Muller has been DJing on the Swiss electronic scene for over thirty years, first under the alias Millenium and now as Kaizersoze. Based in Geneva, he has played across Europe and Latin America and shared decks with Erick Morillo and DJ Pierre. His range runs from deep house to tech house and deep tech, with Afro-Latin colours. He founded and resides at the Santeria party series." }, origin: "Genève, Suisse", sources: ["https://www.mixcloud.com/kaizersoze/"] }, // Kaizersoze
  "kamafaka": { slug: "kamafaka", bio: { fr: "Kamafaka est une DJ hongroise basée à Budapest. Elle joue du hardcore, de la frenchcore, de la hard techno et de la techno industrielle. Elle a fondé Pinkcore, série de soirées hardcore à Budapest, et fait partie du collectif NoFear unity.", en: "Kamafaka is a Hungarian DJ based in Budapest. She plays hardcore, frenchcore, hard techno and industrial techno. She founded Pinkcore, a hardcore party series in Budapest, and is part of the NoFear unity collective." }, origin: "Budapest, Hongrie", sources: ["https://xceed.me/en/artist/kamafaka"] }, // Kamafaka
  "kamma": { slug: "kamma", bio: { fr: "Kamma est une DJ et productrice d'Amsterdam, d'origine sino-indonésienne, qui a grandi avec des parents DJ. Ses sets mêlent house chaleureuse, techno planante et disco. Avec Masalo, elle lance en 2014 la soirée Brighter Days, devenue un rendez-vous de la nuit amstellodamoise ; le duo en publie une compilation sur Rush Hour en 2023 et compte parmi les collaborateurs de longue date de Rush Hour et Dekmantel.", en: "Kamma is a DJ and producer from Amsterdam, of Chinese-Indonesian heritage, who grew up with DJ parents. Her sets blend warm house, trippy techno and disco. With Masalo she started the Brighter Days party in 2014, now a fixture of Amsterdam nightlife; the duo released a Brighter Days compilation on Rush Hour in 2023 and are longtime collaborators of Rush Hour and Dekmantel." }, origin: "Amsterdam, Pays-Bas", since: 2014, labels: ["Rush Hour"], sources: ["https://djmag.com/longreads/positive-vibrations-kamma", "https://rushhourmusic.bandcamp.com/album/brighter-days-2"] }, // Kamma
  "kandelissa": { slug: "kandelissa", bio: { fr: "Kandelissa est une DJ et productrice française basée à Paris. Ses sets mêlent techno groovy, hardgroove, hard house et techno tribale.", en: "Kandelissa is a French DJ and producer based in Paris. Her sets mix groovy techno, hardgroove, hard house and tribal techno." }, origin: "Paris, France", sources: ["https://soundcloud.com/lethimcookradio/kendelissa-let-him-cook-radio-groovy-techno-hardgroove-hard-house-tribal-techno"] }, // Kandelissa
  "kangding-ray": { slug: "kangding-ray", bio: { fr: "Kangding Ray, né en 1978, est un musicien, DJ et producteur français installé à Berlin. Il a signé la bande originale du film Sirāt d'Óliver Laxe (2025). Sa musique relève de la techno et de l'électronique expérimentale.", en: "Kangding Ray, born in 1978, is a French musician, DJ and producer based in Berlin. He wrote the score for Oliver Laxe's 2025 film Sirat. His music sits between techno and experimental electronics." }, origin: "Berlin, Allemagne", sources: ["https://en.wikipedia.org/wiki/Kangding_Ray"] }, // Kangding Ray
  "karah": { slug: "karah", bio: { fr: "KARAH, de son prénom Kadir, est un DJ, producteur et patron de label né et installé à Rotterdam. Il se lance dans la hard techno en 2019 et fonde la même année le label Falsive Records, qui a publié Charlie Sparks, D.N.P, KOZLOV, Oguz, Franky-B et Don Woezik. Il joue en 2026 au Rotterdam Rave Festival, à l'Ahoy.", en: "KARAH, first name Kadir, is a DJ, producer and label owner born and based in Rotterdam. He moved into hard techno in 2019 and founded the Falsive Records label the same year, which has released Charlie Sparks, D.N.P, KOZLOV, Oguz, Franky-B and Don Woezik. In 2026 he plays Rotterdam Rave Festival at the Ahoy." }, origin: "Rotterdam, Pays-Bas", since: 2019, labels: ["Falsive Records"], sources: ["https://promogogo.com/karah/artist/fb03c13e-4ad2-43d6-8935-689961dc1ede"] }, // KARAH
  "karakals": { slug: "karakals", bio: { fr: "Karakals est le nom de scène de Chloë Beyers, DJ belge. Elle commence en 2017 en duo avec Ivan Herrera — les deux atteignent la finale du concours MNM Start To DJ en 2020 — puis poursuit en solo à partir de 2022. Elle a joué à Tomorrowland, au Sunrise Festival, à Rock Werchter et au Balaton Sound, et anime depuis 2025 une émission hebdomadaire sur Qmusic.", en: "Karakals is the stage name of Chloë Beyers, a Belgian DJ. She started in 2017 as a duo with Ivan Herrera — the pair reached the final of the MNM Start To DJ contest in 2020 — then went solo in 2022. She has played Tomorrowland, Sunrise Festival, Rock Werchter and Balaton Sound, and has hosted a weekly show on Qmusic since 2025." }, origin: "Belgique", since: 2017, sources: ["https://karakals.be/", "https://nl.wikipedia.org/wiki/Karakals"] }, // Karakals
  "karlfroye": { slug: "karlfroye", bio: { fr: "Productrice et DJ hardcore du sud de la France, Karlfroye construit des sets narratifs où se croisent gabber, jumpstyle, hardcore et musique de jeu vidéo. Elle est résidente de la radio OLA et a joué au Petit Bain, à La Machine du Moulin Rouge et à La Station - Gare des Mines à Paris, au Recyclart à Bruxelles et à la Rote Fabrik de Zurich.", en: "A hardcore producer and DJ from the south of France, Karlfroye builds narrative sets that run gabber, jumpstyle, hardcore and video-game music together. She is a resident at OLA Radio and has played Petit Bain, La Machine du Moulin Rouge and La Station - Gare des Mines in Paris, Recyclart in Brussels and Rote Fabrik in Zurich." }, origin: "France", sources: ["https://ra.co/dj/karlfroye/biography", "https://www.disversive.com/karlfroye"] }, // Karlfroye
  "kathleen-c": { slug: "kathleen-c", bio: { fr: "Kathleen C est un DJ queer basé à Bruxelles, venu du son : sa formation d'ingénieur du son nourrit des sets qui passent des beats de club rebondissants à des sonorités plus profondes. Il y croise house old-school, trance progressive, rythmes latins percussifs et ghettotech. Avec son ami romanou, il a fondé le collectif pluridisciplinaire « still lookin'… ». Il est programmé au C12, à Bruxelles.", en: "Kathleen C is a queer Brussels-based DJ with a background in sound engineering, which feeds sets that move from fresh, bouncy club beats to deeper sonorities. They take in old-school house, progressive trance, percussive Latin rhythms and ghettotech. With his friend romanou he founded the multi-disciplinary collective \"still lookin'…\". He plays regularly at C12 in Brussels." }, origin: "Bruxelles, Belgique", sources: ["https://c12space.com/event/c12-nite-w-paramida-kathleen-c-softy/"] }, // Kathleen C
  "kaufmann": { slug: "kaufmann", bio: { fr: "Lisa Kaufmann, qui signe Kaufmann (DE), est une DJ et productrice allemande installée à Berlin. Elle sort des disques depuis 2020, sur Drumcode, Stil vor Talent, Truesoul et Senso Sounds notamment, et ses sets circulent entre techno minimale sombre, textures psychédéliques et grooves de peak time. Elle a joué l'Awakenings ADE dans le plateau Drumcode.", en: "Lisa Kaufmann, who records as Kaufmann (DE), is a German DJ and producer based in Berlin. She has been releasing since 2020 on Drumcode, Stil vor Talent, Truesoul and Senso Sounds among others, and her sets move between dark minimal techno, psychedelic textures and peak-time grooves. She has played Awakenings ADE on the Drumcode lineup." }, origin: "Allemagne (basée à Berlin)", since: 2020, labels: ["Drumcode", "Stil vor Talent", "Truesoul"], sources: ["https://electronicgroove.com/eg-artists/eg-techno153-kaufmann/", "https://www.amsterdam-dance-event.nl/en/program/2026/awakenings-ade-drumcode/2806492/"] }, // Kaufmann
  "kavari": { slug: "kavari", bio: { fr: "Née à Birkenhead près de Liverpool et installée à Glasgow, KAVARI est productrice et DJ. Elle se fait connaître au début des années 2020 par ses bootlegs et ses packs d'edits « Lost Cuts » diffusés sur Bandcamp, puis par « Attachment Style (VIP) ». Son travail croise drum & bass, dubstep et noise, avec la distorsion et la rupture de structure pour matière première. Son EP « Plague Music » paraît en février 2026 chez XL Recordings.", en: "Born in Birkenhead near Liverpool and based in Glasgow, KAVARI is a producer and DJ. She emerged in the early 2020s through bootlegs and the \"Lost Cuts\" edit packs on Bandcamp, then through \"Attachment Style (VIP)\". Her work crosses drum & bass, dubstep and noise, built on distortion and structural disruption. Her EP \"Plague Music\" came out on XL Recordings in February 2026." }, origin: "Glasgow, Écosse", labels: ["XL Recordings"], sources: ["https://djmag.com/news/kavari-announces-new-ep-plague-music-xl-shares-iron-veins-listen", "https://www.thefader.com/2026/02/09/kavari-plague-music-ep-interview", "https://www.xlrecordings.com/artists/kavari"] }, // KAVARI
  "kaytranada": { slug: "kaytranada", bio: { fr: "Louis Kevin Celestin, né en 1992 à Port-au-Prince et élevé à Montréal, produit sous le nom Kaytranada depuis 2012. Son remix de « If » de Janet Jackson l'a fait connaître sur SoundCloud en 2013, avant une signature chez XL Recordings fin 2014. Son album 99.9% (2016) a remporté le prix Polaris, et Bubba (2019) deux Grammy Awards. Son écriture croise house, funk, R&B et hip-hop.", en: "Louis Kevin Celestin, born in 1992 in Port-au-Prince and raised in Montreal, has produced as Kaytranada since 2012. His remix of Janet Jackson's \"If\" broke him on SoundCloud in 2013, leading to a deal with XL Recordings in late 2014. His album 99.9% (2016) won the Polaris Music Prize and Bubba (2019) took two Grammy Awards. His writing sits between house, funk, R&B and hip-hop." }, origin: "Montréal, Canada", since: 2012, labels: ["XL Recordings", "RCA Records", "HW&W"], sources: ["https://en.wikipedia.org/wiki/Kaytranada"] }, // Kaytranada
  "ken-ming": { slug: "ken-ming", bio: { fr: "Ken-Ming est un DJ néerlandais installé à Amsterdam, qui puise dans ses origines hongkongaises pour faire dialoguer les deux villes. Il joue une techno tribale mêlée de breakbeat, entre groove et expérimentation.", en: "Ken-Ming is a Dutch DJ based in Amsterdam who draws on his Hong Kong roots to bridge the two cities. He plays tribal techno laced with breakbeat, between groove and experimentation." }, origin: "Amsterdam, Pays-Bas", sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/ken-ming/2622939/"] }, // Ken-Ming
  "kendal": { slug: "kendal", bio: { fr: "Kendal est un producteur et DJ français basé à Toulouse, qui mêle italo-disco, EBM, trance des débuts et synth-wave. Son premier EP, « Manifesto », sort sur Moustache Records en 2019. En 2020 il fonde avec Paul Guglielmi le label Ritmo Fatale, qui revendique un son d'« italo body music ». Il forme aussi le duo INFRAVISION avec Pablo Bozzi, dont l'album « Illegal Future » est paru en 2023.", en: "Kendal is a French producer and DJ based in Toulouse who blends italo-disco, EBM, early trance and synth-wave. His first EP, \"Manifesto\", came out on Moustache Records in 2019. In 2020 he founded the Ritmo Fatale label with Paul Guglielmi, built around a sound they call \"italo body music\". He also forms the duo INFRAVISION with Pablo Bozzi, whose album \"Illegal Future\" was released in 2023." }, origin: "Toulouse, France", since: 2019, labels: ["Ritmo Fatale", "Moustache Records"], sources: ["https://www.undrtone.co.uk/post/kendal-on-nostalgia-futurism-and-the-rise-of-ritmo-fatale", "https://www.phonographecorp.com/chroniques/interviews/ritmo-fatale-kendal-mulla-amp-paul-guglielmi/"] }, // Kendal
  "kerrie": { slug: "kerrie", bio: { fr: "Kerrie est une DJ et productrice irlandaise installée à Manchester, où elle a passé onze ans au disquaire Eastern Bloc Records avant d'y lancer un espace de soirées en 2017. Elle produit et joue exclusivement en live sur machines, entre techno brute et rythmes cassés teintés d'electro. Après un EP sur Blueprint en 2022, Tresor l'annonce résidente du club berlinois début 2024 et publie son EP « Machine Alliance ». Elle dirige son label Dark Machine Funk.", en: "Kerrie is an Irish DJ and producer based in Manchester, where she spent eleven years at the record shop Eastern Bloc Records before opening its in-house event space in 2017. She produces and performs live on a hardware-only setup, between raw techno and broken, electro-tinged rhythms. After an EP on Blueprint in 2022, Tresor announced her as a resident of the Berlin club in early 2024 and released her EP \"Machine Alliance\". She runs her own label, Dark Machine Funk." }, origin: "Irlande / Manchester, Royaume-Uni", labels: ["Dark Machine Funk", "Tresor", "Blueprint"], sources: ["https://tresorberlin.com/artist/kerrie/", "https://www.soundonsound.com/people/kerrie-techno-dj-producer-sos-podcast"] }, // Kerrie
  "kettama": { slug: "kettama", bio: { fr: "Evan Campbell, né en 1997 à Galway en Irlande, produit sous le nom de KETTAMA une house rapide teintée de rave. Il perce en 2018 avec « B O D Y », extrait de l'EP Bucklyn Bridge, relayé par Mall Grab et Annie Mac. En 2019, il cofonde avec Shampain le label G-Town Records, nommé d'après leur ville commune, et joue en 2024 à Glastonbury, Coachella et Boomtown.", en: "Born in Galway, Ireland in 1997, Evan Campbell produces fast, rave-tinged house as KETTAMA. He broke through in 2018 with \"B O D Y\" from the Bucklyn Bridge EP, picked up by Mall Grab and Annie Mac. In 2019 he co-founded the label G-Town Records with Shampain, named after their shared hometown, and in 2024 played Glastonbury, Coachella and Boomtown." }, origin: "Galway, Irlande", since: 2018, labels: ["G-Town Records"], sources: ["https://en.wikipedia.org/wiki/Kettama"] }, // Kettama
  "kevin-arnold": { slug: "kevin-arnold", bio: { fr: "DJ et producteur techno et house installé à Cologne, Kevin Arnold est résident du Bootshaus. Ingénieur du son de formation, il dirige son propre studio, son label Kassiopeia et la série de soirées « Über den Dächern von Köln », organisée sur un toit-parking du centre de Cologne.", en: "A techno and house DJ and producer based in Cologne, Kevin Arnold is a Bootshaus resident. A mixing and mastering engineer by trade, he runs his own studio, his Kassiopeia label and the \"Über den Dächern von Köln\" event series, held on a rooftop car park in central Cologne." }, origin: "Cologne, Allemagne", labels: ["Kassiopeia"], sources: ["https://bootshaus.tv/artists/kevin-arnold/"] }, // Kevin Arnold
  "kevin-de-vries": { slug: "kevin-de-vries", bio: { fr: "Originaire d'une zone rurale près de Cologne, Kevin de Vries s'est installé à Berlin après des années d'allers-retours le week-end, et n'a quitté son emploi de responsable de supermarché qu'en novembre 2019. Il produit une techno mélodique traversée de trance, entièrement dans l'ordinateur, et a sorti sur Afterlife, Cocoon et Anjunadeep, notamment les titres « Arakat » et « Meraki » et un remix de « Saltwater » de Chicane. Il a longtemps tenu une résidence au club Tama, à Poznań.", en: "Raised in the countryside outside Cologne, Kevin de Vries moved to Berlin after years of weekend trips, and only left his supermarket management job in November 2019. He produces trance-inflected melodic techno entirely in the box, releasing on Afterlife, Cocoon and Anjunadeep, including the tracks \"Arakat\" and \"Meraki\" and a remix of Chicane's \"Saltwater\". He has held a long-running residency at the Tama club in Poznań." }, origin: "Région de Cologne, Allemagne", labels: ["Afterlife", "Cocoon", "Anjunadeep"], sources: ["https://www.beatportal.com/articles/324403-introducing-kevin-de-vries-afterlifes-unstoppable-new-talent"] }, // Kevin de Vries
  "kevin-lo": { slug: "kevin-lo", bio: { fr: "Kevin Lo est un DJ néerlandais qui ne joue que de la house : Chicago, Detroit ou deep house, qu'il enchaîne en sets longs, mêlant morceaux émotifs étirés, touches acides et outils percussifs. Il tient une résidence au Wibar, à Leiden, et a fait ses débuts au festival Lowlands en 2024. Il est représenté par l'agence Strength in Sound.", en: "Kevin Lo is a Dutch DJ devoted to house music: Chicago, Detroit or deep house, blended into long sets that mix emotive, stretched-out tracks with acid and percussive tools. He holds a residency at Wibar in Leiden and made his debut at Lowlands festival in 2024. He is booked by the Strength in Sound agency." }, origin: "Pays-Bas", since: 2024, sources: ["https://strengthinsound.nl/kevinlo/"] }, // Kevin Lo
  "kg": { slug: "kg", bio: { fr: "Karen Nyame, qui mixe et produit sous le nom KG, est une productrice et DJ britanno-ghanéenne de Londres. Elle s'est fait connaître à la fin des années 2000 sur la scène UK funky, en diffusant ses dubs sur Touch FM et Westside Radio, avant de revenir en 2018 avec un son croisant afrobeats, amapiano, gqom et 4x4 percussif. Elle a publié sept EP, dont « Sensei II » sur Black Acre, et dirige son label Rhythm In The City.", en: "Karen Nyame, who DJs and produces as KG, is a British-Ghanaian producer and DJ from London. She made her name on the UK funky scene in the late 2000s, airing dubs on Touch FM and Westside Radio, before returning in 2018 with a sound crossing afrobeats, amapiano, gqom and percussive 4x4. She has released seven EPs, including \"Sensei II\" on Black Acre, and runs her Rhythm In The City label." }, origin: "Londres, Royaume-Uni", labels: ["Rhythm In The City", "Black Acre"], sources: ["https://djmag.com/features/recognise-karen-nyame-kg-interview", "https://djmag.com/news/karen-nyame-kg-drops-new-ep-sensei-ii-black-acre", "https://www.karennyamekg.com/"] }, // KG
  "ki-ki": { slug: "ki-ki", bio: { fr: "KI/KI, de son vrai nom Kiki Wesselo, née le 30 août 1996 à Epe, est une DJ et productrice néerlandaise. Ses sets mêlent trance, acid techno et sonorités rave des années 1990 ; elle s'est fait connaître comme résidente de la soirée queer Spielraum à Amsterdam. Elle a fondé le label slash en 2022 et a remporté en 2025 la catégorie Dance des Edison Awards, première femme à y parvenir.", en: "KI/KI, real name Kiki Wesselo, born 30 August 1996 in Epe, is a Dutch DJ and producer. Her sets blend trance, acid techno and 1990s rave sounds; she first became known as a resident of the queer party Spielraum in Amsterdam. She founded the label slash in 2022 and in 2025 won the Dance category at the Edison Awards, the first woman to do so." }, origin: "Epe / Amsterdam, Pays-Bas", since: 2018, labels: ["slash"], sources: ["https://en.wikipedia.org/wiki/KI/KI"] }, // KI/KI
  "kimmic": { slug: "kimmic", bio: { fr: "Kimmic est un duo écossais originaire de Dundee, formé de Keiran McLean et Christopher McComiskie. Ils jouent une musique électronique hard dance à forte énergie et ont sorti leur premier single, « Never Miss A Beat », chez Polydor, relayé par Radio 1, Capital Dance et Kiss FM. Le duo remplit régulièrement le SWG3 de Glasgow.", en: "Kimmic is a Scottish duo from Dundee, made up of Keiran McLean and Christopher McComiskie. They play high-energy hard dance electronic music and released their debut single, \"Never Miss A Beat\", on Polydor, picked up by Radio 1, Capital Dance and Kiss FM. The duo regularly sell out Glasgow's SWG3." }, origin: "Dundee, Écosse", labels: ["Polydor"], sources: ["https://swg3.tv/events/2026/march/kimmic/", "https://www.whatsonglasgow.co.uk/event/134701-kimmic/"] }, // Kimmic
  "kink": { slug: "kink", bio: { fr: "KiNK est le nom de scène de Strahil Velchev, producteur et DJ bulgare originaire de Sofia. Actif depuis 2005, il publie sur Ovum Recordings, Rush Hour, Macro et Running Back, et lance en 2018 son propre label, Sofia. Ses albums Under Destruction (2014) et Playground (2017) prolongent une pratique du live entièrement jouée sur machines, pour laquelle les lecteurs de Resident Advisor l'ont élu meilleur live électronique en 2015 et 2016.", en: "KiNK is the stage name of Strahil Velchev, a Bulgarian producer and DJ from Sofia. Active since 2005, he has released on Ovum Recordings, Rush Hour, Macro and Running Back, and launched his own label, Sofia, in 2018. His albums Under Destruction (2014) and Playground (2017) extend a hardware-driven live practice for which Resident Advisor readers voted him best live electronic act in 2015 and 2016." }, origin: "Sofia, Bulgarie", since: 2005, labels: ["Sofia", "Rush Hour", "Running Back", "Ovum Recordings"], sources: ["https://en.wikipedia.org/wiki/KiNK"] }, // KiNK
  "klangkuenstler": { slug: "klangkuenstler", bio: { fr: "Michael Korb, né en 1990 à Füssen en Bavière, s'installe à Berlin à l'été 2012 après un premier set au Ritter Butzke. Il fonde le label Zuckerton Records en 2011 puis Outworld en 2019, joue d'abord de la deep et de la tech house avant de basculer vers la techno à partir de 2018. En octobre 2023, il cofonde avec le DJ Kobosil la structure Tote Sonne, à la fois label et agence d'artistes.", en: "Born in Füssen, Bavaria in 1990, Michael Korb moved to Berlin in the summer of 2012 after an early set at the club Ritter Butzke. He founded the label Zuckerton Records in 2011 and Outworld in 2019, playing deep and tech house before shifting towards techno from 2018 onwards. In October 2023 he co-founded Tote Sonne, a label and artist agency, with fellow DJ Kobosil." }, origin: "Füssen, Bavière, Allemagne", since: 2011, labels: ["Zuckerton Records", "Outworld", "Tote Sonne"], sources: ["https://en.wikipedia.org/wiki/Klangkuenstler", "https://de.wikipedia.org/wiki/Klangkuenstler"] }, // Klangkuenstler
  "klofama": { slug: "klofama", bio: { fr: "KLOFAMA est le nom de scène de Mats van Biljouw, DJ et producteur néerlandais de hard techno. Son style repose sur des kicks lourds, des charleys très rapides et des mélodies courtes. Il a publié sur Innergate Records, Falsive Records et Altruism Records.", en: "KLOFAMA is the stage name of Mats van Biljouw, a Dutch hard techno DJ and producer. His style rests on heavy kicks, very fast hats and short melodies. He has released on Innergate Records, Falsive Records and Altruism Records." }, origin: "Pays-Bas", labels: ["Innergate Records", "Falsive Records", "Altruism Records"], sources: ["https://www.djguide.nl/djinfo.p?djid=9980&language=en"] }, // KLOFAMA
  "kloud": { slug: "kloud", bio: { fr: "KLOUD est un producteur et artiste électronique installé à Los Angeles. Il décrit sa musique comme un croisement entre sonorités électroniques classiques et production contemporaine, inspiré par la techno et la house sombres, l'electro et les synthétiseurs analogiques.", en: "KLOUD is an electronic producer and artist based in Los Angeles. He describes his music as merging timeless electronic sounds with modern production, drawing on darker techno and house, electro and analogue synthesizers." }, origin: "Los Angeles, États-Unis", sources: ["https://wearekloud.bandcamp.com/"] }, // Kloud
  "kmru": { slug: "kmru", bio: { fr: "KMRU est le nom de scène de Joseph Kamaru, musicien ambient né à Nairobi, au Kenya, et installé à Berlin. Enfant, il joue de la guitare et chante dans une chorale, puis découvre la musique électronique au lycée en trouvant une copie de FL Studio sur les ordinateurs de l'établissement. Il travaille à partir d'enregistrements de terrain, de piano et de synthétiseurs, et a publié près de vingt disques sur Bandcamp entre 2017 et 2021.", en: "KMRU is the stage name of Joseph Kamaru, an ambient musician born in Nairobi, Kenya, and now based in Berlin. As a child he played guitar and sang in a choir, then discovered electronic music in high school after finding a copy of FL Studio on the school computers. He works from field recordings, piano and synthesizers, and released almost twenty records on Bandcamp between 2017 and 2021." }, origin: "Nairobi, Kenya", since: 2017, sources: ["https://en.wikipedia.org/wiki/KMRU"] }, // KMRU
  "kneecap": { slug: "kneecap", bio: { fr: "Kneecap est un trio de hip-hop irlandais de Belfast, formé de Mo Chara, Móglaí Bap et DJ Próvaí. Ils rappent en anglais et en irlandais depuis leur premier single « C.E.A.R.T.A. » en 2017. Leur premier album, Fine Art, paraît en 2024 chez Heavenly Recordings, la même année qu'un film biographique.", en: "Kneecap are an Irish hip-hop trio from Belfast, made up of Mo Chara, Móglaí Bap and DJ Próvaí. They have rapped in English and Irish since their first single \"C.E.A.R.T.A.\" in 2017. Their debut album, Fine Art, came out in 2024 on Heavenly Recordings, the same year as a biographical film." }, origin: "Belfast, Irlande du Nord", since: 2017, labels: ["Heavenly Recordings"], sources: ["https://en.wikipedia.org/wiki/Kneecap_(band)"] }, // Kneecap
  "kobosil": { slug: "kobosil", bio: { fr: "Max Kobosil, né en 1991 à Berlin-Neukölln, produit une techno rapide et abrasive nourrie d'EBM, de noise et d'industriel. Résident du Berghain de décembre 2014 à 2019, il fonde en 2013 son label RK, devenu R Label Group, et sort l'album « We Grow, You Decline » en 2016. En octobre 2023, il cofonde avec le DJ Klangkuenstler la structure Tote Sonne, à la fois label et agence d'artistes.", en: "Born in 1991 in Berlin's Neukölln district, Max Kobosil makes fast, abrasive techno drawing on EBM, noise and industrial. A resident at Berghain from December 2014 through 2019, he founded his RK label in 2013 — later R Label Group — and released the album \"We Grow, You Decline\" in 2016. In October 2023 he co-founded Tote Sonne, a label and artist agency, with fellow DJ Klangkuenstler." }, origin: "Berlin, Allemagne", since: 2013, labels: ["R Label Group", "Tote Sonne"], sources: ["https://en.wikipedia.org/wiki/Kobosil"] }, // Kobosil
  "kode9": { slug: "kode9", bio: { fr: "Kode9 est le nom de scène de Steve Goodman, artiste électronique, DJ et fondateur du label Hyperdub, né en 1973 à Glasgow. Il fait partie des membres fondateurs de la première scène dubstep, aux côtés de son collaborateur The Spaceape, avec qui il signe les albums « Memories of the Future » (2006) et « Black Sun » (2011). Hyperdub a publié Burial, DJ Rashad, Zomby et Fatima Al Qadiri. Docteur en philosophie, il a écrit « Sonic Warfare » en 2009.", en: "Kode9 is the stage name of Steve Goodman, an electronic artist, DJ and founder of the Hyperdub label, born in 1973 in Glasgow. He was one of the founding members of the early dubstep scene alongside his collaborator The Spaceape, with whom he made the albums \"Memories of the Future\" (2006) and \"Black Sun\" (2011). Hyperdub has released Burial, DJ Rashad, Zomby and Fatima Al Qadiri. He holds a PhD in philosophy and published \"Sonic Warfare\" in 2009." }, origin: "Glasgow, Écosse", since: 1991, labels: ["Hyperdub"], sources: ["https://en.wikipedia.org/wiki/Kode9"] }, // Kode9
  "kofu": { slug: "kofu", bio: { fr: "KOFU est une artiste, DJ et productrice nigériane-finlandaise installée à Helsinki, dont la carrière de DJ démarre en 2020. Elle mêle rythmes basses lourdes, hard house euphorique et sons de club de la diaspora, de l'Amérique latine au gqom. Elle joue régulièrement au Kaiku, à l'Ääniwalli et au Post Bar.", en: "KOFU is a Nigerian-Finnish artist, DJ and producer based in Helsinki, who started DJing professionally in 2020. She combines bass-heavy beats, euphoric hard house and diasporic club sounds, from Latin America to gqom. She plays regularly at Kaiku, Ääniwalli and Post Bar." }, origin: "Helsinki, Finlande", since: 2020, sources: ["https://ra.co/dj/kofu/biography", "https://clubkaiku.fi/"] }, // Kofu
  "kokoprisci": { slug: "kokoprisci", bio: { fr: "DJ française d'origine togolaise, originaire du sud de la France et installée à Paris, Kokoprisci navigue entre house, breakbeat et bass music, avec des incursions garage, techno, ballroom et jungle. Elle anime « The Koko Show » sur Rinse France.", en: "A French DJ of Togolese descent, from the south of France and based in Paris, Kokoprisci moves between house, breakbeat and bass music, with detours through garage, techno, ballroom and jungle. She hosts \"The Koko Show\" on Rinse France." }, origin: "France", sources: ["https://www.rinse.fm/shows/kokoprisci", "https://talentboutique.fr/roster/kokoprisci/"] }, // Kokoprisci
  "kolsch": { slug: "kolsch", bio: { fr: "Rune Reilly Kölsch, né en 1977 dans le quartier libre de Christiania à Copenhague, est un producteur et DJ danois. Sa house mélodique et sa techno paraissent principalement chez Kompakt, le label de Cologne, depuis son premier album en 2013. Avant d'adopter ce nom, il avait signé « Calabria » (2003) sous l'alias Rune, un morceau au riff de saxophone synthétique devenu un standard des clubs.", en: "Rune Reilly Kölsch, born in 1977 in Copenhagen's free town of Christiania, is a Danish producer and DJ. His melodic house and techno appear mainly on the Cologne label Kompakt, where he has released albums since 2013. Before adopting that name he cut \"Calabria\" (2003) as Rune, a track built on a synthetic saxophone riff that became a club standard." }, origin: "Copenhague, Danemark", since: 1995, labels: ["Kompakt"], sources: ["https://en.wikipedia.org/wiki/K%C3%B6lsch_(musician)", "https://en.wikipedia.org/wiki/Calabria_(song)"] }, // Kölsch
  "kolter": { slug: "kolter", bio: { fr: "Kolter est un DJ et producteur allemand établi à Cologne, qui a longtemps sorti ses disques sous le nom DJOKO avant d'adopter ce pseudonyme. Sa musique, qu'il présente lui-même comme de la « house from Cologne », mêle house, techno et funk, avec des percussions travaillées et des grooves très marqués. On lui doit notamment les titres « Organize », « Mind Blower » et « Set It Off ».", en: "Kolter is a German DJ and producer based in Cologne who released for years as DJOKO before adopting this alias. His music, which he bills himself as \"house from Cologne\", blends house, techno and funk, with detailed percussion and heavily marked grooves. Among his tracks are \"Organize\", \"Mind Blower\" and \"Set It Off\"." }, origin: "Cologne, Allemagne", sources: ["https://kolter.bandcamp.com/", "https://www.blurreyewear.co.uk/blogs/articles/kolter-the-creative-dj-and-producer", "https://musicbrainz.org/artist/c2b3c551-e673-46fe-bbee-5fd94d00d903"] }, // Kolter
  "konstantin-sibold": { slug: "konstantin-sibold", bio: { fr: "DJ et producteur allemand établi à Stuttgart, Konstantin Sibold s'est fait connaître en 2013 avec « Madeleine », paru sur le label Innervisions. Il a ensuite sorti « Mutter » sur Running Back et « Shake This World » sur Afterlife, et publié également chez Drumcode et Anjunadeep. Ses sets mélangent house, techno, acid et EBM, entre le Berghain, le Fabric de Londres et le Pacha d'Ibiza.", en: "A German DJ and producer based in Stuttgart, Konstantin Sibold made his name in 2013 with \"Madeleine\", released on the Innervisions label. He went on to put out \"Mutter\" on Running Back and \"Shake This World\" on Afterlife, and has also released through Drumcode and Anjunadeep. His sets move between house, techno, acid and EBM, from Berghain to Fabric in London and Pacha in Ibiza." }, origin: "Stuttgart, Allemagne", since: 2013, labels: ["Innervisions", "Running Back", "Afterlife"], sources: ["https://www.auroratalent.agency/konstantinsibold.html"] }, // Konstantin Sibold
  "korolova": { slug: "korolova", bio: { fr: "Korolova est le nom de scène d'Olga Korolova, DJ et productrice ukrainienne née en 1988. Elle joue une techno mélodique et de la progressive house, et publie sur Tomorrowland Music et Armada Electronic Elements.", en: "Korolova is the stage name of Olga Korolova, a Ukrainian DJ and record producer born in 1988. She plays melodic techno and progressive house, releasing on Tomorrowland Music and Armada Electronic Elements." }, origin: "Ukraine", since: 2021, labels: ["Tomorrowland Music", "Armada Electronic Elements"], sources: ["https://en.wikipedia.org/wiki/Korolov", "https://api.discogs.com/database/search?artist=Korolova&type=release"] }, // Korolova
  "koven": { slug: "koven", bio: { fr: "Koven est un duo britannique formé fin 2011 à Londres, réunissant la chanteuse Katie Boyle et le producteur Max Rowat. Le projet mêle drum & bass et dubstep autour de voix chantées et sort principalement sur le label canadien Monstercat, où paraît notamment l'album « Butterfly Effect » en 2020.", en: "Koven is a British duo formed in late 2011 in London, pairing singer Katie Boyle with producer Max Rowat. The project blends drum & bass and dubstep around sung vocals and releases mainly on the Canadian label Monstercat, home to its 2020 album \"Butterfly Effect\"." }, origin: "Londres, Royaume-Uni", since: 2011, labels: ["Monstercat"], sources: ["https://musicbrainz.org/ws/2/artist/ad110705-cbe6-4c47-9b99-8526e6db0f41", "https://api.discogs.com/database/search?artist=Koven&type=release"] }, // Koven
  "kozlov": { slug: "kozlov", bio: { fr: "Kozlov, de son vrai nom Florian Kozlowski, est un DJ et producteur français né en 1995 près de Paris, d'origine polonaise. Il lance le projet KØZLØV à 22 ans et se fait connaître avec les titres « Tchernobyl », « She Wants You to Go Harder » et « Never Come Back ». Sa hard techno emprunte à l'industriel, au schranz et au hardcore, et il a publié sur ARTS, NineTimesNine, Green Fetish Records et OMEN Recordings.", en: "Kozlov, real name Florian Kozlowski, is a French DJ and producer born in 1995 near Paris, of Polish descent. He launched the KØZLØV project at 22 and became known for the tracks \"Tchernobyl\", \"She Wants You to Go Harder\" and \"Never Come Back\". His hard techno borrows from industrial, schranz and hardcore, and he has released on ARTS, NineTimesNine, Green Fetish Records and OMEN Recordings." }, origin: "Paris, France", labels: ["ARTS", "NineTimesNine", "Green Fetish Records", "OMEN Recordings"], sources: ["https://6amgroup.com/articles/all/kozlov-reflecting-on-2023-and-the-future-of-hard-techno"] }, // Kozlov
  "kream": { slug: "kream", bio: { fr: "KREAM est un duo norvégien formé à Bergen par les frères Daniel et Markus Slettebakken. Remarqués en 2015 avec un remix de « Talking Body » de Tove Lo, ils signent en 2017 chez Big Beat / Atlantic Records et sortent « Taped Up Heart » avec Clara Mae, entré au classement Hot Dance/Electronic Songs de Billboard. Leur son est décrit comme de la tech house mélodique.", en: "KREAM is a Norwegian duo formed in Bergen by brothers Daniel and Markus Slettebakken. They drew attention in 2015 with a remix of Tove Lo's \"Talking Body\", signed to Big Beat / Atlantic Records in 2017 and released \"Taped Up Heart\" with Clara Mae, which charted on Billboard's Hot Dance/Electronic Songs. Their sound is described as melodic tech house." }, origin: "Bergen, Norvège", since: 2015, labels: ["Big Beat Records"], sources: ["https://en.wikipedia.org/wiki/Kream", "https://www.insomniac.com/music/artists/kream/"] }, // KREAM
  "krimska": { slug: "krimska", bio: { fr: "Krimska est une DJ et productrice active depuis 2023, dont le parcours est marqué par la scène tchèque. Rentrée en France en 2023, elle débute dans les bars de sa ville d'origine, Limoges, avant de s'installer à Lyon. Ses sets refusent les cases : UK bass et break, techno percutante, sonorités ghetto et ambiances plus hypnotiques s'y succèdent. Elle a joué au Sucre et au Transbordeur, à Lyon.", en: "Krimska is a DJ and producer active since 2023, whose path was shaped by the Czech scene. Back in France in 2023, she started out in the bars of her home town of Limoges before settling in Lyon. Her sets refuse categories, moving between UK bass and breaks, harder techno, ghetto sounds and more hypnotic moods. She has played Le Sucre and Le Transbordeur in Lyon." }, origin: "Lyon, France", since: 2023, sources: ["https://www.transbordeur.fr/artiste/krimska/", "https://le-sucre.eu/artists/krimska/"] }, // Krimska
  "krowdexx": { slug: "krowdexx", bio: { fr: "Krowdexx est un duo italien de hardstyle formé par Giulio Destefanis et Simone Calvino, originaires d'Alba, dans le Piémont. Leur premier titre, « Y.A.T. », paraît fin 2015 sur le label néerlandais X-RAW Records ; ils publient ensuite chez Gearbox Digital et Scantraxx.", en: "Krowdexx are an Italian hardstyle duo formed by Giulio Destefanis and Simone Calvino, from Alba in Piedmont. Their first track, \"Y.A.T.\", came out in late 2015 on the Dutch label X-RAW Records; they went on to release on Gearbox Digital and Scantraxx." }, origin: "Alba, Italie", since: 2015, labels: ["Gearbox Digital", "Scantraxx"], sources: ["https://www.discogs.com/artist/4248911-Krowdexx", "https://www.last.fm/music/Krowdexx/+wiki"] }, // Krowdexx
  "kruelty": { slug: "kruelty", bio: { fr: "KRUELTY est un producteur et DJ au visage masqué qui mêle hardstyle, hard techno et hardcore industriel. Après deux ans de sorties sur les sous-labels TC Labs et Spoontech, il a rejoint le label principal Theracords, où est paru son album BLOODBATH MACHINERY. Il a joué au Defqon.1, au Decibel Outdoor, à l'Intents Festival et à plusieurs éditions de Verknipt.", en: "KRUELTY is a masked producer and DJ blending hardstyle, hard techno and industrial hardcore. After two years of releases on the TC Labs and Spoontech sublabels he joined the main Theracords imprint, home to his album BLOODBATH MACHINERY. He has played Defqon.1, Decibel Outdoor, Intents Festival and several Verknipt events." }, labels: ["Theracords"], sources: ["https://hardnews.nl/en/kruelty-becomes-part-of-theracords-mainlabel-extremely-dark-lugubrious/", "https://limitless-agency.com/kruelty/"] }, // KRUELTY
  "kuko": { slug: "kuko", bio: { fr: "Kuko est un DJ et producteur de techno allemand basé à Cologne. Il s'est fait remarquer par un EP vinyle paru sur le 44 Label Group, dans un registre de hard techno et de techno industrielle mêlée de mélodies de synthétiseur.", en: "Kuko is a German techno DJ and producer based in Cologne. He drew attention with a vinyl EP on 44 Label Group, in a hard and industrial techno vein laced with synth melodies." }, origin: "Cologne, Allemagne", labels: ["44 Label Group"], sources: ["https://technomusicworld.com/artist/kukocologne/about", "https://44labelgroup.bandcamp.com/album/44004"] }, // Kuko
  "kuss": { slug: "kuss", bio: { fr: "Artiste techno français basé à Paris, KUSS publie sur Skryptöm Records, Drawer Records et Agora Records. Sa techno est décrite comme groovy, teintée d'éléments mentaux et hypnotiques. Il explore par ailleurs l'ambient, le downtempo et le rock progressif dans son projet Derivative of the Unconscious.", en: "A French techno artist based in Paris, KUSS releases on Skryptöm Records, Drawer Records and Agora Records. His techno is described as groovy, shaded with mental and hypnotic elements. He also explores ambient, downtempo and progressive rock in his Derivative of the Unconscious project." }, origin: "Paris, France", labels: ["Skryptöm Records", "Drawer Records", "Agora Records"], sources: ["https://hoer.live/artist/kuss/"] }, // KUSS
  "la-bringue": { slug: "la-bringue", bio: { fr: "La Bringue est un collectif pluridisciplinaire fondé en 2020 dans l'Ouest de la France et construit autour de la musique techno. Il organise des raves, des festivals, des podcasts et des parades, avec une attention affichée à l'accueil et à la diversité du public. Le collectif est associé au Warehouse de Nantes, où il tient sa série Shifter, et a monté au Zénith de Saint-Herblain la soirée « Zénith Calling For Rave ».", en: "La Bringue is a multidisciplinary collective founded in 2020 in western France and built around techno music. It puts on raves, festivals, podcasts and parades, with a stated focus on a welcoming, diverse crowd. The collective is tied to Nantes's Warehouse, where it runs its Shifter series, and staged the \"Zénith Calling For Rave\" night at the Zénith in Saint-Herblain." }, origin: "Nantes, France", since: 2020, sources: ["https://www.collectif-la-bringue.fr/", "https://www.warehouse-nantes.fr/event/la-bringue-shifter-2"] }, // La Bringue
  "la-fuente": { slug: "la-fuente", bio: { fr: "La Fuente est le nom de scène de Job Smeltzer, DJ et producteur néerlandais originaire d'Eindhoven. Il devient résident des soirées « Super You & Me » de Laidback Luke après un set au Mixmash Pool Party de la Winter Music Conference à Miami. Son titre « Bang Bang » sort sur le label Mixmash et « Dounia » sur Spinnin' Records, avec lequel il signe un contrat de management en 2011.", en: "La Fuente is the stage name of Job Smeltzer, a Dutch DJ and producer from Eindhoven. He became a resident at Laidback Luke's \"Super You & Me\" parties after playing the Mixmash Pool Party at Miami's Winter Music Conference. His track \"Bang Bang\" came out on the Mixmash label and \"Dounia\" on Spinnin' Records, with whom he signed a management deal in 2011." }, origin: "Eindhoven, Pays-Bas", labels: ["Mixmash Records", "Spinnin' Records"], sources: ["https://www.djguide.nl/djinfo.p?djid=4850&language=en", "https://www.djguide.nl/nieuws.p?id=13748"] }, // La Fuente
  "la-p-tite-fumee": { slug: "la-p-tite-fumee", bio: { fr: "La P'tite Fumée est un groupe français formé en 2013 en Ariège, dont le projet mêle psytrance et instruments acoustiques joués en direct : didgeridoo, flûte traversière, guitare, basse, batterie et percussions. Le collectif est basé dans la région toulousaine et tourne principalement en France, en salle comme en festival.", en: "La P'tite Fumée is a French band formed in 2013 in Ariège, blending psytrance with acoustic instruments played live: didgeridoo, transverse flute, guitar, bass, drums and percussion. Based in the Toulouse area, the collective tours mainly in France, in venues and at festivals." }, origin: "Ariège / Toulouse, France", since: 2013, sources: ["https://www.discogs.com/artist/5444465-La-Ptite-Fumée", "https://www.durevie.paris/article/le-groupe-phare-de-live-psytrance-la-ptite-fumee-annonce-une-nouvelle-tournee-partout-en-france"] }, // La P'tite Fumée
  "lakuti": { slug: "lakuti", bio: { fr: "Lerato Khathi, née et élevée à Soweto, s'installe à Londres en 1997 et y fonde en 2002 le label et la série de soirées Süd Electronic avec Alan « Portable » Abrahams. Après son déménagement à Berlin, elle lance le label Uzuri Recordings et l'agence de booking du même nom. Elle est résidente du Panorama Bar au Berghain.", en: "Lerato Khathi, born and raised in Soweto, moved to London in 1997 and founded the Süd Electronic label and party series there in 2002 with Alan \"Portable\" Abrahams. After relocating to Berlin she launched the Uzuri Recordings imprint and the booking agency of the same name. She is a Panorama Bar resident at Berghain." }, origin: "Soweto, Afrique du Sud", since: 2002, labels: ["Uzuri Recordings", "Süd Electronic"], sources: ["https://archive.bubblegumclub.co.za/music/lakuti-the-south-african-dance-music-legend-you-should-know/", "https://chicagoreader.com/music/international-dance-veterans-tama-sumo-and-lakuti-know-the-best-routes-through-musics-past-and-present/"] }, // Lakuti
  "lane-8": { slug: "lane-8", bio: { fr: "Lane 8 est le nom de scène de Daniel Goldstein, DJ et producteur américain installé à Denver. Il publie ses premiers titres et remixes en 2012 et signe chez Anjunadeep en 2013, avant de lancer son propre label et sa série d'événements This Never Happened, dont le principe est d'interdire téléphones et appareils photo en soirée. Son premier album, Rise, paraît en 2015.", en: "Lane 8 is the stage name of Daniel Goldstein, an American DJ and producer based in Denver. He released his first tracks and remixes in 2012 and signed to Anjunadeep in 2013, before launching his own label and event series This Never Happened, whose rule is that phones and cameras stay away from the dancefloor. His debut album, Rise, came out in 2015." }, origin: "Denver, Colorado, États-Unis", since: 2012, labels: ["This Never Happened", "Anjunadeep"], sources: ["https://anjunadeep.com/artists/57317-lane-8"] }, // Lane 8
  "laura-meester": { slug: "laura-meester", bio: { fr: "Laura Meester est une DJ néerlandaise basée à Amsterdam. Elle puise dans les sons des années 1970 à 1990 et enchaîne disco, house old-school et disco africaine, avec une place particulière pour les breaks de percussions et les samples vocaux.", en: "Laura Meester is a Dutch DJ based in Amsterdam. She draws on sounds from the 1970s to the 1990s, moving between disco, old-school house and African disco, with a particular taste for percussion breaks and vocal samples." }, origin: "Amsterdam, Pays-Bas", sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/laura-meester/2165171/"] }, // Laura Meester
  "laure-croft": { slug: "laure-croft", bio: { fr: "Laure Croft, de son vrai nom Laure Dirven, est une DJ néerlandaise qui joue exclusivement en vinyle. Passée par la house et la hardcore, elle s'est tournée vers une techno underground et queer, rapide et tendue, puisant dans des disques du milieu des années 1990 au milieu des années 2000. Elle partage sa vie entre les Pays-Bas et Berlin.", en: "Laure Croft, real name Laure Dirven, is a Dutch DJ who plays vinyl only. After early success with house and hardcore, she turned to underground queer techno — fast and tense, drawn from records spanning the mid-90s to the mid-2000s. She divides her time between the Netherlands and Berlin." }, origin: "Pays-Bas", sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/laure-croft/2050849/", "https://mixmagnl.com/read/laure-croft-artists"] }, // Laure Croft
  "laurent-garnier": { slug: "laurent-garnier", bio: { fr: "Laurent Garnier, également connu sous le pseudonyme Choice, est un producteur et DJ français né le 1er février 1966. Il commence à mixer à Manchester à la fin des années 1980, devient producteur au début des années 1990 et publie ensuite plusieurs albums.", en: "Laurent Garnier, also known under the alias Choice, is a French producer and DJ born on 1 February 1966. He began DJing in Manchester in the late 1980s, turned producer in the early 1990s and went on to release several albums." }, origin: "Boulogne-Billancourt, France", since: 1987, sources: ["https://en.wikipedia.org/wiki/Laurent_Garnier"] }, // Laurent Garnier
  "law-haktion": { slug: "law-haktion", bio: { fr: "Law & Haktion est un duo de DJ parisien formé en 2016 dans le sous-sol du club U.F.O., autour d'un goût commun pour les musiques électroniques sombres des années 1980. Il rejoint la Tech Noire en 2017, la soirée queer du collectif Forensics, dont il est depuis résident : wave, synth, post-punk, EBM et techno.", en: "Law & Haktion are a Paris DJ duo formed in 2016 in the basement of the club U.F.O., around a shared taste for dark 1980s electronic music. They joined Tech Noire in 2017 — the queer party run by the Forensics collective — and have been residents since: wave, synth, post-punk, EBM and techno." }, origin: "Paris, France", since: 2016, sources: ["https://www.frnscs.com/technoire/", "https://lastation.paris/stationgdm/rendez-vous/tech-noire"] }, // Law & Haktion
  "lee-parkinson": { slug: "lee-parkinson", bio: { fr: "Lee Parkinson est un DJ britannique originaire de Rotherham, dont la carrière commence en 1988 avec l'essor de la culture rave. Après des débuts en vinyle dans les clubs du Yorkshire, il a construit des sets qui font se croiser house, techno, trance et sonorités underground.", en: "Lee Parkinson is a British DJ from Rotherham whose career began in 1988, as rave culture was taking hold. After early vinyl sets in Yorkshire clubs, he has built a style that moves between house, techno, trance and underground sounds." }, origin: "Rotherham, Royaume-Uni", since: 1988, sources: ["https://www.warehouse-nantes.fr/artist/lee-parkinson/"] }, // Lee Parkinson
  "lekkerfaces": { slug: "lekkerfaces", bio: { fr: "Lekkerfaces est un DJ et producteur d'uptempo hardcore installé aux Pays-Bas. Il publie ses premiers morceaux en 2022 et se fait remarquer par son album et show live « Steam Power », construit sur l'alternance de kicks lents et très rapides. Il joue au Masters of Hardcore, à l'Intents Festival, au Dominator et au Harmony of Hardcore.", en: "Lekkerfaces is an uptempo hardcore DJ and producer based in the Netherlands. He released his first tracks in 2022 and made his name with his album and live show \"Steam Power\", built on the alternation of slow and very fast kicks. He plays Masters of Hardcore, Intents Festival, Dominator and Harmony of Hardcore." }, origin: "Pays-Bas", since: 2022, sources: ["https://www.bkjnbookings.com/lekkerfaces", "https://www.discogs.com/artist/11154053-Lekkerfaces"] }, // Lekkerfaces
  "len-faki": { slug: "len-faki", bio: { fr: "Levent Faki, connu sous le nom de Len Faki, est un DJ et producteur allemand de musique électronique, d'origine turque. Il produit aussi sous le pseudonyme La Monde. Son répertoire tourne autour de la techno, du minimal et de la tech house.", en: "Levent Faki, known as Len Faki, is a German DJ and electronic music producer of Turkish descent. He also records under the alias La Monde. His output centres on techno, minimal and tech house." }, origin: "Berlin, Allemagne", sources: ["https://en.wikipedia.org/wiki/Len_Faki", "https://www.last.fm/music/Len+Faki/+tags"] }, // Len Faki
  "levenkhan": { slug: "levenkhan", bio: { fr: "Levenkhan est un DJ et producteur frenchcore américain, présenté comme le premier artiste des États-Unis à avoir signé sur Aggressive Records et Peacock Records. Venu du hip-hop et nourri de musique classique et de punk, il publie aussi sur RSLVD Records et Hardcore France. Ses morceaux « Lesgoo » avec Sickmode et Rooler et « Mind is Everything » avec Mr. Ivex ont tourné sur les scènes de Dominator et du Masters of Hardcore.", en: "Levenkhan is an American frenchcore DJ and producer, described as the first US artist to release on Aggressive Records and Peacock Records. Coming from hip-hop production and drawing on classical music and punk, he also releases on RSLVD Records and Hardcore France. Tracks such as \"Lesgoo\" with Sickmode and Rooler and \"Mind is Everything\" with Mr. Ivex have been played at Dominator and Masters of Hardcore." }, origin: "États-Unis", since: 2019, labels: ["Aggressive Records", "Peacock Records"], sources: ["https://www.insomniac.com/music/artists/levenkhan/", "https://hardstyle.com/en/artists/levenkhan"] }, // Levenkhan
  "lewis-ofman": { slug: "lewis-ofman", bio: { fr: "Lewis Delhomme, né à Paris en 1997, joue de la batterie, de la guitare et des claviers avant de se tourner vers la production. Sa musique prolonge la filiation de la house française — Cerrone, Daft Punk, Cassius — en y mêlant disco et pop ; il la décrit lui-même comme un « melodic groove ». Il a publié les albums Sonic Poems (2022) et Cristal Medium Blue (2024), et signé « Move Me » avec Carly Rae Jepsen en 2022.", en: "Lewis Delhomme, born in Paris in 1997, played drums, guitar and keys before turning to production. His music extends the French house lineage — Cerrone, Daft Punk, Cassius — with disco and pop threaded through it; he calls it \"melodic groove\". He released the albums Sonic Poems (2022) and Cristal Medium Blue (2024), and made \"Move Me\" with Carly Rae Jepsen in 2022." }, origin: "Paris, France", since: 2014, labels: ["Profil de Face"], sources: ["https://en.wikipedia.org/wiki/Lewis_OfMan", "https://www.apartamentomagazine.com/stories/lewis-ofman/"] }, // Lewis OfMan
  "lieks": { slug: "lieks", bio: { fr: "LIEKS est une DJ et productrice néerlandaise, dont les sets sont marqués par la hard techno et la techno industrielle. Repérée d'abord pour ses vidéos sur les réseaux sociaux, elle joue au Now&Wow, au Nachtwacht et au HomeTown Festival, et publie en 2025 son premier titre, GO INSANE.", en: "LIEKS is a Dutch DJ and producer whose sets are built on hard and industrial techno. First noticed for her social-media videos, she has played Now&Wow, Nachtwacht and HomeTown Festival, and released her first track, GO INSANE, in 2025." }, origin: "Pays-Bas", since: 2025, sources: ["https://mach9agency.com/artists/lieks/"] }, // LIEKS
  "lil-texas": { slug: "lil-texas", bio: { fr: "Lil Texas est un producteur et DJ américain né à Dallas et installé à Los Angeles, formé au Berklee College of Music. Il pousse le hardcore au-delà de 200 BPM et a baptisé son style « texcore » : influence gabber old school, mélodies et breakdowns hérités du hardcore des débuts, stabs de synthé et samples d'horreur. Son esthétique de cow-boy à strass va de pair avec ses EP Texcore.", en: "Lil Texas is an American producer and DJ, born in Dallas and based in Los Angeles, who trained at Berklee College of Music. He pushes hardcore past 200 BPM and coined the name \"texcore\" for his style: old-school gabber influence, melodies and breakdowns inherited from early hardcore, synth stabs and horror samples. The rhinestone-cowboy look is part of the package, as are his Texcore EPs." }, origin: "Dallas, États-Unis", sources: ["https://www.thefader.com/2019/11/26/lil-texas-interview"] }, // Lil Texas
  "lilly-palmer": { slug: "lilly-palmer", bio: { fr: "Sonja Rauschenbach, connue sous le nom de Lilly Palmer, née le 5 avril 1999, est une DJ et productrice de techno allemande, formée dans la scène underground zurichoise et installée à Amsterdam. Elle a commencé par la tech house et la deep house au milieu des années 2010 avant d'aller vers des tempos plus rapides. Son EP We Control est sorti sur Drumcode en 2022 ; elle dirige son propre label Spannung Records et est signée chez Armada Music.", en: "Sonja Rauschenbach, known as Lilly Palmer, born 5 April 1999, is a German techno DJ and producer who came up in Zurich's underground scene and is based in Amsterdam. She started out in tech house and deep house in the mid-2010s before moving to faster tempos. Her EP We Control came out on Drumcode in 2022; she runs her own label Spannung Records and is signed to Armada Music." }, origin: "Amsterdam, Pays-Bas", labels: ["Spannung Records", "Armada Music", "Drumcode"], sources: ["https://en.wikipedia.org/wiki/Lilly_Palmer", "https://djmag.com/cover-features/lilly-palmer-strength-through-techno"] }, // Lilly Palmer
  "liquidfive": { slug: "liquidfive", bio: { fr: "liquidfive est le nom de scène de Martin Maximilian Kotzur, DJ, producteur et auteur-compositeur allemand installé à Mülheim. Batteur d'un groupe formé en 2011 puis dissous en 2015, il poursuit seul depuis 2017 une musique qu'il décrit comme un mélange de house, d'electro et de pop.", en: "liquidfive is the stage name of Martin Maximilian Kotzur, a German DJ, producer and songwriter based in Mülheim. Drummer in a band formed in 2011 and disbanded in 2015, he has worked solo since 2017 on what he describes as a mix of house, electro and pop." }, origin: "Mülheim, Allemagne", since: 2017, sources: ["https://rickyleepotts.com/2024/05/liquidfive-interview.html"] }, // Liquidfive
  "lisa-korver": { slug: "lisa-korver", bio: { fr: "Lisa Korver est une DJ et productrice néerlandaise basée à Amsterdam. Ses sets circulent entre trance, techno, hard groove et latincore, et l'ont menée sur les affiches d'Awakenings et de l'UNVRS. Elle est représentée par l'agence amstellodamoise Phase.", en: "Lisa Korver is a Dutch DJ and producer based in Amsterdam. Her sets move between trance, techno, hard groove and latincore, and have taken her to Awakenings and UNVRS line-ups. She is represented by the Amsterdam agency Phase." }, origin: "Amsterdam, Pays-Bas", sources: ["https://www.phase.amsterdam/artists/lisa-korver", "https://www.unvrs.com/artists/lisa-korver", "https://www.awakenings.com/en/artists/lisa-korver/386618/"] }, // Lisa Korver
  "lobster": { slug: "lobster", bio: { fr: "Sem Wotte, alias Lobster, est un DJ et producteur néerlandais installé à Amsterdam depuis 2015, après La Haye. Il joue principalement de la techno, avec des incursions electro, ghetto house et old school. Résident d'Orphic Amsterdam de 2019 à 2021, il est depuis janvier 2022 résident de Vault Sessions, et a joué au Bassiani, à Awakenings, au RSO et au RADION.", en: "Sem Wotte, who records as Lobster, is a Dutch DJ and producer based in Amsterdam since 2015, having moved from The Hague. He plays mainly techno, with detours into electro, ghetto house and old school. A resident at Orphic Amsterdam from 2019 to 2021, he has been a Vault Sessions resident since January 2022, and has played Bassiani, Awakenings, RSO and RADION." }, origin: "Amsterdam, Pays-Bas", sources: ["https://ra.co/dj/lobster-nl/biography", "https://www.awakenings.com/en/artists/lobster/199697/"] }, // Lobster
  "loco-dice": { slug: "loco-dice", bio: { fr: "Loco Dice, de son vrai nom Yassine Ben Achour, est né le 10 août 1974 à Düsseldorf de parents tunisiens, ville où il vit toujours. Il commence comme DJ et rappeur hip-hop, avec une résidence au Salon des Amateurs, avant de passer à la house et à la techno sur les conseils de Timo Maas et Sven Väth. Il dirige le label Desolat et a tenu des résidences aux clubs ibizencos Space et Hi Ibiza.", en: "Loco Dice, real name Yassine Ben Achour, was born on 10 August 1974 in Düsseldorf to Tunisian parents and still lives there. He started out as a hip hop DJ and rapper with a residency at Salon des Amateurs before moving to house and techno at the urging of Timo Maas and Sven Väth. He runs the Desolat label and has held residencies at the Ibiza clubs Space and Hi Ibiza." }, origin: "Düsseldorf, Allemagne", since: 1994, labels: ["Desolat"], sources: ["https://en.wikipedia.org/wiki/Loco_Dice"] }, // Loco Dice
  "lossia": { slug: "lossia", bio: { fr: "LOSSIA est une DJ française basée à Angers. Formée au conservatoire, où elle apprend le piano avant de passer aux platines, elle joue principalement de la house et défend une approche du mix pensée comme un échange avec le public plutôt que comme une démonstration technique.", en: "LOSSIA is a French DJ based in Angers. Trained at a conservatoire, where she learned piano before moving to the decks, she plays mainly house and treats a set as an exchange with the crowd rather than a technical showcase." }, origin: "Angers, France", sources: ["https://www.warehouse-nantes.fr/artist/lossia/"] }, // Lossia
  "lost-frequencies": { slug: "lost-frequencies", bio: { fr: "Lost Frequencies est le nom de scène de Felix De Laet, DJ et producteur belge né en 1993. Il s'est fait connaître en 2014 avec « Are You with Me », puis « Reality » et « Where Are You Now » avec Calum Scott. Il dirige le label Found Frequencies.", en: "Lost Frequencies is the stage name of Felix De Laet, a Belgian DJ and producer born in 1993. He broke through in 2014 with \"Are You with Me\", followed by \"Reality\" and \"Where Are You Now\" with Calum Scott. He runs the Found Frequencies label." }, origin: "Bruxelles, Belgique", since: 2014, labels: ["Found Frequencies", "Armada Music"], sources: ["https://en.wikipedia.org/wiki/Lost_Frequencies", "https://fr.wikipedia.org/wiki/Lost_Frequencies"] }, // Lost Frequencies
  "ltj-bukem": { slug: "ltj-bukem", bio: { fr: "LTJ Bukem est le nom de scène de Daniel Andrew Williamson, musicien, producteur et DJ britannique né en 1967 à Watford. Pianiste de formation classique passé par le jazz-fusion, il se fait connaître dans la scène rave du début des années 1990. Avec son label Good Looking Records, il est associé au versant jazzy et atmosphérique de la jungle.", en: "LTJ Bukem is the stage name of Daniel Andrew Williamson, a British musician, producer and DJ born in 1967 in Watford. A classically trained pianist who came to music through jazz fusion, he made his name in the rave scene of the early 1990s. With his label Good Looking Records he is associated with the jazzy, atmospheric side of jungle." }, origin: "Watford, Angleterre", labels: ["Good Looking Records"], sources: ["https://en.wikipedia.org/wiki/LTJ_Bukem"] }, // LTJ Bukem
  "luca-agnelli": { slug: "luca-agnelli", bio: { fr: "Luca Agnelli est un DJ et producteur italien originaire de Toscane. Sa techno dure et physique garde des racines house, et se teinte volontiers d'industriel et de neo rave. Il a fondé en 2010 le label Etruria Beat, devenu l'une des références italiennes du genre, et signé en 2016 un remix de « Porcelain » de Moby paru sur Drumcode. Il joue régulièrement à l'Amnesia d'Ibiza, à la Fabrique de Milan, à l'Egg de Londres ou au Movement Festival de Turin.", en: "Luca Agnelli is an Italian DJ and producer from Tuscany. His hard, physical techno keeps its house roots while leaning into industrial and neo-rave textures. He founded the label Etruria Beat in 2010, now one of Italy's reference imprints for the style, and in 2016 delivered a remix of Moby's \"Porcelain\" released on Drumcode. He plays regularly at Amnesia in Ibiza, Fabrique in Milan, Egg in London and Turin's Movement Festival." }, origin: "Toscane, Italie", since: 2010, labels: ["Etruria Beat"], sources: ["https://electronicgroove.com/eg-artists/eg-techno-020-luca-agnelli/"] }, // Luca Agnelli
  "luciano": { slug: "luciano", bio: { fr: "Lucien Nicolet, connu sous le nom de Luciano, est un DJ et producteur suisse et chilien né en 1978 à Montcherand. Ses sets sont marqués par les musiques latino-américaines. Parti du minimal techno, son style a évolué vers un mélange de house et de techno. Il a reçu une vingtaine de récompenses, dont les Ibiza DJ Awards.", en: "Lucien Nicolet, known as Luciano, is a Swiss and Chilean DJ and producer born in 1978 in Montcherand. His DJ sets are strongly influenced by Latin American music. Starting from minimal techno, his style has evolved into a blend of house and techno. He has won around twenty awards, including the Ibiza DJ Awards." }, origin: "Suisse / Chili", sources: ["https://en.wikipedia.org/wiki/Luciano_(DJ)"] }, // Luciano
  "luciid": { slug: "luciid", bio: { fr: "Luciid est un projet de techno dont les sorties paraissent depuis 2019 sur Kneaded Pains, Suara et Autektone Records. Son registre relève de la hard techno et d'une techno sombre.", en: "Luciid is a techno project whose releases have appeared since 2019 on Kneaded Pains, Suara and Autektone Records, in a hard techno and dark techno vein." }, since: 2019, labels: ["Kneaded Pains", "Autektone Records"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Luciid&fmt=json", "https://api.discogs.com/database/search?artist=Luciid&type=release"] }, // Luciid
  "luigi-tozzi": { slug: "luigi-tozzi", bio: { fr: "Luigi Tozzi est un DJ et producteur italien basé à Rome. Il travaille une techno lente et hypnotique, proche de la dub techno et de l'ambient, construite sur de longues nappes plutôt que sur des montées.", en: "Luigi Tozzi is an Italian DJ and producer based in Rome. He works a slow, hypnotic techno close to dub techno and ambient, built on long pads rather than build-ups." }, origin: "Rome, Italie", sources: ["https://www.discogs.com/artist/4098420-Luigi-Tozzi", "https://www.last.fm/music/Luigi+Tozzi/+tags"] }, // Luigi Tozzi
  "luneris": { slug: "luneris", bio: { fr: "Luneris est un duo belge formé par deux sœurs, Mathilde au violon et Héloïse à la harpe, toutes deux diplômées du Conservatoire royal de Bruxelles. Leur projet « electro pagan trance » mêle techno et psytrance à la harpe électrique, au violon, à la flûte, à la guimbarde et à l'olifant, dans un répertoire nourri de traditions celtiques et nordiques. Elles tournent avec ce projet depuis 2025 en Belgique, en France et en Tchéquie ; un premier album est annoncé pour 2026.", en: "Luneris is a Belgian duo of two sisters, Mathilde on violin and Héloïse on harp, both graduates of the Royal Conservatory of Brussels. Their \"electro pagan trance\" project sets techno and psytrance against electric harp, violin, flute, jaw harp and oliphant, drawing on Celtic and Nordic traditions. They have toured the project since 2025 in Belgium, France and Czechia, with a first album announced for 2026." }, origin: "Belgique", since: 2025, sources: ["https://www.luneris.band/bio", "https://www.transbordeur.fr/artiste/luneris/"] }, // Luneris
  "lusterclub": { slug: "lusterclub", bio: { fr: "LusterClub est un collectif luxembourgeois né en 2024 de l'amitié entre AAMAR et Jeff Seven, rejoints par Luciano et Eddie. Il réunit DJs et créatifs locaux autour d'une programmation de club qui va des future beats au hip-hop, au dub, au baile funk et au reggaeton, et a pris ses quartiers d'été aux Rotondes de Luxembourg.", en: "LusterClub is a Luxembourg collective formed in 2024 out of the friendship between AAMAR and Jeff Seven, later joined by Luciano and Eddie. It gathers local DJs and creatives around club programming that runs from future beats to hip-hop, dub, baile funk and reggaeton, and took up summer residency at Rotondes in Luxembourg." }, origin: "Luxembourg", since: 2024, sources: ["https://www.rotondes.lu/en/agenda/lusterclub-one-year-anniversary", "https://www.elle.lu/fr/11089-les-collectifs-musicaux-a-suivre-cet-ete-au-luxembourg.html"] }, // LusterClub
  "luuk-van-dijk": { slug: "luuk-van-dijk", bio: { fr: "Luuk van Dijk est un DJ et producteur de house installé à Amsterdam. Il a fondé son label Dark Side Of The Sun en 2019, sur lequel paraît son premier album, First Contact, en novembre 2022, et a également publié sur Hot Creations, Solid Grooves et No Art. Il anime à Amsterdam la série de soirées Get Closer.", en: "Luuk van Dijk is an Amsterdam-based house DJ and producer. He founded his label Dark Side Of The Sun in 2019, which released his debut album First Contact in November 2022, and has also released on Hot Creations, Solid Grooves and No Art. In Amsterdam he runs the Get Closer party series." }, origin: "Amsterdam, Pays-Bas", since: 2019, labels: ["Dark Side Of The Sun"], sources: ["https://www.awakenings.com/en/artists/luuk-van-dijk/904/", "https://darksideofthesunams.bandcamp.com/album/first-contact"] }, // Luuk Van Dijk
  "maceo-plex": { slug: "maceo-plex", bio: { fr: "Eric Estornel, né en 1978 aux États-Unis et élevé entre Dallas et Miami, produit sous les alias Maceo Plex, Maetrik et Mariel Ito une musique qui mêle house, techno et electro. Son premier album, « Life Index », paraît sur Crosstown Rebels en 2011 ; il dirige ensuite ses propres labels Ellum Audio puis Lone Romantic, sur lesquels sortent « Journey to Solar » (2016), « Solar » (2017) et « Mutant Series » (2019). Depuis 2016, il tient à Ibiza sa soirée Mosaic by Maceo au Pacha. Il vit aujourd'hui à Barcelone.", en: "Born in 1978 in the United States and raised between Dallas and Miami, Eric Estornel produces as Maceo Plex, Maetrik and Mariel Ito, mixing house, techno and electro. His first album \"Life Index\" came out on Crosstown Rebels in 2011; he went on to run his own labels Ellum Audio and Lone Romantic, home to \"Journey to Solar\" (2016), \"Solar\" (2017) and \"Mutant Series\" (2019). Since 2016 he has hosted his Mosaic by Maceo night at Pacha in Ibiza. He now lives in Barcelona." }, origin: "Dallas / Miami, États-Unis", labels: ["Ellum Audio", "Lone Romantic"], sources: ["https://en.wikipedia.org/wiki/Maceo_Plex"] }, // Maceo Plex
  "mad-dog": { slug: "mad-dog", bio: { fr: "Mad Dog, de son vrai nom Filippo Calcagni, né le 2 novembre 1980 à Rome, est un DJ et producteur italien de hardcore et de gabber, installé aux Pays-Bas. À 16 ans il forme le groupe Hardcore Terrorists, puis part en solo à l'été 2000 et signe chez Traxtorm Records, le label du duo The Stunned Guys. Il a publié les albums A Night of Madness (2011), Rudeness: Hardcore Beyond the Rules (2013) et Till I Die (2017), et a fondé en 2016 son propre label, Dogfight Records.", en: "Mad Dog, real name Filippo Calcagni, born 2 November 1980 in Rome, is an Italian hardcore and gabber DJ and producer now living in the Netherlands. At 16 he formed the group Hardcore Terrorists, went solo in the summer of 2000 and signed to Traxtorm Records, the label run by the duo The Stunned Guys. He released the albums A Night of Madness (2011), Rudeness: Hardcore Beyond the Rules (2013) and Till I Die (2017), and founded his own label, Dogfight Records, in 2016." }, origin: "Rome, Italie", since: 2000, labels: ["Dogfight Records", "Traxtorm Records"], sources: ["https://en.wikipedia.org/wiki/DJ_Mad_Dog", "https://it.wikipedia.org/wiki/DJ_Mad_Dog"] }, // Mad Dog
  "mad-kate": { slug: "mad-kate", bio: { fr: "Mad Kate est le nom de scène de Kathryn Fischer, artiste électronique, vocaliste et productrice installée à Berlin. Son travail mêle production, performance et texte, à partir d'entretiens, d'enregistrements de terrain et de manipulations sonores. Elle forme avec le producteur TUSK le duo HYENAZ, qu'ils décrivent comme un projet de performance techno et electro.", en: "Mad Kate is the stage name of Kathryn Fischer, an electronic artist, vocalist and producer based in Berlin. Her work combines production, performance and text, built from interviews, field recordings and sonic manipulation. With producer TUSK she forms the duo HYENAZ, which they describe as a techno and electro performance project." }, origin: "Berlin, Allemagne", sources: ["https://madkate.bandcamp.com/", "https://www.berlinartlink.com/2016/04/27/body-queer-bodies-and-performance-an-interview-with-mad-kate/", "https://en.wikipedia.org/wiki/Hyenaz"] }, // Mad Kate
  "maddix": { slug: "maddix", bio: { fr: "Pablo Rindt, alias Maddix, né le 3 décembre 1990 à Eindhoven, est un DJ et producteur néerlandais. Signé chez Revealed Recordings, il oriente son son vers la techno à partir de 2018 et perce avec « Ecstasy » en 2019. Il a lancé son label Extatic (XTTC) en 2023 et figurait cette année-là à la 95e place du Top 100 DJs de DJ Mag.", en: "Pablo Rindt, known as Maddix, born 3 December 1990 in Eindhoven, is a Dutch DJ and producer. Signed to Revealed Recordings, he shifted his sound towards techno from 2018 and broke through with 'Ecstasy' in 2019. He launched his label Extatic (XTTC) in 2023 and ranked number 95 in DJ Mag's Top 100 DJs that year." }, origin: "Eindhoven, Pays-Bas", since: 2018, labels: ["Revealed Recordings", "Extatic"], sources: ["https://en.wikipedia.org/wiki/Maddix_(DJ)", "https://edmtrain.com/news/interview-maddix-reveals-his-journey-becoming-a-big-room-techno-pioneer-214"] }, // Maddix
  "main-phase": { slug: "main-phase", bio: { fr: "Main Phase est le nom de scène d'Adam Emil Schierbeck, DJ et producteur danois de Copenhague. Il a appris le UK garage en écoutant Rinse FM, station où il anime aujourd'hui sa propre émission. Il codirige le label ATW Records avec Interplanetary Criminal et compte parmi les artistes de la deuxième vague de speed garage.", en: "Main Phase is the stage name of Adam Emil Schierbeck, a Danish DJ and producer from Copenhagen. He learned UK garage listening to Rinse FM, the station he now broadcasts on himself. He co-owns the label ATW Records with Interplanetary Criminal and is one of the artists of the second wave of speed garage." }, origin: "Copenhague, Danemark", labels: ["ATW Records"], sources: ["https://ukf.com/read/we-need-to-talk-about-main-phase/", "https://www.rinse.fm/shows/main-phase"] }, // Main Phase
  "mala": { slug: "mala", bio: { fr: "Mala, de son vrai nom Mark Lawrence, est un producteur et DJ britannique originaire de South Norwood, dans le sud de Londres. Il est l'une des deux moitiés du duo dubstep Digital Mystikz avec Coki, et cofondateur du label et de la soirée DMZ à Brixton aux côtés de Coki, Loefah et Sgt. Pokes. Il dirige aussi son propre label, Deep Medi Musik. Son album « Mala in Cuba », enregistré à La Havane avec Gilles Peterson, est paru en 2012.", en: "Mala, real name Mark Lawrence, is a British producer and DJ from South Norwood in south London. He is one half of the dubstep duo Digital Mystikz alongside Coki, and co-founder of the DMZ label and club night in Brixton with Coki, Loefah and Sgt. Pokes. He also runs his own imprint, Deep Medi Musik. His album \"Mala in Cuba\", recorded in Havana with Gilles Peterson, came out in 2012." }, origin: "Londres, Royaume-Uni", since: 2004, labels: ["Deep Medi Musik", "DMZ"], sources: ["https://en.wikipedia.org/wiki/Mala_(musician)"] }, // Mala
  "malice": { slug: "malice", bio: { fr: "Malice est un projet raw hardstyle italien créé en 2013 par Aleandro Bollino et Davide Guernieri. Depuis la séparation du duo, Davide Guernieri le poursuit seul, tandis qu'Aleandro produit sous le nom de Sickmode. Malice est co-fondateur du label Aggressive Records avec Sickmode et Rooler.", en: "Malice is an Italian raw hardstyle project started in 2013 by Aleandro Bollino and Davide Guernieri. Since the duo split, Davide Guernieri has carried it on alone, while Aleandro produces as Sickmode. Malice co-founded the Aggressive Records label with Sickmode and Rooler." }, origin: "Italie", since: 2013, labels: ["Aggressive Records"], sources: ["https://hardnews.nl/en/malice-is-splitting-up-double-the-madness/", "https://harderstylemap.com/artist/malice/"] }, // Malice
  "mall-grab": { slug: "mall-grab", bio: { fr: "Mall Grab est le nom de scène de Jordon Alexander, DJ et producteur australien né en 1994. Repéré au milieu des années 2010 pour ses productions house au grain lo-fi, il dirige le label Looking For Trouble et joue aujourd'hui un répertoire qui va de la house à la techno et aux breakbeats.", en: "Mall Grab is the stage name of Jordon Alexander, an Australian DJ and producer born in 1994. Noticed in the mid-2010s for his lo-fi-tinged house productions, he runs the Looking For Trouble label and now plays a range spanning house, techno and breakbeat." }, origin: "Newcastle, Australie", labels: ["Looking For Trouble"], sources: ["https://en.wikipedia.org/wiki/Mall_Grab", "https://www.last.fm/music/Mall+Grab/+tags"] }, // Mall Grab
  "mandragora": { slug: "mandragora", bio: { fr: "Mandragora, de son vrai nom Eduardo Neto, est un DJ et producteur mexicain né à Chihuahua, passé par le circuit psytrance brésilien et installé à Toulouse depuis 2021. Actif depuis 2012, il se fait connaître avec « Wild Wild West », produit avec Groovaholik en 2014. Il croise trance goa, house progressive et techno sous l'étiquette futureprog, qu'il revendique.", en: "Mandragora, born Eduardo Neto in Chihuahua, Mexico, came up on the Brazilian psytrance circuit and has been based in Toulouse since 2021. Active since 2012, he broke through with 'Wild Wild West', made with Groovaholik in 2014. He crosses Goa trance, progressive house and techno under the futureprog tag he coined." }, origin: "Chihuahua, Mexique", since: 2012, sources: ["https://djmandragora.com/bio"] }, // Mandragora
  "mar-t": { slug: "mar-t", bio: { fr: "Mar-T est un DJ et producteur né à Barcelone, résident du club Amnesia d'Ibiza depuis 1999. Il dirige le label Wow! Recordings et tient une résidence techno et tech house le mercredi avec HYTE lors de la saison 2016, en plus de tournées avec le club en Italie et au Royaume-Uni et de dates avec Do Not Sleep et Cocoon.", en: "Mar-T is a DJ and producer born in Barcelona who has been a resident at Ibiza's Amnesia since 1999. He runs the Wow! Recordings label and held the Wednesday techno and tech house residency with HYTE during the 2016 season, alongside tours with the club in Italy and the UK and dates with Do Not Sleep and Cocoon." }, origin: "Barcelone, Espagne", since: 1999, labels: ["Wow! Recordings"], sources: ["https://www.ibiza-spotlight.com/night/2016/10/feature-mar-ts-top-amnesia-tracks"] }, // Mar-T
  "mara": { slug: "mara", bio: { fr: "Mara est une DJ suisse née et élevée à Genève. Passionnée de drum and bass depuis 2008, elle commence à mixer après des études de graphisme à la HEAD Genève. Elle a lancé en 2018 ses soirées Foulamerde, où se croisent drum and bass, jungle, dancehall et dubstep, tient une résidence chez Subset et a animé de 2018 à 2022 une émission hebdomadaire sur Mouv'. Elle a joué au Montreux Jazz, à Paléo, Solidays et Marsatac.", en: "Mara is a Swiss DJ born and raised in Geneva. Hooked on drum and bass since 2008, she started DJing after studying graphic design at HEAD Geneva. In 2018 she launched her Foulamerde parties, where drum and bass, jungle, dancehall and dubstep meet, holds a residency with Subset and hosted a weekly show on Mouv' from 2018 to 2022. She has played Montreux Jazz, Paléo, Solidays and Marsatac." }, origin: "Genève, Suisse", since: 2016, sources: ["https://allofloride.com/en/our-talents/mara/"] }, // Mara
  "marc-acardipane": { slug: "marc-acardipane", bio: { fr: "Marc Acardipane est l'un des noms de scène de Marc Trauner, producteur allemand établi à Francfort. Il enregistre aussi sous les alias Mescalinum United, The Mover, Pilldriver et Marshall Masters, et est associé à la naissance du hardcore de Francfort.", en: "Marc Acardipane is one of the stage names of Marc Trauner, a German producer based in Frankfurt. He also records as Mescalinum United, The Mover, Pilldriver and Marshall Masters, and is associated with the birth of Frankfurt hardcore." }, origin: "Francfort, Allemagne", sources: ["https://en.wikipedia.org/wiki/Marc_Acardipane"] }, // Marc Acardipane
  "marc-zocher": { slug: "marc-zocher", bio: { fr: "DJ et producteur originaire de Saxe, Marc Zocher joue surtout dans les clubs et festivals de l'est de l'Allemagne. Son style va de la techno appuyée à des moments plus accrocheurs, taillés pour les dancefloors de la région. Il est rattaché au Sky Club de Leipzig et au collectif Beatbrothers.", en: "A DJ and producer from Saxony, Marc Zocher plays mostly in the clubs and festivals of eastern Germany. His style runs from driving techno to more immediate, hook-led moments built for the region's dancefloors. He is attached to Leipzig's Sky Club and the Beatbrothers collective." }, origin: "Leipzig, Allemagne", sources: ["https://www.skyclub-leipzig.de/artist/detail/18-marc-zocher-sky-club-beatbrothers-de"] }, // Marc Zocher
  "marcel-dettmann": { slug: "marcel-dettmann", bio: { fr: "Marcel Dettmann est un DJ, producteur et patron de label allemand, né en 1977 à Pößneck et installé à Berlin. Il est résident du Berghain et a travaillé au disquaire berlinois Hard Wax entre 2002 et 2012. Sa discographie relève de la techno, avec des incursions minimal et electro.", en: "Marcel Dettmann is a German DJ, producer and record label owner, born in 1977 in Pößneck and based in Berlin. He is a resident DJ at Berghain and worked at the Berlin record shop Hard Wax between 2002 and 2012. His catalogue is techno, with minimal and electro excursions." }, origin: "Berlin, Allemagne", sources: ["https://en.wikipedia.org/wiki/Marcel_Dettmann", "https://musicbrainz.org/artist/6d7238a1-f0bc-4408-93fc-8ec64c06f7af", "https://api.discogs.com/database/search?artist=Marcel+Dettmann&type=release&per_page=50"] }, // Marcel Dettmann
  "marcellus-pittman": { slug: "marcellus-pittman", bio: { fr: "Marcellus « Malik » Pittman est un DJ et producteur américain de Détroit. Il publie ses premiers travaux en 1993 avec le collectif hip-hop Home Grown, puis « Essential Selections, Vol. 1 » sur Sound Signature, le label de Theo Parrish. Il rejoint le collectif 3 Chairs, qu'il forme avec Rick Wilhite, Theo Parrish et Kenny « Moodymann » Dixon Jr., et dirige aujourd'hui son propre label, Unirhythm.", en: "Marcellus \"Malik\" Pittman is an American DJ and producer from Detroit. He put out his first productions in 1993 with the hip-hop collective Home Grown, then \"Essential Selections, Vol. 1\" on Sound Signature, Theo Parrish's label. He is part of the 3 Chairs collective alongside Rick Wilhite, Theo Parrish and Kenny \"Moodymann\" Dixon Jr., and now runs his own label, Unirhythm." }, origin: "Détroit, États-Unis", since: 1993, labels: ["Unirhythm"], sources: ["https://earth-agency.com/artist/marcellus-pittman/", "https://en.wikipedia.org/wiki/3_Chairs"] }, // Marcellus Pittman
  "marco-carola": { slug: "marco-carola", bio: { fr: "Marco Carola est un DJ et producteur italien né le 7 février 1975 à Naples. Il a commencé à mixer à quinze ans, après l'achat de ses premières platines, et a publié sur Design Music puis sur M_nus. Sa production tourne autour d'une techno minimale et de la tech house.", en: "Marco Carola is an Italian DJ and producer born on 7 February 1975 in Naples. He started DJing at fifteen, after buying his first set of turntables, and has released on Design Music and later M_nus. His output revolves around minimal techno and tech house." }, origin: "Naples, Italie", labels: ["M_nus", "Design Music"], sources: ["https://en.wikipedia.org/wiki/Marco_Carola", "https://api.discogs.com/database/search?artist=Marco+Carola&type=release"] }, // Marco Carola
  "maribou-state": { slug: "maribou-state", bio: { fr: "Maribou State est un duo électronique anglais formé par Chris Davids et Liam Ivory, originaires de Berkhamsted dans le Hertfordshire, où ils se sont rencontrés au lycée. Ils débutent en 2011 avec l'EP Habitat sur FatCat Records, puis signent chez Counter Records, filiale de Ninja Tune. Leurs albums Portraits (2015), Kingdoms in Colour (2018) et Hallucinating Love (2025) mêlent house, soul et voix invitées, dont celles de Holly Walker et Khruangbin.", en: "Maribou State is an English electronic duo made up of Chris Davids and Liam Ivory, from Berkhamsted in Hertfordshire, where they met at school. They debuted in 2011 with the EP Habitat on FatCat Records, then signed to Counter Records, an imprint of Ninja Tune. Their albums Portraits (2015), Kingdoms in Colour (2018) and Hallucinating Love (2025) blend house, soul and guest vocals, including Holly Walker and Khruangbin." }, origin: "Berkhamsted, Angleterre", since: 2011, labels: ["Counter Records", "Ninja Tune"], sources: ["https://en.wikipedia.org/wiki/Maribou_State"] }, // Maribou State
  "marie-julie": { slug: "marie-julie", bio: { fr: "Marie-Julie est une DJ belge, résidente du Fuse à Bruxelles, où elle joue exclusivement en vinyle sur deux platines et une table de mixage. Ses sets tiennent d'une techno de groove, entre rythmes profonds et passages plus soutenus, et mêlent disques d'occasion et productions récentes. Elle est représentée à l'international par l'agence mutual obsession.", en: "Marie-Julie is a Belgian DJ and a resident of Fuse in Brussels, where she plays vinyl only on two turntables and a mixer. Her sets are groove-led techno, moving between deep, rolling rhythms and harder stretches, mixing second-hand finds with recent records. She is represented internationally by the mutual obsession agency." }, origin: "Bruxelles, Belgique", sources: ["https://mutual-obsession.com/artists/marie-julie", "https://www.fuse.be/resident-team"] }, // Marie-Julie
  "marie-vaunt": { slug: "marie-vaunt", bio: { fr: "Bobbie Merveille, née en 1983 à Seattle et élevée au Japon jusqu'à ses quatorze ans, a d'abord mixé sous le nom DJ Heavygrinder avant d'adopter l'alias Marie Vaunt en 2018. Installée à Los Angeles, elle produit une techno acide et rapide où affleurent ses racines japonaises, comme sur « Kurayami ». Elle a sorti chez Drumcode et sur HILOMATIK, le label de HI-LO.", en: "Bobbie Merveille, born in Seattle in 1983 and raised in Japan until she was fourteen, first DJed as DJ Heavygrinder before taking the Marie Vaunt alias in 2018. Based in Los Angeles, she produces fast, acid-leaning techno in which her Japanese roots surface, as on \"Kurayami\". She has released on Drumcode and on HILOMATIK, HI-LO's label." }, origin: "Seattle, États-Unis", since: 2018, labels: ["Drumcode", "HILOMATIK"], sources: ["https://en.wikipedia.org/wiki/DJ_Heavygrinder", "https://www.beatportal.com/articles/942047-marie-vaunt-bridging-cultures-through-techno"] }, // Marie Vaunt
  "marlon-hoffstadt": { slug: "marlon-hoffstadt", bio: { fr: "Marlon Hoffstadt est un DJ et producteur allemand né et installé à Berlin, également connu sous l'alias DJ Daddy Trance. Il se fait remarquer en 2014 avec le single « Shake That », produit avec Dansson, puis lance son label Midnight Themes en 2017 et la série de soirées Savour The Moment au club Wilde Renate. Ses sets circulent entre disco, house, trance et techno.", en: "Marlon Hoffstadt is a German DJ and producer born and based in Berlin, also known under the alias DJ Daddy Trance. He first drew attention in 2014 with the single \"Shake That\", made with Dansson, then launched his label Midnight Themes in 2017 and the Savour The Moment party series at the Wilde Renate club. His sets move between disco, house, trance and techno." }, origin: "Berlin, Allemagne", since: 2012, labels: ["Midnight Themes", "Retrograde"], sources: ["https://djmag.com/content/cue-marlon-hoffstadt", "https://www.discogs.com/artist/2623061"] }, // Marlon Hoffstadt
  "marmotek-sound-system": { slug: "marmotek-sound-system", bio: { fr: "Marmotek est un sound system breton, actif depuis des années sur la scène hard des free parties et des clubs de l'Ouest. Il est l'un des piliers de la résidence Rave in da Club du Warehouse de Nantes, où il a joué aux côtés de Miss K8, Angerfist et Dr Peacock. Son répertoire couvre le hardtek, la frenchcore, le hardcore, la gabber et le hardstyle, avec des incursions en breakbeat, electro et techno.", en: "Marmotek is a Breton sound system, long active in the hard scene of western France's free parties and clubs. It is one of the mainstays of the Rave in da Club residency at Nantes' Warehouse, where it has played alongside Miss K8, Angerfist and Dr Peacock. Its range covers hardtek, frenchcore, hardcore, gabber and hardstyle, with excursions into breakbeat, electro and techno." }, origin: "Bretagne, France", sources: ["https://www.warehouse-nantes.fr/artist/marmotek", "https://electro-news.eu/nantes-lexode-marmotek-ameson-macadam-2018/"] }, // Marmotek Sound System
  "maro": { slug: "maro", bio: { fr: "Originaire de Cologne et installé à Vienne, Maro est co-fondateur et résident du collectif de DJs et producteurs MAHLWERK. Ses sets mêlent techno, trance et hardgroove à du hip-hop et des breakbeats. Il publie ses morceaux sur Bandcamp, notamment en duo avec GOLDI.", en: "Originally from Cologne and now based in Vienna, Maro is a co-founder and resident of the MAHLWERK DJ and producer collective. His sets mix techno, trance and hardgroove with hip-hop and breakbeats. He releases his tracks on Bandcamp, including as a duo with GOLDI." }, origin: "Vienne, Autriche", labels: ["MAHLWERK"], sources: ["https://ra.co/dj/maro/biography", "https://maro87.bandcamp.com/"] }, // Maro
  "marshmello": { slug: "marshmello", bio: { fr: "Marshmello est le nom de scène de Christopher Comstock, producteur et DJ américain né en 1992 à Philadelphie, qui se produit masqué sous un casque blanc en forme de guimauve. Il a adopté ce pseudonyme en 2015 après avoir publié sous le nom de Dotcom, et son identité a été confirmée par Forbes en 2017. Sa musique, très portée sur les synthés et les basses, croise dubstep, future bass et trap : « Silence » avec Khalid, « Wolves » avec Selena Gomez ou « Happier » avec Bastille. Il a fondé son label indépendant Joytime Collective en 2016.", en: "Marshmello is the stage name of Christopher Comstock, an American producer and DJ born in Philadelphia in 1992, who performs masked under a white marshmallow-shaped helmet. He took the alias in 2015 after releasing as Dotcom, and his identity was confirmed by Forbes in 2017. His synth- and bass-heavy music crosses dubstep, future bass and trap: \"Silence\" with Khalid, \"Wolves\" with Selena Gomez, \"Happier\" with Bastille. He founded his independent label Joytime Collective in 2016." }, origin: "Philadelphie, États-Unis", since: 2015, labels: ["Joytime Collective"], sources: ["https://en.wikipedia.org/wiki/Marshmello"] }, // Marshmello
  "martin-garrix": { slug: "martin-garrix", bio: { fr: "Martin Garrix, de son vrai nom Martijn Gerard Garritsen, est un DJ et producteur néerlandais né en 1996 à Amstelveen. Il produit de la progressive house et de la big room house. Son morceau « Animals », sorti en 2013, l'a propulsé à 17 ans en tête du classement Beatport. Il a fondé son label Stmpd Rcrds en 2016 et a été classé numéro un du Top 100 DJs de DJ Mag en 2016, 2017, 2018, 2022 et 2024.", en: "Martin Garrix, real name Martijn Gerard Garritsen, is a Dutch DJ and producer born in 1996 in Amstelveen. He makes progressive house and big room house. His track \"Animals\", released in 2013, took him to the top of the Beatport chart at 17. He founded his label Stmpd Rcrds in 2016 and topped DJ Mag's Top 100 DJs poll in 2016, 2017, 2018, 2022 and 2024." }, origin: "Amstelveen, Pays-Bas", since: 2013, labels: ["Stmpd Rcrds"], sources: ["https://en.wikipedia.org/wiki/Martin_Garrix"] }, // Martin Garrix
  "marz": { slug: "marz", bio: { fr: "März est une DJ française basée à Rennes et résidente du collectif Solarium. Elle dit puiser son inspiration dans les raves parisiennes, où elle a découvert la hard music. Ses sets, construits en progression, mêlent techno, hard techno et musique expérimentale, entre kicks appuyés et mélodies sombres.", en: "März is a French DJ based in Rennes and a resident of the Solarium collective. She traces her inspiration to Paris raves, where she first encountered hard music. Her sets are built as slow builds and mix techno, hard techno and experimental material, between heavy kicks and dark melodies." }, origin: "Rennes, France", sources: ["https://www.warehouse-nantes.fr/artist/marz"] }, // März
  "masalo": { slug: "masalo", bio: { fr: "DJ, producteur et live act né et élevé à Amsterdam, Masalo passe de la house à la techno, la hi-NRG et le disco dans un même set. Sa première sortie officielle, en 2017, est un remix de « Jama Ko » de Bassekou Kouyaté ; il rejoint le label Rush Hour en 2019 avec l'EP New Dance. Avec Kamma, il tient la série de soirées et de compilations Brighter Days.", en: "An Amsterdam-born DJ, producer and live act, Masalo moves between house, techno, hi-NRG and disco within a single set. His first official release, in 2017, was a remix of Bassekou Kouyaté's \"Jama Ko\"; he joined Rush Hour in 2019 with the EP New Dance. With Kamma he runs the Brighter Days party and compilation series." }, origin: "Amsterdam, Pays-Bas", since: 2017, labels: ["Rush Hour", "Brighter Days"], sources: ["https://ra.co/dj/masalo/biography", "https://www.rushhour.nl/record/vinyl/new-dance", "https://www.stampthewax.com/2018/06/06/masalo-dimensions-dj-directory/"] }, // Masalo
  "masters-at-work": { slug: "masters-at-work", bio: { fr: "Masters at Work est le duo américain de production et de remix formé par « Little » Louie Vega et Kenny « Dope » Gonzalez, réuni à New York en 1990. Le duo a aussi enregistré sous les noms MAW, KenLou, Hardrive et Nuyorican Soul, et fait paraître ses disques sur MAW Records et Strictly Rhythm. Son terrain est la garage house.", en: "Masters at Work is the American production and remix duo of \"Little\" Louie Vega and Kenny \"Dope\" Gonzalez, formed in New York in 1990. The pair have also recorded as MAW, KenLou, Hardrive and Nuyorican Soul, releasing on MAW Records and Strictly Rhythm. Their ground is garage house." }, origin: "New York, États-Unis", since: 1990, labels: ["MAW Records", "Strictly Rhythm"], sources: ["https://en.wikipedia.org/wiki/Masters_at_Work", "https://api.discogs.com/database/search?artist=Masters+at+Work&type=release"] }, // Masters at Work
  "mathame": { slug: "mathame", bio: { fr: "Mathame est un duo italien de techno. Ses disques paraissent sur Afterlife, le label de Tale of Us, ainsi que sur Columbia, dans un registre de techno mélodique et de progressive house.", en: "Mathame is an Italian techno duo. Their records come out on Afterlife, Tale of Us's label, as well as on Columbia, in a melodic techno and progressive house vein." }, origin: "Italie", labels: ["Afterlife"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Mathame&fmt=json", "https://api.discogs.com/database/search?artist=Mathame&type=release"] }, // Mathame
  "mathew-jonson": { slug: "mathew-jonson", bio: { fr: "Mathew Jonson est un producteur et DJ canadien originaire de Vancouver, aujourd'hui installé à Berlin. Formé au piano classique et à la batterie jazz, il a mis la main sur un synthétiseur à neuf ans et sorti son premier single, « New Identity », sur le label britanno-colombien Itiswhatitis en 2001. Il a cofondé le label Wagon Repair en 2005 et joue aussi au sein des formations Cobblestone Jazz et Midnight Operator. Ses live sets sont entièrement joués en temps réel sur des machines analogiques, sans lecture de fichiers préparés.", en: "Mathew Jonson is a Canadian producer and DJ from Vancouver, now based in Berlin. Trained on classical piano and jazz drums, he got his hands on a synthesiser at nine and released his first single, \"New Identity\", on the British Columbia label Itiswhatitis in 2001. He co-founded the Wagon Repair label in 2005 and also plays in the groups Cobblestone Jazz and Midnight Operator. His live sets are performed in real time on analogue gear rather than played back from prepared files." }, origin: "Vancouver, Canada", since: 2001, labels: ["Wagon Repair", "Itiswhatitis"], sources: ["https://grayarea.co/artists/mathew-jonson"] }, // Mathew Jonson
  "matrakk": { slug: "matrakk", bio: { fr: "Matrakk est un DJ et producteur français qui mêle techno, trance et groove, avec des synthés et des voix qui rejouent l'esprit des raves des années 1990. Il a commencé comme DJ généraliste avant de se former à l'école de DJ de l'UCPA, et a cofondé le label Obsession avec R Organic. Sa percée date de « My Drums Hard » (2020) ; il a publié l'album Contre-Sens II en janvier 2024, puis « Romance Under The Sun » sur Speed Master la même année.", en: "Matrakk is a French DJ and producer whose sound mixes techno, trance and groove, with synths and vocals that replay the spirit of 1990s raves. He started out as an all-round DJ before training at the UCPA DJ school, and co-founded the Obsession label with R Organic. His breakthrough came with \"My Drums Hard\" (2020); he released the album Contre-Sens II in January 2024, followed by \"Romance Under The Sun\" on Speed Master the same year." }, origin: "France", since: 2020, labels: ["Obsession"], sources: ["https://electro-news.eu/matrakk-le-dj-generaliste-lyonnais-devenu-ambassadeur-de-la-rave-90s-dans-le-monde-entier/", "https://nuits-sonores.com/en/artiste/matrakk-2/"] }, // Matrakk
  "matthias-geerts": { slug: "matthias-geerts", bio: { fr: "Matthias Geerts est un DJ et producteur belge de techno. Ses sets partent d'un groove posé qui monte progressivement vers une techno classique, en passant par l'acid et la trance des années 1990 ; il remet volontiers en jeu des morceaux anciens. Il a publié sur BCCO et signé un épisode de la série de mixes du label.", en: "Matthias Geerts is a Belgian techno DJ and producer. His sets open on a steady groove that builds towards classic techno by way of acid and 1990s trance, and he readily brings older records back into play. He has released on BCCO and recorded an episode of the label's mix series." }, origin: "Belgique", labels: ["BCCO"], sources: ["https://ra.co/dj/matthiasgeerts/biography", "https://bcco.bandcamp.com/album/bcct003-curated-by-dj-hyperdrive"] }, // Matthias Geerts
  "mau-p": { slug: "mau-p", bio: { fr: "Maurits Westveen, né à Amsterdam en 1996, a d'abord produit sous le nom de Maurice West avant d'adopter l'alias Mau P en 2022. Son morceau « Drugs from Amsterdam », sorti la même année, s'est hissé en tête du classement général de Beatport et a été retenu par Billboard parmi les meilleurs titres dance de 2022. Sa tech house sombre est parue sur des labels comme Repopulate Mars, Diynamic, Defected et Afterlife.", en: "Born in Amsterdam in 1996, Maurits Westveen produced as Maurice West before adopting the Mau P alias in 2022. His track \"Drugs from Amsterdam\", released that same year, topped Beatport's main chart and was named by Billboard among the best dance tracks of 2022. His dark tech house has appeared on labels including Repopulate Mars, Diynamic, Defected and Afterlife." }, origin: "Amsterdam, Pays-Bas", since: 2022, labels: ["Repopulate Mars", "Diynamic", "Defected"], sources: ["https://en.wikipedia.org/wiki/Mau_P"] }, // Mau P
  "maudux": { slug: "maudux", bio: { fr: "Maudux est une DJ et productrice française basée à Paris. Ses sets naviguent entre trance et techno rebondissante, et elle revendique un style personnel, la « Bounce Trap », qui associe des kicks de ghetto trance à des voix trap. Elle publie sur le label la kermess.", en: "Maudux is a French DJ and producer based in Paris. Her sets move between trance and bouncy techno, and she claims a signature style, \"Bounce Trap\", pairing ghetto trance kicks with trap vocals. She releases on the la kermess label." }, origin: "Paris, France", labels: ["la kermess"], sources: ["https://le-sucre.eu/artists/maudux/"] }, // Maudux
  "max-cooper": { slug: "max-cooper", bio: { fr: "Max Cooper, né le 19 mai 1980 à Belfast et installé à Londres, produit de la musique électronique depuis 2007. Il associe techno, électronique et IDM à des œuvres visuelles : plus de soixante-dix morceaux et remixes et une vingtaine de vidéos, principalement sur le label londonien Fields et l'allemand Traum Schallplatten. Ses remixes vont de Michael Nyman et Nils Frahm à Hot Chip et Sasha, et son premier album Human a été salué par la critique.", en: "Max Cooper, born 19 May 1980 in Belfast and based in London, has been releasing electronic music since 2007. He pairs techno, electronica and IDM with visual work: more than seventy tracks and remixes and around twenty accompanying videos, mostly on the London label Fields and Germany's Traum Schallplatten. His remixes range from Michael Nyman and Nils Frahm to Hot Chip and Sasha, and his debut album Human drew critical praise." }, origin: "Belfast, Irlande du Nord", since: 2007, labels: ["Fields", "Traum Schallplatten"], sources: ["https://en.wikipedia.org/wiki/Max_Cooper_(music_producer)", "https://musicbrainz.org/artist/2d68f237-4e00-424a-a03e-d16993d1da15"] }, // Max Cooper
  "max-dean": { slug: "max-dean", bio: { fr: "Max Dean est un DJ et producteur britannique, fondateur du label et de la série de soirées neXup. En moins de deux ans, neXup est passé d'un label confidentiel à l'un des catalogues les plus écoutés de la catégorie minimal / deep tech de Beatport, et sert de plateforme aux artistes émergents. Il a été nommé aux « Best of British » de DJ Mag et figure parmi les Breakthrough DJs 2024 de Mixmag.", en: "Max Dean is a British DJ and producer, founder of the neXup label and party series. In under two years neXup grew from a boutique label into one of Beatport's most-played minimal / deep tech imprints, and serves as a platform for emerging artists. He has been nominated for DJ Mag's \"Best of British\" and named one of Mixmag's Breakthrough DJs of 2024." }, origin: "Royaume-Uni", labels: ["neXup"], sources: ["https://electronicgroove.com/max-dean-brings-nexup-to-drumsheds-london/", "https://thisisframework.com/artist/max-dean/"] }, // Max Dean
  "mc-boogshe": { slug: "mc-boogshe", bio: { fr: "MC Boogshe, de son vrai nom Rachel Velberg, est une MC néerlandaise. Elle commence en 2006 en posant sa voix sur « SLUT » de Dennis Christopher & Tony Cha Cha, puis enregistre avec DJ Jean, Ralvero, Laidback Luke, Showtek et Hardwell. Signée chez Talpa Music en 2011, elle anime clubs et festivals aux Pays-Bas (Mysteryland, Dance Valley) et accompagne Paul Elstak sur la scène hardcore.", en: "MC Boogshe, born Rachel Velberg, is a Dutch MC. She started in 2006 with vocals on 'SLUT' by Dennis Christopher & Tony Cha Cha, then recorded with DJ Jean, Ralvero, Laidback Luke, Showtek and Hardwell. Signed to Talpa Music in 2011, she hosts clubs and festivals across the Netherlands (Mysteryland, Dance Valley) and works alongside Paul Elstak on the hardcore circuit." }, origin: "Pays-Bas", since: 2006, labels: ["Talpa Music"], sources: ["http://www.boogshe.com/biography", "https://www.djguide.nl/djinfo.p?djid=5397&language=en"] }, // MC Boogshe
  "mc-kaman": { slug: "mc-kaman", bio: { fr: "MC Kaman est un DJ résident du club Jæger, à Oslo, où il anime chaque semaine les soirées Nightflight. Il y joue un répertoire ouvert, sans frontière de genre, qui va du club underground aux tubes populaires assumés.", en: "MC Kaman is a resident DJ at Jæger in Oslo, where he hosts the weekly Nightflight nights. He plays an open-format repertoire with no genre boundary, from underground club records to unashamed chart hits." }, origin: "Oslo, Norvège", sources: ["https://jaegeroslo.no/residents/mc-kaman/"] }, // MC Kaman
  "mc-nice": { slug: "mc-nice", bio: { fr: "MC Nice est l'une des voix installées de la scène bass music belge. Il anime les grandes scènes et festivals au micro, dans un style fait de phrases courtes et de débit rapide. Il est un habitué des soirées Star Warz à Gand.", en: "MC Nice is one of the established voices of the Belgian bass music scene. He hosts large stages and festivals on the mic, in a style built on short bars and fast delivery. He is a regular at the Star Warz parties in Ghent." }, origin: "Belgique", sources: ["https://www.starwarz.be/artists/mc-nice"] }, // MC Nice
  "mcde": { slug: "mcde", bio: { fr: "Danilo Plessow, né en 1985 et installé à Stuttgart, produit sous le nom Motor City Drum Ensemble depuis 2007 — un clin d'œil à Détroit autant qu'à la « ville du moteur » allemande. Batteur depuis l'enfance et passé par le big band de son lycée, il construit une house nourrie de jazz, de disco et du sillon de Moodymann et Theo Parrish, réunie sur les compilations Raw Cuts. Il a signé un DJ-Kicks en 2011 et un Fabric Presents en 2021.", en: "Danilo Plessow, born in 1985 and based in Stuttgart, has produced as Motor City Drum Ensemble since 2007 — a nod to Detroit as much as to Germany's own 'motor city'. A drummer since childhood and a school big-band player, he builds a house sound steeped in jazz, disco and the groove of Moodymann and Theo Parrish, collected on the Raw Cuts compilations. He mixed a DJ-Kicks in 2011 and a Fabric Presents in 2021." }, origin: "Stuttgart, Allemagne", since: 2007, sources: ["https://en.wikipedia.org/wiki/Danilo_Plessow", "http://motorcitydrumensemble.com/?page_id=20"] }, // MCDE
  "mcr-t": { slug: "mcr-t", bio: { fr: "Julian McCarthy, alias MCR-T, est un DJ, producteur et rappeur né à Berlin, figure du collectif Live From Earth. Il se met à la production sur Ableton vers 2015 et publie son premier EP, Kraft, sur le label Live From Earth Klub en 2018. Sa musique croise ghetto-tech, Miami bass, hip-hop et techno, avec des refrains rappés par-dessus des tempos rapides.", en: "Julian McCarthy, known as MCR-T, is a Berlin-born DJ, producer and rapper, and a central figure in the Live From Earth collective. He taught himself production on Ableton around 2015 and released his first EP, Kraft, on the Live From Earth Klub imprint in 2018. His music crosses ghetto-tech, Miami bass, hip-hop and techno, layering rapped hooks over fast tempos." }, origin: "Berlin, Allemagne", since: 2018, labels: ["Live From Earth Klub"], sources: ["https://crackmagazine.net/article/profiles/mcr-t-interview-not-the-same/", "https://clubbasis.nl/article-mcr-t-king-of-ghetto-tech/"] }, // MCR-T
  "me": { slug: "me", bio: { fr: "&ME, de son vrai nom André Boadu, est un producteur et DJ allemand de Berlin, actif depuis 2009. Il est cofondateur du label et collectif Keinemusik, aux côtés de Rampa, Adam Port et Reznik, et y publie l'essentiel de ses disques, entre house et techno.", en: "&ME, real name André Boadu, is a German producer and DJ from Berlin, active since 2009. He is a co-founder of the Keinemusik label and collective alongside Rampa, Adam Port and Reznik, where he releases most of his records, between house and techno." }, origin: "Berlin, Allemagne", since: 2009, labels: ["Keinemusik"], sources: ["https://en.wikipedia.org/wiki/%26Me_(DJ)", "https://www.discogs.com/artist/645861-Me"] }, // &ME
  "medusa": { slug: "medusa", bio: { fr: "Medusa est une DJ française basée à Paris. Elle construit des sets hybrides qui passent de la trance et de l'acid au hard techno, en s'appuyant sur les sonorités et l'esthétique des années 2000. Elle joue régulièrement au Warehouse de Nantes.", en: "Medusa is a French DJ based in Paris. She builds hybrid sets moving from trance and acid to hard techno, drawing on the sounds and aesthetics of the 2000s. She plays regularly at the Warehouse in Nantes." }, origin: "Paris, France", sources: ["https://www.warehouse-nantes.fr/artist/medusa"] }, // Medusa
  "meduza": { slug: "meduza", bio: { fr: "Meduza est un trio de production house italien formé à Milan en 2018 par Luca de Gregorio, Mattia Vitale et Simone Giani. Le groupe se fait connaître en 2019 avec « Piece of Your Heart », écrit avec les Britanniques Goodboys, qui atteint la deuxième place des ventes de singles au Royaume-Uni et est nommé au Grammy Award dans la catégorie Best Dance Recording, puis avec « Lose Control » avec Goodboys et Becky Hill. Le trio publie chez Virgin, Polydor et Defected.", en: "Meduza is an Italian house production trio formed in Milan in 2018 by Luca de Gregorio, Mattia Vitale and Simone Giani. They broke through in 2019 with \"Piece of Your Heart\", written with British trio Goodboys, which reached number two on the UK singles chart and was nominated for the Grammy for Best Dance Recording, followed by \"Lose Control\" with Goodboys and Becky Hill. The trio releases on Virgin, Polydor and Defected." }, origin: "Milan, Italie", since: 2018, labels: ["Virgin", "Polydor", "Defected"], sources: ["https://en.wikipedia.org/wiki/Meduza_(producers)"] }, // Meduza
  "melon-bomb": { slug: "melon-bomb", bio: { fr: "Melon Bomb est un collectif ibizenco formé de Corbi, Ben Santiago, Paul Reynolds et Scott Gray, qui a joué son premier set au Freddie's du Pikes en 2015 — l'hôtel reste sa base. Le groupe mélange house et disco et a sorti des disques sur Moxy Musik, Toy Tonics, Basement Discos et son propre label Melon Bomb Records. Il tient une résidence à l'UNVRS et a joué à Glastonbury, Tomorrowland et Defected Croatia.", en: "Melon Bomb is an Ibiza collective made up of Corbi, Ben Santiago, Paul Reynolds and Scott Gray, who played their first set together at Freddie's in Pikes in 2015 — the hotel is still their home base. They mix house and disco and have released on Moxy Musik, Toy Tonics, Basement Discos and their own Melon Bomb Records. They hold a residency at UNVRS and have played Glastonbury, Tomorrowland and Defected Croatia." }, origin: "Ibiza, Espagne", since: 2015, labels: ["Melon Bomb Records"], sources: ["https://www.pikesibiza.com/melon-bomb/", "https://www.ibiza-spotlight.com/magazine/2022/03/los-residentes-011-melon-bomb"] }, // Melon Bomb
  "melvo-baptiste": { slug: "melvo-baptiste", bio: { fr: "Melvo Baptiste est un DJ et directeur musical britannique, originaire de Watford. Neveu de Norman Jay, il a animé pendant sept ans une émission hebdomadaire sur Mi-Soul Radio avant de jouer à la première soirée londonienne de Glitterbox en 2016, puis d'en lancer l'émission de radio en 2017. Il dirige la programmation musicale de Glitterbox et a fondé le label The Remedy Project en 2021.", en: "Melvo Baptiste is a British DJ and music director from Watford. A nephew of Norman Jay, he hosted a weekly show on Mi-Soul Radio for seven years before playing Glitterbox's first London party in 2016, then launching its radio show in 2017. He runs Glitterbox's music programming and founded The Remedy Project label in 2021." }, origin: "Watford, Royaume-Uni", since: 2016, labels: ["The Remedy Project", "Glitterbox"], sources: ["https://djmag.com/features/home-melvo-baptiste-interview-glitterbox-remedy-project"] }, // Melvo Baptiste
  "mestiza": { slug: "mestiza", bio: { fr: "Mëstiza est un duo espagnol formé en 2021 par les DJ Belah Sánchez et Patricia « Pitty » Bernad, après une dizaine d'années de carrières solo en house et techno. Leur projet croise beats de club et instrumentation flamenca, jusque dans leur identité visuelle. Leur premier album, Quëreles, paraît en décembre 2023 sur leur label Sacro Music et atteint la première place des ventes de vinyles en Espagne.", en: "Mëstiza is a Spanish duo formed in 2021 by DJs Belah Sánchez and Patricia \"Pitty\" Bernad, after around a decade of solo careers in house and techno. Their project crosses club beats with flamenco instrumentation, down to their visual identity. Their debut album, Quëreles, came out in December 2023 on their own Sacro Music label and topped Spain's official vinyl sales chart." }, origin: "Espagne", since: 2021, labels: ["Sacro Music"], sources: ["https://en.wikipedia.org/wiki/M%C3%ABstiza_(DJs)", "https://www.hollywoodreporter.com/music/music-industry-news/mestiza-female-music-duo-spain-mixing-flamenco-electronic-1236678370/"] }, // MËSTIZA
  "metrik": { slug: "metrik", bio: { fr: "Tom Mundell, alias Metrik, est un producteur anglais de drum & bass originaire de Londres. Il adopte le pseudonyme en 2007 et sort ses premiers disques sur Intrinsic puis Viper Recordings, avant de signer chez Hospital Records, qui publie son premier album Universal Language en 2014. Ses albums Life/Thrills et Ex Machina ont atteint les 4e et 2e places du UK Dance Albums Chart.", en: "Tom Mundell, known as Metrik, is an English drum and bass producer from London. He took the alias in 2007 and released first on Intrinsic then Viper Recordings before signing to Hospital Records, which issued his debut album Universal Language in 2014. His albums Life/Thrills and Ex Machina reached numbers 4 and 2 on the UK Dance Albums Chart." }, origin: "Londres, Royaume-Uni", since: 2007, labels: ["Hospital Records", "Viper Recordings"], sources: ["https://en.wikipedia.org/wiki/Metrik", "https://www.allmusic.com/artist/metrik-mn0001448740"] }, // Metrik
  "michael-amani": { slug: "michael-amani", bio: { fr: "Michael Amani est un DJ, producteur et vidéaste belge. Son premier single, « Feels Like I Do », paraît en 2018 et fait de lui le premier artiste belge signé sur STMPD RCRDS, le label de Martin Garrix. Il s'est produit à Tomorrowland, Balaton Sound, Paaspop et Intents.", en: "Michael Amani is a Belgian DJ, producer and video maker. His debut single \"Feels Like I Do\" came out in 2018 and made him the first Belgian artist signed to STMPD RCRDS, Martin Garrix's label. He has played Tomorrowland, Balaton Sound, Paaspop and Intents." }, origin: "Belgique", since: 2018, labels: ["STMPD RCRDS"], sources: ["https://www.armadamusicpublishing.com/roster/michael-amani", "https://musicbrainz.org/artist/f2ca2713-b1b3-4279-addb-abbb66093586"] }, // Michael Amani
  "michel-de-hey": { slug: "michel-de-hey", bio: { fr: "Michel de Hey est un DJ et producteur néerlandais dont la carrière débute en 1986 dans un club de Rotterdam. Son disque « Break » (1992) entre dans le top 10 des charts dance américains, et sa soirée Future au Nighttown de Rotterdam, lancée en août 1995, tient sept ans et demi. Il a fondé plusieurs labels — EC, CC, Brave New World, Miracle Records, réunis sous Immaculate Music — et sort ses productions sur HEY! Records, EC Records, Noir Music, Bedrock et Rejected.", en: "Michel de Hey is a Dutch DJ and producer whose career began in 1986 in a small Rotterdam club. His 1992 record \"Break\" reached the top 10 of the US dance charts, and his Future club night at Rotterdam's Nighttown, launched in August 1995, ran for seven and a half years. He founded several labels — EC, CC, Brave New World and Miracle Records, grouped under Immaculate Music — and releases on HEY! Records, EC Records, Noir Music, Bedrock and Rejected." }, origin: "Rotterdam, Pays-Bas", since: 1986, labels: ["EC Records", "HEY! Records", "Immaculate Music"], sources: ["https://www.awakenings.com/en/artists/michel-de-hey/996/"] }, // Michel de Hey
  "mika-heggemann": { slug: "mika-heggemann", bio: { fr: "Mika Heggemann est un DJ et producteur allemand installé à Berlin, associé au courant qu'il appelle la nu trance : l'euphorie de la trance montée sur l'énergie de la techno et le rebond du hard house. Il a cofondé Polyamor Berlin et participe à l'organisation du Berlin Dance Music Event. Il a publié en 2025 sur Polyamor Records, Kontor Records et Teletech.", en: "Mika Heggemann is a German DJ and producer based in Berlin, associated with what he calls nu trance: trance euphoria set on techno energy and hard house bounce. He co-founded Polyamor Berlin and helps run the Berlin Dance Music Event. In 2025 he released on Polyamor Records, Kontor Records and Teletech." }, origin: "Berlin, Allemagne", labels: ["Polyamor Records", "Kontor Records", "Teletech"], sources: ["https://openbeatz.de/artist/mika-heggemann-2/"] }, // Mika Heggemann
  "mila-haj-kasem": { slug: "mila-haj-kasem", bio: { fr: "Mila Haj Kasem est une DJ palestino-néerlandaise installée à Amsterdam, qui joue une techno hypnotique et brute. Elle décrit sa musique comme une forme de résilience et de protestation, et travaille par ailleurs avec NightGuides, une équipe indépendante de veille bienveillante consacrée aux espaces queer en soirée.", en: "Mila Haj Kasem is a Palestinian-Dutch DJ based in Amsterdam who plays hypnotic, raw techno. She describes her music as a form of resilience and protest, and also works with NightGuides, a freelance queer awareness team building safer spaces in nightlife." }, origin: "Amsterdam, Pays-Bas", sources: ["https://ra.co/dj/milahajkasem/biography"] }, // Mila Haj Kasem
  "milion": { slug: "milion", bio: { fr: "Milion est un DJ et producteur néerlandais installé à Amsterdam. Il publie depuis 2021 sur Rawsome Deep, Hardline Sounds, 803 Crystal Grooves et Planet Strangelove, avec des disques classés house, tech house, UK garage et speed garage.", en: "Milion is a Dutch DJ and producer based in Amsterdam. He has released since 2021 on Rawsome Deep, Hardline Sounds, 803 Crystal Grooves and Planet Strangelove, with records filed under house, tech house, UK garage and speed garage." }, origin: "Amsterdam, Pays-Bas", since: 2021, labels: ["Hardline Sounds", "Planet Strangelove", "803 Crystal Grooves"], sources: ["https://www.discogs.com/artist/5733452-Milion"] }, // Milion
  "millad": { slug: "millad", bio: { fr: "Millad est un DJ et producteur français originaire de Paris, venu à la musique par le jazz, le funk et le hip-hop avant de découvrir la musique électronique dans les années 1990 lors de séjours en Angleterre. Ses productions et remixes — « Stay Focused », « Freedom », le remix de « All My People In The House » avec Shiba San — sont distribués sur les plateformes house.", en: "Millad is a French DJ and producer from Paris who came to music through jazz, funk and hip-hop before discovering electronic music in the 1990s on trips to England. His productions and remixes — \"Stay Focused\", \"Freedom\", the \"All My People In The House\" remix with Shiba San — are distributed on house platforms." }, origin: "Paris, France", sources: ["https://www.traxsource.com/artist/531774/millad"] }, // Millad
  "mind-against": { slug: "mind-against", bio: { fr: "Mind Against est un duo italien formé par les frères Alessandro et Federico Fognini, installé à Berlin. Leur musique croise IDM, house et techno, avec des mélodies héritées des bandes originales des années 1980 et un fort travail de sound design. Ils se font connaître en 2013 avec l'EP « Atlant » sur Life and Death, puis publient sur Afterlife — le label de Tale of Us — où sort en 2020 leur titre « Walking Away », ainsi que sur Hotflush et Cocoon.", en: "Mind Against is an Italian duo made up of brothers Alessandro and Federico Fognini, based in Berlin. Their music sits between IDM, house and techno, with melodies borrowed from 1980s soundtracks and a heavy emphasis on sound design. They broke through in 2013 with the EP \"Atlant\" on Life and Death, then released on Afterlife — Tale of Us's label, home to their 2020 track \"Walking Away\" — as well as Hotflush and Cocoon." }, origin: "Italie, installés à Berlin", since: 2013, labels: ["Afterlife", "Life and Death"], sources: ["https://www.awakenings.com/en/artists/mind-against/1010/"] }, // Mind Against
  "mind-compressor": { slug: "mind-compressor", bio: { fr: "Mind Compressor est le projet uptempo hardcore d'Andrea Bovio, DJ et producteur italien. Lancé fin 2016, il publie sur Offensive Rage, Partyraiser Recordings, Footworxx, Young Guns Records et Gearbox Overdrive. La totalité de sa discographie est référencée en hardcore.", en: "Mind Compressor is the uptempo hardcore project of Andrea Bovio, an Italian DJ and producer. Started at the end of 2016, it releases on Offensive Rage, Partyraiser Recordings, Footworxx, Young Guns Records and Gearbox Overdrive. His whole discography is catalogued as hardcore." }, origin: "Italie", since: 2016, labels: ["Offensive Rage", "Partyraiser Recordings"], sources: ["https://www.discogs.com/artist/5616454-Mind-Compressor", "https://partyflock.nl/artist/94816:Mind-Compressor"] }, // Mind Compressor
  "mira-mark": { slug: "mira-mark", bio: { fr: "Mira Mark a grandi près de Sandefjord avant de s'installer à Oslo à 18 ans et de commencer à mixer en 2012, d'abord en dubstep puis en drum & bass. Elle organise Ladies First, la première soirée bass norvégienne consacrée aux artistes femmes, et fait partie du collectif Norgbass. Elle produit aussi de la techno sous l'alias BECH depuis 2020.", en: "Mira Mark grew up near Sandefjord before moving to Oslo at 18 and starting to DJ in 2012, first with dubstep and then drum & bass. She runs Ladies First, Norway's first female-focused bass night, and is part of the Norgbass collective. She also produces techno under the alias BECH, started in 2020." }, origin: "Oslo, Norvège", since: 2012, sources: ["https://jaegeroslo.no/building-blocks-an-interview-with-mira-mark/"] }, // Mira Mark
  "miss-k8": { slug: "miss-k8", bio: { fr: "Kateryna Kremko, connue sous le nom de Miss K8, est une DJ et productrice ukrainienne née à Kiev. Elle joue du hardcore et du gabber, et signe dès 2012 sur le label néerlandais Masters of Hardcore, où paraît son premier single « Unforgettable ». Elle est depuis une habituée des grandes scènes hard dance européennes, de Masters of Hardcore à Defqon.1.", en: "Kateryna Kremko, better known as Miss K8, is a Ukrainian DJ and producer born in Kyiv. She plays hardcore and gabber, and signed in 2012 to the Dutch label Masters of Hardcore, which put out her first single \"Unforgettable\". She has been a regular on Europe's main hard dance stages ever since, from Masters of Hardcore to Defqon.1." }, origin: "Kiev, Ukraine", since: 2012, labels: ["Masters of Hardcore"], sources: ["https://en.wikipedia.org/wiki/Miss_K8"] }, // Miss K8
  "miss-monique": { slug: "miss-monique", bio: { fr: "Miss Monique, de son vrai nom Alesia Arkusha, est une DJ et productrice ukrainienne née en 1992 à Kirovohrad (aujourd'hui Kropyvnytskyï) et formée à Kiev. Elle joue de la progressive house et de la techno mélodique, et s'est fait connaître par ses émissions vidéo « Mind Games » et « MiMo Weekly ». Elle a fondé son label Siona Records en 2019 et sorti des titres sur Armada, Drumcode, Black Hole Recordings et Tomorrowland Music. Elle a été élue révélation de l'année aux DJ Awards en 2024.", en: "Miss Monique, real name Alesia Arkusha, is a Ukrainian DJ and producer born in 1992 in Kirovohrad (now Kropyvnytskyi) and raised as a DJ in Kyiv. She plays progressive house and melodic techno, and built her audience through the video shows \"Mind Games\" and \"MiMo Weekly\". She founded her label Siona Records in 2019 and has released on Armada, Drumcode, Black Hole Recordings and Tomorrowland Music. She won Breakthrough Artist at the DJ Awards in 2024." }, origin: "Kropyvnytskyï, Ukraine", since: 2013, labels: ["Siona Records"], sources: ["https://en.wikipedia.org/wiki/Miss_Monique"] }, // Miss Monique
  "missnoa": { slug: "missnoa", bio: { fr: "MissNoa mixe depuis 1997 et s'installe à Lille en 2002, après des débuts dans les bars et clubs de Reims. Ses influences de départ sont Dave Clarke, Technasia, DJ Rush et Laurent Garnier. Avec Devty, elle fonde l'association Lucky You et la soirée One More Lucky Night, tenue pendant près de cinq ans au Kiosk Club, où elle est résidente jusqu'en 2013. Ses sets vont aujourd'hui vers une techno deep et minimale.", en: "MissNoa has been mixing since 1997 and settled in Lille in 2002, after starting out in the bars and clubs of Reims. Her early influences were Dave Clarke, Technasia, DJ Rush and Laurent Garnier. With Devty she founded the Lucky You association and the One More Lucky Night party, held for nearly five years at the Kiosk Club, where she was a resident until 2013. Her sets now lean deep and minimal." }, origin: "Lille, France", since: 1997, sources: ["https://fr.ra.co/dj/missnoa/biography", "https://www.lillelanuit.com/le-mag/interviews/missnoa/"] }, // Missnoa
  "miyagi": { slug: "miyagi", bio: { fr: "Miyagi est le nom de scène de Robert Wagenknecht, DJ et producteur allemand installé à Hambourg depuis 2009, où il a commencé à mixer avant de produire. Sa musique mêle deep house, tech house et techno mélodique. Il publie sur Katermukke, Einmusika et SOSO, dirige les labels Rennbahn Records et Lost Diaries, et sort en 2014 un premier album, « Forever ».", en: "Miyagi is the stage name of Robert Wagenknecht, a German DJ and producer who moved to Hamburg in 2009, where he started DJing before turning to production. His sound blends deep house, tech house and melodic techno. He releases on Katermukke, Einmusika and SOSO, runs the labels Rennbahn Records and Lost Diaries, and put out a first album, \"Forever\", in 2014." }, origin: "Hambourg, Allemagne", since: 2009, labels: ["Katermukke", "Einmusika", "Rennbahn Records", "Lost Diaries"], sources: ["https://partyflock.nl/artist/93351/biography", "https://www.deephouseamsterdam.com/london/interview-with-miyagi/"] }, // Miyagi
  "mk": { slug: "mk", bio: { fr: "MK est le nom de scène de Marc Kinchen, DJ, producteur et remixeur américain né en 1972 à Détroit. Il atteint la première place du classement dance américain en 1993 et 1994 avec « Always » et « Love Changes », chantés par Alana Simon, et signe avec elle le classique house « Burning ». En 2013, son remix de « Look Right Through » de Storm Queen, sorti sur Defected, se hisse en tête des singles britanniques.", en: "MK is the stage name of Marc Kinchen, an American DJ, producer and remixer born in 1972 in Detroit. He topped the US dance chart in 1993 and 1994 with \"Always\" and \"Love Changes\", both sung by Alana Simon, and made the house classic \"Burning\" with her. In 2013 his remix of Storm Queen's \"Look Right Through\", released on Defected, went to No. 1 on the UK Singles Chart." }, origin: "Détroit, États-Unis", since: 1989, labels: ["AREA10", "Defected"], sources: ["https://en.wikipedia.org/wiki/MK_(record_producer)"] }, // MK
  "modeselektor": { slug: "modeselektor", bio: { fr: "Modeselektor est un duo électronique allemand formé par Gernot Bronsert et Sebastian Szary, qui se sont rencontrés à Berlin en 1992 dans les fêtes clandestines de l'après-Mur. Leur nom vient d'une fonction de l'écho à bande Roland Space Echo. Signés chez BPitch Control à partir de 2000, ils publient Hello Mom! (2005) et Happy Birthday! (2007), où chante Thom Yorke, puis fondent leur label Monkeytown Records. Avec Apparat, ils forment le groupe Moderat.", en: "Modeselektor is a German electronic duo made up of Gernot Bronsert and Sebastian Szary, who met in Berlin in 1992 at the illegal parties that followed the fall of the Wall. Their name comes from a function on the Roland Space Echo tape unit. Signed to BPitch Control from 2000, they released Hello Mom! (2005) and Happy Birthday! (2007), which features Thom Yorke, then founded their label Monkeytown Records. With Apparat they form the group Moderat." }, origin: "Berlin, Allemagne", since: 2000, labels: ["Monkeytown Records", "BPitch Control"], sources: ["https://en.wikipedia.org/wiki/Modeselektor"] }, // Modeselektor
  "monika-seta": { slug: "monika-seta", bio: { fr: "Monika Seta est une DJ et productrice lituanienne originaire de Vilnius, résidente de l'Opium Club de Vilnius et du Lizdas de Kaunas. Son répertoire va de la deep house à la techno. Elle a joué plusieurs éditions du festival Audra, à Kaunas, et anime l'émission Kauno Fonas sur Refuge Worldwide.", en: "Monika Seta is a Lithuanian DJ and producer from Vilnius, resident at Opium Club in Vilnius and Lizdas in Kaunas. Her range runs from deep house to techno. She has played several editions of the Audra festival in Kaunas and hosts the Kauno Fonas show on Refuge Worldwide." }, origin: "Vilnius, Lituanie", sources: ["https://www.viberate.com/artist/monika-seta/", "https://refugeworldwide.com/radio/kauno-fonas-monika-seta-24-mar-2023"] }, // Monika Seta
  "monolink": { slug: "monolink", bio: { fr: "Monolink est le nom de scène de Steffen Linck, auteur-compositeur et producteur allemand né en 1989. Il chante et joue de la guitare sur ses propres productions, entre ambient, house et techno, et publie sur Embassy One.", en: "Monolink is the stage name of Steffen Linck, a German singer-songwriter and electronic dance music producer born in 1989. He sings and plays guitar over his own productions, between ambient, house and techno, and releases on Embassy One." }, origin: "Allemagne", labels: ["Embassy One"], sources: ["https://en.wikipedia.org/wiki/Monolink", "https://api.discogs.com/database/search?artist=Monolink&type=release"] }, // Monolink
  "moodfino": { slug: "moodfino", bio: { fr: "DJ mexicain installé sur la scène grenobloise depuis 2022, Moodfino a joué au Mexique, au Canada et en France. Il est résident de la radio RTL3. Ses sets refusent l'étiquette et passent de la house à la trance, de l'italo à la techno.", en: "A Mexican DJ who has been part of the Grenoble scene since 2022, Moodfino has played in Mexico, Canada and France. He is a resident on RTL3 radio. His sets refuse a label and move from house to trance, italo to techno." }, origin: "Grenoble, France", since: 2022, sources: ["https://www.la-belle-electrique.com/en/events/sicario-soundsystem-2025"] }, // Moodfino
  "moodymann": { slug: "moodymann", bio: { fr: "Moodymann est le nom de scène de Kenny Dixon Jr., musicien américain établi à Détroit. Sa house et sa techno sont bâties sur des boucles de disques soul, funk et disco chinés puis rejouées. Il lance son label KDJ Records en 1994 avec l'EP Moody Trax, publie son premier album Silentintroduction en 1997 sur Planet E Communications, et dirige aussi Mahogani Music. Il fait partie du trio 3 Chairs.", en: "Moodymann is the stage name of Kenny Dixon Jr., an American musician based in Detroit. His house and techno are built on loops lifted from soul, funk and disco records and reworked. He started his label KDJ Records in 1994 with the EP Moody Trax, released his debut album Silentintroduction in 1997 on Planet E Communications, and also runs Mahogani Music. He is a member of the trio 3 Chairs." }, origin: "Détroit, États-Unis", since: 1994, labels: ["KDJ Records", "Mahogani Music"], sources: ["https://en.wikipedia.org/wiki/Moodymann"] }, // Moodymann
  "mosimann": { slug: "mosimann", bio: { fr: "Mosimann, de son vrai nom Quentin Mosimann, est un DJ, producteur et chanteur franco-suisse né le 14 février 1988 à Genève. Il joue une électro grand public entre house et EDM, se produit sur les grands festivals dont Tomorrowland, et a rempli deux fois le Zénith de Paris.", en: "Mosimann, real name Quentin Mosimann, is a Franco-Swiss DJ, producer and singer born on 14 February 1988 in Geneva. He plays mainstream electronic music between house and EDM, performs at major festivals including Tomorrowland, and has sold out two shows at the Zénith de Paris." }, origin: "Genève, Suisse", sources: ["https://www.discogs.com/artist/1117982-Quentin-Mosimann", "https://musicbrainz.org/ws/2/artist/?query=Mosimann&fmt=json"] }, // Mosimann
  "mr-scruff": { slug: "mr-scruff", bio: { fr: "Andrew Carthy, alias Mr. Scruff, est un DJ et producteur anglais né en 1972 à Macclesfield et installé dans la région de Manchester. Il mixe depuis 1994 et signe chez Ninja Tune en 1998, label sur lequel paraissent Keep It Unreal et Trouser Jazz. Il est connu pour ses sets marathon dépassant souvent six heures et pour ses dessins et animations projetés pendant ses concerts.", en: "Andrew Carthy, known as Mr. Scruff, is an English DJ and producer born in 1972 in Macclesfield and based near Manchester. He has been DJing since 1994 and signed to Ninja Tune in 1998, releasing Keep It Unreal and Trouser Jazz there. He is known for marathon sets often running past six hours and for the hand-drawn animations projected during his shows." }, origin: "Macclesfield, Royaume-Uni", since: 1994, labels: ["Ninja Tune"], sources: ["https://en.wikipedia.org/wiki/Mr._Scruff", "https://ninjatune.net/artist/mr-scruff"] }, // Mr Scruff
  "mrak": { slug: "mrak", bio: { fr: "MRAK est le projet solo de Carmine Conte, membre du duo Tale Of Us et cofondateur du label Afterlife. Il l'a lancé en novembre 2021 avec l'EP One, publié sur Afterlife, dont les trois titres — « Never Ends », « Vacio » et « One » — jouent sur la chaleur et la profondeur.", en: "MRAK is the solo project of Carmine Conte, a member of the duo Tale Of Us and co-founder of the Afterlife label. He launched it in November 2021 with the One EP on Afterlife, whose three tracks — \"Never Ends\", \"Vacio\" and \"One\" — trade on warmth and depth." }, origin: "Italie", since: 2021, labels: ["Afterlife"], sources: ["https://electronicgroove.com/tale-of-us-carmine-conte-debuts-solo-project-mrak/"] }, // MRAK
  "multiplex": { slug: "multiplex", bio: { fr: "Mr. Multiplex est un MC néerlandais installé à Utrecht, actif dans la drum & bass et la jungle depuis 2004. Il vient du chant punk et rock, ce qui marque son débit. Il est résident de Blackout (le label de Black Sun Empire), de Korsakov, de Cheeky Monday et de Kaputt! aux Pays-Bas, et a joué à Lowlands et au Dominator Festival.", en: "Mr. Multiplex is a Dutch MC based in Utrecht, active in drum & bass and jungle since 2004. He came from punk and rock singing, which marks his delivery. He is a resident for Blackout (the Black Sun Empire label), Korsakov, Cheeky Monday and Kaputt! in the Netherlands, and has played Lowlands and Dominator Festival." }, origin: "Utrecht, Pays-Bas", since: 2004, labels: ["Blackout", "Korsakov Music"], sources: ["https://eatbrain.net/multiplex-mc"] }, // Multiplex
  "muzz": { slug: "muzz", bio: { fr: "Muzz, anciennement Muzzy, est le nom de scène de Mustafa Ahmed Alobaidi, producteur et DJ de drum and bass anglais né le 10 novembre 1994. Il se fait remarquer en 2010 avec « X No Way Out » sur UKF, et publie surtout sur Monstercat, ainsi que sur UKF Music et Liquicity.", en: "Muzz, formerly Muzzy, is the stage name of Mustafa Ahmed Alobaidi, an English drum and bass producer and DJ born on 10 November 1994. He drew attention in 2010 with \"X No Way Out\" on UKF, and releases mainly on Monstercat, as well as UKF Music and Liquicity." }, origin: "Basingstoke, Royaume-Uni", since: 2010, labels: ["Monstercat"], sources: ["https://en.wikipedia.org/wiki/Muzz_(musician)"] }, // Muzz
  "n-vitral": { slug: "n-vitral", bio: { fr: "N-Vitral est un DJ et producteur néerlandais de hardcore. Son album Louder than a Bomb (2016) marque sa percée et lui vaut d'être associé au « maindustrial », un hardcore industriel aux formes plus grand public. Il quitte The Third Movement en 2020 pour rejoindre Masters of Hardcore, dont il a signé l'hymne 2019 « Vault of Violence » avec Sovereign King.", en: "N-Vitral is a Dutch hardcore DJ and producer. His 2016 album Louder than a Bomb marked his breakthrough and led to him being associated with 'maindustrial', a more mainstream form of industrial hardcore. He left The Third Movement in 2020 for Masters of Hardcore, whose 2019 anthem 'Vault of Violence' he produced with Sovereign King." }, origin: "Pays-Bas", labels: ["Masters of Hardcore", "The Third Movement"], sources: ["https://edm.fandom.com/wiki/N-Vitral"] }, // N-Vitral
  "naft": { slug: "naft", bio: { fr: "NAFT est un groupe belge de tech house instrumentale : quatre cuivres et deux batteurs qui rejouent la techno et la house sans machines, cuivres passés aux pédales d'effets et batteries mêlant acoustique et électronique. Le groupe se produit notamment à l'Effenaar d'Eindhoven.", en: "NAFT is a Belgian instrumental tech house band: four brass players and two drummers who rebuild techno and house without machines, brass run through effects pedals and drums mixing acoustic and electronic kits. The band plays venues including Eindhoven's Effenaar." }, origin: "Belgique", sources: ["https://www.effenaar.nl/agenda/naft", "https://vi.be/platform/nafttheband"] }, // NAFT
  "nastia": { slug: "nastia", bio: { fr: "Nastia est le nom de scène d'Anastasia Topolska, DJ ukrainienne née en 1987 dans la région de Louhansk et installée à Amsterdam. Elle débute en 2005, devient résidente du festival Kazantip puis du club Arma17 à Moscou en 2010, cofonde le festival Strichka à Kyiv en 2014, et lance les labels Propaganda Records puis, en 2019, NECHTO.", en: "Nastia is the stage name of Anastasia Topolska, a Ukrainian DJ born in 1987 in the Luhansk region and based in Amsterdam. She started in 2005, became a resident of the Kazantip festival and then of Moscow's Arma17 in 2010, co-founded the Strichka festival in Kyiv in 2014, and launched the labels Propaganda Records and, in 2019, NECHTO." }, origin: "Ukraine", since: 2005, labels: ["Propaganda Records", "NECHTO"], sources: ["https://www.raw-people.com/artists/nastia"] }, // Nastia
  "nathan-fake": { slug: "nathan-fake", bio: { fr: "Nathan Fake, né le 1er mars 1983 dans le Norfolk, est un musicien électronique britannique remarqué dès 2004 avec « The Sky Was Pink », publié sur le label Border Community de James Holden, dont le remix par Holden a beaucoup circulé. Il a signé sept albums répartis entre Border Community, Ninja Tune, InFiné et son propre label Cambria Instruments, cofondé en 2014. Il a remixé Radiohead, Jon Hopkins et Sasha.", en: "Nathan Fake, born 1 March 1983 in Norfolk, is a British electronic musician who first drew attention in 2004 with \"The Sky Was Pink\", released on James Holden's Border Community label; Holden's remix of it circulated widely. He has released seven albums across Border Community, Ninja Tune, InFiné and his own Cambria Instruments, which he co-founded in 2014. He has remixed Radiohead, Jon Hopkins and Sasha." }, origin: "Necton, Norfolk, Royaume-Uni", since: 2003, labels: ["Border Community", "Ninja Tune", "Cambria Instruments", "InFiné"], sources: ["https://en.wikipedia.org/wiki/Nathan_Fake"] }, // Nathan Fake
  "natte-visstick": { slug: "natte-visstick", bio: { fr: "Natte Visstick est un DJ et producteur néerlandais qui sort de la musique depuis 2021 sous le genre memetechno, un mélange de hard techno et de drum'n'bass à l'esprit punk et aux textes humoristiques. Il a percé en 2022 avec « Visstick gooi die kanker kick », quinzième du Single Top 100. Il publie anonymement et fait partie du Pestcore Collectief.", en: "Natte Visstick is a Dutch DJ and producer releasing since 2021 in the memetechno genre, a mix of hard techno and drum and bass with a punk spirit and humorous lyrics. He broke through in 2022 with 'Visstick gooi die kanker kick', which reached number fifteen in the Single Top 100. He releases anonymously and is part of the Pestcore Collectief." }, origin: "Pays-Bas", since: 2021, sources: ["https://nl.wikipedia.org/wiki/Natte_Visstick"] }, // Natte Visstick
  "nd-baumecker": { slug: "nd-baumecker", bio: { fr: "Andy Baumecker, alias nd_baumecker, commence à Francfort au début des années 1990 : repéré par Heiko et Ata du label Playhouse, il travaille dans leur disquaire Delerium et obtient une résidence au WildPitchClub. Il dirige ensuite le label Freu_nd puis Freundinnen. Installé à Berlin en 2004, il devient résident du Berghain et forme avec Sam Barker le duo Barker & Baumecker, dont les disques paraissent sur Ostgut Ton depuis 2010.", en: "Andy Baumecker, aka nd_baumecker, started out in Frankfurt in the early 1990s: spotted by Heiko and Ata of the Playhouse label, he worked in their Delerium record shop and held a residency at WildPitchClub. He went on to run the Freu_nd and then Freundinnen labels. He moved to Berlin in 2004, became a Berghain resident and formed the duo Barker & Baumecker with Sam Barker, whose records have appeared on Ostgut Ton since 2010." }, origin: "Berlin, Allemagne", labels: ["Freundinnen", "Ostgut Ton"], sources: ["https://www.discogs.com/artist/754433-Andy-Baumecker", "https://api.discogs.com/artists/754433"] }, // nd_baumecker
  "ned-bennett": { slug: "ned-bennett", bio: { fr: "Ned Bennett est un producteur de techno actif depuis 2024. Il a sorti les EP « Percussive Orbit » et « Carnival Revival » ainsi que la série « Groove Alliance » sur le label barcelonais Suara, et « On The Block » et « Class Of '24 » sur Green Roll Records.", en: "Ned Bennett is a techno producer active since 2024. He released the EPs \"Percussive Orbit\" and \"Carnival Revival\" plus the \"Groove Alliance\" series on Barcelona label Suara, and \"On The Block\" and \"Class Of '24\" on Green Roll Records." }, since: 2024, labels: ["Suara", "Green Roll Records"], sources: ["https://www.discogs.com/artist/14510764-Ned-Bennett-3"] }, // Ned Bennett
  "neelix": { slug: "neelix", bio: { fr: "Neelix est le projet de Henrik Twardzik, DJ et producteur allemand établi à Hambourg. Il produit de la psytrance progressive et de la trance progressive, un registre qui l'a mené des soirées goa allemandes aux grandes scènes de festivals en plein air. Son catalogue est référencé sous les étiquettes psytrance, progressive psytrance et progressive trance.", en: "Neelix is the project of Henrik Twardzik, a German DJ and producer based in Hamburg. He makes progressive psytrance and progressive trance, a register that took him from German goa parties to large open-air festival stages. His catalogue is filed under psytrance, progressive psytrance and progressive trance." }, origin: "Hambourg, Allemagne", sources: ["https://musicbrainz.org/artist/86acb593-2bd8-41cb-8edc-fc8ba3620b15"] }, // Neelix
  "negitiv": { slug: "negitiv", bio: { fr: "NEGITIV est le nom de scène de Negir Paknia, DJ et productrice germano-iranienne installée à Cologne. Autodidacte, elle passe de la techno industrielle à un mélange de hard techno, de schranz et de groove. Elle tient une résidence au Kiesgrube et a joué à Tomorrowland, Blackworks et Verknipt.", en: "NEGITIV is the stage name of Negir Paknia, a Persian-German DJ and producer based in Cologne. Self-taught, she moved from industrial techno to a mix of hard techno, schranz and groove. She holds a residency at Kiesgrube and has played Tomorrowland, Blackworks and Verknipt." }, origin: "Cologne, Allemagne", sources: ["https://negitiv.com/", "https://yap-agency.com/roster/negitiv/"] }, // NEGITIV
  "netsky": { slug: "netsky", bio: { fr: "Netsky est le nom de scène de Boris Daenen, né le 22 mars 1989, producteur belge de drum and bass originaire d'Anvers — son alias reprend le nom d'un virus informatique. Il signe fin 2009 chez Hospital Records, label du liquid funk, et sort son premier album Netsky en 2010, suivi de 2 (2012), 3 (2016) et Second Nature (2020). En 2015, il est le premier DJ producteur à recevoir le prix flamand de la Culture pour la musique.", en: "Netsky is the stage name of Boris Daenen, born 22 March 1989, a Belgian drum and bass producer from Antwerp — his alias is taken from a computer virus. He signed to liquid funk label Hospital Records in late 2009 and released his debut album Netsky in 2010, followed by 2 (2012), 3 (2016) and Second Nature (2020). In 2015 he became the first DJ and producer to receive the Flemish Culture Prize for music." }, origin: "Anvers, Belgique", since: 2009, labels: ["Hospital Records"], sources: ["https://en.wikipedia.org/wiki/Netsky_(musician)"] }, // Netsky
  "nghtmre": { slug: "nghtmre", bio: { fr: "NGHTMRE est le nom de scène de Tyler Marenyi, DJ et producteur américain né en 1990 dans le Connecticut et élevé à Raleigh, en Caroline du Nord. Diplômé en finance, il part à Los Angeles suivre les cours de l'Icon Collective, où il rencontre le duo Slander, avec qui il sort son premier EP, « Nuclear Bonds ». Sa musique croise trap, dubstep, future bass et house, publiée sur Mad Decent, Monstercat, OWSLA et Circus Records.", en: "NGHTMRE is the stage name of Tyler Marenyi, an American DJ and producer born in 1990 in Connecticut and raised in Raleigh, North Carolina. After a finance degree he moved to Los Angeles for the Icon Collective school, where he met the duo Slander, with whom he released his first EP, \"Nuclear Bonds\". His music crosses trap, dubstep, future bass and house, released on Mad Decent, Monstercat, OWSLA and Circus Records." }, origin: "Raleigh, États-Unis", since: 2014, labels: ["Mad Decent", "Monstercat", "OWSLA", "Circus Records"], sources: ["https://en.wikipedia.org/wiki/Nghtmre"] }, // NGHTMRE
  "nhu": { slug: "nhu", bio: { fr: "NHŪ est une DJ née à Hanoï, au Viêt Nam, et installée à Lausanne, en Suisse. Elle joue de la techno et de la hard techno, et est représentée par l'agence NOSS. Elle a partagé l'affiche du D! Club de Lausanne avec Trym et ROW1.", en: "NHŪ is a DJ born in Hanoi, Vietnam and based in Lausanne, Switzerland. She plays techno and hard techno, and is represented by the NOSS agency. She has shared a D! Club Lausanne bill with Trym and ROW1." }, origin: "Lausanne, Suisse", sources: ["https://nhumusic.com/", "https://fr.ra.co/dj/nhu"] }, // Nhū
  "nia-archives": { slug: "nia-archives", bio: { fr: "Nia Archives est le nom de scène de Dehaney Nia Lishahn Hunt, productrice, DJ et chanteuse anglaise née en septembre 1999 à Bradford. Après les EP autoproduits Headz Gone West (2021) et Forbidden Feelingz (2022), Sunrise Bang Ur Head Against the Wall (2023) a pris la tête du UK Dance Albums Chart. Son premier album, Silence Is Loud (2024, Island), est monté à la 16e place du classement britannique. Elle joue de la jungle et de la drum & bass.", en: "Nia Archives is the stage name of Dehaney Nia Lishahn Hunt, an English producer, DJ and singer born in September 1999 in Bradford. After the self-released EPs Headz Gone West (2021) and Forbidden Feelingz (2022), Sunrise Bang Ur Head Against the Wall (2023) topped the UK Dance Albums Chart. Her debut album Silence Is Loud (2024, Island) peaked at No. 16 on the UK Albums Chart. She plays jungle and drum & bass." }, origin: "Bradford, Royaume-Uni", since: 2021, labels: ["Island Records", "Hijinxx"], sources: ["https://en.wikipedia.org/wiki/Nia_Archives", "https://api.discogs.com/database/search?artist=Nia+Archives&type=release"] }, // Nia Archives
  "nic-fanciulli": { slug: "nic-fanciulli", bio: { fr: "Nic Fanciulli, de son vrai nom Nicholas Anthony Fanciulli, est un DJ et producteur anglais originaire de Maidstone, dans le Kent. Actif depuis 2003, il a fondé le label Saved Records et joue une house et une tech house de club. Son frère Mark Fanciulli est également DJ.", en: "Nic Fanciulli, real name Nicholas Anthony Fanciulli, is an English DJ and producer from Maidstone, Kent. Active since 2003, he founded the Saved Records label and plays club-focused house and tech house. His brother Mark Fanciulli is also a DJ." }, origin: "Maidstone, Kent, Royaume-Uni", since: 2003, labels: ["Saved Records"], sources: ["https://en.wikipedia.org/wiki/Nic_Fanciulli", "https://www.discogs.com/artist/125548-Nic-Fanciulli"] }, // Nic Fanciulli
  "nick-d-lite": { slug: "nick-d-lite", bio: { fr: "DJ et producteur de Halle et Leipzig, Nick D-Lite s'est fait connaître dans la scène house et bass allemande par ses mixtapes et ses sorties sur Stil vor Talent, King Street Records, Indiana Tones et Klang Gymnastik. Il anime les formats « 30 Minutes of Groove » et « Final Mixtape », et a joué au Sputnik Spring Break, à SonneMondSterne et au Liquid Sunday Festival.", en: "A DJ and producer from Halle and Leipzig, Nick D-Lite made his name in the German house and bass scene through his mixtapes and releases on Stil vor Talent, King Street Records, Indiana Tones and Klang Gymnastik. He runs the \"30 Minutes of Groove\" and \"Final Mixtape\" formats, and has played Sputnik Spring Break, SonneMondSterne and Liquid Sunday Festival." }, origin: "Halle / Leipzig, Allemagne", labels: ["Stil vor Talent", "King Street Records", "Indiana Tones", "Klang Gymnastik"], sources: ["https://www.skyclub-leipzig.de/artist/detail/90-nick-d-lite-dusted-decks-de"] }, // Nick D-lite
  "nickodemus": { slug: "nickodemus", bio: { fr: "DJ et producteur installé à Brooklyn, Nickodemus lance en 1998 avec son partenaire Mariano la série de soirées Turntables on the Hudson, puis en 2004 le label Wonderwheel Recordings, dont la première compilation « Coney Island Love » mêle production électronique et musiques d'Europe de l'Est, d'Afrique du Nord et de Sicile. Il a publié cinq albums.", en: "Brooklyn-based DJ and producer Nickodemus launched the Turntables on the Hudson party series with his partner Mariano in 1998, then the Wonderwheel Recordings label in 2004, whose first compilation \"Coney Island Love\" mixed electronic production with music from Eastern Europe, North Africa and Sicily. He has released five albums." }, origin: "Brooklyn, New York, États-Unis", since: 1998, labels: ["Wonderwheel Recordings"], sources: ["https://wonderwheelrecordings.com/artist/nickodemus/", "https://clocktower.org/show/nickodemus-of-wonderwheel-recordings"] }, // Nickodemus
  "nico-moreno": { slug: "nico-moreno", bio: { fr: "Nico Moreno, de son vrai nom Nicolas Bloche, est un DJ et producteur français né le 20 août 1994 à Caen. Il produit une techno industrielle rapide nourrie de gabber, de hardcore et d'acid, et publie ses premiers titres à partir de 2017. En 2019, il quitte le label BlvckPlvgue pour fonder Insolent Rave Records, où sort son morceau de rupture « Purple Widow ». Il a joué la mainstage de Tomorrowland en 2025 et figure au 67e rang du Top 100 DJs de DJ Mag la même année.", en: "Nico Moreno, born Nicolas Bloche on 20 August 1994 in Caen, is a French DJ and producer. He makes fast industrial techno fed by gabber, hardcore and acid, and released his first tracks from 2017 onwards. In 2019 he left the BlvckPlvgue label to found Insolent Rave Records, home to his breakout track \"Purple Widow\". He played the Tomorrowland main stage in 2025 and entered DJ Mag's Top 100 DJs at number 67 the same year." }, origin: "Caen, France", since: 2017, labels: ["Insolent Rave Records"], sources: ["https://fr.wikipedia.org/wiki/Nico_Moreno", "https://djmag.com/top100djs/2025/67/nico-moreno"] }, // Nico Moreno
  "nicole-moudaber": { slug: "nicole-moudaber", bio: { fr: "Nicole Moudaber est une DJ et productrice libano-britannique. Elle dirige le label MOOD Records et anime l'émission hebdomadaire In The MOOD. Elle a aussi été organisatrice de soirées avant de se consacrer à la production.", en: "Nicole Moudaber is a Lebanese-British DJ and producer. She runs the MOOD Records label and hosts the weekly radio show In The MOOD. She worked as an event promoter before turning to production." }, origin: "Liban / Royaume-Uni", labels: ["MOOD Records"], sources: ["https://en.wikipedia.org/wiki/Nicole_Moudaber"] }, // Nicole Moudaber
  "nikolina": { slug: "nikolina", bio: { fr: "Nikolina, de son prénom Ronja, est une DJ allemande basée à Berlin. Elle fréquente les raves berlinoises dès quatorze ans et tourne professionnellement depuis 2021. Elle appelle « Schroove » son mélange de schranz et de groove, une hard techno pensée pour le corps avant la tête. On la retrouve sur les affiches du circuit hard techno européen, du Bootshaus de Cologne au festival Verknipt.", en: "Nikolina, first name Ronja, is a German DJ based in Berlin. She started going to Berlin raves at fourteen and has been touring professionally since 2021. She calls her blend of schranz and groove \"Schroove\" — hard techno built to hit the body before the mind. She is a regular on the European hard techno circuit, from Cologne's Bootshaus to the Verknipt festival." }, origin: "Berlin, Allemagne", since: 2021, sources: ["https://www.nastymagazine.com/music/schroove-rising-nikolina/", "https://bootshaus.tv/events/unreal-weekender-night-i-september-2026/"] }, // Nikolina
  "nina-kraviz": { slug: "nina-kraviz", bio: { fr: "Née et élevée à Irkoutsk, en Sibérie, Nina Kraviz part étudier la dentisterie à Moscou, anime une émission de radio et tient une résidence au club Propaganda avant de vivre de la musique. Son premier album éponyme paraît en 2012 sur Rekids, elle fonde son label трип (Trip) en 2014 et mixe le quarante-huitième volume de la série DJ-Kicks en 2015. Elle a également composé pour le jeu Cyberpunk 2077, où elle apparaît en caméo.", en: "Born and raised in Irkutsk, Siberia, Nina Kraviz studied dentistry in Moscow, hosted a radio show and held a residency at the Propaganda club before making a living from music. Her self-titled debut album came out on Rekids in 2012, she founded her трип (Trip) label in 2014 and mixed the forty-eighth DJ-Kicks volume in 2015. She also wrote music for the game Cyberpunk 2077, in which she makes a cameo appearance." }, origin: "Irkoutsk, Russie", since: 2012, labels: ["трип (Trip)", "Rekids"], sources: ["https://en.wikipedia.org/wiki/Nina_Kraviz"] }, // Nina Kraviz
  "noiseflow": { slug: "noiseflow", bio: { fr: "Noiseflow est le duo allemand formé par Jonas et Morten. En juillet 2023, ils nomment et lancent le Deutscher Krach, un courant uptempo allemand qui empile des kicks à plus de 200 BPM sous des mélodies proches du hardstyle et des refrains en allemand. Ils en ont bâti l'écosystème : l'agence Krach, le concept de soirées Deutscher Krach XXL et la playlist officielle.", en: "Noiseflow are the German duo of Jonas and Morten. In July 2023 they named and launched Deutscher Krach, a German uptempo strain stacking 200+ BPM kicks under hardstyle-leaning melodies and German-language hooks. They built its ecosystem: the Krach agency, the Deutscher Krach XXL event concept and the official playlist." }, origin: "Allemagne", since: 2023, sources: ["https://www.hdrr.info/new-deutscher-krach-releases"] }, // Noiseflow
  "noize-suppressor": { slug: "noize-suppressor", bio: { fr: "Noize Suppressor est un projet hardcore italien formé en 1996 par Alessandro Dilillo (DJ Bike) et Stefano Soprani (DJ Dek), après l'envoi d'une démo à D-Boy Records. Le duo publie sur Traxtorm Records et crée en 2005 son propre label, Noize Records. Depuis 2009, DJ Bike joue en live avec le « Sonar », un jeu de capteurs infrarouges qui déclenche sons et samples au passage de la main.", en: "Noize Suppressor is an Italian hardcore project formed in 1996 by Alessandro Dilillo (DJ Bike) and Stefano Soprani (DJ Dek) after sending a demo to D-Boy Records. The duo released on Traxtorm Records and set up its own label, Noize Records, in 2005. Since 2009 DJ Bike has performed live with the \"Sonar\", a set of infrared sensors that triggers sounds and samples as a hand passes over them." }, origin: "Italie", since: 1996, labels: ["Traxtorm Records", "Noize Records"], sources: ["https://edm.fandom.com/wiki/Noize_Suppressor", "https://www.discogs.com/artist/20650-Noize-Suppressor"] }, // Noize Suppressor
  "noless": { slug: "noless", bio: { fr: "Maxence, alias NOLESS, est un DJ originaire d'Angers dont les sets sont orientés house et musiques électroniques. Il découvre le mix en 2019 et s'y consacre depuis. Il joue régulièrement au Warehouse de Nantes.", en: "Maxence, who records as NOLESS, is a DJ from Angers whose sets lean towards house and electronic music. He discovered mixing in 2019 and has focused on it since. He plays regularly at the Warehouse in Nantes." }, origin: "Angers, France", since: 2019, sources: ["https://www.warehouse-nantes.fr/artist/noless/"] }, // Noless
  "nordiks": { slug: "nordiks", bio: { fr: "Nordiks est un DJ norvégo-marocain installé à Oslo, où il anime depuis des années le podcast et le label OsloGround. Ses mixes pour le Jaeger penchent vers une house profonde, construite aux boîtes à rythmes et aux basses Roland. Il joue régulièrement au Maroc, où il travaille au déploiement des systèmes de diffusion VOID et suit de près une scène électronique qu'il a vue naître au début des années 2000.", en: "Nordiks is a Norwegian-Moroccan DJ based in Oslo, where he has long run the OsloGround podcast and label. His mixes for Jaeger lean towards a deeper house built on Roland drum machines and bass synths. He plays regularly in Morocco, where he works on rolling out VOID sound systems and follows a scene he watched emerge in the early 2000s." }, origin: "Oslo, Norvège", labels: ["OsloGround"], sources: ["https://jaegeroslo.no/mixes/jm120-nordiks/"] }, // Nordiks
  "novah": { slug: "novah", bio: { fr: "Novah, de son vrai nom Noa Heyse, est une DJ et productrice belge originaire d'Anvers. Ses productions relèvent du hard techno et intègrent des éléments d'acid, de techno industrielle et de psytrance. Elle publie son premier titre, « A Savage », en 2023 sur le label Taapion de Shlømo, puis sort sur Revised Records, Teletech, Tomorrowland Music et la compilation anniversaire d'Exhale Records.", en: "Novah, real name Noa Heyse, is a Belgian DJ and producer from Antwerp. Her productions sit in hard techno and take in acid, industrial techno and psytrance. She released her first track, \"A Savage\", in 2023 on Shlømo's Taapion label, then appeared on Revised Records, Teletech, Tomorrowland Music and the anniversary compilation of Amelie Lens's Exhale Records." }, origin: "Anvers, Belgique", since: 2022, labels: ["Taapion", "Revised Records", "Tomorrowland Music"], sources: ["https://fr.wikipedia.org/wiki/Novah"] }, // Novah
  "nox": { slug: "nox", bio: { fr: "Luís Baptista, qui mixe sous le nom Nox, est actif dans la musique électronique depuis plus de vingt-cinq ans et cofondateur du label lisboète Fuse Records. Son jeu circule entre la house et le versant le plus mélodique de la techno. Il a publié sur Cachai, Radiola Records, Klap House, Kaos et Tamango Records, et joué au BPM Festival, à la WMC et à l'ADE.", en: "Luís Baptista, who DJs as Nox, has been active in electronic music for over twenty-five years and co-founded the Lisbon label Fuse Records. His sets move between house and the more melodic side of techno. He has released on Cachai, Radiola Records, Klap House, Kaos and Tamango Records, and played BPM Festival, WMC and ADE." }, origin: "Lisbonne, Portugal", labels: ["Fuse Records"], sources: ["https://www.fuse.pt/roster", "https://shotgun.live/en/artists/djnoxpt"] }, // NOX
  "nto": { slug: "nto", bio: { fr: "NTO, de son vrai nom Anthony Favier, né en 1985 à Marseille, est un producteur et compositeur français de techno mélodique. Il publie son premier EP, Traque, en 2008 sur Basilic Records sous le nom N'to, puis cofonde en 2013 le collectif et label Hungry Music avec Worakls et Joachim Pastor. Il quitte Hungry Music en 2020 et sort l'album Apnea en 2021 sur AllPoints, suivi de Forever Friends avec le pianiste Sofiane Pamart en 2024.", en: "NTO, real name Anthony Favier, born in 1985 in Marseille, is a French melodic techno producer and composer. He released his first EP, Traque, on Basilic Records in 2008 under the name N'to, then co-founded the Hungry Music collective and label with Worakls and Joachim Pastor in 2013. He left Hungry Music in 2020 and released the album Apnea on AllPoints in 2021, followed by Forever Friends with pianist Sofiane Pamart in 2024." }, origin: "Marseille, France", since: 2008, labels: ["Hungry Music", "AllPoints"], sources: ["https://en.wikipedia.org/wiki/NTO_(musician)", "https://en.wikipedia.org/wiki/Hungry_Music"] }, // NTO
  "nyra": { slug: "nyra", bio: { fr: "NYRA est une DJ originaire de Francfort. Elle défend un son qu'elle appelle « Barbie Bounce », mélange de bounce, de trance et d'éléments de hard techno, à tempo rapide.", en: "NYRA is a DJ from Frankfurt. She champions a sound she calls 'Barbie Bounce', a fast-paced mix of bounce, trance and hard techno elements." }, origin: "Francfort, Allemagne", sources: ["https://scandal.events/lineup"] }, // Nyra
  "octave-one": { slug: "octave-one", bio: { fr: "Octave One est un duo de producteurs américains de Detroit formé par les frères Burden. Leur catalogue relève de la techno de Detroit, avec des incursions house et deep house.", en: "Octave One are an American production duo from Detroit made up of the Burden brothers. Their catalogue is Detroit techno, with house and deep house excursions." }, origin: "Detroit, États-Unis", sources: ["https://musicbrainz.org/artist/db856b35-33f2-4cf9-87cc-9e4e33772d40", "https://api.discogs.com/database/search?artist=Octave+One&type=release&per_page=50"] }, // Octave One
  "octo-octa": { slug: "octo-octa", bio: { fr: "Octo Octa est le nom de scène de Maya Bouldry-Morrison, productrice et DJ de house américaine née le 13 mai 1987 et installée dans le New Hampshire. Elle a fait son coming out en tant que femme transgenre en 2016, après s'être déjà fait connaître comme artiste.", en: "Octo Octa is the stage name of Maya Bouldry-Morrison, an American house producer and DJ born on 13 May 1987 and based in New Hampshire. She came out as a transgender woman in 2016, having already gained prominence as an artist." }, origin: "New Hampshire, États-Unis", sources: ["https://en.wikipedia.org/wiki/Octo_Octa"] }, // Octo Octa
  "ogalla": { slug: "ogalla", bio: { fr: "Toni Ogalla Ortí, né à Torrent en 1982, est un DJ et producteur valencien. Il commence à mixer en 1995 puis à produire en 2004, dans le hardhouse américain croisé de makina qui a donné le newstyle valencien. Résident de la Masia de Segorbe, révélé par le label CHR, il tient à Valence des sets « all night long » de huit heures qui retracent les périodes du genre, de 2005 à aujourd'hui.", en: "Toni Ogalla Ortí, born in Torrent in 1982, is a DJ and producer from Valencia. He started mixing in 1995 and producing in 2004, in the US hardhouse crossed with makina that became Valencian newstyle. A resident at Masia in Segorbe and first known through the CHR label, he now plays eight-hour \"all night long\" sets in Valencia that walk through the genre's eras, from 2005 to the present." }, origin: "Valence, Espagne", since: 1995, labels: ["CHR"], sources: ["https://www.hardmusic.es/en/biografia-dj-ogalla/", "https://invaders.es/event-item/ogalla-all-night-long-spook"] }, // Ogalla
  "ogazon": { slug: "ogazon", bio: { fr: "Ogazón est une DJ installée à Berlin, apparue dans le circuit club après 2020. Elle joue entre house et techno, en travaillant les changements de tempo et la dynamique plutôt que la montée continue. Elle est passée à plusieurs reprises par le Blitz de Munich, dont une soirée Dekmantel.", en: "Ogazón is a Berlin-based DJ who emerged on the club circuit after 2020. She plays between house and techno, working tempo shifts and dynamics rather than a continuous build. She has played Munich's Blitz several times, including a Dekmantel night." }, origin: "Berlin, Allemagne", sources: ["https://ra.co/events/2098730", "https://www.blitz.club/program/dekmantel/"] }, // Ogazón
  "oklou": { slug: "oklou", bio: { fr: "Marylou Mayniel, née en 1993 à Poitiers, compose sous le nom d'Oklou une pop électronique bâtie sur boîtes à rythmes, synthétiseurs et nappes d'ambiance, après une formation classique au piano et au violoncelle. Elle cofonde en 2015 le collectif de DJ féminin TGAF et publie son EP « The Rite of May » sur le label londonien NUXXE en 2018. Sa mixtape « Galore » paraît en 2020 et son premier album, « choke enough », en 2025.", en: "Born in Poitiers in 1993, Marylou Mayniel writes electronic pop as Oklou, built on drum machines, synthesisers and ambient textures, after classical training on piano and cello. She co-founded the all-female DJ collective TGAF in 2015 and released her EP \"The Rite of May\" on London label NUXXE in 2018. Her mixtape \"Galore\" appeared in 2020 and her first album, \"choke enough\", in 2025." }, origin: "Poitiers, France", since: 2014, labels: ["NUXXE"], sources: ["https://en.wikipedia.org/wiki/Oklou", "https://fr.wikipedia.org/wiki/Oklou"] }, // Oklou
  "oliver-magenta": { slug: "oliver-magenta", bio: { fr: "Oliver Magenta est un DJ allemand, résident du Bootshaus de Cologne. Il y tient depuis plusieurs années sa propre soirée, « Oliver Magenta & Friends », dont la programmation est annoncée en electro, deep house et EDM. On l'a vu aux festivals Parookaville et Nature One, et il a partagé l'affiche avec R3HAB, Will Sparks et Timmy Trumpet.", en: "Oliver Magenta is a German DJ and a resident at Bootshaus in Cologne. For several years he has run his own night there, \"Oliver Magenta & Friends\", billed by the club as electro, deep house and EDM. He has played the Parookaville and Nature One festivals and shared line-ups with R3HAB, Will Sparks and Timmy Trumpet." }, origin: "Cologne, Allemagne", sources: ["https://bootshaus.tv/events/oliver-magenta-and-friends-september/", "https://olivermagenta.de/"] }, // Oliver Magenta
  "olivia-lensen": { slug: "olivia-lensen", bio: { fr: "Olivia Lensen est une DJ néerlandaise d'origine moluquoise, aux platines depuis mars 2024. Ses sets font se croiser house, techno et rythmes de club. Elle a joué au Multipla, au PIP, au Toffler et au Thuishaven, et anime l'émission mensuelle OLIVIA ONTDEKT sur PIP Radio.", en: "Olivia Lensen is a Dutch-Moluccan DJ who started behind the decks in March 2024. Her sets move between house, techno and club rhythms. She has played Multipla, PIP, Toffler and Thuishaven, and hosts the monthly show OLIVIA ONTDEKT on PIP Radio." }, origin: "Rotterdam, Pays-Bas", since: 2024, sources: ["https://dgtl-festival.com/en/artists/olivia-lensen/", "https://pipradio.nl/artists/ollie-nesnel", "https://operator-radio.com/artists/olivia-lensen"] }, // Olivia Lensen
  "omiki": { slug: "omiki", bio: { fr: "Omiki est un producteur et DJ israélien de psytrance et de trance progressive, basé à Beer Sheva. Il découvre la psytrance à douze ans et publie depuis 2012, principalement sur Spintwist Records, Prog On Syndicate et Iono Music. Ses morceaux « Psychotic » et « Voodoo » l'ont fait connaître, et il s'est produit à Tomorrowland et Dreamstate.", en: "Omiki is an Israeli psytrance and progressive trance producer and DJ based in Beer Sheva. He discovered psytrance at twelve and has been releasing since 2012, mainly on Spintwist Records, Prog On Syndicate and Iono Music. Tracks such as \"Psychotic\" and \"Voodoo\" brought him wider attention, and he has played Tomorrowland and Dreamstate." }, origin: "Beer Sheva, Israël", since: 2012, labels: ["Spintwist Records", "Iono Music"], sources: ["https://www.discogs.com/artist/2987976-Omiki", "https://trance.fandom.com/wiki/Omiki"] }, // Omiki
  "one87": { slug: "one87", bio: { fr: "Jurgen Vanhessche, alias One87, est un DJ, producteur et organisateur belge actif dans la drum & bass depuis plus de vingt ans. Il est le fondateur de Star Warz, le concept de soirées drum & bass de Gand lancé en 2001, qu'il anime toujours. Il a joué au Metalheadz de Fabric à Londres, à Outlook, à Rampage et à Tomorrowland, et a publié un EP sur Flexout Audio.", en: "Jurgen Vanhessche, who records as One87, is a Belgian DJ, producer and promoter who has worked in drum & bass for more than twenty years. He founded Star Warz, the Ghent drum & bass party concept launched in 2001, and still runs it. He has played Metalheadz at Fabric in London, Outlook, Rampage and Tomorrowland, and released an EP on Flexout Audio." }, origin: "Gand, Belgique", labels: ["Flexout Audio"], sources: ["https://ukf.com/read/in-conversation-with-one87/", "https://www.drumandbass.nl/one87-releases-ep-in-years-flexout-audio/", "https://www.dourfestival.eu/en/artist/detail/One87/"] }, // One87
  "onlynumbers": { slug: "onlynumbers", bio: { fr: "Onlynumbers, de son vrai nom Tom Cillio Bosgiraud, est un producteur et DJ français originaire de Lyon, aujourd'hui installé en Tchéquie. Il joue une hard techno rapide et très travaillée en sound design, qu'il décrit lui-même comme « euphorique, profonde et chaotique, avec des sous-textes cinématographiques ». Il compose entièrement sur ordinateur, sous FL Studio, et s'est imposé sur le circuit européen des festivals à partir de fin 2023.", en: "Onlynumbers, real name Tom Cillio Bosgiraud, is a French producer and DJ from Lyon, now based in Czechia. He plays fast, sound-design-heavy hard techno that he describes himself as \"euphoric, deep and chaotic with cinematic undertones\". He produces entirely in the box, in FL Studio, and broke onto the European festival circuit from late 2023." }, origin: "Lyon, France", sources: ["https://technomusicworld.com/artist/onlynumbers/about", "https://www.trueunderground.one/chaos-beauty-cinematic-techno-the-mind-of-onlynumbers-unveiled/"] }, // Onlynumbers
  "ophidian": { slug: "ophidian", bio: { fr: "Conrad Hoyer, né en 1981 à Arnhem, produit du hardcore et du darkcore aux Pays-Bas depuis 1998. Longtemps signé sur Enzyme Records, il a monté les sous-labels Meta4 et Meta0, ce dernier sous son alias Meander. Ses albums Blackbox (2003), le double Betrayed By Daylight (2005) et Call Of The Void (2021) explorent des tempos plus lents et des textures industrielles.", en: "Conrad Hoyer, born in 1981 in Arnhem, has been making hardcore and darkcore in the Netherlands since 1998. Long signed to Enzyme Records, he set up the Meta4 and Meta0 sub-labels, the latter under his Meander alias. His albums Blackbox (2003), the double Betrayed By Daylight (2005) and Call Of The Void (2021) explore slower tempos and industrial textures." }, origin: "Arnhem, Pays-Bas", since: 1998, labels: ["Enzyme Records", "Meta4"], sources: ["https://nl.wikipedia.org/wiki/Ophidian"] }, // Ophidian
  "ornella": { slug: "ornella", bio: { fr: "Ornella est une DJ et productrice portugaise de hard techno et de schranz. Elle joue son premier événement à Lisbonne en 2019, aux côtés de Sam Paganini, puis se produit au Brunch Electronik de Lisbonne, au Sound Waves Festival, à Blackworks à New York et à Verknipt Portugal. Elle est à l'origine de la série de soirées Ornella Invites dans son pays.", en: "Ornella is a Portuguese hard techno and schranz DJ and producer. She played her first event in Lisbon in 2019 alongside Sam Paganini, then went on to Brunch Electronik Lisbon, Sound Waves Festival, Blackworks in New York and Verknipt Portugal. She founded the Ornella Invites party series in Portugal." }, origin: "Lisbonne, Portugal", since: 2019, sources: ["https://www.awakenings.com/en/artists/ornella/382813/", "https://www.technomag.fr/en/discover-the-world-of-ornella-hard-techno-dj-and-producer/"] }, // Ornella
  "oscar-mulero": { slug: "oscar-mulero", bio: { fr: "Óscar Mulero Crecente est un DJ et producteur de techno madrilène. Il commence à mixer à la fin des années 1980 dans des clubs de Madrid comme le New World et l'Overdrive, puis ouvre en 1994 son propre club, The Omen. Il dirige deux labels : Warm Up Recordings, lancé en 2000, et PoleGroup Recordings, lancé en 2004, qui comptent chacun plus de cent références. Son album Black Propaganda est paru en 2012.", en: "Óscar Mulero Crecente is a techno DJ and producer from Madrid. He began playing in Madrid clubs such as New World and Overdrive in the late 1980s, then opened his own venue, The Omen, in 1994. He runs two labels: Warm Up Recordings, started in 2000, and PoleGroup Recordings, started in 2004, each with more than a hundred releases. His album Black Propaganda came out in 2012." }, origin: "Madrid, Espagne", labels: ["PoleGroup Recordings", "Warm Up Recordings"], sources: ["https://en.wikipedia.org/wiki/Oscar_Mulero"] }, // Oscar Mulero
  "outsiders": { slug: "outsiders", bio: { fr: "Outsiders est le nom de scène de Cem Araci, DJ et producteur néerlandais né en 1985 à La Haye. Le projet est fondé en 2008 en duo avec Murat Meijer, qui le quitte en 2014. Il joue du hardstyle et compte plusieurs disques d'or et un disque de platine dans le genre.", en: "Outsiders is the stage name of Cem Araci, a Dutch DJ and producer born in 1985 in The Hague. The project was founded in 2008 as a duo with Murat Meijer, who left in 2014. He plays hardstyle and has earned several gold records and a platinum record in the genre." }, origin: "La Haye, Pays-Bas", since: 2008, sources: ["https://www.djguide.nl/djinfo.p?djid=5944&language=en", "https://edm.fandom.com/wiki/Outsiders_(NL)"] }, // Outsiders
  "overmono": { slug: "overmono", bio: { fr: "Overmono est un duo gallois de musique électronique formé par les frères Tom et Ed Russell, actifs auparavant en solo sous les alias Truss et Tessela. Ils produisent ensemble depuis 2015 et sortent leur premier EP, Arla, sur XL Recordings en 2016, en parallèle de leur label Poly Kicks. Leur premier album, Good Lies, paraît en mai 2023 chez XL et atteint la 11e place des classements britanniques.", en: "Overmono are a Welsh electronic duo formed by brothers Tom and Ed Russell, previously active solo as Truss and Tessela. They have produced together since 2015 and released their first EP, Arla, on XL Recordings in 2016, alongside their own label Poly Kicks. Their debut album, Good Lies, came out on XL in May 2023 and reached number 11 on the UK Albums Chart." }, origin: "Pays de Galles, Royaume-Uni", since: 2015, labels: ["XL Recordings", "Poly Kicks"], sources: ["https://en.wikipedia.org/wiki/Overmono"] }, // Overmono
  "ozan": { slug: "ozan", bio: { fr: "Ozan est un DJ né à Istanbul et installé à Helsinki, où il est résident du club Kaiku. Il était auparavant organisateur de soirées à Istanbul. Il joue une techno hypnotique et groovy, tournée vers le leftfield contemporain. On l'a entendu au Solstice Festival de Ruka et à l'Ääniwalli Weekender d'Helsinki.", en: "Ozan is a DJ born in Istanbul and based in Helsinki, where he is a resident of club Kaiku. He was previously a promoter in Istanbul. He plays hypnotic, groovy techno drawn from the modern leftfield. He has appeared at Solstice Festival in Ruka and at the Ääniwalli Weekender in Helsinki." }, origin: "Helsinki, Finlande", sources: ["https://solsticefestival.fi/music/ozan", "https://aaniwalli.fi/events/2026-08-16-niwalli_weekender_vum_open_air_2026_12/"] }, // Ozan
  "paco-osuna": { slug: "paco-osuna", bio: { fr: "Paco Osuna est un DJ et producteur espagnol installé à Barcelone. Ses disques paraissent sur Plus 8 Records et M_nus, dans un registre de techno minimale et de tech house.", en: "Paco Osuna is a Spanish DJ and producer based in Barcelona. His records come out on Plus 8 Records and M_nus, in a minimal techno and tech house vein." }, origin: "Barcelone, Espagne", labels: ["Plus 8 Records", "M_nus"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Paco%20Osuna&fmt=json", "https://api.discogs.com/database/search?artist=Paco+Osuna&type=release"] }, // Paco Osuna
  "pact-joachim-pastor-joris-delacroix-teho": { slug: "pact-joachim-pastor-joris-delacroix-teho", bio: { fr: "PACT réunit trois producteurs français de techno mélodique — Joachim Pastor, Joris Delacroix et Teho — dans un projet conçu pour la scène. Le trio joue au milieu du public plutôt que face à lui, et des machines développées pour l'occasion permettent aux spectateurs d'intervenir sur le live.", en: "PACT brings together three French melodic techno producers — Joachim Pastor, Joris Delacroix and Teho — in a project built for the stage. The trio plays among the crowd rather than in front of it, with custom-built machines letting the audience take part in the live set." }, origin: "France", sources: ["https://pactteam.fr/", "https://www.radiofg.com/pact-le-projet-francais-qui-reinvente-les-lives"] }, // PACT (Joachim Pastor + Joris Delacroix + Teho)
  "palms-trax": { slug: "palms-trax", bio: { fr: "Palms Trax est un DJ et producteur britannique originaire de Saltford, dans le Somerset, et installé à Berlin. Sa sélection tourne autour de la house, de la deep house et du disco. Il dirige le label CWPT.", en: "Palms Trax is a British DJ and producer from Saltford, Somerset, based in Berlin. His selection revolves around house, deep house and disco. He runs the CWPT label." }, origin: "Saltford, Royaume-Uni / Berlin", labels: ["CWPT"], sources: ["https://www.discogs.com/artist/3467480-Palms-Trax", "https://www.last.fm/music/Palms+Trax/+tags"] }, // Palms Trax
  "paloma-colombe": { slug: "paloma-colombe", bio: { fr: "DJ, programmatrice, artiste sonore et chroniqueuse radio franco-algérienne installée à Paris, Paloma Colombe construit des sets où se croisent polyrythmies percussives, bass music et techno, avec du soul-jazz, du boogie, du disco-funk et de l'afrobeat en ouverture. Elle est co-fondatrice de l'association Réinventer la nuit et anime une émission sur Rinse France. En 2025 elle publie la compilation Dihya.", en: "A French-Algerian DJ, programmer, sound artist and radio host based in Paris, Paloma Colombe builds sets that run percussive polyrhythms, bass music and techno alongside soul-jazz, boogie, disco-funk and afrobeat in the warm-up. She co-founded the association Réinventer la nuit and hosts a show on Rinse France. In 2025 she released the compilation Dihya." }, origin: "Paris, France", sources: ["https://www.rinse.fm/shows/paloma-colombe", "https://www.timeout.fr/paris/musique/de-reinventer-la-nuit-a-dihya-la-renaissance-de-la-dj-parisienne-paloma-colombe", "https://palaisdetokyo.com/personne/paloma-colombes/"] }, // Paloma Colombe
  "pan-pot": { slug: "pan-pot", bio: { fr: "Pan-Pot est un duo techno berlinois composé de Tassilo Ippenberger et Thomas Benedix. Ils se rencontrent en 2003 au SAE Institute de Berlin, où ils étudient l'ingénierie du son, et se lancent en 2005 avec le maxi « Copy and Paste » sur le label Mobilee d'Anja Schneider. Leur premier album, Pan-O-Rama, sort en 2007. En 2014, ils créent le label Second State, sur lequel ils signent Amelie Lens.", en: "Pan-Pot is a Berlin techno duo made up of Tassilo Ippenberger and Thomas Benedix. They met in 2003 at Berlin's SAE Institute, where they studied audio engineering, and started out in 2005 with the single \"Copy and Paste\" on Anja Schneider's Mobilee label. Their first album, Pan-O-Rama, appeared in 2007. In 2014 they launched the label Second State, where they signed Amelie Lens." }, origin: "Berlin, Allemagne", since: 2005, labels: ["Second State", "Mobilee"], sources: ["https://en.wikipedia.org/wiki/Pan-Pot"] }, // Pan-Pot
  "paralich": { slug: "paralich", bio: { fr: "Paralich est une DJ, productrice et organisatrice de soirées basée à Budapest. Elle a fondé le label et la série de soirées Dead End, et joue une techno industrielle marquée par la culture rave, où les rythmes soutenus croisent des nappes mélodiques.", en: "Paralich is a DJ, producer and party organiser based in Budapest. She founded the Dead End label and party series, and plays rave-influenced industrial techno in which driving rhythms meet melodic textures." }, origin: "Budapest, Hongrie", labels: ["Dead End"], sources: ["https://ra.co/dj/paralich/biography", "https://sachsentrance.com/artists/artist/paralich/"] }, // Paralich
  "paramida": { slug: "paramida", bio: { fr: "Paramida est une DJ, productrice et patronne de label allemande d'origine persane, installée à Berlin depuis 2010 et résidente du Panorama Bar du Berghain. En 2014, alors qu'elle travaille au disquaire OYE Records, elle fonde le label Love on the Rocks, qui publie aussi bien de l'italo et de la disco que de la néo-goa trance. Elle a été retenue parmi les 100 Women de la BBC en 2023.", en: "Paramida is a German DJ, producer and label owner of Persian background, based in Berlin since 2010 and a resident at Berghain's Panorama Bar. In 2014, while working at the OYE Records shop, she founded the Love on the Rocks label, which puts out italo and disco as readily as neo Goa trance. She was named one of the BBC's 100 Women in 2023." }, origin: "Berlin, Allemagne", since: 2014, labels: ["Love on the Rocks"], sources: ["https://en.wikipedia.org/wiki/Paramida"] }, // Paramida
  "part-time-killer": { slug: "part-time-killer", bio: { fr: "Part Time Killer est un projet techno basé à Berlin, qui pose des éléments cinématiques et des atmosphères tendues sur des grooves rapides et une techno de peak time. Il est résident et graphiste du label Selected Berlin, dirige Blake Records et forme la moitié de Vermeer Selected. Il a sorti des disques sur Exhale et Color.", en: "Part Time Killer is a Berlin-based techno project that sets cinematic elements and tense atmospheres over fast grooves and peak-time techno. He is a resident and artwork designer for the Selected Berlin label, runs Blake Records and is one half of Vermeer Selected. He has released on Exhale and Color." }, origin: "Berlin, Allemagne", labels: ["Blake Records", "Exhale", "Color"], sources: ["https://events.musicofourdesire.com/artist/part-time-killer", "https://harderstylemap.com/artist/part-time-killer/"] }, // Part Time Killer
  "partyraiser": { slug: "partyraiser", bio: { fr: "Partyraiser est le nom de scène de Wesley van Swol, DJ et producteur néerlandais né en 1977 à Delft. Il joue du hardcore, du terrorcore et de l'uptempo, a démarré en 1993 et publié son premier EP, A New World Order, en 1997 sur Dutch Gabber Network Records. Il a tenu le label Megarave Records puis fondé Partyraiser Records en 2013, et joue à Defqon.1, Dominator et Decibel.", en: "Partyraiser is the stage name of Wesley van Swol, a Dutch DJ and producer born in 1977 in Delft. He plays hardcore, terrorcore and uptempo, started in 1993 and released his first EP, A New World Order, in 1997 on Dutch Gabber Network Records. He ran Megarave Records, then founded Partyraiser Records in 2013, and plays Defqon.1, Dominator and Decibel." }, origin: "Delft, Pays-Bas", since: 1993, labels: ["Partyraiser Records"], sources: ["https://fr.wikipedia.org/wiki/Wesley_van_Swol", "https://nl.wikipedia.org/wiki/Partyraiser"] }, // Partyraiser
  "pat-b": { slug: "pat-b", bio: { fr: "Pat B est un DJ et producteur belge d'Anvers, actif dans le jumpstyle et le hardstyle depuis le milieu des années 2000. Il a alimenté les catalogues de Be Yourself et Dirty Workz entre 2004 et 2008 et n'a jamais cessé de sortir du jumpstyle depuis. En 2026 il publie « Jumpers In The Place » avec High Resistance et tient son Birthday Bash à la Lotto Arena d'Anvers.", en: "Pat B is a Belgian DJ and producer from Antwerp, active in jumpstyle and hardstyle since the mid-2000s. He filled the rosters of Be Yourself and Dirty Workz between 2004 and 2008 and has released jumpstyle without a break since. In 2026 he put out 'Jumpers In The Place' with High Resistance and held his Birthday Bash at Antwerp's Lotto Arena." }, origin: "Anvers, Belgique", labels: ["Dirty Workz"], sources: ["https://www.hardcultr.com/culture/jumpstyle-revival-2026/", "https://shop.dirtyworkz.com/artists/pat-b/"] }, // Pat B
  "paul-elstak": { slug: "paul-elstak", bio: { fr: "Paul Roger Elstak, connu sous le nom de DJ Paul Elstak, est un DJ, producteur et patron de label néerlandais né à La Haye en 1966. Il a fondé en 1992 Rotterdam Records, premier label hardcore des Pays-Bas, puis Offensive Records en 2001. Ses tubes happy hardcore de 1995-1996, « Luv U More » et « Rainbow in the Sky », se sont classés respectivement 2e et 3e du Top 40 néerlandais. Il a coproduit « Europapa », la chanson des Pays-Bas à l'Eurovision 2024, et reçu le Gouden Harp en 2023.", en: "Paul Roger Elstak, known as DJ Paul Elstak, is a Dutch DJ, producer and label owner born in The Hague in 1966. In 1992 he founded Rotterdam Records, the first hardcore label in the Netherlands, then Offensive Records in 2001. His 1995–96 happy hardcore hits \"Luv U More\" and \"Rainbow in the Sky\" reached number 2 and number 3 in the Dutch Top 40. He co-produced \"Europapa\", the Netherlands' 2024 Eurovision entry, and received the Gouden Harp award in 2023." }, origin: "La Haye, Pays-Bas", since: 1992, labels: ["Rotterdam Records", "Offensive Records"], sources: ["https://nl.wikipedia.org/wiki/Paul_Elstak"] }, // Paul Elstak
  "paul-kalkbrenner": { slug: "paul-kalkbrenner", bio: { fr: "Paul Kalkbrenner, né le 11 juin 1977, est un musicien et producteur allemand qui a grandi à Lichtenberg, dans l'ancien Berlin-Est. Il joue en live plutôt qu'en DJ set, en recomposant ses morceaux élément par élément sur scène. Il a publié ses premiers disques sur BPitch Control à partir de 1999 sous le nom de Paul dB+, puis a tenu le rôle d'Ickarus dans le film Berlin Calling (2008), dont il signe la bande originale et le titre « Sky and Sand », chanté par son frère Fritz Kalkbrenner.", en: "Paul Kalkbrenner, born 11 June 1977, is a German musician and producer who grew up in Lichtenberg, in what was then East Berlin. He performs live rather than as a DJ, rebuilding his tracks element by element on stage. He put out his first records on BPitch Control from 1999 under the name Paul dB+, then played Ickarus in the film Berlin Calling (2008), for which he wrote the soundtrack and the track \"Sky and Sand\", sung by his brother Fritz Kalkbrenner." }, origin: "Berlin, Allemagne", since: 1999, labels: ["BPitch Control"], sources: ["https://en.wikipedia.org/wiki/Paul_Kalkbrenner"] }, // Paul Kalkbrenner
  "paul-van-dyk": { slug: "paul-van-dyk", bio: { fr: "Paul van Dyk, de son vrai nom Matthias Paul, est né le 16 décembre 1971 à Eisenhüttenstadt. DJ et producteur allemand, il a publié huit albums studio et remixé des titres de Justin Timberlake, New Order et U2. Sa musique relève de la trance, même s'il préfère parler de musique électronique de danse.", en: "Paul van Dyk, born Matthias Paul on 16 December 1971 in Eisenhuttenstadt, is a German DJ and producer. He has released eight studio albums and remixed tracks for Justin Timberlake, New Order and U2. His music belongs to trance, though he prefers the broader term electronic dance music." }, origin: "Eisenhüttenstadt, Allemagne", sources: ["https://de.wikipedia.org/wiki/Paul_van_Dyk"] }, // Paul van Dyk
  "pawlowski": { slug: "pawlowski", bio: { fr: "Pawlowski est un DJ et producteur français, représenté par l'agence parisienne Vesuve. Il commence à produire en 2017 avec le producteur VCL et publie son premier EP complet, Final Outsider, le 21 décembre 2023 sur KNTXT RPM. Sa musique puise dans la trance des années 1990, l'acid et la techno rapide.", en: "Pawlowski is a French DJ and producer, represented by the Paris agency Vesuve. He started producing in 2017 with producer VCL and released his first full EP, Final Outsider, on 21 December 2023 on KNTXT RPM. His music draws on 1990s trance, acid and fast techno." }, origin: "France", since: 2017, labels: ["KNTXT RPM"], sources: ["https://thesource.com/2024/02/05/mystery-dj-pawlowski-entrances-global-dance-scene/"] }, // Pawlowski
  "pawsa": { slug: "pawsa", bio: { fr: "Pawsa est le nom de scène de David Esekhile, DJ et producteur britannique. Il dirige le label PAWZ et publie également sur Solid Grooves Records, dans un registre de tech house et de house minimale.", en: "Pawsa is the stage name of David Esekhile, a British DJ and producer. He runs the PAWZ label and also releases on Solid Grooves Records, in a tech house and minimal house vein." }, since: 2017, labels: ["PAWZ", "Solid Grooves Records"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Pawsa&fmt=json", "https://api.discogs.com/database/search?artist=Pawsa&type=release"] }, // Pawsa
  "pegassi": { slug: "pegassi", bio: { fr: "Pegassi, de son vrai nom Sam Huybrecht, est un DJ et producteur belge originaire d'Anvers. Son répertoire assemble des éléments d'eurodance, de trance, de techno et de house, dans un registre de club rapide.", en: "Pegassi, real name Sam Huybrecht, is a Belgian DJ and producer from Antwerp. His output combines elements of eurodance, trance, techno and house, in a fast club register." }, origin: "Anvers, Belgique", sources: ["https://www.discogs.com/artist/5658595-Pegassi", "https://musicbrainz.org/ws/2/artist/?query=Pegassi&fmt=json"] }, // Pegassi
  "peggy-gou": { slug: "peggy-gou", bio: { fr: "Kim Min-ji, née en 1991 en Corée du Sud et installée à Berlin, mixe et produit sous le nom de Peggy Gou, entre house et techno. Elle a publié sept EP, notamment sur Ninja Tune et Phonica, puis fondé son propre label Gudu Records en 2019 et mixé un volume de la série DJ-Kicks pour !K7. Son premier album, « I Hear You », est sorti en juin 2024 chez XL Recordings.", en: "Born in South Korea in 1991 and based in Berlin, Kim Min-ji DJs and produces as Peggy Gou, working between house and techno. She has released seven EPs, notably on Ninja Tune and Phonica, then founded her own label Gudu Records in 2019 and mixed a volume of the DJ-Kicks series for !K7. Her debut album \"I Hear You\" came out in June 2024 on XL Recordings." }, origin: "Corée du Sud", labels: ["Gudu Records", "Ninja Tune"], sources: ["https://en.wikipedia.org/wiki/Peggy_Gou"] }, // Peggy Gou
  "pendulum": { slug: "pendulum", bio: { fr: "Pendulum est un groupe australien de drum & bass fondé en 2002 à Perth par Rob Swire, Gareth McGrillen et Paul « El Hornet » Harding. Leur premier album, Hold Your Colour (2005), reste majoritairement drum & bass, tandis que In Silico et Immersion explorent le rock électronique et industriel. Le groupe s'est mis en pause en 2012 avant de reprendre en 2016.", en: "Pendulum is an Australian drum & bass band founded in 2002 in Perth by Rob Swire, Gareth McGrillen and Paul \"El Hornet\" Harding. Their debut album Hold Your Colour (2005) is mostly drum & bass, while In Silico and Immersion moved into electronic and industrial rock. The band went on hiatus in 2012 and returned in 2016." }, origin: "Perth, Australie", since: 2002, labels: ["Breakbeat Kaos", "Earstorm", "Warner Music UK"], sources: ["https://en.wikipedia.org/wiki/Pendulum_(drum_and_bass_band)"] }, // Pendulum
  "peterblue": { slug: "peterblue", bio: { fr: "Peterblue est un DJ et producteur colombien de Bogotá, installé à Barcelone. Il mêle une techno hardgroove aux rythmes latino-américains — merengue, reggaeton, cumbia, salsa — un courant appelé latin club. Il a fondé son label PA$TI Records en 2023, publié l'EP Bailar Para No Pensar puis Diskoteka Amerikana, et son set pour HÖR Berlin en octobre 2024 l'a fait connaître en Europe.", en: "Peterblue is a Colombian DJ and producer from Bogotá, based in Barcelona. He mixes hardgroove techno with Latin American rhythms — merengue, reggaeton, cumbia, salsa — a strand known as Latin club. He founded his label PA$TI Records in 2023, released the EP Bailar Para No Pensar then Diskoteka Amerikana, and his October 2024 HÖR Berlin set brought him European attention." }, origin: "Bogotá, Colombie", since: 2023, labels: ["PA$TI Records"], sources: ["https://mixmagcaribbean.com/read/peterblue-car-2025-02-digital-magazine"] }, // Peterblue
  "petit-biscuit": { slug: "petit-biscuit", bio: { fr: "Mehdi Benjelloun, alias Petit Biscuit, est un producteur et multi-instrumentiste français né en 1999 à Rouen. Il se fait connaître à seize ans avec le single « Sunset Lover » (2015), qui mêle guitare acoustique, textures électroniques et voix retravaillées, entre deep house et downtempo. Pour rester indépendant, il monte son propre label, Petit Biscuit Music, sur lequel paraissent les albums Presence (2017), Parachute (2020) et Discipline (2024).", en: "Mehdi Benjelloun, who records as Petit Biscuit, is a French producer and multi-instrumentalist born in Rouen in 1999. He broke through at sixteen with the single \"Sunset Lover\" (2015), layering acoustic guitar, electronic textures and treated vocals somewhere between deep house and downtempo. To stay independent he set up his own label, Petit Biscuit Music, home to the albums Presence (2017), Parachute (2020) and Discipline (2024)." }, origin: "Rouen, France", since: 2015, labels: ["Petit Biscuit Music"], sources: ["https://en.wikipedia.org/wiki/Petit_Biscuit", "https://fr.wikipedia.org/wiki/Petit_Biscuit"] }, // Petit Biscuit
  "philou-louzolo": { slug: "philou-louzolo", bio: { fr: "Philou Louzolo est un DJ et producteur néerlandais aux racines congolaises, nigérianes et sierra-léonaises, actif depuis 2013. Il mêle house, deep house et afro house, et s'est fait connaître par des sets marathon de dix à quinze heures à Thuishaven, à Amsterdam. En 2019 il fonde son label Wokoundou, sur lequel paraît en 2022 son premier album.", en: "Philou Louzolo is a Dutch DJ and producer with Congolese, Nigerian and Sierra Leonean roots, releasing since 2013. He works between house, deep house and afro house, and became known for ten- and fifteen-hour marathon sets at Thuishaven in Amsterdam. In 2019 he founded the Wokoundou label, which released his debut album in 2022." }, origin: "Pays-Bas", since: 2013, labels: ["Wokoundou"], sources: ["https://philoulouzolo.com/biography", "https://www.amsterdam-dance-event.nl/en/artists-speakers/philou-louzolo/6500/"] }, // Philou Louzolo
  "phuture-noize": { slug: "phuture-noize", bio: { fr: "Phuture Noize est le nom de scène de Marco Spronk, DJ et producteur de hardstyle néerlandais né le 11 septembre 1994 à Giessen. Le projet démarre en duo en 2009 avec Antoine Kraaij, qui le quitte en 2015. Spronk signe l'hymne du Qapital 2018, publie l'album Silver Bullet en juillet 2020 sur son label Black Mirror Society, et joue au Defqon.1, au Qlimax et au Decibel Outdoor.", en: "Phuture Noize is the stage name of Marco Spronk, a Dutch hardstyle DJ and producer born on 11 September 1994 in Giessen. The project started as a duo in 2009 with Antoine Kraaij, who left in 2015. Spronk wrote the 2018 Qapital anthem, released the album Silver Bullet in July 2020 on his Black Mirror Society label, and plays Defqon.1, Qlimax and Decibel Outdoor." }, origin: "Giessen, Pays-Bas", since: 2009, labels: ["Mirror Society"], sources: ["https://nl.wikipedia.org/wiki/Phuture_Noize"] }, // Phuture Noize
  "piazza": { slug: "piazza", bio: { fr: "Piazza est un DJ et producteur corse installé à Bordeaux, résident du club La Dame. Sa discographie sur label démarre en avril 2025 avec « Salvation » chez Radiant Studios, suivie de trois sorties chez UNCOMMON en 2026 — « DEMONS », « Get Naughty » et « NO TIME TO LOSE ». Parti de l'afro house, il a basculé vers l'indie dance et la melodic house.", en: "Piazza is a Corsican DJ and producer based in Bordeaux and a resident of the club La Dame. His label discography starts in April 2025 with \"Salvation\" on Radiant Studios, followed by three UNCOMMON releases in 2026 — \"DEMONS\", \"Get Naughty\" and \"NO TIME TO LOSE\". Having started in afro house, he moved towards indie dance and melodic house." }, origin: "Corse / Bordeaux, France", since: 2025, labels: ["Radiant Studios", "UNCOMMON"], sources: ["https://www.sxpress.fr/artiste/piazza/"] }, // Piazza
  "pigminds": { slug: "pigminds", bio: { fr: "Pigminds est un DJ et producteur uptempo toulousain, créé en janvier 2017 comme duo puis poursuivi en projet solo, au moment où l'uptempo s'installait en France. Il fait partie des Karnage Soldiers du label Karnage Records et joue régulièrement au Bikini de Ramonville.", en: "Pigminds is an uptempo DJ and producer from Toulouse, started in January 2017 as a duo and continued as a solo project, at the point when uptempo was taking hold in France. He is one of the Karnage Soldiers on the Karnage Records label and plays regularly at Le Bikini in Ramonville." }, origin: "Toulouse, France", since: 2017, labels: ["Karnage Records"], sources: ["https://valliue.com/2025/07/05/karnage-summer-club-la-soiree-hard-de-lete-toulouse/", "https://www.karnagerecords.fr/en/event-details/karnage-summer-club"] }, // Pigminds
  "planetary-assault-systems": { slug: "planetary-assault-systems", bio: { fr: "Planetary Assault Systems est le principal alias de Luke Slater, musicien et producteur anglais né en 1968 à Reading, qui se consacre à la techno depuis le début des années 1990. Sous ce nom, il défend une techno de club dépouillée et physique, notamment sur l'album The Messenger (2011) publié par Ostgut Ton. Il dirige aussi son propre label, Mote-Evolver, lancé en 2006, et enregistre par ailleurs sous les noms The 7th Plain et L.B. Dub Corp.", en: "Planetary Assault Systems is the main alias of Luke Slater, an English musician and producer born in Reading in 1968 who has focused on techno since the early 1990s. Under that name he makes stripped-back, physical club techno, notably on the album The Messenger (2011), released by Ostgut Ton. He also runs his own label, Mote-Evolver, launched in 2006, and records as The 7th Plain and L.B. Dub Corp." }, origin: "Reading, Royaume-Uni", since: 1993, labels: ["Mote-Evolver", "Ostgut Ton", "Peacefrog Records"], sources: ["https://en.wikipedia.org/wiki/Luke_Slater"] }, // Planetary Assault Systems
  "povoa": { slug: "povoa", bio: { fr: "Povoa est un DJ et producteur basé à Paris. Ses sets passent du baile funk au dubstep, de la house à l'hyperpop, et ont été relayés par Four Tet et Ben UFO.", en: "Povoa is a DJ and producer based in Paris. His sets run from baile funk to dubstep, house to hyperpop, and have been picked up by Four Tet and Ben UFO." }, origin: "Paris, France", sources: ["https://dancewax.net/2026/02/04/tapping-in-with-povoa/", "https://povoasound.bandcamp.com/"] }, // Povoa
  "primate": { slug: "primate", bio: { fr: "Primate est le nom de scène de Marcel Matheussen, DJ et producteur drum & bass gantois. Parti du jump-up, il a élargi son répertoire aux hymnes drum & bass et aux morceaux plus durs, avec des collaborations pour le projet NLW d'Afrojack et pour Sigma. Sa soirée « Sticks & Stones » au Club Wintercircus de Gand est sa première tête d'affiche dans sa propre ville.", en: "Primate is the stage name of Marcel Matheussen, a drum & bass DJ and producer from Ghent. Starting out in jump-up, he broadened into feel-good drum & bass anthems and harder underground tracks, with collaborations for Afrojack's NLW project and for Sigma. His \"Sticks & Stones\" show at Ghent's Club Wintercircus is his first headline date in his home city." }, origin: "Gand, Belgique", sources: ["https://www.clubwintercircus.be/primate-presents-sticks-stones/", "https://kurious.be/artist/primate/"] }, // Primate
  "project-one": { slug: "project-one", bio: { fr: "Project One est un projet hardstyle néerlandais réunissant Willem Rebergen (Headhunterz) et Joram Metekohy (Wildstylez), formé en 2008. Le duo a publié un album, un EP et plusieurs singles.", en: "Project One is a Dutch hardstyle project pairing Willem Rebergen (Headhunterz) and Joram Metekohy (Wildstylez), formed in 2008. The duo has released an album, an EP and several singles." }, origin: "Pays-Bas", since: 2008, sources: ["https://en.wikipedia.org/wiki/Project_One", "https://musicbrainz.org/artist/a31c42d5-ca7d-4ecf-a324-d04ad09ea0d2"] }, // Project One
  "prospa": { slug: "prospa", bio: { fr: "Duo britannique formé par Harvey Blumler et Gosha Smith, amis d'enfance originaires de Leeds, Prospa produit ensemble depuis 2013 une house nourrie de rave et de breakbeat. Leur morceau « Prayer » (2018) est choisi par Annie Mac comme Hottest Record in the World sur BBC Radio 1. Après des sorties sur Circoloco Records, le duo a lancé son propre label, Rave Science, distribué par Polydor.", en: "A British duo made up of Harvey Blumler and Gosha Smith, childhood friends from Leeds, Prospa have been producing together since 2013, blending house with rave and breakbeat. Their track \"Prayer\" (2018) was picked by Annie Mac as Hottest Record in the World on BBC Radio 1. After releasing on Circoloco Records, the pair launched their own label, Rave Science, through Polydor." }, origin: "Leeds, Angleterre", since: 2013, labels: ["Rave Science", "Circoloco Records"], sources: ["https://en.wikipedia.org/wiki/Prospa"] }, // Prospa
  "prunk": { slug: "prunk", bio: { fr: "Prunk est le nom de scène de Nilz Pronk, DJ et producteur néerlandais d'origine indonésienne installé à Amsterdam. Il collectionne les disques de house depuis l'enfance et publie ses premiers morceaux au début des années 2010, dont l'EP « Cirque du Soleil » avec Norman Soares. En 2015, il fonde le label PIV, devenu une référence de la house européenne, et sa musique croise house de Chicago, garage britannique et house minimale.", en: "Prunk is the stage name of Nilz Pronk, a Dutch DJ and producer of Indonesian descent based in Amsterdam. He has collected house records since childhood and put out his first tracks in the early 2010s, among them the \"Cirque du Soleil\" EP with Norman Soares. In 2015 he founded the PIV label, now a reference point in European house, and his music crosses Chicago house, UK garage and minimal house." }, origin: "Amsterdam, Pays-Bas", since: 2010, labels: ["PIV"], sources: ["https://grayarea.co/academy/the-indelible-lane-of-house-music-carved-by-piv-records-boss-prunk"] }, // Prunk
  "purple-disco-machine": { slug: "purple-disco-machine", bio: { fr: "Purple Disco Machine est le nom de scène de Tino Piontek, producteur et DJ allemand né le 12 février 1980 à Dresde. Il travaille la nu-disco et la house, et publie notamment sur Sweat It Out! et Columbia.", en: "Purple Disco Machine is the stage name of Tino Piontek, a German record producer and DJ born on 12 February 1980 in Dresden. He works in nu-disco and house, releasing on labels including Sweat It Out! and Columbia." }, origin: "Dresde, Allemagne", labels: ["Sweat It Out!", "Columbia"], sources: ["https://en.wikipedia.org/wiki/Purple_Disco_Machine", "https://api.discogs.com/database/search?artist=Purple+Disco+Machine&type=release"] }, // Purple Disco Machine
  "quelza": { slug: "quelza", bio: { fr: "Quelza est le nom de scène de Léo Naït Aïssa, producteur et DJ français installé à Berlin. Il façonne une techno hypnotique où se glissent des breakbeats et des textures proches de l'IDM, dans un travail sonore souvent décrit comme cinématographique. Ses disques sont sortis sur le label 47 de Tommy Four Seven, sur Hayes Collective, Mord, Kuboraum Editions et sur la série UFO de Dekmantel.", en: "Quelza is the stage name of Léo Naït Aïssa, a French producer and DJ based in Berlin. He builds hypnotic techno laced with breakbeats and IDM-leaning textures, in a sound design frequently described as cinematic. His records have appeared on Tommy Four Seven's 47 imprint, Hayes Collective, Mord, Kuboraum Editions and Dekmantel's UFO series." }, origin: "France, installé à Berlin", labels: ["47", "Hayes Collective", "Dekmantel"], sources: ["https://mixmagde.com/read/french-techno-innovator-quelza-debuts-on-dekmantels-ufo-series-music", "https://www.nts.live/artists/120723-quelza"] }, // Quelza
  "r3hab": { slug: "r3hab", bio: { fr: "R3HAB est le nom de scène de Fadil El Ghoul, né le 2 avril 1986, DJ et producteur néerlandais d'origine marocaine. Il débute fin 2007 avec le morceau « Mrkrstft », remixé par son compatriote de Breda Hardwell, puis signe chez le label d'Afrojack après « Prutataaa ». Il dirige son propre label, CYB3RPVNK, a publié les albums Trouble (2017) et The Wave (2018), et a atteint la 12e place du Top 100 DJs de DJ Mag en 2018.", en: "R3HAB is the stage name of Fadil El Ghoul, born 2 April 1986, a Dutch-Moroccan DJ and producer. He started out in late 2007 with the track \"Mrkrstft\", remixed by fellow Breda DJ Hardwell, then signed to Afrojack's label after \"Prutataaa\". He runs his own imprint CYB3RPVNK, released the albums Trouble (2017) and The Wave (2018), and reached number 12 in DJ Mag's Top 100 DJs in 2018." }, origin: "Breda, Pays-Bas", since: 2007, labels: ["CYB3RPVNK"], sources: ["https://en.wikipedia.org/wiki/R3hab"] }, // R3HAB
  "radical-redemption": { slug: "radical-redemption", bio: { fr: "Radical Redemption est le nom de scène de Joey van Ingen, DJ et producteur néerlandais né le 17 septembre 1990 à Denekamp. Il produit du rawstyle, une variante sombre du hardstyle, et a sorti huit albums en solo ainsi que trois avec le collectif Minus Militia. Après un litige avec son ancien label, il a fondé Redemption Records en 2023.", en: "Radical Redemption is the stage name of Joey van Ingen, a Dutch DJ and producer born on 17 September 1990 in Denekamp. He produces rawstyle, a darker strain of hardstyle, and has released eight solo albums plus three with the Minus Militia collective. After a dispute with his former label, he founded Redemption Records in 2023." }, origin: "Denekamp, Pays-Bas", labels: ["Redemption Records"], sources: ["https://en.wikipedia.org/wiki/Radical_Redemption"] }, // Radical Redemption
  "rampa": { slug: "rampa", bio: { fr: "DJ et producteur allemand, membre fondateur du collectif et label berlinois Keinemusik, lancé en 2009 avec Adam Port, &ME, Reznik et Monja Gentschow. Sa house et sa techno reposent sur des percussions très présentes, souvent d'inspiration africaine, et il a sorti sur Innervisions, Diynamic ou Cocoon. Il a coproduit deux morceaux de l'album Honestly, Nevermind de Drake (2022) et monté TEILE, qui fabrique des effets analogiques pour DJ.", en: "German DJ and producer, a founding member of the Berlin collective and label Keinemusik, launched in 2009 with Adam Port, &ME, Reznik and Monja Gentschow. His house and techno lean on prominent, often African-inflected percussion, and he has released on Innervisions, Diynamic and Cocoon. He co-produced two tracks on Drake's album Honestly, Nevermind (2022) and set up TEILE, which builds analogue effects for DJs." }, origin: "Berlin, Allemagne", since: 2009, labels: ["Keinemusik"], sources: ["https://en.wikipedia.org/wiki/Keinemusik", "https://keinemusik.com/crue/rampa/"] }, // Rampa
  "ran-d": { slug: "ran-d", bio: { fr: "Randy Wieland, connu sous le nom de Ran-D, né le 18 mai 1981, est un DJ et producteur néerlandais de hardstyle. Il forme le duo Gunz for Hire avec Adaro et a joué à Qlimax, Defqon.1, Reverze et Decibel Outdoor.", en: "Randy Wieland, known as Ran-D, born 18 May 1981, is a Dutch hardstyle DJ and producer. He is one half of the duo Gunz for Hire with Adaro and has played Qlimax, Defqon.1, Reverze and Decibel Outdoor." }, origin: "Zélande, Pays-Bas", sources: ["https://en.wikipedia.org/wiki/Ran-D"] }, // Ran-D
  "raxeller": { slug: "raxeller", bio: { fr: "Raxeller est un producteur néerlandais né à Alkmaar. Il produit ses premiers morceaux en 2010 en parallèle d'un emploi salarié, puis commence sa carrière de DJ en 2022. Sa musique relève de la techno industrielle rapide, aux atmosphères dystopiques et cinématographiques. Il a joué en tête d'affiche de Free Your Mind, Rotterdam Rave et Verknipt.", en: "Raxeller is a Dutch producer born in Alkmaar. He made his first tracks in 2010 alongside a day job, then started DJing in 2022. His music is fast industrial techno with dystopian, cinematic atmospheres. He has headlined Free Your Mind, Rotterdam Rave and Verknipt." }, origin: "Alkmaar, Pays-Bas", since: 2010, sources: ["https://www.fazemag.de/raxeller-industrial-hardtechno-breakout-without-the-social-media-hype/", "https://magneticmag.com/2025/07/interview-industrial-techno-artist-raxeller-sacred-court-revised-records-falsive-records/"] }, // Raxeller
  "rdhad": { slug: "rdhad", bio: { fr: "Rødhåd, de son vrai nom Mike Bierbach, est un DJ et producteur de techno né en 1984 et originaire de Berlin-Est. Il obtient sa première résidence au Zementgarten en 2006 et cofonde en 2009 Dystopian, d'abord une série de soirées berlinoises devenue un label. Son registre va de la techno dub et minimale à des sets plus sombres et atmosphériques.", en: "Rødhåd, real name Mike Bierbach, is a techno DJ and producer born in 1984 and from East Berlin. He landed his first residency at Zementgarten in 2006 and in 2009 co-founded Dystopian, first a series of Berlin parties that became a record label. His range runs from dub and minimal techno to darker, atmospheric sets." }, origin: "Berlin, Allemagne", since: 2006, labels: ["Dystopian"], sources: ["https://crackmagazine.net/article/long-reads/rodhad-dystopians-unstoppable-force/", "https://www.discogs.com/artist/2792304-Rødhåd"] }, // Rødhåd
  "rebko": { slug: "rebko", bio: { fr: "Rebko est le pseudonyme de Jan Rebensburg, DJ et producteur drum & bass de Cologne. Il entre dans la scène drum & bass locale en 2012 et cofonde la série de soirées DropThat. Ses sets naviguent entre neurofunk, liquid et dancefloor ; depuis 2020 il se consacre aussi à la production, avec un premier morceau, « Turn Off The Time », coécrit avec Jaycut.", en: "Rebko is the alias of Jan Rebensburg, a drum & bass DJ and producer from Cologne. He entered the city's drum & bass scene in 2012 and co-founded the DropThat party series. His sets move between neurofunk, liquid and dancefloor, and since 2020 he has also focused on production, starting with \"Turn Off The Time\" alongside Jaycut." }, origin: "Cologne, Allemagne", since: 2012, sources: ["https://www.mbartists.co.uk/paulo/rebko"] }, // Rebko
  "regi": { slug: "regi", bio: { fr: "Regi est le nom de scène de Regi Penxten, DJ et producteur belge né en 1976. Il est à l'origine de projets eurodance et trance comme Milk Inc. et Sylver, et a publié trois albums solo entrés dans le top dix belge : Best Of (2005), Registrated (2007) et Registrated 2 (2010).", en: "Regi is the stage name of Regi Penxten, a Belgian DJ and producer born in 1976. He is behind eurodance and trance projects such as Milk Inc. and Sylver, and has released three solo albums that reached the Belgian top ten: Best Of (2005), Registrated (2007) and Registrated 2 (2010)." }, origin: "Belgique", sources: ["https://en.wikipedia.org/wiki/Regi_Penxten"] }, // Regi
  "reinier-zonneveld": { slug: "reinier-zonneveld", bio: { fr: "Reinier Zonneveld est un DJ et producteur néerlandais né en 1991 à Alphen aan den Rijn. Pianiste depuis l'âge de trois ans, il étudie l'économétrie à Rotterdam avant de se tourner vers la techno ; son premier disque paraît sur le label Stil vor Talent d'Oliver Koletzki. Il joue et produit surtout de l'acid techno, se produit en live avec boîtes à rythmes et synthétiseurs, et dirige depuis 2017 le label Filth on Acid.", en: "Reinier Zonneveld is a Dutch DJ and producer born in 1991 in Alphen aan den Rijn. A pianist since the age of three, he studied econometrics in Rotterdam before turning to techno; his first record came out on Oliver Koletzki's Stil vor Talent label. He mainly plays and produces acid techno, performs live with drum machines and synthesisers, and has run the Filth on Acid label since 2017." }, origin: "Alphen aan den Rijn, Pays-Bas", since: 2011, labels: ["Filth on Acid"], sources: ["https://en.wikipedia.org/wiki/Reinier_Zonneveld"] }, // Reinier Zonneveld
  "rekkt": { slug: "rekkt", bio: { fr: "REKKT est un producteur et ingénieur du son belge de hard techno, qui mêle des influences hardcore, gabber et hardstyle. Il publie depuis 2022 sur Gearbox Overdrive, Barbaric Records, The Third Movement et PROCLAM, avec des titres comme « Make It Harder » (2022) et « We Die Alone » (2024).", en: "REKKT is a Belgian hard techno producer and sound engineer who blends hardcore, gabber and hardstyle influences. He has released since 2022 on Gearbox Overdrive, Barbaric Records, The Third Movement and PROCLAM, with tracks such as \"Make It Harder\" (2022) and \"We Die Alone\" (2024)." }, origin: "Belgique", since: 2022, labels: ["The Third Movement", "Gearbox Overdrive", "PROCLAM"], sources: ["https://rekkt.bandcamp.com/", "https://www.discogs.com/artist/7234547-REKKT"] }, // REKKT
  "rey-colino": { slug: "rey-colino", bio: { fr: "Rey Colino est le nom de scène de Colin Volvert, DJ et producteur belge né à Bruxelles. Il dirige le label Kalahari Oyster Cult et la structure de distribution vinyle One Eye Witness. Ses sets mêlent progressive house des années 1990, techno ambient, electro et acid.", en: "Rey Colino is the stage name of Colin Volvert, a Belgian DJ and producer born in Brussels. He runs the Kalahari Oyster Cult label and the vinyl distribution outfit One Eye Witness. His sets mix 1990s-leaning progressive house, ambient techno, electro and acid." }, origin: "Bruxelles, Belgique", labels: ["Kalahari Oyster Cult"], sources: ["https://www.electricsoul.com/artist/rey-colino", "https://musicbrainz.org/ws/2/artist/?query=artist:Rey%20Colino&fmt=json"] }, // Rey Colino
  "ricardo-villalobos": { slug: "ricardo-villalobos", bio: { fr: "Ricardo Villalobos est un producteur et DJ né au Chili en 1970, arrivé enfant en Allemagne où il vit depuis. Il publie ses premiers disques au milieu des années 1990 et s'impose dans la minimal techno et la microhouse, avec des morceaux qui s'étirent souvent au-delà de dix minutes. La compilation Salvador (2006) réunit plusieurs de ses maxis de l'époque.", en: "Ricardo Villalobos is a producer and DJ born in Chile in 1970 who moved to Germany as a child and has lived there since. He began releasing records in the mid-1990s and became a central name in minimal techno and microhouse, with tracks that often run well past ten minutes. The 2006 compilation Salvador collects several of his singles from that period." }, origin: "Santiago, Chili", since: 1993, sources: ["https://en.wikipedia.org/wiki/Ricardo_Villalobos", "https://www.wikidata.org/wiki/Q132415"] }, // Ricardo Villalobos
  "richie-hawtin": { slug: "richie-hawtin", bio: { fr: "Né en 1970 à Banbury en Angleterre et élevé à LaSalle, près de Windsor en Ontario, Richie Hawtin participe à la deuxième vague de la techno de Detroit au début des années 1990 et devient une référence de la techno minimale. Il enregistre sous les alias Plastikman et F.U.S.E., dont l'album « Dimension Intrusion » (1993) paraît dans la série Artificial Intelligence de Warp. Il cofonde le label Plus 8 avec John Acquaviva en 1990, lance M-nus en 1998, tient la soirée ENTER. au Space d'Ibiza de 2012 à 2015 et conçoit en 2016 la table de mixage MODEL 1.", en: "Born in Banbury, England in 1970 and raised in LaSalle, near Windsor, Ontario, Richie Hawtin took part in Detroit techno's second wave in the early 1990s and became a leading minimal techno figure. He records as Plastikman and F.U.S.E., the latter's album \"Dimension Intrusion\" (1993) appearing in Warp's Artificial Intelligence series. He co-founded the Plus 8 label with John Acquaviva in 1990, launched M-nus in 1998, ran the weekly ENTER. party at Space in Ibiza from 2012 to 2015, and designed the MODEL 1 mixer in 2016." }, origin: "Windsor, Canada", since: 1990, labels: ["Plus 8", "M-nus"], sources: ["https://en.wikipedia.org/wiki/Richie_Hawtin"] }, // Richie Hawtin
  "robbie-doherty": { slug: "robbie-doherty", bio: { fr: "Robbie Doherty est un DJ et producteur nord-irlandais basé à Belfast. Nourri de funk, de disco et de la house des années 1990, il se fait connaître en novembre 2019 avec « Pour The Milk », sorti sur Relentless/Cr2 Records. Il a ensuite publié l'EP « Moving Rhythms » sur le label amstellodamois PIV.", en: "Robbie Doherty is a Northern Irish DJ and producer based in Belfast. Raised on funk, disco and 1990s house, he broke through in November 2019 with \"Pour The Milk\", released on Relentless/Cr2 Records. He went on to release the \"Moving Rhythms\" EP on the Amsterdam label PIV." }, origin: "Belfast, Irlande du Nord", since: 2019, labels: ["Cr2 Records", "PIV"], sources: ["https://iamcru.com/get-to-know-belfast-based-dj-and-producer-robbie-doherty/", "https://www.discogs.com/artist/6930639-Robbie-Doherty-2"] }, // Robbie Doherty
  "robert-hood": { slug: "robert-hood", bio: { fr: "Robert Hood est un producteur et DJ américain né en 1965 à Détroit. Membre fondateur d'Underground Resistance aux côtés de Mad Mike Banks et Jeff Mills, il compte parmi les initiateurs de la techno minimale et a fondé le label M-Plant à Détroit en 1994.", en: "Robert Hood is an American producer and DJ born in 1965 in Detroit. A founding member of Underground Resistance alongside Mad Mike Banks and Jeff Mills, he is one of the originators of minimal techno and founded the M-Plant label in Detroit in 1994." }, origin: "Détroit, États-Unis", since: 1990, labels: ["M-Plant"], sources: ["https://en.wikipedia.org/wiki/Robert_Hood"] }, // Robert Hood
  "robot-rock-alive": { slug: "robot-rock-alive", bio: { fr: "Robot Rock Alive est un spectacle hommage à Daft Punk qui rejoue la tournée Alive 2007 : la pyramide, les casques et le répertoire du duo, interprétés en live sur machines avec lumières et visuels synchronisés. La production tourne en salles européennes, dont La Seine Musicale à Boulogne-Billancourt.", en: "Robot Rock Alive is a Daft Punk tribute show that recreates the Alive 2007 tour: the pyramid, the helmets and the duo's repertoire, performed live on hardware with synchronised lighting and visuals. The production tours European venues, including La Seine Musicale in Boulogne-Billancourt." }, sources: ["https://robotrock.live/", "https://www.laseinemusicale.com/spectacles-concerts/robot-rock-alive-daft-punk-tribute/"] }, // Robot Rock Alive
  "romare": { slug: "romare", bio: { fr: "Romare est le nom de scène d'Archie Fairhurst, producteur britannique. Après des études sur la culture visuelle afro-américaine, il commence à composer à partir de samples de vinyles d'occasion, signe chez Black Acre en 2012 puis chez Ninja Tune. Son premier album, Projections (2015), a été élu album de l'année par DJ Mag ; ont suivi Love Songs: Part Two (2016) et Home (2020).", en: "Romare is the stage name of Archie Fairhurst, a British producer. After studying African American visual culture, he began composing from second-hand vinyl samples, signing to Black Acre in 2012 and then to Ninja Tune. His debut album, Projections (2015), was voted album of the year by DJ Mag; Love Songs: Part Two (2016) and Home (2020) followed." }, origin: "Londres, Royaume-Uni", since: 2012, labels: ["Ninja Tune", "Black Acre"], sources: ["https://ninjatune.net/artist/romare"] }, // Romare
  "ron-trent": { slug: "ron-trent", bio: { fr: "Ronald Trent, né le 23 mai 1973 à Chicago, est un DJ et producteur américain de house. Il compte parmi les producteurs de la deep house de Chicago.", en: "Ronald Trent, born 23 May 1973 in Chicago, is an American house music DJ and record producer, part of the city's deep house lineage." }, origin: "Chicago, États-Unis", sources: ["https://en.wikipedia.org/wiki/Ron_Trent", "https://musicbrainz.org/artist/3af43a8a-f0b0-4dda-8cd8-ff4941c05316"] }, // Ron Trent
  "rooler": { slug: "rooler", bio: { fr: "Rooler est le nom de scène de Christopher Rossi, DJ et producteur italien né en 1994. Il produit du raw hardstyle, reconnaissable à ses kicks saturés et à ses ambiances sombres. Ses disques sont parus sur Spoontech Records, Dirty Workz, Intents Records et Q-dance, et il a signé avec Atmozfears « Into The Wild », hymne officiel de l'Intents Festival 2024. On lui doit aussi « Flyin' High » avec Warface et « Set Me Free » avec TNT.", en: "Rooler is the stage name of Christopher Rossi, an Italian DJ and producer born in 1994. He makes raw hardstyle, recognisable by its distorted kicks and dark atmospheres. His records have appeared on Spoontech Records, Dirty Workz, Intents Records and Q-dance, and with Atmozfears he wrote \"Into The Wild\", the official Intents Festival 2024 anthem. He is also behind \"Flyin' High\" with Warface and \"Set Me Free\" with TNT." }, origin: "Italie", since: 2015, labels: ["Spoontech Records", "Dirty Workz", "Intents Records"], sources: ["https://hardstyle.com/en/artists/rooler", "https://musicbrainz.org/artist/07b7e791-ccfa-4ec4-b2f9-e136d4cf0746"] }, // Rooler
  "roots-zombie": { slug: "roots-zombie", bio: { fr: "Roots Zombie est un projet français né entre Paris et Bordeaux en 2009. Venu du punk, le duo qualifie sa musique d'« electro voodoo dub » : dub, bass music et jungle, avec des influences reggae, hip-hop et musiques traditionnelles. Il joue aussi bien en live sur scène qu'en sound system.", en: "Roots Zombie is a French project started between Paris and Bordeaux in 2009. Coming from punk, the duo calls its music \"electro voodoo dub\": dub, bass music and jungle, with reggae, hip hop and traditional music influences. They play live on stage as well as on sound systems." }, origin: "Bordeaux, France", since: 2009, sources: ["https://rootszombie.bandcamp.com/", "https://musicbrainz.org/artist/04f94a42-8a15-4769-95ae-5a679c8534a8"] }, // Roots Zombie
  "rose": { slug: "rose", bio: { fr: "Rōse est une DJ et productrice suisse basée à Lausanne, habituée du D! Club. Ses sets couvrent la techno groovy, la hard techno, la tekno et la psytrance, entre 135 et 158 BPM. Elle dirige le label Alwarda Records et a cofondé l'association d'événements Vlast ; elle jouait au festival Paléo en juillet 2022.", en: "Rōse is a Swiss DJ and producer based in Lausanne and a regular at D! Club. Her sets span groovy techno, hard techno, tekno and psytrance, between 135 and 158 BPM. She runs the label Alwarda Records and co-founded the event association Vlast; she played the Paléo festival in July 2022." }, origin: "Lausanne, Suisse", labels: ["Alwarda Records"], sources: ["https://dclub.ch/artist/rose/", "https://www.blick.ch/fr/pop-culture/rose-dj-survoltee-a-paleo-jaime-lidee-detre-une-rose-qui-envoie-du-sale-id17658123.html"] }, // Rōse
  "row1": { slug: "row1", bio: { fr: "ROW1 est un DJ et producteur belge de hard dance, dont les sets combinent hard trance et percussions appuyées. Il a publié son premier single, « Packs », sur Tomorrowland Music.", en: "ROW1 is a Belgian hard dance DJ and producer whose sets combine hard trance with heavy percussion. He released his first single, \"Packs\", on Tomorrowland Music." }, origin: "Belgique", labels: ["Tomorrowland Music"], sources: ["https://www.ravejungle.com/2026/06/01/row1-packs-tomorrowland-music/", "https://www.paradisecity.be/en/bands/row1"] }, // Row1
  "royksopp": { slug: "royksopp", bio: { fr: "Röyksopp est un duo électronique norvégien formé en 1998 à Tromsø par Svein Berge et Torbjørn Brundtland. Leur premier album, Melody A.M. (2001), paraît chez Wall of Sound. Le duo a remporté sept Spellemannprisen et a été nommé deux fois aux Grammy Awards.", en: "Röyksopp are a Norwegian electronic duo formed in 1998 in Tromsø by Svein Berge and Torbjørn Brundtland. Their debut album, Melody A.M. (2001), came out on Wall of Sound. The duo have won seven Spellemannprisen awards and received two Grammy nominations." }, origin: "Tromsø, Norvège", since: 1998, labels: ["Wall of Sound"], sources: ["https://en.wikipedia.org/wiki/R%C3%B6yksopp"] }, // Röyksopp
  "roza-terenzi": { slug: "roza-terenzi", bio: { fr: "Roza Terenzi est l'alias de Katie Campbell, DJ et productrice australienne originaire de Perth, installée à Melbourne depuis 2017. Formée à la Western Australian Academy of the Performing Arts, elle a d'abord produit sous le nom de Catlips avant d'adopter en 2016 ce pseudonyme emprunté à l'astrophysicienne et musicienne italienne Fiorella Terenzi. Son premier album, Modern Bliss, est sorti en 2020.", en: "Roza Terenzi is the alias of Katie Campbell, an Australian DJ and producer originally from Perth who moved to Melbourne in 2017. Trained at the Western Australian Academy of the Performing Arts, she first produced as Catlips before taking on this name in 2016, borrowed from the Italian astrophysicist and musician Fiorella Terenzi. Her debut album, Modern Bliss, came out in 2020." }, origin: "Perth, Australie", since: 2016, sources: ["https://en.wikipedia.org/wiki/Roza_Terenzi"] }, // Roza Terenzi
  "ryan-dank": { slug: "ryan-dank", bio: { fr: "Ryan Dank est un DJ et producteur installé à Copenhague, membre du collectif LOVE STOMP et habitué du club Culture Box, pour lequel il a enregistré le podcast n° 55. Il joue une house organique, analogique et construite sur des échantillons.", en: "Ryan Dank is a DJ and producer based in Copenhagen, a member of the LOVE STOMP collective and a regular at the Culture Box club, for which he recorded podcast no. 55. He plays organic, analogue, sample-based house." }, origin: "Copenhague, Danemark", sources: ["https://culture-box.com/podcast/"] }, // Ryan Dank
  "ryan-elliott": { slug: "ryan-elliott", bio: { fr: "Ryan Elliott est un DJ et producteur américain originaire de Détroit, installé à Berlin. Analyste financier chez Ford le jour, il jouait le soir avec le collectif Spectral Sound avant de quitter les États-Unis en 2009. Devenu résident du Berghain / Panorama Bar, il mixe à la frontière de la house et de la techno et a sorti ses disques sur Ostgut Ton, Dekmantel, Innervisions et Rekids. Il a fondé son label Faith Beat en 2019.", en: "Ryan Elliott is an American DJ and producer from Detroit, based in Berlin. A financial analyst at Ford by day, he played at night with the Spectral Sound crew before leaving the United States in 2009. Now a resident at Berghain / Panorama Bar, he mixes on the line between house and techno and has released on Ostgut Ton, Dekmantel, Innervisions and Rekids. He founded his own label, Faith Beat, in 2019." }, origin: "Détroit, États-Unis", since: 2009, labels: ["Ostgut Ton", "Faith Beat"], sources: ["https://www.beatportal.com/articles/695100-keeping-faith-with-ryan-elliott-nine-acts-that-make-american-dance-music-move"] }, // Ryan Elliott
  "s-p-y": { slug: "s-p-y", bio: { fr: "S.P.Y est le nom de scène de Carlos Lima, producteur de drum & bass né le 30 décembre 1976 à São Paulo et installé à Londres. Ses disques paraissent principalement sur Hospital Records, entre liquid funk, neurofunk et jungle.", en: "S.P.Y is the stage name of Carlos Lima, a drum & bass producer born on 30 December 1976 in São Paulo and based in London. His records come out mainly on Hospital Records, between liquid funk, neurofunk and jungle." }, origin: "São Paulo, Brésil", labels: ["Hospital Records"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:S.P.Y&fmt=json", "https://api.discogs.com/database/search?artist=S.P.Y&type=release"] }, // S.P.Y
  "saar-kuus": { slug: "saar-kuus", bio: { fr: "Saar Kuus, de son vrai nom Sarah Kuus, est une DJ d'Amsterdam. Elle débute derrière les platines au Chicago Social Club au sein du Super Social Soundsystem, avec lequel elle joue à Amsterdam Open Air et Bungalup. Ses sets mêlent house, house minimale aux couleurs old-school et UK garage.", en: "Saar Kuus, born Sarah Kuus, is an Amsterdam DJ. She started behind the decks at Chicago Social Club with the Super Social Soundsystem, playing Amsterdam Open Air and Bungalup along the way. Her sets mix house, old-school-tinged minimal house and UK garage." }, origin: "Amsterdam, Pays-Bas", sources: ["https://rextheagency.com/saar-kuus/", "https://www.mysteryland.nl/act/saar-kuus"] }, // Saar Kuus
  "saltysis": { slug: "saltysis", bio: { fr: "SaltySis est une DJ et productrice allemande installée à Berlin. Elle joue à la jonction de la hard techno, du schranz, de la hard trance et du hardstyle, et pose ses propres voix sur ses productions. Elle a publié sur H33 Records, Sachsentrance et Whalien, et joué pour Blackworks, Dystopia et Technotrain.", en: "SaltySis is a German DJ and producer based in Berlin. She plays at the junction of hard techno, schranz, hard trance and hardstyle, and sings her own vocals on her productions. She has released on H33 Records, Sachsentrance and Whalien, and played for Blackworks, Dystopia and Technotrain." }, origin: "Berlin, Allemagne", labels: ["H33 Records", "Sachsentrance", "Whalien"], sources: ["https://hoer.live/artist/saltysis/", "https://www.ampliaberlin.com/artists/saltysis"] }, // SaltySis
  "sama-abdulhadi": { slug: "sama-abdulhadi", bio: { fr: "Sama' Abdulhadi est une DJ et productrice de techno palestinienne née en 1990 à Amman, en Jordanie, dans une famille palestinienne. Elle joue depuis 2010 et s'est fait connaître comme l'une des premières artistes techno issues de la scène palestinienne à tourner en Europe.", en: "Sama' Abdulhadi is a Palestinian techno DJ and producer born in 1990 in Amman, Jordan, to a Palestinian family. She has been performing since 2010 and became known as one of the first techno artists from the Palestinian scene to tour in Europe." }, origin: "Amman, Jordanie / Palestine", since: 2010, sources: ["https://en.wikipedia.org/wiki/Sama%CA%BC_Abdulhadi", "https://www.discogs.com/artist/8036010-Sama-Abdulhadi"] }, // Sama' Abdulhadi
  "sammy-virji": { slug: "sammy-virji", bio: { fr: "Sammy Virji, de son nom complet Samuel Bashir Virji, est un DJ et producteur britannique né le 30 septembre 1996. Né à Londres et élevé à Witney, il a quitté l'université de Newcastle pour la musique. Son album Spice Up My Life (2020) s'est classé 7e au UK Dance Albums Chart ; ses premiers morceaux relevaient de la bassline, les suivants de l'UK garage.", en: "Sammy Virji, full name Samuel Bashir Virji, is a British DJ and record producer born on 30 September 1996. Born in London and raised in Witney, he dropped out of Newcastle University to pursue music. His 2020 album Spice Up My Life reached No. 7 on the UK Dance Albums Chart; his earlier work belonged to bassline, his later work to UK garage." }, origin: "Londres, Royaume-Uni", since: 2017, sources: ["https://en.wikipedia.org/wiki/Sammy_Virji", "https://musicbrainz.org/ws/2/artist/?query=artist:Sammy%20Virji&fmt=json"] }, // Sammy Virji
  "samuel-moriero": { slug: "samuel-moriero", bio: { fr: "Samuel Moriero est un DJ et producteur italien de hard techno, qui a commencé à jouer à treize ans. Ses morceaux sont soutenus par I Hate Models, Sara Landry, Shlømo, Nico Moreno, Azyr, Omaks et Restricted.", en: "Samuel Moriero is an Italian hard techno DJ and producer who started playing at thirteen. His tracks are supported by I Hate Models, Sara Landry, Shlømo, Nico Moreno, Azyr, Omaks and Restricted." }, origin: "Italie", sources: ["https://www.warehouse-nantes.fr/artist/samuel-moriero"] }, // Samuel Moriero
  "sandrien": { slug: "sandrien", bio: { fr: "Sandrien van Rossum est une DJ et productrice d'Amsterdam active depuis 1999. Elle a été résidente du Trouw puis de De School, où elle a lancé en 2010 la soirée Imprint qui a accueilli Ben Sims, DVS1, Marcel Dettmann, Oscar Mulero et Rødhåd. Elle a longtemps travaillé dans les disquaires Rush Hour et Killacutz, et compte parmi les fondatrices de la série de soirées IsBurning.", en: "Sandrien van Rossum is a DJ and producer from Amsterdam, active since 1999. She was a resident of Trouw and later De School, where she launched the Imprint night in 2010, hosting Ben Sims, DVS1, Marcel Dettmann, Oscar Mulero and Rodhad. She worked for years in the Rush Hour and Killacutz record shops and co-founded the IsBurning party series." }, origin: "Amsterdam, Pays-Bas", since: 1999, sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/sandrien/7090/", "https://www.awakenings.com/en/artists/sandrien/1364/"] }, // Sandrien
  "sanem": { slug: "sanem", bio: { fr: "Sanem est une DJ suisse dont les sets croisent hard techno et psytrance : le kick sec de l'une et les nappes trippantes de l'autre, à tempo rapide. Elle a grandi en Suisse et s'est tournée tôt vers les musiques électroniques.", en: "Sanem is a Swiss DJ whose sets cross hard techno with psytrance: the dry kick of one and the trippy layers of the other, at pace. She grew up in Switzerland and turned to electronic music early." }, origin: "Suisse", sources: ["https://ra.co/dj/sanem/biography", "https://bugece.co/en/artist/sanem--78ba554c"] }, // Sanem
  "saoirse": { slug: "saoirse", bio: { fr: "DJ et productrice irlandaise formée à Dublin, Saoirse débute sur les radios pirates locales et dans les soirées hard house et trance avant de quitter un poste chez Resident Advisor pour la musique. Elle publie les EP trUst 001 et Two Bruised Egos, tient une résidence house sur Rinse FM, et dirige le label et la soirée trUst Recordings. Ses sets circulent entre house, techno, garage et bass.", en: "An Irish DJ and producer who came up in Dublin, Saoirse started out on local pirate radio and in hard house and trance parties before leaving a job at Resident Advisor for music. She released the EPs trUst 001 and Two Bruised Egos, held a house-focused residency on Rinse FM, and runs the trUst Recordings label and party. Her sets move between house, techno, garage and bass." }, origin: "Dublin, Irlande", labels: ["trUst Recordings"], sources: ["https://djmag.com/cover-features/saoirse-body-mover", "https://mixmag.net/feature/saoirse-interview", "https://www.awakenings.com/en/artists/saorise/345894/"] }, // Saoirse
  "sara-landry": { slug: "sara-landry", bio: { fr: "Sara Landry, née le 22 septembre 1993 à Sausalito en Californie, est une DJ et productrice américaine installée à Amsterdam depuis 2022. Elle joue une hard techno industrielle sombre et se présente comme productrice et ingénieure du son autodidacte. En juillet 2021, elle a fondé son label Hekate Records, qui publie notamment Nico Moreno, Shlømo et Charlie Sparks. Elle est entrée au Top 100 DJs de DJ Mag en 2024, à la 75e place.", en: "Sara Landry, born 22 September 1993 in Sausalito, California, is an American DJ and producer who has been based in Amsterdam since 2022. She plays dark, industrial hard techno and describes herself as a self-taught producer and audio engineer. In July 2021 she founded her label Hekate Records, which releases artists including Nico Moreno, Shlømo and Charlie Sparks. She entered DJ Mag's Top 100 DJs at number 75 in 2024." }, origin: "Sausalito, États-Unis", since: 2018, labels: ["Hekate Records"], sources: ["https://en.wikipedia.org/wiki/Sara_Landry"] }, // Sara Landry
  "sasha": { slug: "sasha", bio: { fr: "Alexander Paul Coe, connu sous le nom de Sasha, est un DJ et producteur gallois né le 4 septembre 1969 à Bangor. Il forme avec John Digweed le duo Sasha & John Digweed. Sa discographie relève surtout de la progressive house et de la progressive trance.", en: "Alexander Paul Coe, known as Sasha, is a Welsh DJ and record producer born on 4 September 1969 in Bangor. He forms the duo Sasha & John Digweed with John Digweed. His catalogue is mostly progressive house and progressive trance." }, origin: "Bangor, Pays de Galles", sources: ["https://en.wikipedia.org/wiki/Sasha_(DJ)", "https://musicbrainz.org/artist/68be8273-cb12-4053-964d-157b7e5cf265", "https://api.discogs.com/database/search?artist=Sasha&type=release&per_page=50"] }, // Sasha
  "scientyfreaks": { slug: "scientyfreaks", bio: { fr: "Scientyfreaks est le projet solo de Seb, ingénieur du son, compositeur et batteur du groupe de natural trance Hilight Tribe. Son travail associe une expérience du break beat et de l'abstract techno à un goût pour la trance progressive et les musiques du monde, avec des beats appuyés sur des mélodies et des motifs ethniques. Il se produit régulièrement en France, notamment aux côtés d'Hilight Tribe.", en: "Scientyfreaks is the solo project of Seb, a sound engineer, composer and the drummer of the natural trance band Hilight Tribe. His work pairs a background in break beat and abstract techno with a taste for progressive trance and world music, laying heavy beats under melodies and ethnic motifs. He plays regularly in France, often alongside Hilight Tribe." }, origin: "France", sources: ["https://lautrecanalnancy.fr/scientyfreaks", "https://stereolux.org/agenda/hilight-tribe-scientyfreaks"] }, // Scientyfreaks
  "scooter": { slug: "scooter", bio: { fr: "Groupe allemand formé à Hambourg en 1993 autour du chanteur H. P. Baxxter, passé de la techno hardcore à la happy hardcore et à l'eurodance. « Hyper Hyper » (1994), « How Much Is the Fish? » et « Nessaja » comptent parmi ses succès, pour plus de 30 millions de disques vendus. Le groupe découpe sa carrière en « chapitres », le septième ayant débuté fin 2022.", en: "German band formed in Hamburg in 1993 around singer H. P. Baxxter, moving from hardcore techno into happy hardcore and Eurodance. \"Hyper Hyper\" (1994), \"How Much Is the Fish?\" and \"Nessaja\" are among their hits, for over 30 million records sold. The band splits its career into \"chapters\", the seventh of which began in late 2022." }, origin: "Hambourg, Allemagne", since: 1993, labels: ["Sheffield Tunes"], sources: ["https://en.wikipedia.org/wiki/Scooter_(band)"] }, // Scooter
  "scott-steer": { slug: "scott-steer", bio: { fr: "Scott Steer est un DJ et producteur de house originaire du sud-est de Londres, âgé de 22 ans. Ses morceaux et ses edits, construits sur des lignes de basse marquées, ont été soutenus par Chris Stussy et Max Dean. Il a sorti « Style » sur Dionysus Records, « Surrounding Me » sur Groove Cartel Records et « Wanna Feel » sur Creamfields Recordings.", en: "Scott Steer is a 22-year-old house DJ and producer from South-East London. His tracks and edits, built on prominent basslines, have been supported by Chris Stussy and Max Dean. He has released \"Style\" on Dionysus Records, \"Surrounding Me\" on Groove Cartel Records and \"Wanna Feel\" on Creamfields Recordings." }, origin: "Londres, Royaume-Uni", labels: ["Creamfields Recordings", "Dionysus Records", "Groove Cartel Records"], sources: ["https://www.creamfieldsrecordings.com/artists/scottsteer"] }, // Scott Steer
  "sebastian": { slug: "sebastian", bio: { fr: "Sébastien Akchoté-Božović, né le 3 février 1981 à Boulogne-Billancourt, produit sous le nom SebastiAn et est affilié au label Ed Banger Records. Sa musique relève de l'electro house, de l'electro et de la house. Il a remixé Daft Punk, Charlotte Gainsbourg, Beastie Boys, Bloc Party et Nero, produit pour Frank Ocean, Kavinsky, Uffie, Juliette Armanet et Woodkid, et composé les bandes originales des films « Notre jour viendra » et « Le monde est à toi ».", en: "Sébastien Akchoté-Božović, born 3 February 1981 in Boulogne-Billancourt, records as SebastiAn and is affiliated with Ed Banger Records. His music is described as electro house, electro and house. He has remixed Daft Punk, Charlotte Gainsbourg, Beastie Boys, Bloc Party and Nero, produced for Frank Ocean, Kavinsky, Uffie, Juliette Armanet and Woodkid, and scored the films \"Our Day Will Come\" and \"The World Is Yours\"." }, origin: "Boulogne-Billancourt, France", labels: ["Ed Banger Records"], sources: ["https://en.wikipedia.org/wiki/Sebastian_(French_musician)"] }, // SebastiAn
  "seconds-setaoc-mass-phara": { slug: "seconds-setaoc-mass-phara", bio: { fr: "SECONDS est l'alias commun des producteurs techno Setaoc Mass et Phara, née d'années de sets en back-to-back, notamment au Fuse de Bruxelles où Phara est résidente. Le duo réserve le projet à des sets longs sur des scènes choisies, avec un label dédié à leurs productions communes.", en: "SECONDS is the joint alias of techno producers Setaoc Mass and Phara, grown out of years of back-to-back sets, notably at Brussels club Fuse where Phara is a resident. The duo reserves the project for extended sets on selected stages, with a label dedicated to their shared productions." }, since: 2025, sources: ["https://midnightdancemusic.com/phara-y-setaoc-mass-fusionan-sus-venerados-estilos-techno-en-el-nuevo-alias-duo-seconds/"] }, // SECONDS (Setaoc Mass & Phara)
  "see-rose": { slug: "see-rose", bio: { fr: "Batteur et guitariste avant de passer aux musiques électroniques, See Rose a fondé les associations FFLAND Festival et LES FFRIDAYS Électro. Son univers est centré sur la trance et la hardtrance, avec des sets construits en montée et des mélodies euphorisantes. Il joue notamment au Warehouse de Nantes.", en: "A drummer and guitarist before he moved to electronic music, See Rose founded the FFLAND Festival and LES FFRIDAYS Électro associations. His sets are built around trance and hard trance, gradual in construction and euphoric in melody. He plays at the Warehouse in Nantes among other venues." }, origin: "Nantes, France", sources: ["https://www.warehouse-nantes.fr/artist/see-rose/"] }, // See Rose
  "serafina": { slug: "serafina", bio: { fr: "Serafina est une DJ allemande basée à Hambourg, où elle a commencé à mixer en 2023. Elle a d'abord joué une techno industrielle très frontale, portée par des basses lourdes, avant d'élargir ses sets à un versant plus rapide et mélodique. Elle tourne depuis sur le circuit européen, notamment pour Awakenings.", en: "Serafina is a German DJ based in Hamburg, where she started playing out in 2023. She built her sets on blunt, bass-heavy industrial techno before widening them towards a faster, more melodic register. She now works the European circuit, including for Awakenings." }, origin: "Hambourg, Allemagne", since: 2023, sources: ["https://framedagency.au/artists/serafina", "https://www.awakenings.com/en/artists/serafina/386088/"] }, // Serafina
  "seth-troxler": { slug: "seth-troxler", bio: { fr: "Seth Troxler est un DJ et producteur américain originaire de Lake Orion, dans le Michigan. Ses sets tournent autour de la house et de la techno, et il a publié sur Wolf + Lamb, Crosstown Rebels et Circus Company, en collaborant notamment avec Art Department, Deetron, Tiefschwarz et Matthew Dear. Il a cofondé le label Visionquest et dirige Tuskegee, Soft Touch et Play It, Say It.", en: "Seth Troxler is an American DJ and producer from Lake Orion, Michigan. His sets revolve around house and techno, and he has released on Wolf + Lamb, Crosstown Rebels and Circus Company, working with Art Department, Deetron, Tiefschwarz and Matthew Dear. He co-founded the Visionquest label and runs Tuskegee, Soft Touch and Play It, Say It." }, origin: "Lake Orion, Michigan, États-Unis", labels: ["Visionquest", "Tuskegee", "Play It, Say It"], sources: ["https://en.wikipedia.org/wiki/Seth_Troxler"] }, // Seth Troxler
  "shae-reid": { slug: "shae-reid", bio: { fr: "Shae Reid est une DJ et productrice installée à Londres. Elle a joué pour Defected, PIV et Más Tiempo, et fait partie de la résidence Club Room de Más Tiempo au Hï Ibiza, les samedis de Black Coffee. Son premier single, « Let's Dance », a été soutenu par Jamie Jones, Vintage Culture et Skepta.", en: "Shae Reid is a DJ and producer based in London. She has played for Defected, PIV and Más Tiempo, and is part of the Más Tiempo Club Room residency at Hï Ibiza on Black Coffee's Saturdays. Her first single, 'Let's Dance', drew support from Jamie Jones, Vintage Culture and Skepta." }, origin: "Londres, Royaume-Uni", sources: ["https://www.a-listmgmt.com/shae-reid", "https://www.ibiza-spotlight.com/magazine/2025/05/caught-in-the-moment-030-shae-reid-hi-ibiza"] }, // Shae Reid
  "shanti-celeste": { slug: "shanti-celeste", bio: { fr: "Shanti Celeste est une DJ, productrice et illustratrice née le 20 octobre 1988 à Temuco, au Chili. Installée à Londres après des années à Bristol, elle dirige le label Peach Discs. Sa musique est rattachée à la house, à la techno, à l'electro et à l'ambient ; son premier album, « Tangerine », est paru en 2019.", en: "Shanti Celeste is a DJ, producer and illustrator born on 20 October 1988 in Temuco, Chile. Based in London after years in Bristol, she runs the Peach Discs label. Her music is associated with house, techno, electro and ambient; her debut album, \"Tangerine\", came out in 2019." }, origin: "Temuco, Chili / Londres", labels: ["Peach Discs"], sources: ["https://en.wikipedia.org/wiki/Shanti_Celeste", "https://www.discogs.com/artist/3416319-Shanti-Celeste"] }, // Shanti Celeste
  "she-her": { slug: "she-her", bio: { fr: "SHE/HER est le nom de scène de Kim Vereijken, DJ techno néerlandaise de Bois-le-Duc, aux platines depuis 2020. Elle joue une techno rapide et roulante, construite sur la progression du rythme, et est résidente de Vulged à Amsterdam. Elle s'est produite pour Vault Sessions, Intercell, Radion, Bret et Basis.", en: "SHE/HER is the stage name of Kim Vereijken, a Dutch techno DJ from 's-Hertogenbosch, behind the decks since 2020. She plays fast, rolling techno built on rhythmic progression, and is a resident at Vulged in Amsterdam. She has played for Vault Sessions, Intercell, Radion, Bret and Basis." }, origin: "Bois-le-Duc, Pays-Bas", since: 2020, sources: ["https://www.awakenings.com/en/artists/she-her/386449/", "https://www.djguide.nl/djinfo.p?djid=9967&language=en"] }, // SHE/HER
  "sherelle": { slug: "sherelle", bio: { fr: "Sherelle est le nom de scène de Sherelle Camille Thomas, DJ et musicienne britannique. Venue du dancehall et de la culture rave, elle est connue pour ses sets et ses mixes à haut tempo. Elle a cofondé le label Hooversound avec Naina, et fondé Beautiful, label et projet musical dédié aux artistes noirs et LGBT.", en: "Sherelle is the stage name of Sherelle Camille Thomas, a British DJ and electronic musician. Coming out of dancehall and rave culture, she is known for her high-tempo sets and mixes. She co-founded the Hooversound label with Naina, and founded Beautiful, a label and musical project for Black and LGBT artists." }, origin: "Londres, Royaume-Uni", labels: ["Hooversound", "Beautiful"], sources: ["https://en.wikipedia.org/wiki/Sherelle"] }, // Sherelle
  "shlmo": { slug: "shlmo", bio: { fr: "Shlømo est le nom de scène de Shaun Baron-Carvais, producteur et DJ techno français. Il fonde le label Taapion Records en 2013, puis SAIKE en 2022, et publie en 2018 un premier album, « Mercurial Skin », qui s'écarte de la techno de club vers l'ambient et l'IDM. Depuis 2023, il fait tourner sa propre série de soirées, Welcome Back Devil.", en: "Shlømo is the stage name of Shaun Baron-Carvais, a French techno producer and DJ. He founded the label Taapion Records in 2013, then SAIKE in 2022, and released a first album in 2018, \"Mercurial Skin\", which stepped away from club techno towards ambient and IDM. Since 2023 he has toured his own event series, Welcome Back Devil." }, origin: "Paris, France", since: 2013, labels: ["Taapion Records", "SAIKE"], sources: ["https://djmag.com/news/criminal-complaint-filed-against-shlomo-paris-court", "https://mnmt.no/magazine/2018/04/07/shlomo/"] }, // Shlømo
  "shygirl": { slug: "shygirl", bio: { fr: "Shygirl est le nom de scène de Blane Muise, chanteuse, rappeuse et DJ britannique née à Londres en 1993, cofondatrice du label et collectif Nuxxe. Sa musique mêle dance, hip-hop, pop expérimentale, grime et club déconstruit. Son premier album, « Nymph », paraît en 2022 ; l'EP « Club Shy », sorti en 2024 sur Because Music, réécrit des tubes dance des années 1990 et 2000 et a donné naissance à une série de soirées du même nom.", en: "Shygirl is the stage name of Blane Muise, a British singer, rapper and DJ born in London in 1993 and co-founder of the Nuxxe label and collective. Her music mixes dance, hip-hop, experimental pop, grime and deconstructed club. Her debut album \"Nymph\" came out in 2022; the \"Club Shy\" EP, released in 2024 on Because Music, reworks dance hits from the 1990s and 2000s and gave its name to a series of club nights." }, origin: "Londres, Angleterre", since: 2016, labels: ["Nuxxe", "Because Music"], sources: ["https://en.wikipedia.org/wiki/Shygirl", "https://en.wikipedia.org/wiki/Club_Shy"] }, // Shygirl
  "sigma": { slug: "sigma", bio: { fr: "Sigma est un duo britannique de drum and bass formé en 2007 par Cameron Edwards et Joe Lenzie, qui se sont rencontrés à l'université de Leeds lors de soirées drum and bass avant de s'installer à Londres. Après des sorties sur Hospital Records et Breakbeat Kaos, leur signature chez 3 Beat Records en 2013 les a menés à deux numéros un consécutifs au Royaume-Uni : « Nobody to Love » puis « Changing » avec Paloma Faith, tous deux en 2014. Ont suivi « Higher » avec Labrinth et « Glitterball » avec Ella Henderson en 2015.", en: "Sigma are a British drum and bass duo formed in 2007 by Cameron Edwards and Joe Lenzie, who met at drum and bass nights while studying at Leeds University before moving to London. After releases on Hospital Records and Breakbeat Kaos, signing to 3 Beat Records in 2013 took them to two consecutive UK number ones: \"Nobody to Love\" and then \"Changing\" with Paloma Faith, both in 2014. \"Higher\" with Labrinth and \"Glitterball\" with Ella Henderson followed in 2015." }, origin: "Harpenden, Royaume-Uni", since: 2007, labels: ["3 Beat Records", "Hospital Records"], sources: ["https://en.wikipedia.org/wiki/Sigma_(group)"] }, // Sigma
  "silva-bumpa": { slug: "silva-bumpa", bio: { fr: "Silva Bumpa est un producteur et DJ né à Sheffield. Initié au piano par son grand-père, il produit depuis ses quinze ans et puise dans l'héritage bassline, house et speed garage de sa ville. Son premier EP, What About The DJ?, est sorti sur Locked On Records ; il a été élu Breakthrough DJ aux Best of British Awards 2025 de DJ Mag.", en: "Silva Bumpa is a producer and DJ born in Sheffield. Taught piano by his grandfather, he has been producing since he was fifteen and draws on his city's bassline, house and speed garage legacy. His debut EP What About The DJ? came out on Locked On Records, and he was named Breakthrough DJ at DJ Mag's 2025 Best of British Awards." }, origin: "Sheffield, Royaume-Uni", labels: ["Locked On Records"], sources: ["https://djmag.com/features/fresh-kicks-209-silva-bumpa"] }, // Silva Bumpa
  "skarn": { slug: "skarn", bio: { fr: "Skarn, de son vrai nom Emil Frilund, est un DJ danois résident du Culture Box de Copenhague. Il joue depuis 2007, d'abord dans les clubs de la capitale alors qu'il est encore lycéen. Son premier titre, « Sknof », coécrit avec Denis Horvat, est sorti sur Innervisions.", en: "Skarn, born Emil Frilund, is a Danish DJ and a resident of Copenhagen's Culture Box. He has played since 2007, starting in the city's clubs while still at school. His first track, 'Sknof', made with Denis Horvat, came out on Innervisions." }, origin: "Copenhague, Danemark", since: 2007, sources: ["https://ra.co/dj/skarn", "https://culture-box.com/podcast/"] }, // Skarn
  "skepta": { slug: "skepta", bio: { fr: "Skepta, de son vrai nom Joseph Junior Adenuga, est un rappeur, MC et producteur anglais né le 19 septembre 1982 à Tottenham, membre du collectif Boy Better Know et venu du grime. Avec Jammer, il a lancé Más Tiempo, un label et une marque de soirées consacrés à la house, prolongés par une résidence estivale au Hï Ibiza.", en: "Skepta, born Joseph Junior Adenuga on 19 September 1982 in Tottenham, is an English rapper, MC and producer, a member of the Boy Better Know collective who came up through grime. With Jammer he launched Más Tiempo, a house-focused label and party brand, extended by a summer residency at Hï Ibiza." }, origin: "Tottenham, Londres, Royaume-Uni", labels: ["Boy Better Know", "Más Tiempo"], sources: ["https://mixmag.net/read/skepta-jammer-house-label-mas-tiempo-mas-murder-ep-news", "https://www.hiibiza.com/artists/2026/skepta", "https://en.wikipedia.org/wiki/Skepta"] }, // Skepta
  "skream": { slug: "skream", bio: { fr: "Skream, de son vrai nom Oliver Dene Jones, est un DJ et producteur anglais né le 1er juin 1986 à West Wickham, dans le sud de Londres. Figure des débuts du dubstep sur le label Tempa et membre du groupe Magnetic Man, il s'est réorienté à partir de 2013 vers la house et le disco, qui constituent aujourd'hui l'essentiel de ses sets.", en: "Skream, real name Oliver Dene Jones, is an English DJ and producer born on 1 June 1986 in West Wickham, south London. A figure of dubstep's early days on the Tempa label and a member of the group Magnetic Man, he shifted from 2013 onwards towards house and disco, which now make up most of his sets." }, origin: "Londres, Royaume-Uni", since: 2002, labels: ["Tempa", "Tectonic", "Deep Medi Musik"], sources: ["https://en.wikipedia.org/wiki/Skream", "https://www.discogs.com/artist/189821-Skream"] }, // Skream
  "skream-benga": { slug: "skream-benga", bio: { fr: "Skream et Benga se rencontrent adolescents au disquaire Big Apple Records de Croydon, foyer du dubstep londonien. Ils sortent « The Judgement » sous ce nom commun en 2003, puis forment avec Artwork le trio Magnetic Man, dont l'album éponyme paraît chez Columbia en 2010 et le single « I Need Air » atteint la 10e place au Royaume-Uni. Ils se remettent à produire ensemble à partir de 2022.", en: "Skream and Benga met as teenagers at the Big Apple Records shop in Croydon, the home of London dubstep. They released \"The Judgement\" under that shared name in 2003, then formed the trio Magnetic Man with Artwork, whose self-titled album came out on Columbia in 2010 and whose single \"I Need Air\" reached number 10 in the UK. They returned to producing together from 2022." }, origin: "Croydon, Royaume-Uni", since: 2003, sources: ["https://en.wikipedia.org/wiki/Magnetic_Man", "https://www.nme.com/news/music/dubstep-pioneers-skream-and-benga-are-returning-in-2022-3131546"] }, // Skream & Benga
  "skrillex": { slug: "skrillex", bio: { fr: "Sonny Moore, né en 1988 à Los Angeles, a d'abord chanté dans le groupe post-hardcore From First to Last avant d'adopter l'alias Skrillex en 2008. Son dubstep saturé, lancé par l'EP Scary Monsters and Nice Sprites (2010) puis Bangarang (2011), lui a valu neuf Grammy Awards. Il a fondé le label OWSLA en 2011 et publié en 2023 les albums Quest for Fire et Don't Get Too Close.", en: "Sonny Moore, born in Los Angeles in 1988, first sang in the post-hardcore band From First to Last before taking the Skrillex alias in 2008. His saturated dubstep, launched by the EP Scary Monsters and Nice Sprites (2010) then Bangarang (2011), has earned him nine Grammy Awards. He founded the OWSLA label in 2011 and released the albums Quest for Fire and Don't Get Too Close in 2023." }, origin: "Los Angeles, États-Unis", since: 2008, labels: ["OWSLA"], sources: ["https://en.wikipedia.org/wiki/Skrillex"] }, // Skrillex
  "slvl": { slug: "slvl", bio: { fr: "SLVL est un DJ et producteur néerlandais de Maastricht, apparu sur la scène en 2022. Il joue une hard techno industrielle bâtie sur des kicks très saturés, ce qui lui vaut le surnom de « The Kick Dealer », et a fondé le label Altruism Records. Il a joué au Rotterdam Rave, à Verknipt, au Duro Festival et à Free Your Mind.", en: "SLVL is a Dutch DJ and producer from Maastricht who emerged in 2022. He plays industrial hard techno built on heavily saturated kicks, which earned him the nickname \"The Kick Dealer\", and founded the label Altruism Records. He has played Rotterdam Rave, Verknipt, Duro Festival and Free Your Mind." }, origin: "Maastricht, Pays-Bas", since: 2022, labels: ["Altruism Records"], sources: ["https://www.nxnewcastle.com/events/slush/"] }, // SLVL
  "snts": { slug: "snts", bio: { fr: "SNTS est un producteur et DJ de techno allemand, masqué et resté anonyme depuis ses débuts en 2012. Il a publié des disques sur Edit Select, Horizontal Ground, Token, Soma et Stroboscopic Artefacts, et dirige ses propres labels SNTS Records et Sacred Court. Son répertoire va de la techno industrielle à l'ambient et l'electro.", en: "SNTS is a masked German techno producer and DJ who has stayed anonymous since debuting in 2012. He has released on Edit Select, Horizontal Ground, Token, Soma and Stroboscopic Artefacts, and runs his own labels SNTS Records and Sacred Court. His output ranges from industrial techno to ambient and electro." }, origin: "Allemagne", since: 2012, labels: ["SNTS Records", "Sacred Court"], sources: ["https://djmag.com/news/snts-drops-dark-dusty-techno-figures-mist-premiere"] }, // SNTS
  "sofia-kourtesis": { slug: "sofia-kourtesis", bio: { fr: "Sofia Kourtesis est une DJ et productrice péruvienne née le 18 août 1985 à Lima et installée à Berlin. Sa musique relève de la house, de la deep house et de la microhouse, avec des éléments latino-américains.", en: "Sofia Kourtesis is a Peruvian DJ and producer born on 18 August 1985 in Lima and based in Berlin. Her music is house, deep house and microhouse, with Latin American elements." }, origin: "Lima, Pérou", sources: ["https://en.wikipedia.org/wiki/Sofia_Kourtesis", "https://musicbrainz.org/artist/2f8d2007-7666-45af-89d4-dec4921dce04", "https://api.discogs.com/database/search?artist=Sofia+Kourtesis&type=release&per_page=50"] }, // Sofia Kourtesis
  "solomun": { slug: "solomun", bio: { fr: "Mladen Solomun, connu sous le nom de Solomun, est un DJ et producteur bosno-allemand né le 27 décembre 1975 à Travnik et élevé à Hambourg. Il fonde fin 2005 le label Diynamic avec Adriano Trolio, puis le label plus expérimental 2DIY4 en 2010. Son remix d'Around de Noir & Haze, sorti en 2011, a été élu meilleur remix de l'année par Resident Advisor.", en: "Mladen Solomun, known as Solomun, is a Bosnian-German DJ and producer born on 27 December 1975 in Travnik and raised in Hamburg. He founded the Diynamic label with Adriano Trolio at the end of 2005, then the more experimental 2DIY4 in 2010. His 2011 remix of Noir & Haze's \"Around\" was voted remix of the year by Resident Advisor." }, origin: "Travnik, Bosnie-Herzégovine / Hambourg, Allemagne", since: 2005, labels: ["Diynamic", "2DIY4"], sources: ["https://fr.wikipedia.org/wiki/Solomun", "https://en.wikipedia.org/wiki/Solomun_(musician)"] }, // Solomun
  "sonny-fodera": { slug: "sonny-fodera", bio: { fr: "DJ et producteur house australien né à Adélaïde en 1985, installé à Londres. Venu à la house après avoir vu jouer Derrick Carter en club, il a sorti sur Defected et Cajual avant de fonder son propre label Solotoko début 2017. « One Night » avec MK (2019) et « Somedays » avec Jazzy et D.O.D. (2025) figurent parmi ses titres certifiés au Royaume-Uni.", en: "Australian house DJ and producer, born in Adelaide in 1985 and based in London. He turned to house after seeing Derrick Carter play in a club, released on Defected and Cajual, then founded his own Solotoko label in early 2017. \"One Night\" with MK (2019) and \"Somedays\" with Jazzy and D.O.D. (2025) are among his UK-certified tracks." }, origin: "Adélaïde, Australie", labels: ["Solotoko", "Defected"], sources: ["https://en.wikipedia.org/wiki/Sonny_Fodera"] }, // Sonny Fodera
  "sound-rush": { slug: "sound-rush", bio: { fr: "Sound Rush est un duo hardstyle néerlandais formé par les frères Jeroen et Martijn Boeren. Leur discographie est presque entièrement hardstyle, avec quelques titres happy hardcore et hardcore.", en: "Sound Rush are a Dutch hardstyle duo made up of brothers Jeroen and Martijn Boeren. Their catalogue is almost entirely hardstyle, with a few happy hardcore and hardcore tracks." }, origin: "Pays-Bas", sources: ["https://musicbrainz.org/artist/72d65c02-1b1f-4458-9ab8-6544eea4bdf0", "https://api.discogs.com/database/search?artist=Sound+Rush&type=release&per_page=50"] }, // Sound Rush
  "space-92": { slug: "space-92", bio: { fr: "Space 92 est le projet techno de Mathieu Mourareau, producteur français qui a grandi à Carcassonne. Après une dizaine d'années sous le nom Matt Minimal, il lance Space 92 en 2019 avec « Another Galaxy » : une techno mélodique et trancey, percussions saturées et nappes de synthé nourries de science-fiction des années 1980. « Planet X », avec The YellowHeads, est resté sept semaines en tête du classement techno de Beatport, où il fut l'artiste techno le plus vendu de 2020.", en: "Space 92 is the techno project of Mathieu Mourareau, a French producer who grew up in Carcassonne. After roughly a decade as Matt Minimal, he launched Space 92 in 2019 with \"Another Galaxy\": melodic, trance-leaning techno with distorted percussion and synth pads fed by 1980s science fiction. \"Planet X\", with The YellowHeads, spent seven weeks at number one on Beatport's techno chart, where he was the best-selling techno artist of 2020." }, origin: "Carcassonne, France", since: 2019, labels: ["Perfekt Groove Recordings", "Filth On Acid", "1605"], sources: ["https://www.beatportal.com/articles/12120-introducing-space-92-technos-new-cosmic-champion"] }, // Space 92
  "speedwagon": { slug: "speedwagon", bio: { fr: "Speedwagon est un DJ et producteur de drum & bass originaire de Louvain, en Belgique, actif depuis une quinzaine d'années sur la scène belge. Il joue l'ensemble des sous-genres de la drum & bass, des festivals aux maisons de jeunes. Il a participé à l'organisation du festival gratuit en plein air Nightscapes entre 2000 et 2007.", en: "Speedwagon is a drum & bass DJ and producer from Leuven, Belgium, active on the Belgian scene for some fifteen years. He plays across the drum & bass subgenres, from festivals to youth clubs, and was involved in running the free open-air festival Nightscapes between 2000 and 2007." }, origin: "Louvain, Belgique", sources: ["https://api.discogs.com/artists/5492325", "https://soundcloud.com/speedwagonconform"] }, // Speedwagon
  "speedy-j": { slug: "speedy-j", bio: { fr: "Speedy J est le nom de scène de Jochem Paap, producteur néerlandais né en 1969 à Rotterdam. Son morceau « Pullover » (1992) le fait connaître, et il publie ensuite chez Warp Records, notamment dans la série Artificial Intelligence et avec l'album Ginger en 1993.", en: "Speedy J is the stage name of Jochem Paap, a Dutch producer born in 1969 in Rotterdam. His 1992 track \"Pullover\" brought him recognition, and he went on to release on Warp Records, including in the Artificial Intelligence series and with the 1993 album Ginger." }, origin: "Rotterdam, Pays-Bas", since: 1992, labels: ["Warp Records", "Plus 8", "Electric Deluxe"], sources: ["https://en.wikipedia.org/wiki/Speedy_J"] }, // Speedy J
  "spfdj": { slug: "spfdj", bio: { fr: "SPFDJ est le nom de scène de Lina Jonsson, DJ suédoise installée à Berlin. Elle s'est fait connaître dans la scène londonienne avec les soirées Universe of Tang avant de devenir résidente des Herrensauna berlinoises. Elle joue une techno rapide traversée d'acid, d'EBM et d'influences industrielles, et a fondé en décembre 2018 le label Intrepid Skin, qui a notamment publié Nene H.", en: "SPFDJ is the stage name of Lina Jonsson, a Swedish DJ based in Berlin. She made her name in London through the Universe of Tang parties before becoming a resident at Berlin's Herrensauna. She plays fast techno shot through with acid, EBM and industrial influences, and in December 2018 founded the Intrepid Skin label, which has released Nene H among others." }, origin: "Berlin, Allemagne", since: 2018, labels: ["Intrepid Skin"], sources: ["https://www.electronicbeats.net/an-interview-with-spfdj"] }, // SPFDJ
  "spoink": { slug: "spoink", bio: { fr: "Spoink est un quartet de musique électronique improvisée né à l'été 2019 dans l'est parisien. Son live est intégralement improvisé, joué sur instruments, et traverse techno, drum & bass, dubstep et touches rock. Le groupe a publié l'album Sharp en janvier 2023 et compte plus de 160 concerts en France et en Europe.", en: "Spoink is an improvised electronic music quartet formed in summer 2019 in eastern Paris. Their live show is fully improvised and played on instruments, moving through techno, drum & bass, dubstep and rock touches. The group released the album Sharp in January 2023 and has played over 160 shows across France and Europe." }, origin: "Paris, France", since: 2019, sources: ["https://spoinkmusic.fr/", "https://electro-news.eu/spoink-le-groupe-francais-qui-casse-les-codes-en-melangeant-le-rock-et-la-techno/"] }, // Spoink
  "stef-davidse": { slug: "stef-davidse", bio: { fr: "Stef Davidse est un DJ et producteur néerlandais basé à Rotterdam, venu du hip-hop avant de découvrir la house en 2018. Sa musique garde cet héritage : basses roulantes, groove tech house et voix soul. Il publie sur No Art, WYLD Records, Micro Hertz et Eastenderz, le label d'East End Dubs, et sa collaboration « Burnin » avec ANOTR dépasse les deux millions d'écoutes sur Spotify.", en: "Stef Davidse is a Dutch DJ and producer based in Rotterdam who came from hip-hop before discovering house in 2018. That background still shows: rolling basslines, tech house groove and soulful vocals. He releases on No Art, WYLD Records, Micro Hertz and Eastenderz, East End Dubs' label, and his collaboration \"Burnin\" with ANOTR has passed two million Spotify streams." }, origin: "Rotterdam, Pays-Bas", since: 2018, labels: ["No Art", "WYLD Records", "Eastenderz"], sources: ["https://grayarea.co/magazine/press-play-on-stef-davidse-rotterdam-s-rising-house-star"] }, // Stef Davidse
  "stephan-bodzin": { slug: "stephan-bodzin", bio: { fr: "Stephan Bodzin est un DJ, producteur et patron de label allemand né en 1969 à Brême, fils d'un musicien expérimental. Musicien de formation classique, il compose d'abord pour des théâtres européens avant de créer son label HERZBLUT en 2006. Son premier album, « Liebe ist… », sort en 2007, suivi de « Powers of Ten » (2015) et « Boavista » (2021). Il se produit en live et a remixé Depeche Mode, Booka Shade et The Knife.", en: "Stephan Bodzin is a German DJ, producer and label owner born in 1969 in Bremen, the son of an experimental musician. Classically trained, he first wrote music for European theatres before founding his HERZBLUT label in 2006. His debut album \"Liebe ist…\" came out in 2007, followed by \"Powers of Ten\" (2015) and \"Boavista\" (2021). He performs as a live act and has remixed Depeche Mode, Booka Shade and The Knife." }, origin: "Brême, Allemagne", since: 2005, labels: ["HERZBLUT"], sources: ["https://en.wikipedia.org/wiki/Stephan_Bodzin"] }, // Stephan Bodzin
  "stephan-licha": { slug: "stephan-licha", bio: { fr: "Stephan Licha mixe depuis 2005. Il obtient d'abord une résidence aux soirées Glamnight de Bayreuth, sa ville d'origine, puis s'installe à Berlin en 2009 et commence à produire, entre le KingSize Bar et le Rekorder Club. Son premier disque paraît en 2015 sur le label suisse ShikkiMikki Records ; suivent des sorties sur Lapsus Music et Yellow Productions, le label de Bob Sinclar. Son titre « Choose One » est monté à la troisième place du classement tech house de Traxsource.", en: "Stephan Licha has been DJing since 2005. He first held a residency at the Glamnight parties in his home town of Bayreuth, then moved to Berlin in 2009 and began producing, playing the KingSize Bar and Rekorder Club. His first record came out in 2015 on the Swiss label ShikkiMikki Records, followed by releases on Lapsus Music and Bob Sinclar's Yellow Productions. His track \"Choose One\" reached number three on the Traxsource tech house chart." }, origin: "Berlin, Allemagne", since: 2005, labels: ["ShikkiMikki Records", "Lapsus Music", "Yellow Productions"], sources: ["https://goout.net/en/stephan-licha/pzlexdg/"] }, // Stephan Licha
  "steve-aoki": { slug: "steve-aoki", bio: { fr: "DJ et producteur américain né en 1977, Steve Aoki a fondé son label Dim Mak Records en 1996, qui a publié MSTRKRFT, The Bloody Beetroots, Bloc Party ou Klaxons. Son premier album, « Wonderland » (2012), a été nommé au Grammy du meilleur album dance/électronique en 2013, et Pollstar l'a désigné en 2012 comme l'artiste EDM générant le plus de recettes de tournée en Amérique du Nord. Il a signé sept albums studio et publié en 2019 un livre de mémoires, « Blue: The Color of Noise ».", en: "An American DJ and producer born in 1977, Steve Aoki founded his label Dim Mak Records in 1996, releasing MSTRKRFT, The Bloody Beetroots, Bloc Party and Klaxons among others. His first album \"Wonderland\" (2012) was nominated for the Grammy for Best Dance/Electronica Album in 2013, and Pollstar named him the highest-grossing EDM touring artist in North America in 2012. He has released seven studio albums and published a memoir, \"Blue: The Color of Noise\", in 2019." }, origin: "États-Unis", since: 1996, labels: ["Dim Mak Records"], sources: ["https://en.wikipedia.org/wiki/Steve_Aoki"] }, // Steve Aoki
  "stijn-vm": { slug: "stijn-vm", bio: { fr: "Stijn VM, de son vrai nom Stijn Van Mol, est un DJ belge originaire de Lier. Il joue en club et en festival depuis les années 2000 — Noxx, La Rocca, Illusion, Beachland, Sunset Festival — sur un répertoire répertorié comme club, electro, house et trance progressive.", en: "Stijn VM, real name Stijn Van Mol, is a Belgian DJ from Lier. He has played clubs and festivals since the 2000s — Noxx, La Rocca, Illusion, Beachland, Sunset Festival — across a repertoire listed as club, electro, house and progressive trance." }, origin: "Lier, Belgique", sources: ["https://harderstylemap.com/artist/stijn-vm/", "https://partyflock.nl/en/artist/68294/archive"] }, // Stijn VM
  "sub-focus": { slug: "sub-focus", bio: { fr: "Sub Focus, de son vrai nom Nicolaas Douwe Douwma, est un producteur et DJ anglais né le 13 avril 1982 à Guildford, dans le Surrey. Repéré par Andy C, il signe sur Frequency puis RAM Records, où « X-Ray » (2005) le fait connaître. Son quatrième album, « Evolve », est paru le 12 mai 2023.", en: "Sub Focus, real name Nicolaas Douwe Douwma, is an English producer and DJ born on 13 April 1982 in Guildford, Surrey. Spotted by Andy C, he signed to Frequency and then RAM Records, where \"X-Ray\" (2005) made his name. His fourth album, \"Evolve\", was released on 12 May 2023." }, origin: "Guildford, Surrey, Royaume-Uni", since: 2002, labels: ["RAM Records", "Virgin EMI"], sources: ["https://en.wikipedia.org/wiki/Sub_Focus", "https://www.discogs.com/artist/142440-Sub-Focus"] }, // Sub Focus
  "sub-zero-project": { slug: "sub-zero-project", bio: { fr: "Sub Zero Project est un duo hardstyle néerlandais. Ses sorties paraissent sur Dirty Workz et sur son label Anarchy, avec un son classé raw hardstyle.", en: "Sub Zero Project is a Dutch hardstyle duo. Their releases come out on Dirty Workz and on their own Anarchy label, in a raw hardstyle vein." }, origin: "Pays-Bas", labels: ["Dirty Workz", "Anarchy"], sources: ["https://musicbrainz.org/ws/2/artist/?query=artist:Sub%20Zero%20Project&fmt=json", "https://api.discogs.com/database/search?artist=Sub+Zero+Project&type=release"] }, // Sub Zero Project
  "suze": { slug: "suze", bio: { fr: "SUZé est une DJ et productrice allemande basée à Hambourg, régulière de l'écurie Katermukke où elle joue les open airs et les takeovers de la marque. Elle mêle house progressive et techno mélodique, sur des sets construits autour de nappes atmosphériques et de breaks. Elle a également joué au festival Deichbrand.", en: "SUZé is a German DJ and producer based in Hamburg and a regular of the Katermukke roster, playing the label's open airs and takeovers. She blends progressive house and melodic techno in sets built around atmospheric pads and breaks. She has also played the Deichbrand festival." }, origin: "Hambourg, Allemagne", labels: ["Katermukke"], sources: ["https://deichbrand.de/en/line-up/artist/suze/", "https://djanetop.com/djanes/suze/"] }, // SUZé
  "sven-vath": { slug: "sven-vath", bio: { fr: "Né en 1964 à Obertshausen, près de Francfort, il ouvre le club Omen en 1988 et fonde successivement les labels Eye Q (1991), Harthouse (1992) puis Cocoon Recordings (1999). Sa techno traversée de trance et d'ambient s'entend sur l'album Accident in Paradise (1992). Il a tenu la résidence Cocoon du lundi soir à l'Amnesia d'Ibiza de 1999 à 2018.", en: "Born in 1964 in Obertshausen, near Frankfurt, he opened the Omen club in 1988 and founded the labels Eye Q (1991), Harthouse (1992) and then Cocoon Recordings (1999). His techno, run through with trance and ambient, is heard on the album Accident in Paradise (1992). He held the Monday-night Cocoon residency at Amnesia in Ibiza from 1999 to 2018." }, origin: "Obertshausen, Allemagne", since: 1986, labels: ["Cocoon Recordings", "Harthouse", "Eye Q Records"], sources: ["https://en.wikipedia.org/wiki/Sven_V%C3%A4th"] }, // Sven Väth
  "swedish-house-mafia": { slug: "swedish-house-mafia", bio: { fr: "Swedish House Mafia est un trio de house suédois formé fin 2008 par Axwell, Steve Angello et Sebastian Ingrosso. Le groupe a porté la progressive house vers le grand public au tournant des années 2010 avec « One (Your Name) » et « Miami 2 Ibiza », puis a mené une tournée d'adieu en 2012 avant de se reformer.", en: "Swedish House Mafia are a Swedish house trio formed in late 2008 by Axwell, Steve Angello and Sebastian Ingrosso. The group carried progressive house into the mainstream around 2010 with \"One (Your Name)\" and \"Miami 2 Ibiza\", then ran a farewell tour in 2012 before reuniting." }, origin: "Stockholm, Suède", since: 2008, sources: ["https://en.wikipedia.org/wiki/Swedish_House_Mafia"] }, // Swedish House Mafia
  "sydney-ayven": { slug: "sydney-ayven", bio: { fr: "Sydney Ayven est un DJ belge aux sets open format. Il se fait connaître en terminant deuxième d'un concours de DJ organisé avec la radio TOPradio pour jouer à Tomorrowland, et se produit depuis à Tomorrowland, The Day Before Tomorrow, Sunrise Festival et Sunset Festival.", en: "Sydney Ayven is a Belgian open-format DJ. He made his name finishing second in a DJ contest run with the radio station TOPradio for a Tomorrowland slot, and has since played Tomorrowland, The Day Before Tomorrow, Sunrise Festival and Sunset Festival." }, origin: "Belgique", sources: ["https://www.groundcontrolagency.be/artist/sydney-ayven", "https://www.thedaybeforetomorrow.be/line-up/"] }, // Sydney Ayven
  "syreeta": { slug: "syreeta", bio: { fr: "SYREETA est une DJ et productrice britannique dont les sets puisent dans la house et la techno, sur des basses épaisses et des grooves mélodiques. Elle a sorti des disques sur Nervous Records, Sound International, Edible et HE.SHE.THEY., a livré son premier Essential Mix sur BBC Radio 1 en 2025 et joue régulièrement aux soirées Paradise de Jamie Jones.", en: "SYREETA is a British DJ and producer whose sets draw on house and techno, over chunky basslines and melodic grooves. She has released on Nervous Records, Sound International, Edible and HE.SHE.THEY., delivered her first BBC Radio 1 Essential Mix in 2025, and plays regularly at Jamie Jones's Paradise parties." }, origin: "Royaume-Uni", labels: ["Nervous Records", "Edible", "HE.SHE.THEY."], sources: ["https://www.liaisonartists.com/artists/syreeta/", "https://ra.co/dj/syreeta-uk/biography"] }, // Syreeta
  "tassery": { slug: "tassery", bio: { fr: "TASSERY est une DJ et productrice basée à Paris, qui mêle hard techno, trance et schranz. Elle a sorti les EP Lost In The Blue sur Innergate Records et Catch The Light sur Hardest Soft Records, et son premier album est paru sur PARFAIT en juin 2025. Elle joue en France, en Allemagne, en Espagne, en Inde et aux Pays-Bas.", en: "TASSERY is a Paris-based DJ and producer blending hard techno, trance and schranz. She released the EPs Lost In The Blue on Innergate Records and Catch The Light on Hardest Soft Records, and her debut album came out on PARFAIT in June 2025. She plays in France, Germany, Spain, India and the Netherlands." }, origin: "Paris, France", labels: ["PARFAIT", "Innergate Records", "Hardest Soft Records"], sources: ["https://6amgroup.com/articles/music-interviews/whats-in-your-toolbox-tassery"] }, // Tassery
  "tauceti": { slug: "tauceti", bio: { fr: "Tauceti est l'alias de Lilou Chelal, DJ, productrice et compositrice installée à Lyon et résidente du club Le Sucre. Batteuse avant de passer à l'électronique, elle produit une techno sombre, percussive et texturée doublée d'un versant ambient. Son EP Facing Herself in the Bathroom Mirror paraît sur Semantica, son premier album ambient sur Denovali, et elle publie aussi sur la série Weapons du label Raise.", en: "Tauceti is the alias of Lilou Chelal, a DJ, producer and composer based in Lyon and a resident at Le Sucre. A drummer before moving to electronic music, she makes dark, percussive, textured techno alongside an ambient strand. Her EP Facing Herself in the Bathroom Mirror came out on Semantica, her first ambient album on Denovali, and she also appears on the Weapons series from the Raise label." }, origin: "Lyon, France", labels: ["Semantica", "Denovali", "Raise"], sources: ["https://www.cyclicdefrost.com/2025/11/listen-to-a-premiere-of-lyon-based-taucetis-debut-album/", "https://tribunedelyon.fr/culture/electro-lyon-tauceti/"] }, // Tauceti
  "technimatic": { slug: "technimatic", bio: { fr: "Technimatic est un duo anglais de drum & bass formé en 2008 par Pete Rogers (Technicolour) et Andy Powell (Komatic). Leur premier single, « Preacher », paraît en 2009 sur Worldwide Audio, avant des sorties sur Critical, Hospital, Spearhead, Viper et Good Looking Records. Ils signent chez SGN:LTD, le label associé à Shogun Audio, en 2012 avec l'EP Intersection.", en: "Technimatic is an English drum & bass duo formed in 2008 by Pete Rogers (Technicolour) and Andy Powell (Komatic). Their first single, \"Preacher\", came out in 2009 on Worldwide Audio, followed by releases on Critical, Hospital, Spearhead, Viper and Good Looking Records. They signed to SGN:LTD, Shogun Audio's sister label, in 2012 with the Intersection EP." }, origin: "Royaume-Uni", since: 2008, labels: ["Shogun Audio", "SGN:LTD", "Hospital Records"], sources: ["https://www.shogunaudio.co.uk/pages/technimatic"] }, // Technimatic
  "teho": { slug: "teho", bio: { fr: "Teho, de son vrai nom Théo Vicente, est un producteur et DJ français installé à Montpellier, actif dans la techno mélodique. Il se fait connaître par des sorties sur Parquet Recordings et Traum Schallplatten, puis fonde en novembre 2016 son propre label, Labo T., conçu comme un laboratoire sonore ouvert à plusieurs genres. Il a notamment publié les albums Infinity en 2022 et Shifting en 2024.", en: "Teho, real name Théo Vicente, is a French producer and DJ based in Montpellier, working in melodic techno. He first drew attention with releases on Parquet Recordings and Traum Schallplatten, then founded his own label, Labo T., in November 2016, conceived as a sound laboratory open to several genres. His albums include Infinity in 2022 and Shifting in 2024." }, origin: "Montpellier, France", labels: ["Labo T.", "Traum Schallplatten"], sources: ["https://electronicgroove.com/artist-profile-teho/", "https://www.discogs.com/artist/1457615"] }, // Teho
  "teknoclash": { slug: "teknoclash", bio: { fr: "Teknoclash est l'alias lancé en 2015 par Johnny Eckebrecht, DJ et producteur qui signe alors chez MXUP Records. Sa musique croise electro, future house et bass ; ses titres « Outta My Mind » et « Lose Your Mind » sont entrés dans les classements Beatport.", en: "Teknoclash is the alias launched in 2015 by Johnny Eckebrecht, a DJ and producer who signed to MXUP Records that year. His music crosses electro, future house and bass; his tracks \"Outta My Mind\" and \"Lose Your Mind\" charted on Beatport." }, since: 2015, labels: ["MXUP Records"], sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/teknoclash/15788/"] }, // Teknoclash
  "the-avalanches": { slug: "the-avalanches", bio: { fr: "The Avalanches est un groupe électronique australien formé à Melbourne en 1997, aujourd'hui composé de Robbie Chater et Tony Di Blasi, membres fondateurs, et du multi-instrumentiste Andy Szekeres. Ils pratiquent le plunderphonics, une musique entièrement bâtie à partir de disques échantillonnés, et leur premier album Since I Left You (2000) en est considéré comme une référence. Ont suivi Wildflower (2016) et We Will Always Love You (2020). Sur scène, ils mêlent jeu live et DJing.", en: "The Avalanches are an Australian electronic group formed in Melbourne in 1997, now made up of founding members Robbie Chater and Tony Di Blasi plus multi-instrumentalist Andy Szekeres. They work in plunderphonics, music built entirely from sampled records, and their first album Since I Left You (2000) is widely treated as a benchmark of the genre. Wildflower (2016) and We Will Always Love You (2020) followed. On stage they combine live playing with DJing." }, origin: "Melbourne, Australie", since: 1997, labels: ["Modular Recordings", "XL Recordings"], sources: ["https://en.wikipedia.org/wiki/The_Avalanches"] }, // The Avalanches
  "the-avener": { slug: "the-avener", bio: { fr: "The Avener est le nom de scène de Tristan Casara, DJ et producteur français né en 1987 à Nice. Il travaille une deep house teintée d'electro. Son premier single, « Fade Out Lines », paru en septembre 2014, est une relecture de « The Fade Out Line » de Phoebe Killdeer & The Short Straws : il atteint la 3e place en France et la première en Autriche, en Allemagne et en Espagne.", en: "The Avener is the stage name of Tristan Casara, a French DJ and producer born in 1987 in Nice. He works in deep house tinged with electro. His first single, \"Fade Out Lines\", released in September 2014, is a rework of \"The Fade Out Line\" by Phoebe Killdeer & The Short Straws: it reached No. 3 in France and No. 1 in Austria, Germany and Spain." }, origin: "Nice, France", since: 2014, sources: ["https://en.wikipedia.org/wiki/The_Avener"] }, // The Avener
  "the-blaze": { slug: "the-blaze", bio: { fr: "The Blaze est un duo électronique parisien formé par les cousins Guillaume et Jonathan Alric. Ils produisent musique et images en même temps, et ont publié l'EP Territory (2017) puis les albums Dancehall (2018) et Jungle (2023) sur Animal63.", en: "The Blaze is a Paris-based electronic duo made up of cousins Guillaume and Jonathan Alric. They produce sound and visuals at the same time, and have released the EP Territory (2017) and the albums Dancehall (2018) and Jungle (2023) on Animal63." }, origin: "Paris, France", since: 2017, labels: ["Animal63"], sources: ["https://en.wikipedia.org/wiki/The_Blaze_(band)", "https://api.discogs.com/database/search?artist=The+Blaze&type=release"] }, // The Blaze
  "the-lady-machine": { slug: "the-lady-machine", bio: { fr: "The Lady Machine est une DJ et productrice née au Brésil et installée à Berlin. Elle mixe en vinyle depuis le début des années 2000 et codirige depuis 2019, avec Decka, le label Unterwegs Records.", en: "The Lady Machine is a Brazilian-born DJ and producer based in Berlin. She has been playing vinyl since the early 2000s and, since 2019, co-runs the Unterwegs Records label with Decka." }, origin: "Brésil / Berlin, Allemagne", labels: ["Unterwegs Records"], sources: ["https://www.discogs.com/artist/6154918-The-Lady-Machine"] }, // The Lady Machine
  "the-prodigy": { slug: "the-prodigy", bio: { fr: "The Prodigy est un groupe électronique anglais formé en 1990 à Braintree, dans l'Essex, autour du producteur et claviériste Liam Howlett, rejoint par les danseurs Keith Flint et Leeroy Thornhill. Parti du breakbeat hardcore et de la scène rave avec l'EP « What Evil Lurks » (1991), le groupe bascule vers le big beat et les guitares avec « The Fat of the Land » (1997). Il compte sept albums numéro un consécutifs au Royaume-Uni.", en: "The Prodigy are an English electronic band formed in 1990 in Braintree, Essex, around producer and keyboardist Liam Howlett, joined by dancers Keith Flint and Leeroy Thornhill. Starting out in breakbeat hardcore and the rave scene with the \"What Evil Lurks\" EP (1991), the band moved towards big beat and guitars with \"The Fat of the Land\" (1997). They have scored seven consecutive UK number one albums." }, origin: "Braintree, Essex, Royaume-Uni", since: 1990, sources: ["https://en.wikipedia.org/wiki/The_Prodigy", "https://www.discogs.com/artist/66852-The-Prodigy"] }, // The Prodigy
  "the-purge": { slug: "the-purge", bio: { fr: "Manuel Moscardo, alias The Purge, est un producteur né à Monza (Italie) et installé à Utrecht, aux Pays-Bas. Il est l'un des fondateurs du label Savage Squad Recordings, créé pendant la pandémie avec Alberto (Mind Dimension) et Jordy. Ses productions travaillent des kicks distordus, des screeches et des ambiances industrielles, entre raw hardstyle et uptempo.", en: "Manuel Moscardo, who produces as The Purge, was born in Monza, Italy and is based in Utrecht, the Netherlands. He is one of the founders of Savage Squad Recordings, launched during the pandemic with Alberto (Mind Dimension) and Jordy. His productions build on distorted kicks, screeches and industrial atmospheres, between raw hardstyle and uptempo." }, origin: "Monza, Italie", labels: ["Savage Squad Recordings"], sources: ["https://edm.fandom.com/wiki/The_Purge", "https://www.savagesquad.nl/", "https://harderstylemap.com/artist/the-purge/"] }, // The Purge
  "the-sabres-of-paradise": { slug: "the-sabres-of-paradise", bio: { fr: "The Sabres of Paradise est un groupe électronique londonien formé en 1992 par Andrew Weatherall, Jagz Kooner et Gary Burns. Il a publié Sabresonic en 1993 et Haunted Dancehall en 1994, où la house et la techno croisent le dub et des textures industrielles. Kooner et Burns ont repris les concerts après la réédition des deux albums, sans Weatherall, mort en 2020.", en: "The Sabres of Paradise are a London electronic group formed in 1992 by Andrew Weatherall, Jagz Kooner and Gary Burns. They released Sabresonic in 1993 and Haunted Dancehall in 1994, where house and techno meet dub and industrial textures. Kooner and Burns resumed live shows after both albums were reissued, without Weatherall, who died in 2020." }, origin: "Londres, Royaume-Uni", since: 1992, sources: ["https://en.wikipedia.org/wiki/The_Sabres_of_Paradise", "https://nuits-sonores.com/en/artiste/the-sabres-of-paradise-live-2/"] }, // The Sabres of Paradise
  "the-saints": { slug: "the-saints", bio: { fr: "The Saints est un duo néerlandais de hard dance formé par Jules van de Sant et Rick de Deken. Jules a quitté le sport de haut niveau en 2019 pour se consacrer au hardstyle. Le duo a fait ses débuts sur la mainstage de l'Intents Festival, sur la scène BLUE du Defqon.1 et à Supremacy, où il a présenté « Legacy » avec Noxiouz et Satirized.", en: "The Saints are a Dutch hard dance duo made up of Jules van de Sant and Rick de Deken. Jules left top-level sport in 2019 to pursue hardstyle. The duo debuted on the Intents Festival mainstage, on Defqon.1's BLUE stage and at Supremacy, where they premiered 'Legacy' with Noxiouz and Satirized." }, origin: "Pays-Bas", since: 2019, sources: ["https://hardnews.nl/en/the-saints-from-the-bar-to-ultra-miami/"] }, // The Saints
  "the-shapeshifters": { slug: "the-shapeshifters", bio: { fr: "The Shapeshifters est le projet du producteur house britannique Simon Marlin, actif depuis 2004. À l'origine un duo formé avec le Suédois Max Reich, rencontré à Göteborg en 1996, il continue seul depuis le départ de ce dernier en 2017. Le projet a été signé sur Positiva puis Defected à partir de 2008, et publie depuis 2017 sur Glitterbox Recordings, entre house et nu-disco.", en: "The Shapeshifters is the project of British house producer Simon Marlin, active since 2004. Originally a duo with Swedish producer Max Reich, whom he met in Gothenburg in 1996, it has continued solo since Reich's departure in 2017. The project was signed to Positiva and then Defected from 2008, and has released on Glitterbox Recordings since 2017, working between house and nu-disco." }, origin: "Royaume-Uni", since: 2004, labels: ["Defected", "Glitterbox Recordings"], sources: ["https://en.wikipedia.org/wiki/The_Shapeshifters", "https://www.defectedmusic.com/artists/7"] }, // The Shapeshifters
  "the-tunegirl": { slug: "the-tunegirl", bio: { fr: "Andrea Gill, alias The Tunegirl, est une artiste allemande qui joue exclusivement en live sur son propre système modulaire Eurorack. Passée par le hard rock des années 1970, puis le funk, la soul et la synth-pop, elle bascule vers la techno de Detroit, la minimale et l'acid, sous l'influence de Jeff Mills, Robert Hood, Richie Hawtin et K-Hand. Elle a construit sa pratique du modulaire après cinquante ans et a fait ses débuts à Awakenings Upclose au printemps 2026.", en: "Andrea Gill, who performs as The Tunegirl, is a German artist who plays live only, on her own Eurorack modular system. She came through 1970s hard rock, then funk, soul and synth-pop, before turning to Detroit techno, minimal and acid under the influence of Jeff Mills, Robert Hood, Richie Hawtin and K-Hand. She built her modular practice after fifty and made her Awakenings Upclose debut in spring 2026." }, origin: "Allemagne", sources: ["https://weraveyou.com/2026/05/tunegirl-awakenings-debut-story/", "https://dancefloordispatch.ghost.io/andrea-gill-aka-tunegirl-one-of-technos-most-unexpected-rising-stars/"] }, // The Tunegirl
  "thiso": { slug: "thiso", bio: { fr: "DJ et producteur néerlandais, Thiso joue une hard techno décrite comme brute et hypnotique, construite autour de son propre sound design et de sets fortement thématisés. Il s'est produit à Berlin, notamment au Lokschuppen, et à Paris.", en: "Dutch DJ and producer Thiso plays hard techno described as raw and hypnotic, built around his own sound design and strongly themed sets. He has played Berlin, notably Lokschuppen, and Paris." }, origin: "Pays-Bas", sources: ["https://ra.co/dj/thiso"] }, // Thiso
  "thylacine": { slug: "thylacine", bio: { fr: "Thylacine est le nom de scène de William Rezé, musicien et compositeur français né le 13 août 1992 à Angers. Formé au conservatoire puis aux beaux-arts, saxophoniste, il compose de la musique électronique depuis 2012. Son premier album, Transsiberian (2015), a été enregistré à bord du Transsibérien entre Moscou et Vladivostok ; le suivant a été composé lors d'un voyage en Argentine.", en: "Thylacine is the stage name of William Rezé, a French musician and composer born on 13 August 1992 in Angers. Trained at a conservatory then at art school, and a saxophonist, he has been making electronic music since 2012. His first album, Transsiberian (2015), was recorded aboard the Trans-Siberian railway between Moscow and Vladivostok; the follow-up was composed on a journey through Argentina." }, origin: "Angers, France", since: 2012, sources: ["https://fr.wikipedia.org/wiki/Thylacine_(musicien)", "https://musicbrainz.org/artist/e095407c-4103-4c66-b616-0dab1db05106"] }, // Thylacine
  "tiesto": { slug: "tiesto", bio: { fr: "Tijs Verwest, né en 1969 à Breda aux Pays-Bas, a commencé à mixer dans les clubs néerlandais dès le milieu des années 1980 avant de fonder en 1997 le label Black Hole Recordings avec Arny Bink. Son premier album solo, « In My Memory » (2001), et son remix de « Silence » de Delerium l'ont fait connaître au grand public ; il a été élu meilleur DJ du monde par DJ Mag trois années de suite, de 2002 à 2004. En 2004, il est devenu le premier DJ à jouer sur scène lors d'une cérémonie d'ouverture olympique, à Athènes.", en: "Born in Breda, the Netherlands in 1969, Tijs Verwest began DJing in Dutch clubs in the mid-1980s before founding the Black Hole Recordings label with Arny Bink in 1997. His first solo album \"In My Memory\" (2001) and his remix of Delerium's \"Silence\" brought him to a wider audience; DJ Mag readers voted him world number one DJ three years running, from 2002 to 2004. In 2004 he became the first DJ to play live on stage at an Olympic opening ceremony, in Athens." }, origin: "Breda, Pays-Bas", labels: ["Black Hole Recordings"], sources: ["https://en.wikipedia.org/wiki/Ti%C3%ABsto"] }, // Tiësto
  "timmy-trumpet": { slug: "timmy-trumpet", bio: { fr: "Timmy Trumpet est le nom de scène de Timothy Jude Smith, musicien, DJ et producteur australien né le 9 juin 1982. Il joue de la trompette en direct par-dessus ses sets et fait entrer des éléments de jazz dans la musique de danse, ce qui a fait sa réputation à l'international.", en: "Timmy Trumpet is the stage name of Timothy Jude Smith, an Australian musician, DJ and producer born on 9 June 1982. He plays trumpet live over his sets and brings jazz elements into dance music, which is what made his international name." }, origin: "Sydney, Australie", sources: ["https://en.wikipedia.org/wiki/Timmy_Trumpet", "https://musicbrainz.org/artist/07aceecf-0fa2-4d51-865f-273313cba931"] }, // Timmy Trumpet
  "todd-edwards": { slug: "todd-edwards", bio: { fr: "Todd Edward Imperatrice, né en 1972 à Bloomfield (New Jersey), produit de la garage house depuis 1992. Son montage de micro-échantillons vocaux, inauguré sur « Guide My Soul » (1993) chez Nervous Records puis sur « Saved My Life » (1995), a servi de matrice au UK garage et au speed garage britanniques. Daft Punk l'a invité à chanter et coproduire « Face to Face » sur Discovery. Defected a racheté son catalogue.", en: "Todd Edward Imperatrice, born in 1972 in Bloomfield, New Jersey, has been producing garage house since 1992. His chopped micro-sampled vocal style, introduced on \"Guide My Soul\" (1993) for Nervous Records and cemented by \"Saved My Life\" (1995), became a template for UK garage and speed garage. Daft Punk had him sing and co-produce \"Face to Face\" on Discovery. Defected has since acquired his catalogue." }, origin: "Bloomfield, New Jersey, États-Unis", since: 1992, labels: ["Nervous Records", "i! Records", "Defected"], sources: ["https://en.wikipedia.org/wiki/Todd_Edwards", "https://www.musicbusinessworldwide.com/defected-records-acquires-catalog-of-producer-todd-edwards/"] }, // Todd Edwards
  "toirabat": { slug: "toirabat", bio: { fr: "Toirabat est, avec DJ Bisou, le co-fondateur de Deux Chevaux, une soirée bruxelloise construite sur des tempos lents : l'idée est qu'en descendant le BPM, la danse devient plus intense et plus psychédélique. Le duo programme et joue ces nuits au Beursschouwburg.", en: "Toirabat is, with DJ Bisou, the co-founder of Deux Chevaux, a Brussels party built on slow tempos: the idea being that dropping the BPM makes dancing more intense and more psychedelic. The pair programme and play these nights at the Beursschouwburg." }, origin: "Bruxelles, Belgique", sources: ["https://ra.co/events/2494084"] }, // Toirabat
  "tommy-phillips": { slug: "tommy-phillips", bio: { fr: "Tommy Phillips est un producteur et DJ britannique originaire de Northampton, qui croise house de Chicago, énergie breakbeat et refrains vocaux. Son EP « Smokin », paru sur le label Roush d'Hector Couto, l'a fait remarquer, suivi de l'EP « Foolish Stuff » sur Meta, le label de Ben Rau. Il est représenté par l'agence LOCUS.", en: "Tommy Phillips is a British producer and DJ from Northampton who fuses early Chicago house with breakbeat-driven energy and vocal hooks. His \"Smokin\" EP on Hector Couto's Roush label brought him wider attention, followed by the \"Foolish Stuff\" EP on Ben Rau's Meta. He is booked by the LOCUS agency." }, origin: "Northampton, Royaume-Uni", labels: ["Roush", "Meta"], sources: ["https://www.lgrp.co/artists/tommyphillips-phlzb-7r325-2fxs4"] }, // Tommy Phillips
  "traumer": { slug: "traumer", bio: { fr: "Traumer, de son vrai nom Romain Reynaud, est un DJ et producteur français né à Avignon et installé à Paris. Il débute en 2011 avec des disques techno sur Skryptöm, puis son style s'oriente vers la house minimale à partir de 2016, année où il fonde son label Gettraum. Il produit aussi sous les alias Romain Poncet et Sergie Rezza, ce dernier avec DJ Deep.", en: "Traumer, real name Romain Reynaud, is a French DJ and producer born in Avignon and based in Paris. He debuted in 2011 with techno records on Skryptom, then shifted towards minimal house from 2016, the year he founded his Gettraum label. He also produces as Romain Poncet and, with DJ Deep, as Sergie Rezza." }, origin: "Paris, France", since: 2011, labels: ["Gettraum", "Skryptöm"], sources: ["https://xlr8r.com/features/20-questions-traumer/", "https://gettraum.bandcamp.com/track/dj-deep-sunday-loop-traumer-stripped-down"] }, // Traumer
  "tricky": { slug: "tricky", bio: { fr: "Tricky est le nom de scène d'Adrian Nicholas Matthews Thaws, né le 27 janvier 1968 à Knowle West, un quartier de Bristol. Il se fait d'abord connaître au sein de Massive Attack, sur l'album Blue Lines (1991), avant de publier en 1995 Maxinquaye, disque fondateur du trip hop enregistré avec la chanteuse Martina Topley-Bird. Il dirige le label False Idols et a également sorti des disques sur Domino, Epitaph et Island.", en: "Tricky is the stage name of Adrian Nicholas Matthews Thaws, born 27 January 1968 in Knowle West, Bristol. He first came to attention with Massive Attack on Blue Lines (1991), then released Maxinquaye in 1995, a founding trip hop record made with singer Martina Topley-Bird. He runs the False Idols label and has also released on Domino, Epitaph and Island." }, origin: "Bristol, Royaume-Uni", since: 1985, labels: ["False Idols", "Domino", "Island Records"], sources: ["https://en.wikipedia.org/wiki/Tricky_(musician)"] }, // Tricky
  "trinix": { slug: "trinix", bio: { fr: "Trinix est un duo français de musique électronique actif depuis 2012, qui publie sur son propre label Trinix Music. Sa musique est classée en EDM et electro house, et il s'est fait connaître par ses remixes.", en: "Trinix is a French electronic duo active since 2012, releasing on their own label Trinix Music. Their music is classified as EDM and electro house, and they became known through their remixes." }, origin: "France", since: 2012, labels: ["Trinix Music"], sources: ["https://fr.wikipedia.org/wiki/Trinix"] }, // Trinix
  "trym": { slug: "trym", bio: { fr: "Trym, de son vrai nom Martin Drack, est un DJ et producteur français né en 1997 et formé à Paris. Sa percée date de 2019, avec un Boiler Room pour le collectif parisien Possession, dont il devient résident. Il dirige le label COLOR et joue une techno rapide à la lisière de la hard dance et de la hard trance.", en: "Trym, real name Martin Drack, is a French DJ and producer born in 1997 and trained in Paris. His breakthrough came in 2019 with a Boiler Room for the Paris collective Possession, where he became a resident. He runs the COLOR label and plays fast techno on the edge of hard dance and hard trance." }, origin: "Paris, France", since: 2019, labels: ["COLOR"], sources: ["https://www.connectedartists.com/artists/trym"] }, // Trym
  "twonot": { slug: "twonot", bio: { fr: "Twonot est un DJ et producteur français de Saint-Nazaire, venu à la musique électronique par la French Touch des années 1990-2000. Il joue des sets house éclectiques, d'Ibiza à Amsterdam, et collabore depuis ses débuts avec le label Jango Records. Ses productions récentes vont vers la techno mélodique.", en: "Twonot is a French DJ and producer from Saint-Nazaire who came to electronic music through the French Touch of the 1990s and 2000s. He plays eclectic house sets from Ibiza to Amsterdam and has worked with the label Jango Records since its early days. His recent productions lean towards melodic techno." }, origin: "Saint-Nazaire, France", labels: ["Jango Records"], sources: ["https://www.warehouse-nantes.fr/artist/twonot"] }, // Twonot
  "ueberrest": { slug: "ueberrest", bio: { fr: "Ueberrest est le nom de scène de Tim Werder, DJ et producteur suisse apparu dans la scène hard techno européenne autour de 2021. Son premier disque sur 44 Label Group réunit huit titres dont « Cryptic » et « Blut Aus Gold ». Il joue une hard techno rapide au grain industriel, associée au courant hard bounce.", en: "Ueberrest is the stage name of Tim Werder, a Swiss DJ and producer who emerged in the European hard techno scene around 2021. His first record on 44 Label Group gathers eight tracks including \"Cryptic\" and \"Blut Aus Gold\". He plays fast, industrial-edged hard techno tied to the hard bounce wave." }, origin: "Suisse", since: 2021, labels: ["44 Label Group"], sources: ["https://openbeatz.de/artist/ueberrest/"] }, // Ueberrest
  "underworld": { slug: "underworld", bio: { fr: "Groupe électronique britannique formé en 1987, né de la rencontre de Karl Hyde et Rick Smith à Cardiff. Leur techno progressive mêlée de spoken word s'impose avec l'album Dubnobasswithmyheadman (1994), puis avec « Born Slippy .NUXX », porté par la bande originale de Trainspotting en 1996. Darren Emerson en a été le troisième membre de 1990 à 2000.", en: "British electronic group formed in 1987, born of Karl Hyde and Rick Smith meeting in Cardiff. Their progressive techno laced with spoken word took hold with the album Dubnobasswithmyheadman (1994), then with \"Born Slippy .NUXX\", carried by the Trainspotting soundtrack in 1996. Darren Emerson was the third member from 1990 to 2000." }, origin: "Cardiff, Royaume-Uni", since: 1987, labels: ["Junior Boy's Own", "Cooking Vinyl"], sources: ["https://en.wikipedia.org/wiki/Underworld_(band)"] }, // Underworld
  "ush": { slug: "ush", bio: { fr: "USH est un DJ et producteur néerlandais de hard techno. Son jeu repose sur des kicks lourds, une énergie industrielle et des atmosphères sombres, à des tempos élevés. Il est devenu un nom régulier des plateaux hard techno du pays et joue notamment pour Verknipt, Rotterdam Rave, Fury, Rebellion, Nacht Wacht, Khaotic et Complex.", en: "USH is a Dutch hard techno DJ and producer. His sets are built on heavy kicks, industrial energy and dark atmospheres at high tempos. He has become a regular name on the country's hard techno line-ups and plays for Verknipt, Rotterdam Rave, Fury, Rebellion, Nacht Wacht, Khaotic and Complex." }, origin: "Pays-Bas", sources: ["https://www.nxnewcastle.com/events/slush/"] }, // USH
  "vabu": { slug: "vabu", bio: { fr: "VABU mixe dans la scène techno de Hambourg depuis 2017. Ses premiers sets ont eu lieu au Bollwerk de Lübeck, puis avec le collectif « Harmonie im Bassgewitter ». Elle joue un mélange de melodic house & techno, de tech house et d'indie dance, et a été programmée au Feel Festival, à Habitat, Deichbrand, Pangea et MS Dockville.", en: "VABU has been part of Hamburg's techno scene since 2017. Her first sets were at Bollwerk in Lübeck, then with the collective \"Harmonie im Bassgewitter\". She plays a mix of melodic house & techno, tech house and indie dance, and has been booked for Feel Festival, Habitat, Deichbrand, Pangea and MS Dockville." }, origin: "Hambourg, Allemagne", since: 2017, sources: ["https://ra.co/dj/vabu/biography"] }, // Vabu
  "vai": { slug: "vai", bio: { fr: "Vaï est cofondatrice du média TROP TARD, bookeuse et programmatrice, passée récemment derrière les platines. Ses sets tournent autour d'une trance bouncy, de grooves mélodiques et de textures lumineuses, avec des voix planantes et des pianos euphorisants. Elle est basée à Vannes et joue régulièrement au Warehouse de Nantes.", en: "Vaï co-founded the media outlet TROP TARD and works as a booker and programmer; she recently started DJing. Her sets are built on bouncy trance, melodic grooves and bright textures, with floating vocals and euphoric pianos. She is based in Vannes and plays regularly at the Warehouse in Nantes." }, origin: "Vannes, France", sources: ["https://www.warehouse-nantes.fr/artist/vai"] }, // Vaï
  "vendex": { slug: "vendex", bio: { fr: "Vendex est un DJ et producteur espagnol né à Barcelone, où il commence à mixer vers quatorze ans avant de se mettre à produire en 2016. Il a passé ses étés à Ibiza, où sa famille est installée. Sa techno se veut sombre, industrielle et acide : il a sorti l'EP « Obscure » sur Mind & Me Music en 2018, puis « Summum Grimorium » sur Insane Industry en 2020, et joue régulièrement pour Verknipt et Rotterdam Rave.", en: "Vendex is a Spanish DJ and producer born in Barcelona, where he started mixing at around fourteen before taking up production in 2016. He spent his summers in Ibiza, where his family lives. His techno is dark, industrial and acid-leaning: he released the \"Obscure\" EP on Mind & Me Music in 2018, then \"Summum Grimorium\" on Insane Industry in 2020, and plays regularly for Verknipt and Rotterdam Rave." }, origin: "Barcelone, Espagne", since: 2016, sources: ["https://www.somarecords.com/artists/vendex/", "https://musicbrainz.org/artist/9018e7b1-4ad7-4498-a3a9-e7454af8d0ac"] }, // Vendex
  "venehing": { slug: "venehing", bio: { fr: "Venëhing est un DJ nantais dont les sets tiennent d'un continuum sombre : techno hypnotique, pression industrielle, énergie schranz. Il construit ses passages sur des boucles obsessionnelles et des pulsations distordues, en alternant brutalité et moments de suspension.", en: "Venëhing is a Nantes DJ whose sets run as a single dark continuum: hypnotic techno, industrial pressure, schranz energy. He builds them on obsessive loops and distorted pulses, alternating brutality with moments of suspension." }, origin: "Nantes, France", sources: ["https://www.warehouse-nantes.fr/artist/venehing/"] }, // Venëhing
  "venga": { slug: "venga", bio: { fr: "Venga est une DJ et productrice française installée dans le sud de la France. Partie de la bass house, elle a fait évoluer son répertoire vers la tech house, l'acid et la techno, notamment avec son EP « Daddy » puis « In The City » sur Sink Or Swim Records. Elle est résidente du rooftop R2 à Marseille.", en: "Venga is a French DJ and producer based in the south of France. Starting out in bass house, she moved her sound towards tech house, acid and techno, notably with her \"Daddy\" EP and then \"In The City\" on Sink Or Swim Records. She is a resident at the R2 rooftop in Marseille." }, origin: "Sud de la France", labels: ["Sink Or Swim Records"], sources: ["https://handsupelectro.fr/interviews/interview-venga/", "https://www.plages-electroniques.com/artistes/venga/"] }, // Venga
  "verdun": { slug: "verdun", bio: { fr: "Verdun est un DJ nantais qui découvre la musique électronique à dix-neuf ans, en arrivant à Nantes, puis la techno lors d'un séjour à Ibiza en 2013. Il fait partie des DJs réguliers du Warehouse de Nantes. Son répertoire va de la deep progressive à la minimal techno, avec une préférence assumée pour la tech house festive.", en: "Verdun is a Nantes-based DJ who discovered electronic music at nineteen after moving to the city, then techno during a stay in Ibiza in 2013. He is one of the regular DJs at Nantes' Warehouse club. His range runs from deep progressive to minimal techno, with a stated preference for party-leaning tech house." }, origin: "Nantes, France", since: 2013, sources: ["https://www.warehouse-nantes.fr/artist/verdun"] }, // Verdun
  "vertile": { slug: "vertile", bio: { fr: "Vertile est le nom de scène de Mees van den Berg, DJ et producteur de hardstyle néerlandais. Il sort ses premiers titres en 2019 dans la série Q-Dance Presents NEXT, puis publie sur Nightbreed Records, Roughstate et Art Of Creation. Il a signé en 2022 l'hymne officiel du festival Shockerz, « Complex Aftermath ».", en: "Vertile is the stage name of Mees van den Berg, a Dutch hardstyle DJ and producer. He put out his first tracks in 2019 in the Q-Dance Presents NEXT series, then released on Nightbreed Records, Roughstate and Art Of Creation. In 2022 he wrote the official anthem of the Shockerz festival, \"Complex Aftermath\"." }, origin: "Pays-Bas", since: 2019, labels: ["Nightbreed Records", "Roughstate"], sources: ["https://www.discogs.com/artist/7233886-Vertile", "https://api.discogs.com/artists/7233886/releases"] }, // Vertile
  "victor-ruiz": { slug: "victor-ruiz", bio: { fr: "Producteur et DJ brésilien installé à Amsterdam, Victor Ruiz joue une techno mélodique de peak time et revendique une influence rock dans ses productions. Il sort sur Drumcode et a remixé Moby, Stephan Bodzin et Dubfire. Ses sets sont aussi connus pour ses edits non officiels de classiques signés The Prodigy, Robert Miles, Depeche Mode ou Massive Attack.", en: "A Brazilian producer and DJ based in Amsterdam, Victor Ruiz plays peak-time melodic techno and claims a rock influence in his productions. He releases on Drumcode and has remixed Moby, Stephan Bodzin and Dubfire. His sets are also known for his unofficial edits of classics by The Prodigy, Robert Miles, Depeche Mode and Massive Attack." }, origin: "Brésil", labels: ["Drumcode"], sources: ["https://www.drumcode.se/artists/victor-ruiz"] }, // Victor Ruiz
  "vieze-asbak": { slug: "vieze-asbak", bio: { fr: "Vieze Asbak est un DJ et producteur néerlandais actif depuis 2021, où il commence par écrire des morceaux pour ses amis avant que ceux-ci ne circulent sur les réseaux. Il joue une hard techno qui assume l'humour et le sample absurde — ce que la scène appelle « memetechno » — et a signé le remix « Meet Her At The Love Parade » puis, avec le rappeur Joost Klein, « Friesenjung », disque d'or en Allemagne. Il a cofondé le collectif Pestcore et son festival Pestival.", en: "Vieze Asbak is a Dutch DJ and producer active since 2021, when he began making tracks for friends that then spread on social media. He plays hard techno built on humour and absurd samples — what the scene calls \"memetechno\" — and is behind the \"Meet Her At The Love Parade\" remix and, with rapper Joost Klein, \"Friesenjung\", certified gold in Germany. He co-founded the Pestcore collective and its Pestival event." }, origin: "Pays-Bas", since: 2021, sources: ["https://www.apokalyptoagency.com/pages/vieze-asbak"] }, // Vieze Asbak
  "vini-vici": { slug: "vini-vici", bio: { fr: "Vini Vici est un duo israélien de psytrance formé par Matan Kadosh et Aviram Saharai, basé à Afula. Les deux producteurs travaillaient ensemble depuis 2001 sous le nom Sesto Sento avant d'adopter Vini Vici en 2013. Leur remix de « Free Tibet » de Hilight Tribe puis « Great Spirit » (2016), avec Armin van Buuren, ont fait passer la psytrance sur les grandes scènes ; ils ont lancé le label Alteza Records en 2018.", en: "Vini Vici are an Israeli psytrance duo made up of Matan Kadosh and Aviram Saharai, based in Afula. The pair had worked together since 2001 as Sesto Sento before taking the Vini Vici name in 2013. Their remix of Hilight Tribe's \"Free Tibet\" and then \"Great Spirit\" (2016) with Armin van Buuren carried psytrance onto festival main stages; they launched the label Alteza Records in 2018." }, origin: "Afula, Israël", since: 2013, labels: ["Alteza Records"], sources: ["https://en.wikipedia.org/wiki/Vini_Vici"] }, // Vini Vici
  "virginia": { slug: "virginia", bio: { fr: "Virginia est une DJ, productrice, autrice et chanteuse née à Munich et installée à Berlin, active depuis la fin des années 1990. Elle est résidente de la Panorama Bar du Berghain depuis 2012 et a publié sur Ostgut Ton l'album Fierce For The Night (2016) puis le double EP Work A Change avec Steffi. Elle chante en direct par-dessus ses sets house.", en: "Virginia is a DJ, producer, songwriter and singer born in Munich and based in Berlin, active since the late 1990s. She has been a resident at Berghain's Panorama Bar since 2012 and released the album Fierce For The Night (2016) and the double EP Work A Change with Steffi on Ostgut Ton. She sings live over her house sets." }, origin: "Berlin, Allemagne", labels: ["Ostgut Ton"], sources: ["https://old.ostgut.de/booking/artist/virginia", "https://www.thevinylfactory.com/news/steffi-and-virginia-new-double-ep-ostgut-ton-work-a-change-vinyl"] }, // Virginia
  "vladimir-cauchemar": { slug: "vladimir-cauchemar", bio: { fr: "Vladimir Cauchemar, de son vrai nom Guillaume Brière, né le 17 décembre 1978 à Reims, est un DJ, compositeur et producteur français. Membre des groupes The Shoes et The Film, il se fait connaître en solo avec le single Aulos, publié sur Ed Banger Records. Il se produit toujours masqué, derrière une tête de mort, et a produit des titres pour Lomepal, Roméo Elvis et Vald.", en: "Vladimir Cauchemar, real name Guillaume Brière, born 17 December 1978 in Reims, is a French DJ, composer and producer. A member of the bands The Shoes and The Film, he broke through solo with the single \"Aulos\" on Ed Banger Records. He always performs masked, behind a skull, and has produced tracks for Lomepal, Roméo Elvis and Vald." }, origin: "Reims, France", since: 2017, labels: ["Ed Banger Records", "Lokomotiv Sound"], sources: ["https://fr.wikipedia.org/wiki/Vladimir_Cauchemar", "https://en.wikipedia.org/wiki/Vladimir_Cauchemar"] }, // Vladimir Cauchemar
  "vortek-s": { slug: "vortek-s", bio: { fr: "Vortek's est un DJ et producteur français originaire de Cherbourg, issu de la scène free party et des styles tribe, acidcore et hardtek. Son signe distinctif : des rythmiques massives, des textures acid et des nappes immersives, sur des morceaux comme « Darkness ». Il collabore régulièrement avec Felckin, Venom, Teksa ou D-Frek, et ses disques paraissent notamment sur Omny Lab, Acid Pirate et Underground Tekno.", en: "Vortek's is a French DJ and producer from Cherbourg who came up through the free party scene and its tribe, acidcore and hardtek strands. His trademark is heavy rhythm work, acid textures and immersive pads, heard on tracks such as \"Darkness\". He works regularly with Felckin, Venom, Teksa and D-Frek, and releases on labels including Omny Lab, Acid Pirate and Underground Tekno." }, origin: "Cherbourg, France", labels: ["Omny Lab", "Acid Pirate", "Underground Tekno"], sources: ["https://dreamnation.fr/en/artiste/vorteks/", "https://download.undergroundtekno.com/en/artists/vorteks/tracks"] }, // Vortek's
  "warface": { slug: "warface", bio: { fr: "Warface est un projet néerlandais de raw hardstyle porté par Youri Claessens et Remco-Jan Prevoo, ce dernier également connu comme le producteur hardcore Triax. Un seul des deux membres assure les sets, masqué et en tenue militaire. Le projet publie sur End of Line Recordings, Defqon.1 Records et Intents Records, avec des titres comme « Embrace The Madness », « Filthy Rave » avec Rebelion ou « To The Stars » avec Paul Elstak.", en: "Warface is a Dutch raw hardstyle project run by Youri Claessens and Remco-Jan Prevoo, the latter also known as hardcore producer Triax. Only one of the two performs the DJ sets, masked and in military dress. The project releases on End of Line Recordings, Defqon.1 Records and Intents Records, with tracks such as \"Embrace The Madness\", \"Filthy Rave\" with Rebelion and \"To The Stars\" with Paul Elstak." }, origin: "Pays-Bas", labels: ["End of Line Recordings"], sources: ["https://hardstyle.com/en/artists/warface", "https://hardstylemag.com/catch-up-interview-with-warface/", "https://www.discogs.com/artist/1120960"] }, // Warface
  "wilkinson": { slug: "wilkinson", bio: { fr: "Wilkinson est le nom de scène de Mark Wilkinson, producteur et DJ anglais né le 18 avril 1989 à Hammersmith. Il publie sur RAM Records et Hospital Records, ainsi que sur Virgin EMI. Son single « Afterglow » (2013), chanté par Becky Hill, a atteint la 8e place des charts britanniques.", en: "Wilkinson is the stage name of Mark Wilkinson, an English producer and DJ born on 18 April 1989 in Hammersmith. He releases on RAM Records and Hospital Records, as well as Virgin EMI. His 2013 single \"Afterglow\", with vocals by Becky Hill, reached number eight on the UK Singles Chart." }, origin: "Hammersmith, Royaume-Uni", labels: ["RAM Records", "Hospital Records"], sources: ["https://en.wikipedia.org/wiki/Wilkinson_(musician)", "https://api.discogs.com/database/search?artist=Wilkinson&type=release"] }, // Wilkinson
  "worship": { slug: "worship", bio: { fr: "Worship est un projet collectif de drum & bass britannique réunissant Sub Focus, Dimension, Culture Shock et 1991. Le groupe est programmé en tête d'affiche d'Ultra Europe 2026, au Park Mladeži de Split.", en: "Worship is a British drum & bass collective project bringing together Sub Focus, Dimension, Culture Shock and 1991. The group was billed as a headline act at Ultra Europe 2026, at Split's Park Mladeži." }, origin: "Royaume-Uni", sources: ["https://www.ravejungle.com/2026/05/19/ultra-europe-2026-lineup-phase-2/", "https://ufo-network.com/2025/10/09/ultra-music-festival-2026/"] }, // Worship
  "xmoze": { slug: "xmoze", bio: { fr: "Øxmoze est un DJ nantais qui joue de la hardtechno et de la hardtrance. Il est résident des collectifs No Limit Event et Ventrachouille, et se produit régulièrement au Warehouse de Nantes.", en: "Øxmoze is a DJ from Nantes who plays hard techno and hard trance. He is a resident of the No Limit Event and Ventrachouille collectives, and appears regularly at the Warehouse in Nantes." }, origin: "Nantes, France", sources: ["https://www.warehouse-nantes.fr/artist/oxmoze/"] }, // Øxmoze
  "yaeji": { slug: "yaeji", bio: { fr: "Kathy Yaeji Lee, née le 6 août 1993 dans le Queens à New York, produit et mixe sous le nom Yaeji depuis Brooklyn. Sa musique croise house et hip-hop, avec un chant murmuré en anglais et en coréen. Ses EP « EP1 » et « EP2 » (2017) puis la mixtape « What We Drew » et l'album « With a Hammer » (2023) sont parus sur XL Recordings.", en: "Kathy Yaeji Lee, born 6 August 1993 in Queens, New York, produces and DJs as Yaeji out of Brooklyn. Her music blends house and hip hop with quiet vocals sung in both English and Korean. Her EPs \"EP1\" and \"EP2\" (2017), the mixtape \"What We Drew\" and the album \"With a Hammer\" (2023) came out on XL Recordings." }, origin: "Queens, New York, États-Unis", since: 2016, labels: ["XL Recordings"], sources: ["https://en.wikipedia.org/wiki/Yaeji", "https://api.discogs.com/database/search?type=release&artist=Yaeji"] }, // Yaeji
  "yanamaste": { slug: "yanamaste", bio: { fr: "Yanamaste, de son vrai nom Irakli Danelia, est un DJ et producteur géorgien né et grandi à Batumi. Musicien de formation — piano dès six ans, percussions traditionnelles géorgiennes, huit ans dans l'ensemble national de danse —, il découvre le club à 16 ans et se tourne vers la techno. Il travaille beaucoup au synthétiseur modulaire et joue notamment à Awakenings, à Amsterdam.", en: "Yanamaste, real name Irakli Danelia, is a Georgian DJ and producer born and raised in Batumi. A trained musician — piano from the age of six, traditional Georgian percussion, eight years in the national dance ensemble — he first walked into a club at 16 and turned to techno. He works extensively with modular synthesisers and has played at Awakenings in Amsterdam, among others." }, origin: "Batumi, Géorgie", sources: ["https://surefire.agency/yanamaste", "https://www.numeronetherlands.com/in-conversation-with/in-conversation-with-yanamaste"] }, // Yanamaste
  "yoshiko": { slug: "yoshiko", bio: { fr: "Giada Morone, alias Yoshiko, est une DJ hardcore née en Italie de parents brésiliens, japonais et italiens. Elle découvre le hardstyle à quatorze ans puis le hardcore, s'installe aux Pays-Bas après le lycée et prend pour nom de scène celui de sa tante japonaise. Elle est représentée par BKJN Bookings.", en: "Giada Morone, who performs as Yoshiko, is a hardcore DJ born in Italy to Brazilian, Japanese and Italian parents. She discovered hardstyle at fourteen and then hardcore, moved to the Netherlands after finishing school, and took her stage name from her Japanese aunt. She is booked through BKJN Bookings." }, origin: "Italie / Pays-Bas", sources: ["https://www.discogs.com/artist/6595648-Yoshiko-6", "https://www.bkjnbookings.com/yoshiko"] }, // Yoshiko
  "young-marco": { slug: "young-marco", bio: { fr: "Young Marco est le nom de scène de Marco Sterk, DJ et producteur néerlandais d'Amsterdam. Il joue une house psychédélique tirant vers la transe et a publié sur Rush Hour puis ESP Institute, avec les albums Biology et Bahasa. Il dirige le label Safe Trip, connu pour ses compilations de house italienne des années 90 et de trance ancienne, et forme avec Gigi Masin et Jonny Nash le trio ambient Gaussian Curve.", en: "Young Marco is the stage name of Marco Sterk, a Dutch DJ and producer from Amsterdam. He plays psychedelic, trance-leaning house and has released on Rush Hour and ESP Institute, with the albums Biology and Bahasa. He runs the Safe Trip label, known for its compilations of 90s Italian house and early trance, and forms the ambient trio Gaussian Curve with Gigi Masin and Jonny Nash." }, origin: "Amsterdam, Pays-Bas", labels: ["Safe Trip", "ESP Institute", "Rush Hour"], sources: ["https://dgtl-festival.com/en/artists/young-marco/"] }, // Young Marco
  "ypy": { slug: "ypy", bio: { fr: "YPY est le projet solo de Koshiro Hino, musicien d'Osaka lancé en 2014, également membre des groupes goat et bonanzas. Sa production va de la techno et de la house de dancefloor à des pièces plus expérimentales et bruitistes, avec une place centrale donnée aux percussions. Il dirige les labels Birdfriend, en cassettes, et NAKID.", en: "YPY is the solo project of Koshiro Hino, an Osaka musician, launched in 2014; he is also a member of the bands goat and bonanzas. His output runs from dancefloor techno and house to headier, noisier pieces, with percussion at the centre throughout. He runs the cassette label Birdfriend and the label NAKID." }, origin: "Osaka, Japon", since: 2014, labels: ["NAKID", "Birdfriend"], sources: ["https://tokyo.mutek.org/en/artists/ypy-1", "https://xlr8r.com/features/bubbling-up-ypy/", "https://www.japantimes.co.jp/culture/2017/02/05/music/koshiro-hino-pushes-limits-control-ypy/"] }, // YPY
  "yung-singh": { slug: "yung-singh", bio: { fr: "Yung Singh est un DJ britannique issu de la communauté punjabi-sikh du Royaume-Uni, membre du collectif Daytimers. Son mix « Punjabi Garage » publié en 2020 remet en lumière un pan oublié de la culture club britannique ; il co-produit ensuite avec Ministry of Sound le documentaire « The Birth of Punjabi Garage ». Ses sets mêlent UK garage, house, jungle et musique punjabi. DJ Mag le désigne Breakthrough DJ of the Year en 2021 et il obtient une résidence sur BBC Radio 1 en 2023.", en: "Yung Singh is a British DJ from the UK's Punjabi-Sikh community and a member of the Daytimers collective. His 2020 \"Punjabi Garage\" mix brought a forgotten strand of British club culture back into focus; he went on to co-produce the documentary \"The Birth of Punjabi Garage\" with Ministry of Sound. His sets blend UK garage, house, jungle and Punjabi music. DJ Mag named him Breakthrough DJ of the Year in 2021 and he took up a BBC Radio 1 residency in 2023." }, origin: "Royaume-Uni", sources: ["https://www.yungsingh.com/biography", "https://mixmag.net/read/punjabi-garage-documentary-yung-singh-ministry-of-sound-news"] }, // Yung Singh
  "yves-deruyter": { slug: "yves-deruyter", bio: { fr: "Yves Deruyter est un DJ et producteur belge né le 4 mai 1970 à Anvers. Il s'est fait connaître par son travail pour le label Bonzai Records, dans un registre de trance, de hard trance et de techno rave des années 1990.", en: "Yves Deruyter is a Belgian DJ and producer born on 4 May 1970 in Antwerp. He is known for his work on Bonzai Records, in a 1990s trance, hard trance and rave techno vein." }, origin: "Anvers, Belgique", since: 1993, labels: ["Bonzai Records"], sources: ["https://en.wikipedia.org/wiki/Yves_Deruyter", "https://musicbrainz.org/ws/2/artist/?query=artist:Yves%20Deruyter&fmt=json"] }, // Yves Deruyter
  "zapravka": { slug: "zapravka", bio: { fr: "Zapravka est un duo russe formé en 2021 par deux amis qui se sont rencontrés comme DJs dans une agence spécialisée dans les mariages. Après être passés par la drum & bass, le hardstyle et la bass house, ils se sont fixés sur une hard techno rapide à kicks gabber. Leurs titres, souvent chantés en russe, ont circulé par millions de vues sur TikTok.", en: "Zapravka are a Russian duo formed in 2021 by two friends who met as DJs at a wedding events agency. After passing through drum & bass, hardstyle and bass house, they settled on a fast hard techno built on gabber kicks. Their tracks, often sung in Russian, have racked up millions of views on TikTok." }, origin: "Russie", since: 2021, sources: ["https://electro-news.eu/zapravka-le-nouveau-duo-de-dj-dejantes-qui-mixent-et-chantent-en-meme-temps/"] }, // Zapravka
  "zara-larsson": { slug: "zara-larsson", bio: { fr: "Zara Larsson est une chanteuse et autrice-compositrice suédoise née en 1997 à Solna, dans la banlieue de Stockholm. Elle s'est fait connaître à dix ans en remportant la deuxième saison de l'émission Talang en 2008, puis avec le single « Uncover » en 2013, numéro un en Suède. Sa pop teintée de house et de dance a franchi les frontières avec « Lush Life » en 2015 et « Symphony », avec Clean Bandit, numéro un au Royaume-Uni. Elle a lancé son propre label, Sommer House, en 2022, et son album « Midnight Sun » (2025) lui a valu sa première nomination aux Grammy Awards.", en: "Zara Larsson is a Swedish singer and songwriter born in 1997 in Solna, on the edge of Stockholm. She first became known at ten by winning the second season of the talent show Talang in 2008, then with the single \"Uncover\" in 2013, a number one in Sweden. Her house- and dance-inflected pop crossed over with \"Lush Life\" in 2015 and \"Symphony\" with Clean Bandit, a UK number one. She launched her own label, Sommer House, in 2022, and her album \"Midnight Sun\" (2025) earned her a first Grammy nomination." }, origin: "Solna, Suède", since: 2008, labels: ["Sommer House", "Epic Records"], sources: ["https://en.wikipedia.org/wiki/Zara_Larsson"] }, // Zara Larsson
  "zelecter": { slug: "zelecter", bio: { fr: "Zelecter est un DJ et producteur allemand originaire de Heidelberg. Il s'est spécialisé dans le hardstyle, en particulier l'early hardstyle et le raw hardstyle, et ses sets font se croiser les classiques du genre avec des passages hardcore et uptempo.", en: "Zelecter is a German DJ and producer from Heidelberg. He specialises in hardstyle, in particular early hardstyle and raw hardstyle, and his sets cross the genre's classics with hardcore and uptempo passages." }, origin: "Heidelberg, Allemagne", sources: ["https://openbeatz.de/artist/zelecter-2/", "https://www.discogs.com/artist/12164173-Zelecter"] }, // Zelecter
};
/* BIOS:end */

export const bioFor = (slug: string): ArtistBio | undefined => BIOS[slug];

export const bioText = (b: ArtistBio, lang: Lang): string => (lang === "fr" ? b.bio.fr : b.bio.en);

/** How many artist pages currently carry a researched bio — used by the audit script. */
export const BIO_COUNT = Object.keys(BIOS).length;
